{
  "name": "NeoOps 3D O&M Canvas",
  "description": "A sophisticated 3D operations and maintenance topology editor featuring dynamic effects, relationship mapping, and AI-driven architecture analysis.",
  "requestFramePermissions": []
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum ServiceType {
  DATABASE = 'database',
  SERVER = 'server',
  GATEWAY = 'gateway',
  CACHE = 'cache',
  LOAD_BALANCER = 'load_balancer',
  FIREWALL = 'firewall'
}

export interface Vector3Array {
  x: number;
  y: number;
  z: number;
}

export interface ServiceNode {
  id: string;
  name: string;
  type: ServiceType;
  position: Vector3Array;
  status: 'online' | 'warning' | 'error';
  lastUpdated: string;
}

export interface Connection {
  id: string;
  sourceId: string;
  targetId: string;
  label: string;
  trafficLoad: number; // 0-1
}

export interface AppState {
  nodes: ServiceNode[];
  connections: Connection[];
  selectedNodeId: string | null;
  mode: 'select' | 'add' | 'connect';
}

import React from 'react';
import { ServiceType } from './types';

export const THEME = {
  primary: '#0ea5e9', // Sky 500
  secondary: '#6366f1', // Indigo 500
  success: '#22c55e', // Green 500
  warning: '#eab308', // Yellow 500
  danger: '#ef4444', // Red 500
  bg: '#020617',
  nodeBg: '#1e293b'
};

export const SERVICE_ICONS: Record<ServiceType, string> = {
  [ServiceType.DATABASE]: 'fa-database',
  [ServiceType.SERVER]: 'fa-server',
  [ServiceType.GATEWAY]: 'fa-network-wired',
  [ServiceType.CACHE]: 'fa-bolt',
  [ServiceType.LOAD_BALANCER]: 'fa-code-branch',
  [ServiceType.FIREWALL]: 'fa-shield-halved'
};

export const SERVICE_COLORS: Record<ServiceType, string> = {
  [ServiceType.DATABASE]: '#fb923c', // orange-400
  [ServiceType.SERVER]: '#38bdf8', // sky-400
  [ServiceType.GATEWAY]: '#818cf8', // indigo-400
  [ServiceType.CACHE]: '#facc15', // yellow-400
  [ServiceType.LOAD_BALANCER]: '#4ade80', // green-400
  [ServiceType.FIREWALL]: '#f87171' // red-400
};

import { GoogleGenAI, Type } from "@google/genai";
import { ServiceNode, Connection } from "./types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export async function analyzeTopology(nodes: ServiceNode[], connections: Connection[]) {
  const prompt = `
    Analyze this system architecture and suggest improvements for reliability and scalability.

    Nodes: ${JSON.stringify(nodes.map(n => ({ id: n.id, type: n.type, name: n.name })))}
    Connections: ${JSON.stringify(connections.map(c => ({ from: c.sourceId, to: c.targetId, label: c.label })))}

    Provide a brief JSON summary.
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            score: { type: Type.NUMBER, description: "Architecture health score 0-100" },
            bottlenecks: { type: Type.ARRAY, items: { type: Type.STRING } },
            recommendations: { type: Type.ARRAY, items: { type: Type.STRING } }
          },
          required: ["score", "bottlenecks", "recommendations"]
        }
      }
    });

    return JSON.parse(response.text);
  } catch (error) {
    console.error("AI Analysis failed:", error);
    return null;
  }
}

export async function suggestLayout(description: string) {
    const prompt = `Based on the description: "${description}", generate a 3D topology layout.
    Return a JSON object with nodes and connections. 
    Positions should be roughly within -10 to 10 on X, Y, Z.`;

    const response = await ai.models.generateContent({
        model: "gemini-3-flash-preview",
        contents: prompt,
        config: {
            responseMimeType: "application/json",
            responseSchema: {
                type: Type.OBJECT,
                properties: {
                    nodes: {
                        type: Type.ARRAY,
                        items: {
                            type: Type.OBJECT,
                            properties: {
                                name: { type: Type.STRING },
                                type: { type: Type.STRING, description: "database, server, gateway, cache, load_balancer, firewall" },
                                x: { type: Type.NUMBER },
                                y: { type: Type.NUMBER },
                                z: { type: Type.NUMBER }
                            },
                            required: ["name", "type", "x", "y", "z"]
                        }
                    },
                    connections: {
                        type: Type.ARRAY,
                        items: {
                            type: Type.OBJECT,
                            properties: {
                                sourceIndex: { type: Type.INTEGER },
                                targetIndex: { type: Type.INTEGER },
                                label: { type: Type.STRING }
                            },
                            required: ["sourceIndex", "targetIndex", "label"]
                        }
                    }
                },
                required: ["nodes", "connections"]
            }
        }
    });

    return JSON.parse(response.text);
}

import React, { useState, useCallback, useRef, useEffect } from 'react';
import { Canvas } from '@react-three/fiber';
import { OrbitControls, Stars, PerspectiveCamera, Environment, ContactShadows } from '@react-three/drei';
import Scene from './components/Scene';
import Sidebar from './components/Sidebar';
import UIOverlay from './components/UIOverlay';
import { ServiceNode, Connection, ServiceType } from './types';
import { analyzeTopology, suggestLayout } from './geminiService';

const App: React.FC = () => {
  const [nodes, setNodes] = useState<ServiceNode[]>([
    { id: '1', name: 'User Gateway', type: ServiceType.GATEWAY, position: { x: -5, y: 0, z: 0 }, status: 'online', lastUpdated: new Date().toISOString() },
    { id: '2', name: 'Auth Server', type: ServiceType.SERVER, position: { x: 0, y: 2, z: 0 }, status: 'online', lastUpdated: new Date().toISOString() },
    { id: '3', name: 'Product DB', type: ServiceType.DATABASE, position: { x: 5, y: 0, z: 0 }, status: 'warning', lastUpdated: new Date().toISOString() },
  ]);

  const [connections, setConnections] = useState<Connection[]>([
    { id: 'c1', sourceId: '1', targetId: '2', label: 'HTTP Auth', trafficLoad: 0.4 },
    { id: 'c2', sourceId: '2', targetId: '3', label: 'SQL Query', trafficLoad: 0.8 },
  ]);

  const [selectedNodeId, setSelectedNodeId] = useState<string | null>(null);
  const [mode, setMode] = useState<'select' | 'add' | 'connect'>('select');
  const [connectSourceId, setConnectSourceId] = useState<string | null>(null);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [analysisResult, setAnalysisResult] = useState<any>(null);

  const addNode = useCallback((type: ServiceType, name: string) => {
    const newNode: ServiceNode = {
      id: Math.random().toString(36).substr(2, 9),
      name,
      type,
      position: { 
        x: (Math.random() - 0.5) * 10, 
        y: (Math.random() - 0.5) * 10, 
        z: (Math.random() - 0.5) * 10 
      },
      status: 'online',
      lastUpdated: new Date().toISOString()
    };
    setNodes(prev => [...prev, newNode]);
  }, []);

  const handleNodeClick = useCallback((id: string) => {
    if (mode === 'connect') {
      if (!connectSourceId) {
        setConnectSourceId(id);
      } else if (connectSourceId !== id) {
        // Create connection
        const newConn: Connection = {
          id: `c-${Date.now()}`,
          sourceId: connectSourceId,
          targetId: id,
          label: 'New Link',
          trafficLoad: 0.2
        };
        setConnections(prev => [...prev, newConn]);
        setConnectSourceId(null);
        setMode('select');
      }
    } else {
      setSelectedNodeId(id === selectedNodeId ? null : id);
    }
  }, [mode, connectSourceId, selectedNodeId]);

  const handleAnalyze = async () => {
    setIsAnalyzing(true);
    const result = await analyzeTopology(nodes, connections);
    setAnalysisResult(result);
    setIsAnalyzing(false);
  };

  const handleAutoLayout = async (desc: string) => {
    setIsAnalyzing(true);
    try {
        const layout = await suggestLayout(desc);
        const newNodes: ServiceNode[] = layout.nodes.map((n: any, i: number) => ({
            id: `node-${i}`,
            name: n.name,
            type: n.type as ServiceType,
            position: { x: n.x, y: n.y, z: n.z },
            status: 'online',
            lastUpdated: new Date().toISOString()
        }));
        const newConns: Connection[] = layout.connections.map((c: any, i: number) => ({
            id: `conn-${i}`,
            sourceId: `node-${c.sourceIndex}`,
            targetId: `node-${c.targetIndex}`,
            label: c.label,
            trafficLoad: 0.1
        }));
        setNodes(newNodes);
        setConnections(newConns);
    } catch (e) {
        console.error(e);
    }
    setIsAnalyzing(false);
  };

  const updateNodePosition = (id: string, pos: { x: number, y: number, z: number }) => {
    setNodes(prev => prev.map(n => n.id === id ? { ...n, position: pos } : n));
  };

  return (
    <div className="flex h-screen w-screen bg-slate-950 text-slate-100 overflow-hidden font-sans">
      <Sidebar 
        nodes={nodes} 
        connections={connections}
        selectedNodeId={selectedNodeId}
        addNode={addNode}
        onAnalyze={handleAnalyze}
        isAnalyzing={isAnalyzing}
        analysisResult={analysisResult}
        onAutoLayout={handleAutoLayout}
      />

      <main className="flex-1 relative">
        <UIOverlay 
            mode={mode} 
            setMode={setMode} 
            connectSource={connectSourceId ? nodes.find(n => n.id === connectSourceId)?.name : null}
        />

        <Canvas shadows dpr={[1, 2]}>
          <PerspectiveCamera makeDefault position={[15, 15, 15]} fov={50} />
          <OrbitControls 
            enableDamping 
            dampingFactor={0.05} 
            makeDefault 
            enabled={mode !== 'connect' || !connectSourceId}
          />

          <color attach="background" args={['#020617']} />
          <fog attach="fog" args={['#020617', 20, 50]} />

          <ambientLight intensity={0.5} />
          <spotLight position={[10, 10, 10]} angle={0.15} penumbra={1} intensity={1} castShadow />
          <pointLight position={[-10, -10, -10]} intensity={0.5} />

          <Scene 
            nodes={nodes} 
            connections={connections} 
            selectedId={selectedNodeId}
            onNodeClick={handleNodeClick}
            onNodeMove={updateNodePosition}
            mode={mode}
          />

          <Stars radius={100} depth={50} count={5000} factor={4} saturation={0} fade speed={1} />
          <Environment preset="city" />
          <ContactShadows resolution={1024} scale={20} blur={2} opacity={0.25} far={10} color="#000" />
        </Canvas>

        {isAnalyzing && (
            <div className="absolute inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm">
                <div className="bg-slate-900 p-8 rounded-2xl shadow-2xl border border-sky-500/50 flex flex-col items-center">
                    <div className="w-16 h-16 border-4 border-sky-500 border-t-transparent rounded-full animate-spin mb-4"></div>
                    <h3 className="text-xl font-bold text-sky-400">AI Processing Topology...</h3>
                    <p className="text-slate-400 mt-2">Analyzing nodes, relationships, and performance metrics.</p>
                </div>
            </div>
        )}
      </main>
    </div>
  );
};

export default App;

import React, { useMemo } from 'react';
import { useFrame } from '@react-three/fiber';
import ServiceNodeMesh from './ServiceNodeMesh';
import ConnectionLine from './ConnectionLine';
import { ServiceNode, Connection } from '../types';

interface SceneProps {
  nodes: ServiceNode[];
  connections: Connection[];
  selectedId: string | null;
  onNodeClick: (id: string) => void;
  onNodeMove: (id: string, pos: { x: number, y: number, z: number }) => void;
  mode: string;
}

const Scene: React.FC<SceneProps> = ({ nodes, connections, selectedId, onNodeClick, onNodeMove, mode }) => {
  return (
    <group>
      {nodes.map((node) => (
        <ServiceNodeMesh 
          key={node.id} 
          node={node} 
          isSelected={selectedId === node.id}
          onClick={() => onNodeClick(node.id)}
          onMove={(pos) => onNodeMove(node.id, pos)}
          draggable={mode === 'select'}
        />
      ))}

      {connections.map((conn) => {
        const sourceNode = nodes.find(n => n.id === conn.sourceId);
        const targetNode = nodes.find(n => n.id === conn.targetId);

        if (!sourceNode || !targetNode) return null;

        return (
          <ConnectionLine 
            key={conn.id} 
            connection={conn}
            start={sourceNode.position}
            end={targetNode.position}
          />
        );
      })}
    </group>
  );
};

export default Scene;

import React, { useRef, useState } from 'react';
import { useFrame, ThreeEvent } from '@react-three/fiber';
import { Text, Float, RoundedBox, Html } from '@react-three/drei';
import * as THREE from 'three';
import { ServiceNode, ServiceType } from '../types';
import { SERVICE_COLORS, SERVICE_ICONS } from '../constants';

interface ServiceNodeMeshProps {
  node: ServiceNode;
  isSelected: boolean;
  onClick: (e: ThreeEvent<MouseEvent>) => void;
  onMove: (pos: { x: number, y: number, z: number }) => void;
  draggable: boolean;
}

const ServiceNodeMesh: React.FC<ServiceNodeMeshProps> = ({ node, isSelected, onClick, onMove, draggable }) => {
  const meshRef = useRef<THREE.Group>(null);
  const [hovered, setHovered] = useState(false);

  const color = SERVICE_COLORS[node.type];
  const statusColor = node.status === 'online' ? '#22c55e' : node.status === 'warning' ? '#eab308' : '#ef4444';

  useFrame((state) => {
    if (meshRef.current) {
      const time = state.clock.getElapsedTime();
      // subtle idle animation
      if (!isSelected) {
        meshRef.current.position.y = node.position.y + Math.sin(time + Number(node.id)) * 0.1;
      }
    }
  });

  return (
    <Float speed={2} rotationIntensity={0.5} floatIntensity={0.5}>
      <group 
        ref={meshRef} 
        position={[node.position.x, node.position.y, node.position.z]}
        onClick={(e) => {
          e.stopPropagation();
          onClick(e);
        }}
        onPointerOver={() => setHovered(true)}
        onPointerOut={() => setHovered(false)}
      >
        <RoundedBox args={[1.2, 1.2, 0.4]} radius={0.1} smoothness={4}>
          <meshStandardMaterial 
            color={isSelected ? '#38bdf8' : hovered ? '#1e293b' : '#0f172a'} 
            emissive={isSelected ? '#0ea5e9' : '#000'}
            emissiveIntensity={0.5}
            roughness={0.1}
            metalness={0.8}
          />
        </RoundedBox>

        {/* Status ring */}
        <mesh position={[0, 0, -0.21]} rotation={[0, 0, 0]}>
          <ringGeometry args={[0.7, 0.75, 32]} />
          <meshBasicMaterial color={statusColor} transparent opacity={0.6} />
        </mesh>

        <Text
          position={[0, -0.9, 0]}
          fontSize={0.3}
          color="white"
          anchorX="center"
          anchorY="middle"
          font="https://fonts.gstatic.com/s/roboto/v18/KFOmCnqEu92Fr1Mu4mxM.woff"
        >
          {node.name}
        </Text>

        <Html position={[0, 0.8, 0]} center distanceFactor={10}>
          <div className="flex flex-col items-center pointer-events-none select-none">
            <div className={`px-2 py-0.5 rounded-full text-[10px] font-bold uppercase ${
              node.status === 'online' ? 'bg-green-500/20 text-green-400 border border-green-500/50' : 
              node.status === 'warning' ? 'bg-yellow-500/20 text-yellow-400 border border-yellow-500/50' : 
              'bg-red-500/20 text-red-400 border border-red-500/50'
            }`}>
              {node.status}
            </div>
            <i className={`fas ${SERVICE_ICONS[node.type]} mt-2 text-lg drop-shadow-[0_0_8px_rgba(255,255,255,0.5)]`} style={{ color }}></i>
          </div>
        </Html>

        {isSelected && (
           <mesh rotation={[Math.PI / 2, 0, 0]} position={[0, -1.5, 0]}>
             <torusGeometry args={[1.5, 0.02, 16, 100]} />
             <meshBasicMaterial color="#0ea5e9" />
           </mesh>
        )}
      </group>
    </Float>
  );
};

export default ServiceNodeMesh;

import React, { useRef, useMemo } from 'react';
import { useFrame } from '@react-three/fiber';
import * as THREE from 'three';
import { Line, QuadraticBezierLine } from '@react-three/drei';
import { Connection, Vector3Array } from '../types';

interface ConnectionLineProps {
  connection: Connection;
  start: Vector3Array;
  end: Vector3Array;
}

const ConnectionLine: React.FC<ConnectionLineProps> = ({ connection, start, end }) => {
  const particleRef = useRef<THREE.Mesh>(null);
  const lineRef = useRef<any>(null);

  const startVec = useMemo(() => new THREE.Vector3(start.x, start.y, start.z), [start]);
  const endVec = useMemo(() => new THREE.Vector3(end.x, end.y, end.z), [end]);

  // Create a midpoint for the curve
  const mid = useMemo(() => {
    const v = new THREE.Vector3().addVectors(startVec, endVec).multiplyScalar(0.5);
    v.y += 2; // Curve up
    return v;
  }, [startVec, endVec]);

  const curve = useMemo(() => {
    return new THREE.QuadraticBezierCurve3(startVec, mid, endVec);
  }, [startVec, mid, endVec]);

  useFrame((state) => {
    if (particleRef.current) {
      const time = (state.clock.getElapsedTime() * 0.5 * (1 + connection.trafficLoad)) % 1;
      const point = curve.getPoint(time);
      particleRef.current.position.copy(point);
    }
  });

  return (
    <group>
      <QuadraticBezierLine
        start={startVec}
        end={endVec}
        mid={mid}
        color={connection.trafficLoad > 0.7 ? "#ef4444" : "#38bdf8"}
        lineWidth={1}
        transparent
        opacity={0.4}
      />

      {/* Dynamic flow particle */}
      <mesh ref={particleRef}>
        <sphereGeometry args={[0.1, 8, 8]} />
        <meshBasicMaterial color="#7dd3fc" />
      </mesh>

      {/* Connection label at midpoint */}
      <group position={[mid.x, mid.y + 0.5, mid.z]}>
         <mesh>
            <sphereGeometry args={[0.05, 8, 8]} />
            <meshBasicMaterial color="#64748b" />
         </mesh>
      </group>
    </group>
  );
};

export default ConnectionLine;

import React, { useState } from 'react';
import { ServiceNode, Connection, ServiceType } from '../types';
import { SERVICE_ICONS, SERVICE_COLORS } from '../constants';

interface SidebarProps {
  nodes: ServiceNode[];
  connections: Connection[];
  selectedNodeId: string | null;
  addNode: (type: ServiceType, name: string) => void;
  onAnalyze: () => void;
  isAnalyzing: boolean;
  analysisResult: any;
  onAutoLayout: (desc: string) => void;
}

