        </h1>
        <p className="text-xs text-slate-500 mt-1 uppercase tracking-widest font-bold">Topology Editor</p>
      </div>

      <div className="flex-1 overflow-y-auto p-4 space-y-6">
        {/* Selected Node Info */}
        <section>
          <h3 className="text-xs font-bold text-slate-500 uppercase mb-3 tracking-wider">Node Details</h3>
          {selectedNode ? (
            <div className="bg-slate-800/50 p-4 rounded-xl border border-sky-500/30">
              <div className="flex items-center gap-3 mb-2">
                <div className="p-2 rounded-lg bg-slate-900">
                   <i className={`fas ${SERVICE_ICONS[selectedNode.type]} text-lg`} style={{ color: SERVICE_COLORS[selectedNode.type] }}></i>
                </div>
                <div>
                  <h4 className="font-bold">{selectedNode.name}</h4>
                  <p className="text-[10px] text-slate-400 uppercase">{selectedNode.type}</p>
                </div>
              </div>
              <div className="space-y-2 mt-4 text-xs">
                <div className="flex justify-between">
                  <span className="text-slate-500">Status</span>
                  <span className={selectedNode.status === 'online' ? 'text-green-400' : 'text-yellow-400'}>{selectedNode.status}</span>
                </div>
                <div className="flex justify-between">
                  <span className="text-slate-500">Last Ping</span>
