            <div className="p-3 bg-indigo-950/30 border border-indigo-500/30 rounded-xl">
                <p className="text-[10px] text-indigo-400 font-bold mb-2 uppercase italic flex items-center gap-2">
                    <i className="fas fa-wand-magic-sparkles"></i> Topology Suggestion
                </p>
                <textarea 
                    placeholder="Describe your architecture (e.g. 'A scalable web app with 3 frontend nodes and a redundant DB cluster')..."
