                    disabled={isAnalyzing || !layoutPrompt}
                    onClick={() => onAutoLayout(layoutPrompt)}
                    className="w-full mt-2 bg-indigo-600 hover:bg-indigo-500 text-white font-bold py-2 rounded-lg text-xs transition-colors disabled:opacity-50"
