import React, { useRef, useState, useEffect } from 'react';
import { ServiceNode, Connection } from '../types';
import { SERVICE_ICONS, SERVICE_COLORS } from '../constants';

interface WorkspaceProps {
  nodes: ServiceNode[];
  connections: Connection[];
  selectedId: string | null;
  onNodeClick: (id: string) => void;
  onNodeMove: (id: string, x: number, y: number) => void;
  mode: string;
}

const Workspace: React.FC<WorkspaceProps> = ({ nodes, connections, selectedId, onNodeClick, onNodeMove, mode }) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const [draggingId, setDraggingId] = useState<string | null>(null);

  const handleMouseMove = (e: React.MouseEvent) => {
    if (draggingId && containerRef.current && mode === 'select') {
      const rect = containerRef.current.getBoundingClientRect();
      const x = e.clientX - rect.left - 60; // Offset for node half-width
      const y = e.clientY - rect.top - 20; // Offset for node half-height
      onNodeMove(draggingId, x, y);
    }
  };

  const handleMouseUp = () => setDraggingId(null);

  return (
    <div 
      ref={containerRef}
      className="w-full h-full relative select-none"
      onMouseMove={handleMouseMove}
      onMouseUp={handleMouseUp}
      onMouseLeave={handleMouseUp}
    >
      {/* SVG Layer for Connections */}
      <svg className="absolute inset-0 w-full h-full pointer-events-none">
        <defs>
          <marker
            id="arrowhead"
            markerWidth="10"
            markerHeight="7"
            refX="10"
            refY="3.5"
            orient="auto"
          >
            <polygon points="0 0, 10 3.5, 0 7" fill="#38bdf8" />
          </marker>
        </defs>
        {connections.map((conn) => {
          const source = nodes.find(n => n.id === conn.sourceId);
          const target = nodes.find(n => n.id === conn.targetId);
          if (!source || !target) return null;

          const startX = source.position.x + 60;
          const startY = source.position.y + 20;
          const endX = target.position.x + 60;
          const endY = target.position.y + 20;

          return (
            <g key={conn.id}>
              <path
                d={`M ${startX} ${startY} Q ${(startX + endX) / 2} ${(startY + endY) / 2 - 50} ${endX} ${endY}`}
                stroke={conn.trafficLoad > 0.7 ? "#ef4444" : "#38bdf8"}
                strokeWidth="2"
                fill="none"
                strokeDasharray="5,5"
                markerEnd="url(#arrowhead)"
                className="opacity-60"
              />
              <circle r="4" fill="#7dd3fc">
                <animateMotion
                  dur={`${3 - conn.trafficLoad * 2}s`}
                  repeatCount="indefinite"
                  path={`M ${startX} ${startY} Q ${(startX + endX) / 2} ${(startY + endY) / 2 - 50} ${endX} ${endY}`}
                />
              </circle>
            </g>
          );
        })}
      </svg>

      {/* HTML Layer for Nodes */}
      {nodes.map((node) => {
        const isSelected = selectedId === node.id;
        const color = SERVICE_COLORS[node.type];

        return (
          <div
            key={node.id}
            style={{
              left: node.position.x,
              top: node.position.y,
              width: '120px',
              height: '40px',
            }}
            className={`absolute z-10 node-button rounded flex items-center justify-center cursor-pointer animate-rgb-flash ${
              isSelected ? 'ring-2 ring-sky-400' : ''
            }`}
            onClick={(e) => {
                e.stopPropagation();
                onNodeClick(node.id);
            }}
            onMouseDown={(e) => {
                if (mode === 'select') {
                    setDraggingId(node.id);
                }
            }}
          >
            <div className="flex items-center gap-2">
              <i className={`fas ${SERVICE_ICONS[node.type]} text-xs`} style={{ color }}></i>
              <span className="text-[10px] font-bold truncate max-w-[80px]">{node.name}</span>
            </div>
            {/* Status indicator */}
            <div className={`absolute -top-1 -right-1 w-2 h-2 rounded-full border border-slate-900 ${
                node.status === 'online' ? 'bg-green-500' : node.status === 'warning' ? 'bg-yellow-500' : 'bg-red-500'
            }`} />
          </div>
        );
      })}
    </div>
  );
};

