import React, { useState, useCallback } from 'react';
import Sidebar from './components/Sidebar';
import UIOverlay from './components/UIOverlay';
import Workspace from './components/Workspace';
import { ServiceNode, Connection, ServiceType } from './types';
import { analyzeTopology, suggestLayout } from './geminiService';

const App: React.FC = () => {
  const [nodes, setNodes] = useState<ServiceNode[]>([
    { id: '1', name: '用户网关', type: ServiceType.GATEWAY, position: { x: 100, y: 200, z: 0 }, status: 'online', lastUpdated: new Date().toISOString() },
    { id: '2', name: '认证服务器', type: ServiceType.SERVER, position: { x: 400, y: 100, z: 0 }, status: 'online', lastUpdated: new Date().toISOString() },
    { id: '3', name: '产品数据库', type: ServiceType.DATABASE, position: { x: 700, y: 300, z: 0 }, status: 'warning', lastUpdated: new Date().toISOString() },
  ]);

  const [connections, setConnections] = useState<Connection[]>([
    { id: 'c1', sourceId: '1', targetId: '2', label: 'HTTP 认证', trafficLoad: 0.4 },
    { id: 'c2', sourceId: '2', targetId: '3', label: 'SQL 查询', trafficLoad: 0.8 },
  ]);

  const [selectedNodeId, setSelectedNodeId] = useState<string | null>(null);
  const [mode, setMode] = useState<'select' | 'add' | 'connect'>('select');
  const [connectSourceId, setConnectSourceId] = useState<string | null>(null);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [analysisResult, setAnalysisResult] = useState<any>(null);

  const addNode = useCallback((type: ServiceType, name: string) => {
    const newNode: ServiceNode = {
      id: Math.random().toString(36).substr(2, 9),
      name,
      type,
      position: { 
        x: Math.random() * 600 + 50, 
        y: Math.random() * 400 + 50, 
        z: 0 
      },
      status: 'online',
      lastUpdated: new Date().toISOString()
    };
    setNodes(prev => [...prev, newNode]);
  }, []);

  const deleteNode = useCallback((id: string) => {
    setNodes(prev => prev.filter(n => n.id !== id));
    setConnections(prev => prev.filter(c => c.sourceId !== id && c.targetId !== id));
    // 强制清除选中状态，如果删除的是当前选中的节点
    setSelectedNodeId(current => current === id ? null : current);
  }, []);

  const deleteConnection = useCallback((id: string) => {
    setConnections(prev => prev.filter(c => c.id !== id));
  }, []);

  const handleNodeClick = useCallback((id: string) => {
    if (mode === 'connect') {
      if (!connectSourceId) {
        setConnectSourceId(id);
      } else if (connectSourceId !== id) {
        const newConn: Connection = {
          id: `c-${Date.now()}`,
          sourceId: connectSourceId,
          targetId: id,
          label: '新链路',
          trafficLoad: 0.2
        };
        setConnections(prev => [...prev, newConn]);
        setConnectSourceId(null);
        setMode('select');
      }
    } else {
      setSelectedNodeId(id === selectedNodeId ? null : id);
    }
  }, [mode, connectSourceId, selectedNodeId]);

  const handleAnalyze = async () => {
    setIsAnalyzing(true);
    const result = await analyzeTopology(nodes, connections);
    setAnalysisResult(result);
    setIsAnalyzing(false);
  };

  const handleAutoLayout = async (desc: string) => {
    setIsAnalyzing(true);
    try {
        const layout = await suggestLayout(desc);
        const newNodes: ServiceNode[] = layout.nodes.map((n: any, i: number) => ({
            id: `node-${i}`,
            name: n.name,
            type: n.type as ServiceType,
            position: { x: (n.x + 10) * 40, y: (n.y + 10) * 30, z: 0 },
            status: 'online',
            lastUpdated: new Date().toISOString()
        }));
        const newConns: Connection[] = layout.connections.map((c: any, i: number) => ({
            id: `conn-${i}`,
            sourceId: `node-${c.sourceIndex}`,
            targetId: `node-${c.targetIndex}`,
            label: c.label,
            trafficLoad: 0.1
        }));
        setNodes(newNodes);
        setConnections(newConns);
    } catch (e) {
        console.error(e);
    }
    setIsAnalyzing(false);
  };

  const updateNodePosition = useCallback((id: string, x: number, y: number) => {
    setNodes(prev => prev.map(n => n.id === id ? { ...n, position: { ...n.position, x, y } } : n));
  }, []);

  return (
    <div className="flex h-screen w-screen bg-slate-950 text-slate-100 overflow-hidden font-sans">
      <style>{`
        @keyframes rgb-flash {
          0% { border-color: #ef4444; box-shadow: 0 0 15px rgba(239, 68, 68, 0.6); }
          33% { border-color: #22c55e; box-shadow: 0 0 15px rgba(34, 197, 94, 0.6); }
          66% { border-color: #3b82f6; box-shadow: 0 0 15px rgba(59, 130, 246, 0.6); }
          100% { border-color: #ef4444; box-shadow: 0 0 15px rgba(239, 68, 68, 0.6); }
        }
        .animate-rgb-flash {
          animation: rgb-flash 3s linear infinite;
        }
        .node-button {
          background: rgba(15, 23, 42, 0.85);
          border-width: 2px;
          backdrop-filter: blur(8px);
          transition: transform 0.1s ease-out, background-color 0.2s;
        }
        .node-button:hover {
          background: rgba(30, 41, 59, 0.95);
        }
        .node-delete-btn {
          opacity: 0;
          transition: opacity 0.2s;
        }
        .node-button:hover .node-delete-btn {
          opacity: 1;
        }
      `}</style>

      <Sidebar 
        nodes={nodes} 
        connections={connections}
        selectedNodeId={selectedNodeId}
        addNode={addNode}
        deleteNode={deleteNode}
        deleteConnection={deleteConnection}
        onAnalyze={handleAnalyze}
        isAnalyzing={isAnalyzing}
        analysisResult={analysisResult}
        onAutoLayout={handleAutoLayout}
      />

      <main className="flex-1 relative overflow-hidden bg-[radial-gradient(circle_at_center,_#1e293b_0%,_#020617_100%)]">
        <UIOverlay 
            mode={mode} 
            setMode={setMode} 
            connectSource={connectSourceId ? nodes.find(n => n.id === connectSourceId)?.name : null}
        />

        <Workspace 
          nodes={nodes} 
          connections={connections}
          selectedId={selectedNodeId}
          onNodeClick={handleNodeClick}
          onNodeMove={updateNodePosition}
          onDeleteNode={deleteNode}
          mode={mode}
        />

        {isAnalyzing && (
            <div className="absolute inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm">
                <div className="bg-slate-900 p-8 rounded-2xl shadow-2xl border border-sky-500/50 flex flex-col items-center">
                    <div className="w-16 h-16 border-4 border-sky-500 border-t-transparent rounded-full animate-spin mb-4"></div>
                    <h3 className="text-xl font-bold text-sky-400">AI 正在分析拓扑结构...</h3>
                    <p className="text-slate-400 mt-2">正在评估节点关系、性能指标及架构健康度。</p>
                </div>
            </div>
        )}
      </main>
    </div>
  );
};

export default App;

import React, { useRef, useState, useCallback } from 'react';
import { ServiceNode, Connection } from '../types';
import { SERVICE_ICONS, SERVICE_COLORS } from '../constants';

interface WorkspaceProps {
  nodes: ServiceNode[];
  connections: Connection[];
  selectedId: string | null;
  onNodeClick: (id: string) => void;
  onNodeMove: (id: string, x: number, y: number) => void;
  onDeleteNode: (id: string) => void;
  mode: string;
}

const Workspace: React.FC<WorkspaceProps> = ({ 
  nodes, 
  connections, 
  selectedId, 
  onNodeClick, 
  onNodeMove, 
  onDeleteNode,
  mode 
}) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const [draggingId, setDraggingId] = useState<string | null>(null);

  const handleMouseMove = (e: React.MouseEvent) => {
    if (draggingId && containerRef.current && mode === 'select') {
      const rect = containerRef.current.getBoundingClientRect();
      const x = e.clientX - rect.left - 60; // Offset for node half-width
      const y = e.clientY - rect.top - 20; // Offset for node half-height
      onNodeMove(draggingId, x, y);
    }
  };

  const handleMouseUp = () => setDraggingId(null);

  const handleDelete = useCallback((e: React.MouseEvent, node: ServiceNode) => {
    e.stopPropagation();
    if (confirm(`确定要删除服务 "${node.name}" 吗？`)) {
      onDeleteNode(node.id);
    }
  }, [onDeleteNode]);

  return (
    <div 
      ref={containerRef}
      className="w-full h-full relative select-none"
      onMouseMove={handleMouseMove}
      onMouseUp={handleMouseUp}
      onMouseLeave={handleMouseUp}
    >
      {/* SVG Layer for Connections */}
      <svg className="absolute inset-0 w-full h-full pointer-events-none">
        <defs>
          <marker
            id="arrowhead"
            markerWidth="10"
            markerHeight="7"
            refX="10"
            refY="3.5"
            orient="auto"
          >
            <polygon points="0 0, 10 3.5, 0 7" fill="#38bdf8" />
          </marker>
        </defs>
        {connections.map((conn) => {
          const source = nodes.find(n => n.id === conn.sourceId);
          const target = nodes.find(n => n.id === conn.targetId);
          if (!source || !target) return null;

          const startX = source.position.x + 60;
          const startY = source.position.y + 20;
          const endX = target.position.x + 60;
          const endY = target.position.y + 20;

          return (
            <g key={conn.id}>
              <path
                d={`M ${startX} ${startY} Q ${(startX + endX) / 2} ${(startY + endY) / 2 - 50} ${endX} ${endY}`}
                stroke={conn.trafficLoad > 0.7 ? "#ef4444" : "#38bdf8"}
                strokeWidth="2"
                fill="none"
                strokeDasharray="5,5"
                markerEnd="url(#arrowhead)"
                className="opacity-60"
              />
              <circle r="4" fill="#7dd3fc">
                <animateMotion
                  dur={`${3 - conn.trafficLoad * 2}s`}
                  repeatCount="indefinite"
                  path={`M ${startX} ${startY} Q ${(startX + endX) / 2} ${(startY + endY) / 2 - 50} ${endX} ${endY}`}
                />
              </circle>
            </g>
          );
        })}
      </svg>

      {/* HTML Layer for Nodes */}
      {nodes.map((node) => {
        const isSelected = selectedId === node.id;
        const color = SERVICE_COLORS[node.type];

        return (
          <div
            key={node.id}
            style={{
              left: node.position.x,
              top: node.position.y,
              width: '120px',
              height: '40px',
            }}
            className={`absolute z-10 node-button rounded shadow-lg flex items-center justify-center cursor-pointer animate-rgb-flash ${
              isSelected ? 'ring-2 ring-sky-400' : ''
            }`}
            onClick={(e) => {
                e.stopPropagation();
                onNodeClick(node.id);
            }}
            onMouseDown={(e) => {
                if (mode === 'select') {
                    setDraggingId(node.id);
                }
            }}
          >
            <div className="flex items-center gap-2">
              <i className={`fas ${SERVICE_ICONS[node.type]} text-xs`} style={{ color }}></i>
              <span className="text-[10px] font-bold truncate max-w-[80px]">{node.name}</span>
            </div>

            {/* Direct Delete Button on Node */}
            <button
              className="node-delete-btn absolute -top-2 -right-2 w-5 h-5 bg-red-600 rounded-full flex items-center justify-center text-[8px] text-white shadow-md hover:bg-red-500 transition-colors border border-slate-900"
              onClick={(e) => handleDelete(e, node)}
              title="删除节点"
            >
              <i className="fas fa-times"></i>
            </button>

            {/* Status indicator */}
            <div className={`absolute -bottom-1 -right-1 w-2.5 h-2.5 rounded-full border-2 border-slate-900 ${
                node.status === 'online' ? 'bg-green-500' : node.status === 'warning' ? 'bg-yellow-500' : 'bg-red-500'
            }`} />
          </div>
        );
      })}
    </div>
  );
};

