            </div>

            {/* Delete Button */}
            <div
              className="absolute -top-3 -right-3 w-6 h-6 bg-red-600 hover:bg-red-400 rounded-full flex items-center justify-center text-[10px] text-white shadow-2xl border-2 border-slate-900 z-20 cursor-pointer transition-all hover:scale-125"
