        .animate-flash-warning { animation: flash-warning 1.2s ease-in-out infinite; }
        .animate-flash-error { animation: flash-error 0.5s step-end infinite; }

        .node-button {
          border-width: 2px;
          backdrop-filter: blur(8px);
          transition: transform 0.1s ease-out;
        }

        .node-button:hover {
          filter: brightness(1.2);
