import React, { useRef, useState, useCallback } from 'react';
import { ServiceNode, Connection } from '../types';
import { SERVICE_ICONS, SERVICE_COLORS } from '../constants';

interface WorkspaceProps {
  nodes: ServiceNode[];
  connections: Connection[];
  selectedId: string | null;
  onNodeClick: (id: string) => void;
  onNodeMove: (id: string, x: number, y: number) => void;
  onDeleteNode: (id: string) => void;
  mode: string;
}

const Workspace: React.FC<WorkspaceProps> = ({ 
  nodes, 
  connections, 
  selectedId, 
  onNodeClick, 
  onNodeMove, 
  onDeleteNode,
  mode 
}) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const [draggingId, setDraggingId] = useState<string | null>(null);

  const handleMouseMove = (e: React.MouseEvent) => {
    if (draggingId && containerRef.current && mode === 'select') {
      const rect = containerRef.current.getBoundingClientRect();
      const x = e.clientX - rect.left - 60;
      const y = e.clientY - rect.top - 20;
      onNodeMove(draggingId, x, y);
    }
  };

  const handleMouseUp = () => setDraggingId(null);

  const handleDeleteNode = (e: React.MouseEvent, id: string) => {
    e.preventDefault();
    e.stopPropagation();
    onDeleteNode(id);
  };

  // 映射状态到纯色闪缩类名
  const getStrobeClass = (status: string) => {
    switch(status) {
      case 'online': return 'animate-strobe-green';
      case 'warning': return 'animate-strobe-yellow';
      case 'error': return 'animate-strobe-red';
      default: return 'animate-strobe-green';
    }
  };

  return (
    <div 
      ref={containerRef}
      className="w-full h-full relative select-none"
      onMouseMove={handleMouseMove}
      onMouseUp={handleMouseUp}
      onMouseLeave={handleMouseUp}
    >
      {/* SVG Connections Layer */}
      <svg className="absolute inset-0 w-full h-full pointer-events-none">
        <defs>
          <marker id="arrowhead" markerWidth="10" markerHeight="7" refX="10" refY="3.5" orient="auto">
            <polygon points="0 0, 10 3.5, 0 7" fill="#38bdf8" />
          </marker>
        </defs>
        {connections.map((conn) => {
          const source = nodes.find(n => n.id === conn.sourceId);
          const target = nodes.find(n => n.id === conn.targetId);
          if (!source || !target) return null;

          const startX = source.position.x + 60;
          const startY = source.position.y + 20;
          const endX = target.position.x + 60;
          const endY = target.position.y + 20;

          return (
            <g key={conn.id}>
              <path
                d={`M ${startX} ${startY} Q ${(startX + endX) / 2} ${(startY + endY) / 2 - 40} ${endX} ${endY}`}
                stroke={conn.trafficLoad > 0.7 ? "#ef4444" : "#38bdf8"}
                strokeWidth="2"
                fill="none"
                strokeDasharray="4,4"
                markerEnd="url(#arrowhead)"
                className="opacity-25"
              />
              <circle r="2.5" fill="#7dd3fc">
                <animateMotion
                  dur={`${3 - conn.trafficLoad * 2.5}s`}
                  repeatCount="indefinite"
                  path={`M ${startX} ${startY} Q ${(startX + endX) / 2} ${(startY + endY) / 2 - 40} ${endX} ${endY}`}
                />
              </circle>
            </g>
          );
        })}
      </svg>

      {/* Nodes Layer */}
      {nodes.map((node) => {
        const isSelected = selectedId === node.id;

        return (
          <div
            key={node.id}
            style={{
              left: node.position.x,
              top: node.position.y,
              width: '120px',
              height: '40px',
            }}
            className={`absolute z-10 node-button rounded-lg shadow-2xl flex items-center justify-center cursor-pointer transition-transform ${getStrobeClass(node.status)} ${
              isSelected ? 'ring-4 ring-white/60 scale-110 z-20' : ''
            }`}
            onClick={(e) => {
                e.stopPropagation();
                onNodeClick(node.id);
            }}
            onMouseDown={(e) => {
                if (mode === 'select') {
                    setDraggingId(node.id);
                }
            }}
          >
            <div className="flex items-center gap-2 pointer-events-none px-2">
              <i className={`fas ${SERVICE_ICONS[node.type]} text-xs text-white`}></i>
              <span className="text-[10px] font-black text-white uppercase tracking-tighter truncate max-w-[80px]">
                {node.name}
              </span>
            </div>

            {/* Delete Button */}
            <div
              className="absolute -top-3 -right-3 w-6 h-6 bg-slate-900 border-2 border-slate-700 hover:bg-red-600 hover:border-red-400 rounded-full flex items-center justify-center text-[10px] text-white shadow-xl z-30 cursor-pointer transition-all node-delete-btn"
              onClick={(e) => handleDeleteNode(e, node.id)}
              title="删除此服务"
            >
              <i className="fas fa-times"></i>
            </div>

            {/* Bottom Status Pill */}
            <div className={`absolute -bottom-2 px-1.5 rounded-full border border-slate-900 text-[7px] font-black text-white shadow-md ${
                node.status === 'online' ? 'bg-green-600' : node.status === 'warning' ? 'bg-yellow-600' : 'bg-red-600'
            }`}>
              {node.status.toUpperCase()}
            </div>
          </div>
        );
      })}
    </div>
  );
};

export default Workspace;

