              <button onClick={() => deleteNode(selectedNode.id)} className="w-full mt-4 bg-red-600/20 text-red-400 py-2 rounded-lg text-[10px] font-bold">注销资源</button>
            </div>
          </section>
        )}
      </div>
    </aside>
  );
};

