import React, { useRef, useState } from 'react';
import { ServiceNode, Connection, GroupNode } from '../types';
import { SERVICE_ICONS } from '../constants';

interface WorkspaceProps {
  nodes: ServiceNode[];
  groups: GroupNode[];
  connections: Connection[];
  selectedId: string | null;
  onNodeClick: (id: string) => void;
  onNodeMove: (id: string, x: number, y: number) => void;
  onUpdateGroup: (id: string, updates: Partial<GroupNode>) => void;
  onDeleteGroup: (id: string) => void;
  onDeleteNode: (id: string) => void;
  mode: string;
}

const Workspace: React.FC<WorkspaceProps> = ({ 
  nodes, 
  groups,
  connections, 
  selectedId, 
  onNodeClick, 
  onNodeMove, 
  onUpdateGroup,
  onDeleteGroup,
  onDeleteNode,
  mode 
}) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const [draggingId, setDraggingId] = useState<string | null>(null);
  const [resizingId, setResizingId] = useState<string | null>(null);
  const [dragType, setDragType] = useState<'node' | 'group' | 'resize'>('node');

  const handleMouseMove = (e: React.MouseEvent) => {
    if (!containerRef.current || mode !== 'select') return;
    const rect = containerRef.current.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;

    if (draggingId) {
      if (dragType === 'node') {
        onNodeMove(draggingId, x - 60, y - 20);
      } else if (dragType === 'group') {
        onUpdateGroup(draggingId, { position: { x: x - 50, y: y - 20 } });
      }
    } else if (resizingId) {
      const group = groups.find(g => g.id === resizingId);
      if (group) {
        const newWidth = Math.max(100, x - group.position.x);
        const newHeight = Math.max(100, y - group.position.y);
        onUpdateGroup(resizingId, { size: { width: newWidth, height: newHeight } });
      }
    }
  };

  const handleMouseUp = () => {
    setDraggingId(null);
    setResizingId(null);
  };

  const getStrobeClass = (status: string) => {
    switch(status) {
      case 'online': return 'animate-strobe-green';
      case 'warning': return 'animate-strobe-yellow';
      case 'error': return 'animate-strobe-red';
      default: return 'animate-strobe-green';
    }
  };

  const getStatusConfig = (status: string) => {
    switch(status) {
      case 'online': return { text: '● 在线', color: 'text-emerald-400', border: 'border-emerald-500/30' };
      case 'warning': return { text: '▲ 警告', color: 'text-amber-400', border: 'border-amber-500/30' };
      case 'error': return { text: '✖ 故障', color: 'text-rose-400', border: 'border-rose-500/30' };
      default: return { text: '● 在线', color: 'text-emerald-400', border: 'border-emerald-500/30' };
    }
  };

  return (
    <div 
      ref={containerRef}
      className="w-full h-full relative select-none"
      onMouseMove={handleMouseMove}
      onMouseUp={handleMouseUp}
      onMouseLeave={handleMouseUp}
    >
      {/* 1. Containers (Groups) Layer - Bottom */}
      {groups.map((group) => {
        const statusConfig = getStatusConfig(group.status);
        return (
          <div
            key={group.id}
            style={{
              left: group.position.x,
              top: group.position.y,
              width: group.size.width,
              height: group.size.height,
            }}
            className={`absolute rounded-3xl border-2 border-dashed bg-slate-900/40 backdrop-blur-sm z-0 group/container flex flex-col items-center ${getStrobeClass(group.status)} transition-all`}
            onMouseDown={(e) => {
              if (mode === 'select') {
                 setDraggingId(group.id);
                 setDragType('group');
              }
            }}
          >
            {/* Header */}
            <div className="absolute top-4 left-6 flex items-center gap-2 pointer-events-none">
              <i className="fas fa-cubes text-[10px] text-slate-400"></i>
              <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{group.name}</span>
            </div>

            {/* Integrated Status Label for Container - Similar to Nodes */}
            <div className={`absolute -bottom-2 left-1/2 -translate-x-1/2 px-3 py-1 rounded-full text-[8px] font-black bg-slate-950 border ${statusConfig.border} backdrop-blur-md shadow-2xl transition-transform ${statusConfig.color} tracking-[0.2em] uppercase whitespace-nowrap z-20`}>
              {statusConfig.text} CONTAINER
            </div>

            {/* Resize Handle */}
            <div 
              className="absolute bottom-1 right-1 w-8 h-8 flex items-center justify-center cursor-nwse-resize hover:bg-white/10 rounded-tl-xl rounded-br-2xl transition-colors z-30"
              onMouseDown={(e) => {
                e.stopPropagation();
                setResizingId(group.id);
                setDragType('resize');
              }}
            >
              <i className="fas fa-expand-arrows-alt text-slate-500 text-xs opacity-40 group-hover/container:opacity-100"></i>
            </div>

            {/* Delete Group */}
            <div 
              className="absolute top-3 right-3 w-6 h-6 rounded-full bg-slate-800/50 flex items-center justify-center text-[10px] text-slate-500 opacity-0 group-hover/container:opacity-100 cursor-pointer hover:bg-red-500/20 hover:text-red-400"
              onClick={(e) => { e.stopPropagation(); onDeleteGroup(group.id); }}
            >
              <i className="fas fa-trash"></i>
            </div>
          </div>
        );
      })}

      {/* 2. Connections Layer */}
      <svg className="absolute inset-0 w-full h-full pointer-events-none z-[5]">
        <defs>
          <marker id="arrowhead" markerWidth="10" markerHeight="7" refX="10" refY="3.5" orient="auto">
            <polygon points="0 0, 10 3.5, 0 7" fill="#38bdf8" />
          </marker>
        </defs>
        {connections.map((conn) => {
          const source = nodes.find(n => n.id === conn.sourceId);
          const target = nodes.find(n => n.id === conn.targetId);
          if (!source || !target) return null;
          const startX = source.position.x + 60;
          const startY = source.position.y + 20;
          const endX = target.position.x + 60;
          const endY = target.position.y + 20;
          return (
            <g key={conn.id}>
              <path d={`M ${startX} ${startY} L ${endX} ${endY}`} stroke="#38bdf8" strokeWidth="2" strokeDasharray="4,4" markerEnd="url(#arrowhead)" className="opacity-30" />
              <circle r="2.5" fill="#7dd3fc">
                <animateMotion dur="2s" repeatCount="indefinite" path={`M ${startX} ${startY} L ${endX} ${endY}`} />
              </circle>
            </g>
          );
        })}
      </svg>

      {/* 3. Service Nodes Layer - Top */}
      {nodes.map((node) => {
        const isSelected = selectedId === node.id;
        const statusConfig = getStatusConfig(node.status);

        return (
          <div
            key={node.id}
            style={{
              left: node.position.x,
              top: node.position.y,
              width: '120px',
              height: '40px',
            }}
            className="absolute z-10 flex flex-col items-center group/node"
          >
            <div
              className={`w-full h-full node-button rounded-lg shadow-2xl flex items-center justify-center cursor-pointer relative ${getStrobeClass(node.status)} ${
                isSelected ? 'ring-4 ring-white/60 scale-105 z-20' : ''
              }`}
              onClick={(e) => { e.stopPropagation(); onNodeClick(node.id); }}
              onMouseDown={(e) => {
                if (mode === 'select') {
                  e.stopPropagation();
                  setDraggingId(node.id);
                  setDragType('node');
                }
              }}
            >
              <div className="flex items-center gap-2 pointer-events-none px-2 mb-1">
                <i className={`fas ${SERVICE_ICONS[node.type]} text-xs text-white`}></i>
                <span className="text-[10px] font-black text-white uppercase tracking-tighter truncate">{node.name}</span>
              </div>

              <div className="absolute -top-2 -right-2 w-5 h-5 bg-slate-900 border border-slate-700 hover:bg-red-600 rounded-full flex items-center justify-center text-[8px] text-white z-30 transition-all shadow-lg opacity-0 group-hover/node:opacity-100"
                onClick={(e) => { e.stopPropagation(); onDeleteNode(node.id); }}>
                <i className="fas fa-times"></i>
              </div>

              <div className={`absolute -bottom-2 left-1/2 -translate-x-1/2 px-2 py-0.5 rounded-full text-[7px] font-black bg-slate-950 border ${statusConfig.border} backdrop-blur-md shadow-xl transition-transform ${statusConfig.color} tracking-[0.2em] uppercase whitespace-nowrap z-20`}>
                {statusConfig.text}
              </div>
            </div>
          </div>
        );
      })}
    </div>
  );
};

export default Workspace;

import React, { useState, useCallback } from 'react';
import Sidebar from './components/Sidebar';
import UIOverlay from './components/UIOverlay';
import Workspace from './components/Workspace';
import { ServiceNode, Connection, ServiceType, GroupNode } from './types';
import { analyzeTopology, suggestLayout } from './geminiService';

const App: React.FC = () => {
  const [nodes, setNodes] = useState<ServiceNode[]>([
    { id: '1', name: '用户网关', type: ServiceType.GATEWAY, position: { x: 150, y: 250, z: 0 }, status: 'online', lastUpdated: new Date().toISOString() },
    { id: '2', name: '认证服务', type: ServiceType.SERVER, position: { x: 450, y: 200, z: 0 }, status: 'online', lastUpdated: new Date().toISOString() },
    { id: '3', name: '产品数据库', type: ServiceType.DATABASE, position: { x: 750, y: 350, z: 0 }, status: 'warning', lastUpdated: new Date().toISOString() },
  ]);

  const [groups, setGroups] = useState<GroupNode[]>([
    { id: 'g1', name: '生产集群-A', position: { x: 100, y: 150 }, size: { width: 500, height: 250 }, color: '#38bdf8', status: 'online' }
  ]);

  const [connections, setConnections] = useState<Connection[]>([
    { id: 'c1', sourceId: '1', targetId: '2', label: 'HTTP 认证', trafficLoad: 0.4 },
    { id: 'c2', sourceId: '2', targetId: '3', label: 'SQL 查询', trafficLoad: 0.8 },
  ]);

  const [selectedNodeId, setSelectedNodeId] = useState<string | null>(null);
  const [mode, setMode] = useState<'select' | 'add' | 'connect'>('select');
  const [connectSourceId, setConnectSourceId] = useState<string | null>(null);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [analysisResult, setAnalysisResult] = useState<any>(null);

  const addNode = useCallback((type: ServiceType, name: string) => {
    const newNode: ServiceNode = {
      id: `node-${Date.now()}`,
      name,
      type,
      position: { x: 200, y: 200, z: 0 },
      status: 'online',
      lastUpdated: new Date().toISOString()
    };
    setNodes(prev => [...prev, newNode]);
  }, []);

  const addGroup = useCallback((name: string, status: 'online' | 'warning' | 'error' = 'online') => {
    const newGroup: GroupNode = {
      id: `group-${Date.now()}`,
      name,
      position: { x: 200, y: 200 },
      size: { width: 300, height: 200 },
      color: '#818cf8',
      status: status
    };
    setGroups(prev => [...prev, newGroup]);
  }, []);

  const updateGroup = useCallback((id: string, updates: Partial<GroupNode>) => {
    setGroups(prev => prev.map(g => g.id === id ? { ...g, ...updates } : g));
  }, []);

  const deleteGroup = useCallback((id: string) => {
    setGroups(prev => prev.filter(g => g.id !== id));
    setConnections(prev => prev.filter(c => c.sourceId !== id && c.targetId !== id));
  }, []);

  const deleteNode = useCallback((id: string) => {
    setNodes(prev => prev.filter(n => n.id !== id));
    setConnections(prev => prev.filter(c => c.sourceId !== id && c.targetId !== id));
    setSelectedNodeId(null);
  }, []);

  // 核心逻辑：处理节点或容器的交互（点击）
  const handleElementInteraction = useCallback((id: string) => {
    if (mode === 'connect') {
      if (!connectSourceId) {
        setConnectSourceId(id);
      } else if (connectSourceId !== id) {
        setConnections(prev => [...prev, {
          id: `c-${Date.now()}`,
          sourceId: connectSourceId,
          targetId: id,
          label: '新链路',
          trafficLoad: 0.2
        }]);
        setConnectSourceId(null);
        setMode('select');
      }
    } else {
      setSelectedNodeId(id === selectedNodeId ? null : id);
    }
  }, [mode, connectSourceId, selectedNodeId]);

  const updateNodePosition = useCallback((id: string, x: number, y: number) => {
    setNodes(prev => prev.map(n => n.id === id ? { ...n, position: { ...n.position, x, y } } : n));
  }, []);

  const handleAnalyze = async () => {
    if (nodes.length === 0) return;
    setIsAnalyzing(true);
    const result = await analyzeTopology(nodes, connections);
    setAnalysisResult(result);
    setIsAnalyzing(false);
  };

  const handleAutoLayout = async (desc: string) => {
    if (!desc) return;
    setIsAnalyzing(true);
    try {
        const layout = await suggestLayout(desc);
        const newNodes: ServiceNode[] = layout.nodes.map((n: any, i: number) => ({
            id: `ai-node-${i}-${Date.now()}`,
            name: n.name,
            type: n.type as ServiceType,
            position: { x: (n.x + 10) * 40, y: (n.y + 10) * 30, z: 0 },
            status: 'online',
            lastUpdated: new Date().toISOString()
        }));

        const newConns: Connection[] = layout.connections.map((c: any, i: number) => ({
            id: `ai-conn-${i}-${Date.now()}`,
            sourceId: newNodes[c.sourceIndex].id,
            targetId: newNodes[c.targetIndex].id,
            label: c.label,
            trafficLoad: Math.random() * 0.5
        }));

        setNodes(newNodes);
        setConnections(newConns);
    } catch (e) {
        console.error("AI Layout failed", e);
    }
    setIsAnalyzing(false);
  };

  const getActiveSourceLabel = () => {
    if (!connectSourceId) return null;
    const node = nodes.find(n => n.id === connectSourceId);
    if (node) return node.name;
    const group = groups.find(g => g.id === connectSourceId);
    if (group) return group.name;
    return "未知节点";
  };

  return (
    <div className="flex h-screen w-screen bg-slate-950 text-slate-100 overflow-hidden font-sans">
      <style>{`
        @keyframes strobe-green {
          0%, 100% { background-color: rgba(34, 197, 94, 0.15); box-shadow: 0 0 15px rgba(34, 197, 94, 0.2); border-color: rgba(34, 197, 94, 0.6); }
          50% { background-color: rgba(34, 197, 94, 0.02); box-shadow: 0 0 5px rgba(34, 197, 94, 0.05); border-color: rgba(34, 197, 94, 0.2); }
        }
        @keyframes strobe-yellow {
          0%, 100% { background-color: rgba(234, 179, 8, 0.3); box-shadow: 0 0 20px rgba(234, 179, 8, 0.4); border-color: rgba(234, 179, 8, 0.8); }
          50% { background-color: rgba(234, 179, 8, 0.05); box-shadow: 0 0 8px rgba(234, 179, 8, 0.1); border-color: rgba(234, 179, 8, 0.2); }
        }
        @keyframes strobe-red {
          0%, 100% { background-color: rgba(239, 68, 68, 0.4); box-shadow: 0 0 25px rgba(239, 68, 68, 0.5); border-color: rgba(239, 68, 68, 0.8); }
          50% { background-color: rgba(239, 68, 68, 0.05); box-shadow: 0 0 10px rgba(239, 68, 68, 0.1); border-color: rgba(239, 68, 68, 0.3); }
        }
        .animate-strobe-green { animation: strobe-green 3s ease-in-out infinite; }
        .animate-strobe-yellow { animation: strobe-yellow 1s ease-in-out infinite; }
        .animate-strobe-red { animation: strobe-red 0.4s cubic-bezier(0.4, 0, 0.2, 1) infinite; }
        .node-button { border-width: 2px; backdrop-filter: blur(12px); transition: transform 0.1s ease-out, filter 0.2s; }
        .node-button:hover { filter: brightness(1.25); z-index: 50; }
        .resize-handle { cursor: nwse-resize; }
      `}</style>

      <Sidebar 
        nodes={nodes} 
        connections={connections}
        selectedNodeId={selectedNodeId}
        addNode={addNode}
        addGroup={addGroup}
        deleteNode={deleteNode}
        deleteConnection={() => {}}
        onAnalyze={handleAnalyze}
        isAnalyzing={isAnalyzing}
        analysisResult={analysisResult}
        onAutoLayout={handleAutoLayout}
      />

      <main className="flex-1 relative overflow-hidden bg-[radial-gradient(circle_at_center,_#1e293b_0%,_#020617_100%)]">
        <UIOverlay 
            mode={mode} 
            setMode={setMode} 
            connectSource={getActiveSourceLabel()}
        />

        <Workspace 
          nodes={nodes} 
          groups={groups}
          connections={connections}
          selectedId={selectedNodeId}
          onElementClick={handleElementInteraction}
          onNodeMove={updateNodePosition}
          onUpdateGroup={updateGroup}
          onDeleteGroup={deleteGroup}
          onDeleteNode={deleteNode}
          mode={mode}
        />

        {isAnalyzing && (
            <div className="absolute inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-md">
                <div className="bg-slate-900 p-8 rounded-2xl shadow-2xl border border-sky-500/50 flex flex-col items-center">
