import React, { useRef, useState, useMemo, useEffect } from 'react';
import { ServiceNode, Connection, GroupNode } from '../types';
import { SERVICE_ICONS } from '../constants';

interface WorkspaceProps {
  nodes: ServiceNode[];
  groups: GroupNode[];
  connections: Connection[];
  selectedId: string | null;
  onElementClick: (id: string) => void;
  onNodeMove: (id: string, x: number, y: number) => void;
  onUpdateGroup: (id: string, updates: Partial<GroupNode>) => void;
  onDeleteGroup: (id: string) => void;
  onDeleteNode: (id: string) => void;
  mode: string;
  isLocked: boolean;
}

const Workspace: React.FC<WorkspaceProps> = ({ 
  nodes, 
  groups,
  connections, 
  selectedId, 
  onElementClick, 
  onNodeMove, 
  onUpdateGroup,
  onDeleteGroup,
  onDeleteNode,
  mode,
  isLocked
}) => {
  const containerRef = useRef<HTMLDivElement>(null);

  // 视野偏移状态 (Panning)
  const [viewOffset, setViewOffset] = useState({ x: 0, y: 0 });
  const [isPanning, setIsPanning] = useState(false);
  // Fix: Initialized lastMousePos with default values { x: 0, y: 0 } as 'e' is not defined during state initialization
  const [lastMousePos, setLastMousePos] = useState({ x: 0, y: 0 });

  const [draggingId, setDraggingId] = useState<string | null>(null);
  const [resizingId, setResizingId] = useState<string | null>(null);
  const [dragType, setDragType] = useState<'node' | 'group' | 'resize' | 'scroll-h' | 'scroll-v'>('node');

  // 计算内容边界和滚动范围
  const contentBounds = useMemo(() => {
    if (nodes.length === 0 && groups.length === 0) {
      return { minX: 0, maxX: 1000, minY: 0, maxY: 1000 };
    }

    let minX = Infinity, maxX = -Infinity, minY = Infinity, maxY = -Infinity;

    nodes.forEach(n => {
      minX = Math.min(minX, n.position.x);
      maxX = Math.max(maxX, n.position.x + 120);
      minY = Math.min(minY, n.position.y);
      maxY = Math.max(maxY, n.position.y + 40);
    });

    groups.forEach(g => {
      minX = Math.min(minX, g.position.x);
      maxX = Math.max(maxX, g.position.x + g.size.width);
      minY = Math.min(minY, g.position.y);
      maxY = Math.max(maxY, g.position.y + g.size.height);
    });

    const margin = 500;
    return {
      minX: Math.min(0, minX - margin),
      maxX: Math.max(window.innerWidth, maxX + margin),
      minY: Math.min(0, minY - margin),
      maxY: Math.max(window.innerHeight, maxY + margin)
    };
  }, [nodes, groups]);

  const handleMouseDown = (e: React.MouseEvent) => {
    if (!containerRef.current) return;
    if (e.target === containerRef.current) {
      setIsPanning(true);
      setLastMousePos({ x: e.clientX, y: e.clientY });
    }
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (!containerRef.current) return;

    if (isPanning) {
      const dx = e.clientX - lastMousePos.x;
      const dy = e.clientY - lastMousePos.y;
      setViewOffset(prev => ({ x: prev.x + dx, y: prev.y + dy }));
      setLastMousePos({ x: e.clientX, y: e.clientY });
      return;
    }

    if (draggingId === 'scrollbar-h' || draggingId === 'scrollbar-v') {
        const rect = containerRef.current.getBoundingClientRect();
        const contentWidth = contentBounds.maxX - contentBounds.minX;
        const contentHeight = contentBounds.maxY - contentBounds.minY;

        if (draggingId === 'scrollbar-h') {
            const ratio = (e.clientX - rect.left) / rect.width;
            const targetX = contentBounds.minX + ratio * contentWidth - rect.width / 2;
            setViewOffset(prev => ({ ...prev, x: -targetX }));
        } else {
            const ratio = (e.clientY - rect.top) / rect.height;
            const targetY = contentBounds.minY + ratio * contentHeight - rect.height / 2;
            setViewOffset(prev => ({ ...prev, y: -targetY }));
        }
        return;
    }

    if (mode !== 'select' || isLocked) return;

    const rect = containerRef.current.getBoundingClientRect();
    const x = e.clientX - rect.left - viewOffset.x;
    const y = e.clientY - rect.top - viewOffset.y;

    if (draggingId && dragType === 'node') {
      onNodeMove(draggingId, x - 60, y - 20);
    } else if (draggingId && dragType === 'group') {
      onUpdateGroup(draggingId, { position: { x: x - (groups.find(g => g.id === draggingId)?.size.width || 0) / 2, y: y - 20 } });
    } else if (resizingId) {
      const group = groups.find(g => g.id === resizingId);
      if (group) {
        const newWidth = Math.max(200, x - group.position.x);
        const newHeight = Math.max(150, y - group.position.y);
        onUpdateGroup(resizingId, { size: { width: newWidth, height: newHeight } });
      }
    }
  };

  const handleMouseUp = () => {
    setIsPanning(false);
    setDraggingId(null);
    setResizingId(null);
  };

  const scrollMetrics = useMemo(() => {
    if (!containerRef.current) return { hThumb: { left: 0, width: 0 }, vThumb: { top: 0, height: 0 } };
    const viewWidth = window.innerWidth - 320;
    const viewHeight = window.innerHeight;
    const contentWidth = contentBounds.maxX - contentBounds.minX;
    const contentHeight = contentBounds.maxY - contentBounds.minY;
    const hRatio = viewWidth / contentWidth;
    const hThumbWidth = Math.max(40, viewWidth * hRatio);
    const hProgress = (-viewOffset.x - contentBounds.minX) / (contentWidth - viewWidth);
    const vRatio = viewHeight / contentHeight;
    const vThumbHeight = Math.max(40, viewHeight * vRatio);
    const vProgress = (-viewOffset.y - contentBounds.minY) / (contentHeight - viewHeight);
    return {
        hThumb: { left: Math.max(0, Math.min(viewWidth - hThumbWidth, hProgress * (viewWidth - hThumbWidth))), width: hThumbWidth },
        vThumb: { top: Math.max(0, Math.min(viewHeight - vThumbHeight, vProgress * (viewHeight - vThumbHeight))), height: vThumbHeight }
    };
  }, [viewOffset, contentBounds]);

  const getStrobeClass = (status: string) => {
    switch(status) {
      case 'online': return 'animate-strobe-green';
      case 'warning': return 'animate-strobe-yellow';
      case 'error': return 'animate-strobe-red';
      default: return 'animate-strobe-green';
    }
  };

  const getStatusConfig = (status: string) => {
    switch(status) {
      case 'online': return { text: '运行', color: 'text-emerald-400', border: 'border-emerald-500/50', glow: 'shadow-[inset_0_0_20px_rgba(52,211,153,0.1)]' };
      case 'warning': return { text: '警告', color: 'text-amber-400', border: 'border-amber-500/50', glow: 'shadow-[inset_0_0_20px_rgba(251,191,36,0.1)]' };
      case 'error': return { text: '故障', color: 'text-rose-400', border: 'border-rose-500/50', glow: 'shadow-[inset_0_0_20px_rgba(244,63,94,0.15)]' };
      default: return { text: '运行', color: 'text-emerald-400', border: 'border-emerald-500/50', glow: 'shadow-[inset_0_0_20px_rgba(52,211,153,0.1)]' };
    }
  };

  const getElementInfo = (id: string) => {
    const node = nodes.find(n => n.id === id);
    if (node) return { x: node.position.x, y: node.position.y, w: 120, h: 40, cx: node.position.x + 60, cy: node.position.y + 20, isGroup: false };
    const group = groups.find(g => g.id === id);
    if (group) return { x: group.position.x, y: group.position.y, w: group.size.width, h: group.size.height, cx: group.position.x + group.size.width / 2, cy: group.position.y + group.size.height / 2, isGroup: true };
    return null;
  };

  const getConnectionPoint = (sourceId: string, targetId: string) => {
    const s = getElementInfo(sourceId);
    const t = getElementInfo(targetId);
    if (!s || !t) return null;
    const getIntersection = (rect: any, otherCenter: {x: number, y: number}) => {
      if (!rect.isGroup) return { x: rect.cx, y: rect.cy };
      const dx = otherCenter.x - rect.cx;
      const dy = otherCenter.y - rect.cy;
      const hw = rect.w / 2;
      const hh = rect.h / 2;
      const scale = Math.min(dx !== 0 ? Math.abs(hw / dx) : Infinity, dy !== 0 ? Math.abs(hh / dy) : Infinity);
      return { x: rect.cx + dx * scale, y: rect.cy + dy * scale };
    };
    return { start: getIntersection(s, { x: t.cx, y: t.cy }), end: getIntersection(t, { x: s.cx, y: s.cy }) };
  };

  const gridBackground = useMemo(() => ({
    backgroundImage: `
      linear-gradient(to right, rgba(14, 165, 233, 0.05) 1px, transparent 1px),
      linear-gradient(to bottom, rgba(14, 165, 233, 0.05) 1px, transparent 1px),
      linear-gradient(to right, rgba(14, 165, 233, 0.02) 1px, transparent 1px),
      linear-gradient(to bottom, rgba(14, 165, 233, 0.02) 1px, transparent 1px)
    `,
    backgroundSize: '100px 100px, 100px 100px, 20px 20px, 20px 20px',
    backgroundPosition: `${viewOffset.x}px ${viewOffset.y}px`
  }), [viewOffset]);

  return (
    <div 
      ref={containerRef}
      style={gridBackground}
      className={`w-full h-full relative select-none transition-colors overflow-hidden ${isPanning ? 'cursor-grabbing' : 'cursor-default'}`}
      onMouseDown={handleMouseDown}
      onMouseMove={handleMouseMove}
      onMouseUp={handleMouseUp}
      onMouseLeave={handleMouseUp}
    >
      <div 
        style={{ 
          transform: `translate(${viewOffset.x}px, ${viewOffset.y}px)`,
          position: 'absolute',
          inset: 0,
          pointerEvents: 'none'
        }}
      >
        {/* 容器层 (Groups) */}
        {groups.map((group) => {
          const statusConfig = getStatusConfig(group.status);
          const strobeClass = getStrobeClass(group.status);

          return (
            <div
              key={group.id}
              style={{
                left: group.position.x,
                top: group.position.y,
                width: group.size.width,
                height: group.size.height,
                pointerEvents: 'auto'
              }}
              className={`absolute group/container z-0 transition-all ${
                isLocked ? 'pointer-events-auto' : 'cursor-move'
              }`}
              onMouseDown={(e) => {
                if (mode === 'select' && !isLocked) {
                   e.stopPropagation();
                   setDraggingId(group.id);
                   setDragType('group');
                }
              }}
            >
              {/* 背景与内部装饰 */}
              <div className={`absolute inset-0 rounded-2xl bg-slate-900/40 backdrop-blur-md border border-slate-700/30 overflow-hidden ${statusConfig.glow} ${strobeClass}`}>
                 {/* 内部微网格 */}
                 <div className="absolute inset-0 opacity-[0.03] pointer-events-none" style={{ backgroundImage: 'radial-gradient(#38bdf8 1px, transparent 0)', backgroundSize: '10px 10px' }}></div>
                 {/* 扫描线 */}
                 <div className="absolute inset-0 scan-effect bg-gradient-to-b from-transparent via-sky-500/5 to-transparent h-1/2 w-full"></div>
              </div>

              {/* L-型护角设计 */}
              <div className="absolute -top-[1px] -left-[1px] w-6 h-6 border-t-2 border-l-2 border-sky-400/60 rounded-tl-2xl pointer-events-none group-hover/container:scale-105 transition-transform duration-500"></div>
              <div className="absolute -top-[1px] -right-[1px] w-6 h-6 border-t-2 border-r-2 border-sky-400/60 rounded-tr-2xl pointer-events-none group-hover/container:scale-105 transition-transform duration-500"></div>
              <div className="absolute -bottom-[1px] -left-[1px] w-6 h-6 border-b-2 border-l-2 border-sky-400/60 rounded-bl-2xl pointer-events-none group-hover/container:scale-105 transition-transform duration-500"></div>
              <div className="absolute -bottom-[1px] -right-[1px] w-6 h-6 border-b-2 border-r-2 border-sky-400/60 rounded-br-2xl pointer-events-none group-hover/container:scale-105 transition-transform duration-500"></div>

              {/* 页眉 - 工业风格标题栏 */}
              <div className="absolute top-0 left-0 right-0 h-8 bg-slate-950/40 border-b border-slate-700/20 px-4 flex items-center justify-between pointer-events-none">
                <div className="flex items-center gap-3">
                  <div className={`w-1.5 h-1.5 rounded-full ${group.status === 'online' ? 'bg-emerald-500' : group.status === 'warning' ? 'bg-amber-500' : 'bg-rose-500'} animate-pulse`}></div>
                  <span className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">{group.name}</span>
                </div>
                <div className="flex items-center gap-2">
                   <div className={`text-[8px] font-black px-2 py-0.5 rounded bg-slate-900 border ${statusConfig.border} ${statusConfig.color}`}>{statusConfig.text}</div>
                </div>
              </div>

              {/* 底部功能按钮 (仅未锁定时) */}
              {!isLocked && (
                <>
                  <div 
                    className="absolute -bottom-1 -right-1 w-8 h-8 flex items-center justify-center cursor-nwse-resize hover:bg-sky-500/20 rounded-tl-xl rounded-br-2xl transition-all z-30"
                    onMouseDown={(e) => { e.stopPropagation(); setResizingId(group.id); setDragType('resize'); }}
                  >
                    <i className="fas fa-expand-arrows-alt text-sky-400/40 text-xs"></i>
                  </div>
                  <div 
                    className="absolute -top-3 -right-3 w-7 h-7 rounded-full bg-slate-950 border border-slate-800 flex items-center justify-center text-[10px] text-slate-500 opacity-0 group-hover/container:opacity-100 cursor-pointer hover:bg-rose-500/20 hover:text-rose-400 shadow-xl transition-all hover:scale-110 z-30"
                    onClick={(e) => { e.stopPropagation(); onDeleteGroup(group.id); }}
                  >
                    <i className="fas fa-trash-alt"></i>
                  </div>
                </>
              )}
            </div>
          );
        })}

        {/* 连线层 */}
        <svg className="absolute inset-0 w-full h-full pointer-events-none z-[5]">
          <defs>
             <filter id="glow">
                <feGaussianBlur stdDeviation="2.5" result="coloredBlur"/>
                <feMerge>
                    <feMergeNode in="coloredBlur"/>
                    <feMergeNode in="SourceGraphic"/>
                </feMerge>
             </filter>
          </defs>
          {connections.map((conn) => {
            const points = getConnectionPoint(conn.sourceId, conn.targetId);
            if (!points) return null;
            const { start, end } = points;
            const isCritical = nodes.find(n => n.id === conn.targetId)?.status === 'error';

            return (
              <g key={conn.id}>
                {/* 基础链路 */}
                <path d={`M ${start.x} ${start.y} L ${end.x} ${end.y}`} stroke="#334155" strokeWidth="1" strokeDasharray="4,4" className="opacity-40" />

                {/* 心跳脉冲路径 */}
                <path 
                  d={`M ${start.x} ${start.y} L ${end.x} ${end.y}`} 
                  stroke={isCritical ? "#f43f5e" : "#0ea5e9"} 
                  strokeWidth="2.5" 
                  filter="url(#glow)"
                  className="connection-heartbeat opacity-80" 
                  style={{ 
                    animationDuration: `${3 - conn.trafficLoad * 2}s` 
                  }}
                />
              </g>
            );
          })}
        </svg>

        {/* 节点层 */}
        {nodes.map((node) => {
          const isSelected = selectedId === node.id;
          const statusConfig = getStatusConfig(node.status);
          return (
            <div
              key={node.id}
              style={{ left: node.position.x, top: node.position.y, width: '120px', height: '40px', pointerEvents: 'auto' }}
              className="absolute z-10 flex flex-col items-center group/node"
            >
              <div
                className={`w-full h-full node-button rounded-lg shadow-2xl flex items-center justify-center relative ${getStrobeClass(node.status)} ${
                  isSelected ? 'ring-4 ring-white/60 scale-105 z-20' : ''
                } ${isLocked ? 'cursor-default' : 'cursor-pointer hover:scale-105'}`}
                onClick={(e) => { e.stopPropagation(); onElementClick(node.id); }}
                onMouseDown={(e) => {
                  if (mode === 'select' && !isLocked) {
                    e.stopPropagation();
                    setDraggingId(node.id);
                    setDragType('node');
                  }
                }}
              >
                <div className="flex items-center gap-2 pointer-events-none px-2 mb-1">
                  <i className={`fas ${SERVICE_ICONS[node.type]} text-xs text-white`}></i>
                  <span className="text-[10px] font-black text-white uppercase tracking-tighter truncate">{node.name}</span>
                </div>
                {!isLocked && (
                  <div className="absolute -top-2 -right-2 w-5 h-5 bg-slate-950 border border-slate-800 hover:bg-rose-600 rounded-full flex items-center justify-center text-[8px] text-white z-30 transition-all shadow-lg opacity-0 group-hover/node:opacity-100 cursor-pointer"
                    onClick={(e) => { e.stopPropagation(); onDeleteNode(node.id); }}>
                    <i className="fas fa-times"></i>
                  </div>
                )}
                <div className={`absolute -bottom-2 left-1/2 -translate-x-1/2 px-2 py-0.5 rounded-full text-[7px] font-black bg-slate-950 border ${statusConfig.border} backdrop-blur-md shadow-xl transition-transform ${statusConfig.color} tracking-[0.2em] uppercase whitespace-nowrap z-20`}>
                  {statusConfig.text}
                </div>
              </div>
            </div>
          );
        })}
      </div>

      {/* 水平滚动条 */}
      <div className="absolute bottom-0 left-0 right-1 w-[calc(100%-4px)] h-1 px-1 group/scrollbar-h">
        <div className="w-full h-full bg-slate-800/30 rounded-full transition-all group-hover/scrollbar-h:h-2 group-hover/scrollbar-h:bg-slate-800/50">
           <div 
             className="h-full bg-sky-500/50 rounded-full cursor-pointer hover:bg-sky-400/80 transition-colors pointer-events-auto"
             style={{ position: 'absolute', left: `${scrollMetrics.hThumb.left}px`, width: `${scrollMetrics.hThumb.width}px` }}
             onMouseDown={(e) => { e.stopPropagation(); setDraggingId('scrollbar-h'); }}
           />
        </div>
      </div>

      {/* 垂直滚动条 */}
      <div className="absolute top-0 right-0 bottom-1 w-1 h-[calc(100%-4px)] py-1 group/scrollbar-v">
        <div className="w-full h-full bg-slate-800/30 rounded-full transition-all group-hover/scrollbar-v:w-2 group-hover/scrollbar-v:bg-slate-800/50">
           <div 
             className="w-full bg-sky-500/50 rounded-full cursor-pointer hover:bg-sky-400/80 transition-colors pointer-events-auto"
             style={{ position: 'absolute', top: `${scrollMetrics.vThumb.top}px`, height: `${scrollMetrics.vThumb.height}px` }}
             onMouseDown={(e) => { e.stopPropagation(); setDraggingId('scrollbar-v'); }}
           />
        </div>
      </div>

      <div className="absolute bottom-10 right-10 pointer-events-none opacity-40">
        <div className="flex flex-col items-end gap-1">
          <span className="text-[9px] font-black text-sky-500 uppercase tracking-tighter">View Offset: {Math.round(viewOffset.x)}, {Math.round(viewOffset.y)}</span>
          <span className="text-[8px] text-slate-500">使用边缘滚动条或拖拽背景导航</span>
        </div>
      </div>
    </div>
  );
};

export default Workspace;

import React, { useState, useCallback } from 'react';
import Sidebar from './components/Sidebar';
import UIOverlay from './components/UIOverlay';
import Workspace from './components/Workspace';
import { ServiceNode, Connection, ServiceType, GroupNode } from './types';
import { suggestLayout } from './geminiService';

const App: React.FC = () => {
  const [nodes, setNodes] = useState<ServiceNode[]>([
    { id: '1', name: '用户网关', type: ServiceType.GATEWAY, position: { x: 150, y: 250, z: 0 }, status: 'online', lastUpdated: new Date().toISOString() },
    { id: '2', name: '认证服务', type: ServiceType.SERVER, position: { x: 450, y: 200, z: 0 }, status: 'online', lastUpdated: new Date().toISOString() },
    { id: '3', name: '产品数据库', type: ServiceType.DATABASE, position: { x: 750, y: 350, z: 0 }, status: 'warning', lastUpdated: new Date().toISOString() },
  ]);

  const [groups, setGroups] = useState<GroupNode[]>([
    { id: 'g1', name: '生产集群-A', position: { x: 100, y: 150 }, size: { width: 500, height: 350 }, color: '#38bdf8', status: 'online' }
  ]);

  const [connections, setConnections] = useState<Connection[]>([
    { id: 'c1', sourceId: '1', targetId: '2', label: 'HTTP 认证', trafficLoad: 0.4 },
    { id: 'c2', sourceId: '2', targetId: '3', label: 'SQL 查询', trafficLoad: 0.8 },
  ]);

  const [selectedNodeId, setSelectedNodeId] = useState<string | null>(null);
  const [mode, setMode] = useState<'select' | 'add' | 'connect'>('select');
  const [isLocked, setIsLocked] = useState(false);
  const [connectSourceId, setConnectSourceId] = useState<string | null>(null);
  const [isAnalyzing, setIsAnalyzing] = useState(false);

  const addNode = useCallback((type: ServiceType, name: string, status: 'online' | 'warning' | 'error' = 'online') => {
    if (isLocked) return;
    const newNode: ServiceNode = {
      id: `node-${Date.now()}`,
      name,
      type,
      position: { x: 200, y: 200, z: 0 },
      status,
      lastUpdated: new Date().toISOString()
    };
    setNodes(prev => [...prev, newNode]);
  }, [isLocked]);

  const addGroup = useCallback((name: string, status: 'online' | 'warning' | 'error' = 'online') => {
    if (isLocked) return;
    const newGroup: GroupNode = {
      id: `group-${Date.now()}`,
      name,
      position: { x: 200, y: 200 },
      size: { width: 400, height: 300 },
      color: '#818cf8',
      status: status
    };
    setGroups(prev => [...prev, newGroup]);
  }, [isLocked]);

  const updateGroup = useCallback((id: string, updates: Partial<GroupNode>) => {
    if (isLocked) return;
    setGroups(prev => prev.map(g => g.id === id ? { ...g, ...updates } : g));
  }, [isLocked]);

  const deleteGroup = useCallback((id: string) => {
    if (isLocked) return;
    setGroups(prev => prev.filter(g => g.id !== id));
    setConnections(prev => prev.filter(c => c.sourceId !== id && c.targetId !== id));
  }, [isLocked]);

  const deleteNode = useCallback((id: string) => {
    if (isLocked) return;
    setNodes(prev => prev.filter(n => n.id !== id));
    setConnections(prev => prev.filter(c => c.sourceId !== id && c.targetId !== id));
    setSelectedNodeId(null);
  }, [isLocked]);

  const handleElementInteraction = useCallback((id: string) => {
    if (mode === 'connect' && !isLocked) {
      if (!connectSourceId) {
        setConnectSourceId(id);
      } else if (connectSourceId !== id) {
        setConnections(prev => [...prev, {
          id: `c-${Date.now()}`,
          sourceId: connectSourceId,
          targetId: id,
          label: '新链路',
          trafficLoad: 0.2
        }]);
        setConnectSourceId(null);
        setMode('select');
      }
    } else {
      setSelectedNodeId(id === selectedNodeId ? null : id);
    }
  }, [mode, connectSourceId, selectedNodeId, isLocked]);

  const updateNodePosition = useCallback((id: string, x: number, y: number) => {
    if (isLocked) return;
    setNodes(prev => prev.map(n => n.id === id ? { ...n, position: { ...n.position, x, y } } : n));
  }, [isLocked]);

  const handleAutoLayout = async (desc: string) => {
    if (!desc || isLocked) return;
    setIsAnalyzing(true);
    try {
        const layout = await suggestLayout(desc);
        const newNodes: ServiceNode[] = layout.nodes.map((n: any, i: number) => ({
            id: `ai-node-${i}-${Date.now()}`,
            name: n.name,
            type: n.type as ServiceType,
            position: { x: (n.x + 10) * 40, y: (n.y + 10) * 30, z: 0 },
            status: 'online',
            lastUpdated: new Date().toISOString()
        }));

        const newConns: Connection[] = layout.connections.map((c: any, i: number) => ({
            id: `ai-conn-${i}-${Date.now()}`,
            sourceId: newNodes[c.sourceIndex].id,
            targetId: newNodes[c.targetIndex].id,
            label: c.label,
            trafficLoad: Math.random() * 0.5
        }));

        setNodes(newNodes);
        setConnections(newConns);
    } catch (e) {
        console.error("AI Layout failed", e);
    }
    setIsAnalyzing(false);
  };

  const getActiveSourceLabel = () => {
    if (!connectSourceId) return null;
    const node = nodes.find(n => n.id === connectSourceId);
    if (node) return node.name;
    const group = groups.find(g => g.id === connectSourceId);
    if (group) return group.name;
    return "未知节点";
  };

  return (
    <div className="flex h-screen w-screen bg-slate-950 text-slate-100 overflow-hidden font-sans">
      <style>{`
        @keyframes strobe-green {
          0%, 100% { background-color: rgba(34, 197, 94, 0.08); box-shadow: 0 0 20px rgba(34, 197, 94, 0.1), inset 0 0 10px rgba(34, 197, 94, 0.05); border-color: rgba(34, 197, 94, 0.4); }
          50% { background-color: rgba(34, 197, 94, 0.02); box-shadow: 0 0 5px rgba(34, 197, 94, 0.02); border-color: rgba(34, 197, 94, 0.1); }
        }
        @keyframes strobe-yellow {
          0%, 100% { background-color: rgba(234, 179, 8, 0.15); box-shadow: 0 0 30px rgba(234, 179, 8, 0.2); border-color: rgba(234, 179, 8, 0.6); }
          50% { background-color: rgba(234, 179, 8, 0.05); box-shadow: 0 0 10px rgba(234, 179, 8, 0.05); border-color: rgba(234, 179, 8, 0.2); }
        }
        @keyframes strobe-red {
          0%, 100% { 
            background-color: rgba(239, 68, 68, 0.2); 
            box-shadow: 0 0 40px rgba(239, 68, 68, 0.4), inset 0 0 15px rgba(239, 68, 68, 0.2); 
            border-color: rgba(239, 68, 68, 0.8);
          }
          50% { 
            background-color: rgba(239, 68, 68, 0.03); 
            box-shadow: 0 0 10px rgba(239, 68, 68, 0.1); 
            border-color: rgba(239, 68, 68, 0.2);
          }
        }
        @keyframes scan-line {
          0% { transform: translateY(-100%); opacity: 0; }
          50% { opacity: 0.1; }
          100% { transform: translateY(100%); opacity: 0; }
        }
        /* 进阶心跳信号动效：模拟电子脉冲 */
        @keyframes signal-pulse {
          from { stroke-dashoffset: 240; }
          to { stroke-dashoffset: 0; }
        }

        .animate-strobe-green { animation: strobe-green 4s ease-in-out infinite; }
        .animate-strobe-yellow { animation: strobe-yellow 2.5s ease-in-out infinite; }
        .animate-strobe-red { animation: strobe-red 1.2s ease-in-out infinite; }
        .node-button { border-width: 2px; backdrop-filter: blur(12px); transition: transform 0.1s ease-out, filter 0.2s; }
        .node-button:hover { filter: brightness(1.25); z-index: 50; }
        .scan-effect { animation: scan-line 6s linear infinite; }

        /* 心跳脉冲样式：通过巨大的 dasharray 创建单一的“信号头”效果 */
        .connection-heartbeat {
          stroke-dasharray: 40, 200; /* 信号长度 40，间隔 200 */
          animation: signal-pulse 2s linear infinite;
          stroke-linecap: round;
        }
      `}</style>

      <Sidebar 
        nodes={nodes} 
        connections={connections}
        selectedNodeId={selectedNodeId}
        addNode={addNode}
        addGroup={addGroup}
        deleteNode={deleteNode}
        deleteConnection={() => {}}
        isAnalyzing={isAnalyzing}
        onAutoLayout={handleAutoLayout}
        isLocked={isLocked}
      />

      <main className="flex-1 relative overflow-hidden bg-[radial-gradient(circle_at_center,_#1e293b_0%,_#020617_100%)]">
        <UIOverlay 
            mode={mode} 
            setMode={setMode} 
            connectSource={getActiveSourceLabel()}
            isLocked={isLocked}
            setIsLocked={setIsLocked}
        />

        <Workspace 
          nodes={nodes} 
          groups={groups}
          connections={connections}
          selectedId={selectedNodeId}
          onElementClick={handleElementInteraction}
          onNodeMove={updateNodePosition}
          onUpdateGroup={updateGroup}
          onDeleteGroup={deleteGroup}
          onDeleteNode={deleteNode}
          mode={mode}
          isLocked={isLocked}
        />

        {isAnalyzing && (
            <div className="absolute inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-md">
                <div className="bg-slate-900 p-8 rounded-2xl shadow-2xl border border-sky-500/50 flex flex-col items-center">
                    <div className="w-16 h-16 border-4 border-sky-500 border-t-transparent rounded-full animate-spin mb-4"></div>
                    <h3 className="text-xl font-bold text-sky-400 font-mono tracking-widest text-center">AI_SYNTHESIZING...</h3>
                </div>
            </div>
        )}
      </main>
    </div>
  );
};

export default App;

import React, { useRef, useState, useMemo, useEffect } from 'react';
import { ServiceNode, Connection, GroupNode } from '../types';
import { SERVICE_ICONS } from '../constants';

interface WorkspaceProps {
  nodes: ServiceNode[];
  groups: GroupNode[];
  connections: Connection[];
  selectedId: string | null;
  onElementClick: (id: string) => void;
  onNodeMove: (id: string, x: number, y: number) => void;
  onUpdateGroup: (id: string, updates: Partial<GroupNode>) => void;
  onDeleteGroup: (id: string) => void;
  onDeleteNode: (id: string) => void;
  mode: string;
  isLocked: boolean;
}

const Workspace: React.FC<WorkspaceProps> = ({ 
  nodes, 
  groups,
  connections, 
  selectedId, 
  onElementClick, 
  onNodeMove, 
  onUpdateGroup,
  onDeleteGroup,
  onDeleteNode,
  mode,
  isLocked
}) => {
  const containerRef = useRef<HTMLDivElement>(null);

  const [viewOffset, setViewOffset] = useState({ x: 0, y: 0 });
  const [isPanning, setIsPanning] = useState(false);
  const [lastMousePos, setLastMousePos] = useState({ x: 0, y: 0 });

  const [draggingId, setDraggingId] = useState<string | null>(null);
  const [resizingId, setResizingId] = useState<string | null>(null);
  const [dragType, setDragType] = useState<'node' | 'group' | 'resize' | 'scroll-h' | 'scroll-v'>('node');

  const contentBounds = useMemo(() => {
    if (nodes.length === 0 && groups.length === 0) {
      return { minX: 0, maxX: 1000, minY: 0, maxY: 1000 };
    }

    let minX = Infinity, maxX = -Infinity, minY = Infinity, maxY = -Infinity;

    nodes.forEach(n => {
      minX = Math.min(minX, n.position.x);
      maxX = Math.max(maxX, n.position.x + 120);
      minY = Math.min(minY, n.position.y);
      maxY = Math.max(maxY, n.position.y + 40);
    });

    groups.forEach(g => {
      minX = Math.min(minX, g.position.x);
      maxX = Math.max(maxX, g.position.x + g.size.width);
      minY = Math.min(minY, g.position.y);
      maxY = Math.max(maxY, g.position.y + g.size.height);
    });

    const margin = 500;
    return {
      minX: Math.min(0, minX - margin),
      maxX: Math.max(window.innerWidth, maxX + margin),
      minY: Math.min(0, minY - margin),
      maxY: Math.max(window.innerHeight, maxY + margin)
    };
  }, [nodes, groups]);

  const handleMouseDown = (e: React.MouseEvent) => {
    if (!containerRef.current) return;
    if (e.target === containerRef.current) {
      setIsPanning(true);
      setLastMousePos({ x: e.clientX, y: e.clientY });
    }
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (!containerRef.current) return;

    if (isPanning) {
      const dx = e.clientX - lastMousePos.x;
      const dy = e.clientY - lastMousePos.y;
      setViewOffset(prev => ({ x: prev.x + dx, y: prev.y + dy }));
      setLastMousePos({ x: e.clientX, y: e.clientY });
      return;
    }

    if (draggingId === 'scrollbar-h' || draggingId === 'scrollbar-v') {
        const rect = containerRef.current.getBoundingClientRect();
        const contentWidth = contentBounds.maxX - contentBounds.minX;
        const contentHeight = contentBounds.maxY - contentBounds.minY;

        if (draggingId === 'scrollbar-h') {
            const ratio = (e.clientX - rect.left) / rect.width;
            const targetX = contentBounds.minX + ratio * contentWidth - rect.width / 2;
            setViewOffset(prev => ({ ...prev, x: -targetX }));
        } else {
            const ratio = (e.clientY - rect.top) / rect.height;
            const targetY = contentBounds.minY + ratio * contentHeight - rect.height / 2;
            setViewOffset(prev => ({ ...prev, y: -targetY }));
        }
        return;
    }

    if (mode !== 'select' || isLocked) return;

    const rect = containerRef.current.getBoundingClientRect();
    const x = e.clientX - rect.left - viewOffset.x;
    const y = e.clientY - rect.top - viewOffset.y;

    if (draggingId && dragType === 'node') {
      onNodeMove(draggingId, x - 60, y - 20);
    } else if (draggingId && dragType === 'group') {
      onUpdateGroup(draggingId, { position: { x: x - (groups.find(g => g.id === draggingId)?.size.width || 0) / 2, y: y - 20 } });
    } else if (resizingId) {
      const group = groups.find(g => g.id === resizingId);
      if (group) {
        const newWidth = Math.max(200, x - group.position.x);
        const newHeight = Math.max(150, y - group.position.y);
        onUpdateGroup(resizingId, { size: { width: newWidth, height: newHeight } });
      }
    }
  };

  const handleMouseUp = () => {
    setIsPanning(false);
    setDraggingId(null);
    setResizingId(null);
  };

  const scrollMetrics = useMemo(() => {
    if (!containerRef.current) return { hThumb: { left: 0, width: 0 }, vThumb: { top: 0, height: 0 } };
    const viewWidth = window.innerWidth - 320;
    const viewHeight = window.innerHeight;
    const contentWidth = contentBounds.maxX - contentBounds.minX;
    const contentHeight = contentBounds.maxY - contentBounds.minY;
    const hRatio = viewWidth / contentWidth;
    const hThumbWidth = Math.max(40, viewWidth * hRatio);
    const hProgress = (-viewOffset.x - contentBounds.minX) / (contentWidth - viewWidth);
    const vRatio = viewHeight / contentHeight;
    const vThumbHeight = Math.max(40, viewHeight * vRatio);
    const vProgress = (-viewOffset.y - contentBounds.minY) / (contentHeight - viewHeight);
    return {
        hThumb: { left: Math.max(0, Math.min(viewWidth - hThumbWidth, hProgress * (viewWidth - hThumbWidth))), width: hThumbWidth },
        vThumb: { top: Math.max(0, Math.min(viewHeight - vThumbHeight, vProgress * (viewHeight - vThumbHeight))), height: vThumbHeight }
    };
  }, [viewOffset, contentBounds]);

  const getStrobeClass = (status: string) => {
    switch(status) {
      case 'online': return 'animate-strobe-green';
      case 'warning': return 'animate-strobe-yellow';
      case 'error': return 'animate-strobe-red';
      default: return 'animate-strobe-green';
    }
  };

  const getStatusConfig = (status: string) => {
    switch(status) {
      case 'online': return { text: '运行', color: 'text-emerald-400', border: 'border-emerald-500/50', glow: 'shadow-[inset_0_0_20px_rgba(52,211,153,0.1)]' };
      case 'warning': return { text: '警告', color: 'text-amber-400', border: 'border-amber-500/50', glow: 'shadow-[inset_0_0_20px_rgba(251,191,36,0.1)]' };
      case 'error': return { text: '故障', color: 'text-rose-400', border: 'border-rose-500/50', glow: 'shadow-[inset_0_0_20px_rgba(244,63,94,0.15)]' };
      default: return { text: '运行', color: 'text-emerald-400', border: 'border-emerald-500/50', glow: 'shadow-[inset_0_0_20px_rgba(52,211,153,0.1)]' };
    }
  };

  const getElementInfo = (id: string) => {
    const node = nodes.find(n => n.id === id);
    if (node) return { x: node.position.x, y: node.position.y, w: 120, h: 40, cx: node.position.x + 60, cy: node.position.y + 20, isGroup: false };
    const group = groups.find(g => g.id === id);
    if (group) return { x: group.position.x, y: group.position.y, w: group.size.width, h: group.size.height, cx: group.position.x + group.size.width / 2, cy: group.position.y + group.size.height / 2, isGroup: true };
    return null;
  };

  const getConnectionPoint = (sourceId: string, targetId: string) => {
    const s = getElementInfo(sourceId);
    const t = getElementInfo(targetId);
    if (!s || !t) return null;
    const getIntersection = (rect: any, otherCenter: {x: number, y: number}) => {
      const dx = otherCenter.x - rect.cx;
      const dy = otherCenter.y - rect.cy;
      const hw = rect.w / 2;
      const hh = rect.h / 2;
      const scale = Math.min(dx !== 0 ? Math.abs(hw / dx) : Infinity, dy !== 0 ? Math.abs(hh / dy) : Infinity);
      return { x: rect.cx + dx * scale, y: rect.cy + dy * scale };
    };
    return { start: getIntersection(s, { x: t.cx, y: t.cy }), end: getIntersection(t, { x: s.cx, y: s.cy }) };
  };

  /**
   * 生成三阶贝塞尔曲线路径
   * @param start 起点
   * @param end 终点
   */
  const getBezierPath = (start: {x: number, y: number}, end: {x: number, y: number}) => {
    const dx = Math.abs(end.x - start.x);
    const horizontal = dx > 100;

    // 计算控制点：如果是横向跨度大，控制点在 X 轴偏移；如果是纵向大，则在 Y 轴偏移
    const ctrl1 = horizontal 
      ? { x: start.x + dx / 2, y: start.y } 
      : { x: start.x, y: start.y + (end.y - start.y) / 2 };

    const ctrl2 = horizontal 
      ? { x: end.x - dx / 2, y: end.y } 
      : { x: end.x, y: end.y - (end.y - start.y) / 2 };

    return `M ${start.x} ${start.y} C ${ctrl1.x} ${ctrl1.y}, ${ctrl2.x} ${ctrl2.y}, ${end.x} ${end.y}`;
  };

  const gridBackground = useMemo(() => ({
    backgroundImage: `
      linear-gradient(to right, rgba(14, 165, 233, 0.05) 1px, transparent 1px),
      linear-gradient(to bottom, rgba(14, 165, 233, 0.05) 1px, transparent 1px),
      linear-gradient(to right, rgba(14, 165, 233, 0.02) 1px, transparent 1px),
      linear-gradient(to bottom, rgba(14, 165, 233, 0.02) 1px, transparent 1px)
    `,
    backgroundSize: '100px 100px, 100px 100px, 20px 20px, 20px 20px',
    backgroundPosition: `${viewOffset.x}px ${viewOffset.y}px`
  }), [viewOffset]);

  return (
    <div 
      ref={containerRef}
      style={gridBackground}
      className={`w-full h-full relative select-none transition-colors overflow-hidden ${isPanning ? 'cursor-grabbing' : 'cursor-default'}`}
      onMouseDown={handleMouseDown}
      onMouseMove={handleMouseMove}
      onMouseUp={handleMouseUp}
      onMouseLeave={handleMouseUp}
    >
      <div 
        style={{ 
          transform: `translate(${viewOffset.x}px, ${viewOffset.y}px)`,
          position: 'absolute',
          inset: 0,
          pointerEvents: 'none'
        }}
      >
        {/* 容器层 (Groups) */}
        {groups.map((group) => {
          const statusConfig = getStatusConfig(group.status);
          const strobeClass = getStrobeClass(group.status);

          return (
            <div
              key={group.id}
              style={{
                left: group.position.x,
                top: group.position.y,
                width: group.size.width,
                height: group.size.height,
                pointerEvents: 'auto'
              }}
              className={`absolute group/container z-0 transition-all ${
                isLocked ? 'pointer-events-auto' : 'cursor-move'
              }`}
              onMouseDown={(e) => {
                if (mode === 'select' && !isLocked) {
                   e.stopPropagation();
                   setDraggingId(group.id);
                   setDragType('group');
                }
              }}
            >
              <div className={`absolute inset-0 rounded-2xl bg-slate-900/40 backdrop-blur-md border border-slate-700/30 overflow-hidden ${statusConfig.glow} ${strobeClass}`}>
                 <div className="absolute inset-0 opacity-[0.03] pointer-events-none" style={{ backgroundImage: 'radial-gradient(#38bdf8 1px, transparent 0)', backgroundSize: '10px 10px' }}></div>
                 <div className="absolute inset-0 scan-effect bg-gradient-to-b from-transparent via-sky-500/5 to-transparent h-1/2 w-full"></div>
              </div>

              <div className="absolute -top-[1px] -left-[1px] w-6 h-6 border-t-2 border-l-2 border-sky-400/60 rounded-tl-2xl pointer-events-none group-hover/container:scale-105 transition-transform duration-500"></div>
              <div className="absolute -top-[1px] -right-[1px] w-6 h-6 border-t-2 border-r-2 border-sky-400/60 rounded-tr-2xl pointer-events-none group-hover/container:scale-105 transition-transform duration-500"></div>
              <div className="absolute -bottom-[1px] -left-[1px] w-6 h-6 border-b-2 border-l-2 border-sky-400/60 rounded-bl-2xl pointer-events-none group-hover/container:scale-105 transition-transform duration-500"></div>
              <div className="absolute -bottom-[1px] -right-[1px] w-6 h-6 border-b-2 border-r-2 border-sky-400/60 rounded-br-2xl pointer-events-none group-hover/container:scale-105 transition-transform duration-500"></div>

              <div className="absolute top-0 left-0 right-0 h-8 bg-slate-950/40 border-b border-slate-700/20 px-4 flex items-center justify-between pointer-events-none">
                <div className="flex items-center gap-3">
                  <div className={`w-1.5 h-1.5 rounded-full ${group.status === 'online' ? 'bg-emerald-500' : group.status === 'warning' ? 'bg-amber-500' : 'bg-rose-500'} animate-pulse`}></div>
                  <span className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">{group.name}</span>
                </div>
                <div className="flex items-center gap-2">
                   <div className={`text-[8px] font-black px-2 py-0.5 rounded bg-slate-900 border ${statusConfig.border} ${statusConfig.color}`}>{statusConfig.text}</div>
                </div>
              </div>

              {!isLocked && (
                <>
                  <div 
                    className="absolute -bottom-1 -right-1 w-8 h-8 flex items-center justify-center cursor-nwse-resize hover:bg-sky-500/20 rounded-tl-xl rounded-br-2xl transition-all z-30"
                    onMouseDown={(e) => { e.stopPropagation(); setResizingId(group.id); setDragType('resize'); }}
                  >
                    <i className="fas fa-expand-arrows-alt text-sky-400/40 text-xs"></i>
                  </div>
                  <div 
                    className="absolute -top-3 -right-3 w-7 h-7 rounded-full bg-slate-950 border border-slate-800 flex items-center justify-center text-[10px] text-slate-500 opacity-0 group-hover/container:opacity-100 cursor-pointer hover:bg-rose-500/20 hover:text-rose-400 shadow-xl transition-all hover:scale-110 z-30"
                    onClick={(e) => { e.stopPropagation(); onDeleteGroup(group.id); }}
                  >
                    <i className="fas fa-trash-alt"></i>
                  </div>
                </>
              )}
            </div>
          );
        })}

        {/* 连线层 - 升级为贝塞尔曲线和增强动效 */}
        <svg className="absolute inset-0 w-full h-full pointer-events-none z-[5]">
          <defs>
             <filter id="neon-glow" x="-50%" y="-50%" width="200%" height="200%">
                <feGaussianBlur stdDeviation="3" result="blur"/>
                <feComposite in="SourceGraphic" in2="blur" operator="over"/>
             </filter>
             <marker id="arrow-blue" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="4" markerHeight="4" orient="auto">
                <path d="M 0 0 L 10 5 L 0 10 z" fill="#0ea5e9" opacity="0.6" />
             </marker>
             <marker id="arrow-red" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="4" markerHeight="4" orient="auto">
                <path d="M 0 0 L 10 5 L 0 10 z" fill="#f43f5e" opacity="0.6" />
             </marker>
          </defs>

          {connections.map((conn) => {
            const points = getConnectionPoint(conn.sourceId, conn.targetId);
            if (!points) return null;
            const { start, end } = points;
            const targetStatus = nodes.find(n => n.id === conn.targetId)?.status || 'online';
            const isCritical = targetStatus === 'error';
            const bezierPath = getBezierPath(start, end);

            return (
              <g key={conn.id}>
                {/* 1. 背景轨道：低透明度的贝塞尔曲线 */}
                <path 
                  d={bezierPath} 
                  stroke={isCritical ? "#f43f5e" : "#334155"} 
                  strokeWidth="1.5" 
                  fill="none" 
                  className="opacity-30"
                  markerEnd={`url(#${isCritical ? 'arrow-red' : 'arrow-blue'})`}
                />

                {/* 2. 增强心跳脉冲：模拟电子信号头 */}
                <path 
                  d={bezierPath} 
                  stroke={isCritical ? "#f43f5e" : "#0ea5e9"} 
                  strokeWidth="2.5" 
                  fill="none"
                  filter="url(#neon-glow)"
                  className="connection-heartbeat" 
                  style={{ 
                    animationDuration: `${Math.max(0.5, 3 - conn.trafficLoad * 3)}s`,
                    opacity: 0.8
                  }}
                />

                {/* 3. 可选：流量强度标签 */}
                {conn.trafficLoad > 0.6 && (
                   <circle r="3" fill={isCritical ? "#f43f5e" : "#7dd3fc"}>
                      <animateMotion dur={`${Math.max(1, 4 - conn.trafficLoad * 4)}s`} repeatCount="indefinite" path={bezierPath} />
                   </circle>
                )}
              </g>
            );
          })}
        </svg>

        {/* 节点层 */}
        {nodes.map((node) => {
          const isSelected = selectedId === node.id;
          const statusConfig = getStatusConfig(node.status);
          return (
            <div
              key={node.id}
              style={{ left: node.position.x, top: node.position.y, width: '120px', height: '40px', pointerEvents: 'auto' }}
              className="absolute z-10 flex flex-col items-center group/node"
            >
              <div
                className={`w-full h-full node-button rounded-lg shadow-2xl flex items-center justify-center relative ${getStrobeClass(node.status)} ${
                  isSelected ? 'ring-4 ring-white/60 scale-105 z-20' : ''
                } ${isLocked ? 'cursor-default' : 'cursor-pointer hover:scale-105'}`}
                onClick={(e) => { e.stopPropagation(); onElementClick(node.id); }}
                onMouseDown={(e) => {
                  if (mode === 'select' && !isLocked) {
                    e.stopPropagation();
                    setDraggingId(node.id);
                    setDragType('node');
                  }
                }}
              >
                <div className="flex items-center gap-2 pointer-events-none px-2 mb-1">
                  <i className={`fas ${SERVICE_ICONS[node.type]} text-xs text-white`}></i>
                  <span className="text-[10px] font-black text-white uppercase tracking-tighter truncate">{node.name}</span>
                </div>
                {!isLocked && (
                  <div className="absolute -top-2 -right-2 w-5 h-5 bg-slate-950 border border-slate-800 hover:bg-rose-600 rounded-full flex items-center justify-center text-[8px] text-white z-30 transition-all shadow-lg opacity-0 group-hover/node:opacity-100 cursor-pointer"
                    onClick={(e) => { e.stopPropagation(); onDeleteNode(node.id); }}>
                    <i className="fas fa-times"></i>
                  </div>
                )}
                <div className={`absolute -bottom-2 left-1/2 -translate-x-1/2 px-2 py-0.5 rounded-full text-[7px] font-black bg-slate-950 border ${statusConfig.border} backdrop-blur-md shadow-xl transition-transform ${statusConfig.color} tracking-[0.2em] uppercase whitespace-nowrap z-20`}>
                  {statusConfig.text}
                </div>
              </div>
            </div>
          );
        })}
      </div>

      {/* 滚动条 */}
      <div className="absolute bottom-0 left-0 right-1 w-[calc(100%-4px)] h-1 px-1 group/scrollbar-h">
        <div className="w-full h-full bg-slate-800/30 rounded-full transition-all group-hover/scrollbar-h:h-2 group-hover/scrollbar-h:bg-slate-800/50">
           <div 
             className="h-full bg-sky-500/50 rounded-full cursor-pointer hover:bg-sky-400/80 transition-colors pointer-events-auto"
             style={{ position: 'absolute', left: `${scrollMetrics.hThumb.left}px`, width: `${scrollMetrics.hThumb.width}px` }}
             onMouseDown={(e) => { e.stopPropagation(); setDraggingId('scrollbar-h'); }}
           />
        </div>
      </div>

      <div className="absolute top-0 right-0 bottom-1 w-1 h-[calc(100%-4px)] py-1 group/scrollbar-v">
        <div className="w-full h-full bg-slate-800/30 rounded-full transition-all group-hover/scrollbar-v:w-2 group-hover/scrollbar-v:bg-slate-800/50">
           <div 
             className="w-full bg-sky-500/50 rounded-full cursor-pointer hover:bg-sky-400/80 transition-colors pointer-events-auto"
             style={{ position: 'absolute', top: `${scrollMetrics.vThumb.top}px`, height: `${scrollMetrics.vThumb.height}px` }}
             onMouseDown={(e) => { e.stopPropagation(); setDraggingId('scrollbar-v'); }}
           />
        </div>
      </div>

      <div className="absolute bottom-10 right-10 pointer-events-none opacity-40">
        <div className="flex flex-col items-end gap-1">
          <span className="text-[9px] font-black text-sky-500 uppercase tracking-tighter">坐标系偏移: {Math.round(viewOffset.x)}, {Math.round(viewOffset.y)}</span>
          <span className="text-[8px] text-slate-500">拓扑渲染层级: SVG_BEZIER_V2</span>
        </div>
      </div>
    </div>
  );
};

export default Workspace;

export enum ServiceType {
  DATABASE = 'database',
  SERVER = 'server',
  GATEWAY = 'gateway',
  CACHE = 'cache',
  LOAD_BALANCER = 'load_balancer',
  FIREWALL = 'firewall',
  CONTAINER = 'container'
}

export interface Vector3Array {
  x: number;
  y: number;
  z: number;
}

export interface ServiceNode {
  id: string;
  name: string;
  type: ServiceType;
  position: Vector3Array;
  status: 'online' | 'warning' | 'error';
  lastUpdated: string;
}

export interface GroupNode {
  id: string;
  name: string;
  position: { x: number; y: number };
  size: { width: number; height: number };
  color: string;
  status: 'online' | 'warning' | 'error';
}

export interface Connection {
  id: string;
  sourceId: string;
  targetId: string;
  label: string;
  trafficLoad: number; // 0-1
  status?: 'online' | 'warning' | 'error'; // 新增链路状态
}

export interface AppState {
  nodes: ServiceNode[];
  groups: GroupNode[];
  connections: Connection[];
  selectedNodeId: string | null;
  mode: 'select' | 'add' | 'connect';
}

import React, { useState, useCallback } from 'react';
import Sidebar from './components/Sidebar';
import UIOverlay from './components/UIOverlay';
import Workspace from './components/Workspace';
import { ServiceNode, Connection, ServiceType, GroupNode } from './types';
import { suggestLayout } from './geminiService';

const App: React.FC = () => {
  const [nodes, setNodes] = useState<ServiceNode[]>([
    { id: '1', name: '用户网关', type: ServiceType.GATEWAY, position: { x: 150, y: 250, z: 0 }, status: 'online', lastUpdated: new Date().toISOString() },
    { id: '2', name: '认证服务', type: ServiceType.SERVER, position: { x: 450, y: 200, z: 0 }, status: 'online', lastUpdated: new Date().toISOString() },
    { id: '3', name: '产品数据库', type: ServiceType.DATABASE, position: { x: 750, y: 350, z: 0 }, status: 'warning', lastUpdated: new Date().toISOString() },
  ]);

  const [groups, setGroups] = useState<GroupNode[]>([
    { id: 'g1', name: '生产集群-A', position: { x: 100, y: 150 }, size: { width: 500, height: 350 }, color: '#38bdf8', status: 'online' }
  ]);

  const [connections, setConnections] = useState<Connection[]>([
    { id: 'c1', sourceId: '1', targetId: '2', label: 'HTTP 认证', trafficLoad: 0.4, status: 'online' },
    { id: 'c2', sourceId: '2', targetId: '3', label: 'SQL 查询', trafficLoad: 0.8, status: 'warning' },
  ]);

  const [selectedNodeId, setSelectedNodeId] = useState<string | null>(null);
  const [mode, setMode] = useState<'select' | 'add' | 'connect'>('select');
  const [isLocked, setIsLocked] = useState(false);
  const [connectSourceId, setConnectSourceId] = useState<string | null>(null);
  const [isAnalyzing, setIsAnalyzing] = useState(false);

  const addNode = useCallback((type: ServiceType, name: string, status: 'online' | 'warning' | 'error' = 'online') => {
    if (isLocked) return;
    const newNode: ServiceNode = {
      id: `node-${Date.now()}`,
      name,
      type,
      position: { x: 200, y: 200, z: 0 },
      status,
      lastUpdated: new Date().toISOString()
    };
    setNodes(prev => [...prev, newNode]);
  }, [isLocked]);

  const addGroup = useCallback((name: string, status: 'online' | 'warning' | 'error' = 'online') => {
    if (isLocked) return;
    const newGroup: GroupNode = {
      id: `group-${Date.now()}`,
      name,
      position: { x: 200, y: 200 },
      size: { width: 400, height: 300 },
      color: '#818cf8',
      status: status
    };
    setGroups(prev => [...prev, newGroup]);
  }, [isLocked]);

  const updateGroup = useCallback((id: string, updates: Partial<GroupNode>) => {
    if (isLocked) return;
    setGroups(prev => prev.map(g => g.id === id ? { ...g, ...updates } : g));
  }, [isLocked]);

  const deleteGroup = useCallback((id: string) => {
    if (isLocked) return;
    setGroups(prev => prev.filter(g => g.id !== id));
    setConnections(prev => prev.filter(c => c.sourceId !== id && c.targetId !== id));
  }, [isLocked]);

  const deleteNode = useCallback((id: string) => {
    if (isLocked) return;
    setNodes(prev => prev.filter(n => n.id !== id));
    setConnections(prev => prev.filter(c => c.sourceId !== id && c.targetId !== id));
    setSelectedNodeId(null);
  }, [isLocked]);

  const handleElementInteraction = useCallback((id: string) => {
    if (mode === 'connect' && !isLocked) {
      if (!connectSourceId) {
        setConnectSourceId(id);
      } else if (connectSourceId !== id) {
        setConnections(prev => [...prev, {
          id: `c-${Date.now()}`,
          sourceId: connectSourceId,
          targetId: id,
          label: '新链路',
          trafficLoad: 0.2,
          status: 'online'
        }]);
        setConnectSourceId(null);
        setMode('select');
      }
    } else {
      setSelectedNodeId(id === selectedNodeId ? null : id);
    }
  }, [mode, connectSourceId, selectedNodeId, isLocked]);

  const updateNodePosition = useCallback((id: string, x: number, y: number) => {
    if (isLocked) return;
    setNodes(prev => prev.map(n => n.id === id ? { ...n, position: { ...n.position, x, y } } : n));
  }, [isLocked]);

  const handleAutoLayout = async (desc: string) => {
    if (!desc || isLocked) return;
    setIsAnalyzing(true);
    try {
        const layout = await suggestLayout(desc);
        const newNodes: ServiceNode[] = layout.nodes.map((n: any, i: number) => ({
            id: `ai-node-${i}-${Date.now()}`,
            name: n.name,
            type: n.type as ServiceType,
            position: { x: (n.x + 10) * 40, y: (n.y + 10) * 30, z: 0 },
            status: 'online',
            lastUpdated: new Date().toISOString()
        }));

        const newConns: Connection[] = layout.connections.map((c: any, i: number) => ({
            id: `ai-conn-${i}-${Date.now()}`,
            sourceId: newNodes[c.sourceIndex].id,
            targetId: newNodes[c.targetIndex].id,
            label: c.label,
            trafficLoad: Math.random() * 0.5,
            status: 'online'
        }));

        setNodes(newNodes);
        setConnections(newConns);
    } catch (e) {
        console.error("AI Layout failed", e);
    }
    setIsAnalyzing(false);
  };

  const getActiveSourceLabel = () => {
    if (!connectSourceId) return null;
    const node = nodes.find(n => n.id === connectSourceId);
    if (node) return node.name;
    const group = groups.find(g => g.id === connectSourceId);
    if (group) return group.name;
    return "未知节点";
  };

  return (
    <div className="flex h-screen w-screen bg-slate-950 text-slate-100 overflow-hidden font-sans">
      <style>{`
        @keyframes strobe-green {
          0%, 100% { background-color: rgba(34, 197, 94, 0.08); box-shadow: 0 0 20px rgba(34, 197, 94, 0.1), inset 0 0 10px rgba(34, 197, 94, 0.05); border-color: rgba(34, 197, 94, 0.4); }
          50% { background-color: rgba(34, 197, 94, 0.02); box-shadow: 0 0 5px rgba(34, 197, 94, 0.02); border-color: rgba(34, 197, 94, 0.1); }
        }
        @keyframes strobe-yellow {
          0%, 100% { background-color: rgba(234, 179, 8, 0.15); box-shadow: 0 0 30px rgba(234, 179, 8, 0.2); border-color: rgba(234, 179, 8, 0.6); }
          50% { background-color: rgba(234, 179, 8, 0.05); box-shadow: 0 0 10px rgba(234, 179, 8, 0.05); border-color: rgba(234, 179, 8, 0.2); }
        }
        @keyframes strobe-red {
          0%, 100% { 
            background-color: rgba(239, 68, 68, 0.2); 
            box-shadow: 0 0 40px rgba(239, 68, 68, 0.4), inset 0 0 15px rgba(239, 68, 68, 0.2); 
            border-color: rgba(239, 68, 68, 0.8);
          }
          50% { 
            background-color: rgba(239, 68, 68, 0.03); 
            box-shadow: 0 0 10px rgba(239, 68, 68, 0.1); 
            border-color: rgba(239, 68, 68, 0.2);
          }
        }
        @keyframes scan-line {
          0% { transform: translateY(-100%); opacity: 0; }
          50% { opacity: 0.1; }
          100% { transform: translateY(100%); opacity: 0; }
        }

        /* 心跳脉冲信号动效 */
        @keyframes signal-flow {
          0% { stroke-dashoffset: 400; }
          100% { stroke-dashoffset: 0; }
        }

        .animate-strobe-green { animation: strobe-green 4s ease-in-out infinite; }
        .animate-strobe-yellow { animation: strobe-yellow 2.5s ease-in-out infinite; }
        .animate-strobe-red { animation: strobe-red 1.2s ease-in-out infinite; }
        .node-button { border-width: 2px; backdrop-filter: blur(12px); transition: transform 0.1s ease-out, filter 0.2s; }
        .node-button:hover { filter: brightness(1.25); z-index: 50; }
        .scan-effect { animation: scan-line 6s linear infinite; }

        .connection-heartbeat {
          stroke-dasharray: 60, 340; /* 信号头 60，间隔 340 */
          animation: signal-flow 3s linear infinite;
          stroke-linecap: round;
          filter: drop-shadow(0 0 5px currentColor);
        }
      `}</style>

      <Sidebar 
        nodes={nodes} 
        connections={connections}
        selectedNodeId={selectedNodeId}
        addNode={addNode}
        addGroup={addGroup}
        deleteNode={deleteNode}
        deleteConnection={() => {}}
        isAnalyzing={isAnalyzing}
        onAutoLayout={handleAutoLayout}
        isLocked={isLocked}
      />

      <main className="flex-1 relative overflow-hidden bg-[radial-gradient(circle_at_center,_#1e293b_0%,_#020617_100%)]">
        <UIOverlay 
            mode={mode} 
            setMode={setMode} 
            connectSource={getActiveSourceLabel()}
            isLocked={isLocked}
            setIsLocked={setIsLocked}
        />

        <Workspace 
          nodes={nodes} 
          groups={groups}
          connections={connections}
          selectedId={selectedNodeId}
          onElementClick={handleElementInteraction}
          onNodeMove={updateNodePosition}
          onUpdateGroup={updateGroup}
          onDeleteGroup={deleteGroup}
          onDeleteNode={deleteNode}
          mode={mode}
          isLocked={isLocked}
        />

        {isAnalyzing && (
            <div className="absolute inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-md">
                <div className="bg-slate-900 p-8 rounded-2xl shadow-2xl border border-sky-500/50 flex flex-col items-center">
                    <div className="w-16 h-16 border-4 border-sky-500 border-t-transparent rounded-full animate-spin mb-4"></div>
                    <h3 className="text-xl font-bold text-sky-400 font-mono tracking-widest text-center">AI_SYNTHESIZING...</h3>
                </div>
            </div>
        )}
      </main>
    </div>
  );
};

export default App;

import React, { useRef, useState, useMemo, useEffect } from 'react';
import { ServiceNode, Connection, GroupNode } from '../types';
import { SERVICE_ICONS } from '../constants';

interface WorkspaceProps {
  nodes: ServiceNode[];
  groups: GroupNode[];
  connections: Connection[];
  selectedId: string | null;
  onElementClick: (id: string) => void;
  onNodeMove: (id: string, x: number, y: number) => void;
  onUpdateGroup: (id: string, updates: Partial<GroupNode>) => void;
  onDeleteGroup: (id: string) => void;
  onDeleteNode: (id: string) => void;
  mode: string;
  isLocked: boolean;
}

const Workspace: React.FC<WorkspaceProps> = ({ 
  nodes, 
  groups,
  connections, 
  selectedId, 
  onElementClick, 
  onNodeMove, 
  onUpdateGroup,
  onDeleteGroup,
  onDeleteNode,
  mode,
  isLocked
}) => {
  const containerRef = useRef<HTMLDivElement>(null);

  const [viewOffset, setViewOffset] = useState({ x: 0, y: 0 });
  const [isPanning, setIsPanning] = useState(false);
  const [lastMousePos, setLastMousePos] = useState({ x: 0, y: 0 });

  const [draggingId, setDraggingId] = useState<string | null>(null);
  const [resizingId, setResizingId] = useState<string | null>(null);
  const [dragType, setDragType] = useState<'node' | 'group' | 'resize' | 'scroll-h' | 'scroll-v'>('node');

  const contentBounds = useMemo(() => {
    if (nodes.length === 0 && groups.length === 0) {
      return { minX: 0, maxX: 1000, minY: 0, maxY: 1000 };
    }

    let minX = Infinity, maxX = -Infinity, minY = Infinity, maxY = -Infinity;

    nodes.forEach(n => {
      minX = Math.min(minX, n.position.x);
      maxX = Math.max(maxX, n.position.x + 120);
      minY = Math.min(minY, n.position.y);
      maxY = Math.max(maxY, n.position.y + 40);
    });

    groups.forEach(g => {
      minX = Math.min(minX, g.position.x);
      maxX = Math.max(maxX, g.position.x + g.size.width);
      minY = Math.min(minY, g.position.y);
      maxY = Math.max(maxY, g.position.y + g.size.height);
    });

    const margin = 500;
    return {
      minX: Math.min(0, minX - margin),
      maxX: Math.max(window.innerWidth, maxX + margin),
      minY: Math.min(0, minY - margin),
      maxY: Math.max(window.innerHeight, maxY + margin)
    };
  }, [nodes, groups]);

  const handleMouseDown = (e: React.MouseEvent) => {
    if (!containerRef.current) return;
    if (e.target === containerRef.current) {
      setIsPanning(true);
      setLastMousePos({ x: e.clientX, y: e.clientY });
    }
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (!containerRef.current) return;

    if (isPanning) {
      const dx = e.clientX - lastMousePos.x;
      const dy = e.clientY - lastMousePos.y;
      setViewOffset(prev => ({ x: prev.x + dx, y: prev.y + dy }));
      setLastMousePos({ x: e.clientX, y: e.clientY });
      return;
    }

    if (draggingId === 'scrollbar-h' || draggingId === 'scrollbar-v') {
        const rect = containerRef.current.getBoundingClientRect();
        const contentWidth = contentBounds.maxX - contentBounds.minX;
        const contentHeight = contentBounds.maxY - contentBounds.minY;

        if (draggingId === 'scrollbar-h') {
            const ratio = (e.clientX - rect.left) / rect.width;
            const targetX = contentBounds.minX + ratio * contentWidth - rect.width / 2;
            setViewOffset(prev => ({ ...prev, x: -targetX }));
        } else {
            const ratio = (e.clientY - rect.top) / rect.height;
            const targetY = contentBounds.minY + ratio * contentHeight - rect.height / 2;
            setViewOffset(prev => ({ ...prev, y: -targetY }));
        }
        return;
    }

    if (mode !== 'select' || isLocked) return;

    const rect = containerRef.current.getBoundingClientRect();
    const x = e.clientX - rect.left - viewOffset.x;
    const y = e.clientY - rect.top - viewOffset.y;

    if (draggingId && dragType === 'node') {
      onNodeMove(draggingId, x - 60, y - 20);
    } else if (draggingId && dragType === 'group') {
      onUpdateGroup(draggingId, { position: { x: x - (groups.find(g => g.id === draggingId)?.size.width || 0) / 2, y: y - 20 } });
    } else if (resizingId) {
      const group = groups.find(g => g.id === resizingId);
      if (group) {
        const newWidth = Math.max(200, x - group.position.x);
        const newHeight = Math.max(150, y - group.position.y);
        onUpdateGroup(resizingId, { size: { width: newWidth, height: newHeight } });
      }
    }
  };

  const handleMouseUp = () => {
    setIsPanning(false);
    setDraggingId(null);
    setResizingId(null);
  };

  const scrollMetrics = useMemo(() => {
    if (!containerRef.current) return { hThumb: { left: 0, width: 0 }, vThumb: { top: 0, height: 0 } };
    const viewWidth = window.innerWidth - 320;
    const viewHeight = window.innerHeight;
    const contentWidth = contentBounds.maxX - contentBounds.minX;
    const contentHeight = contentBounds.maxY - contentBounds.minY;
    const hRatio = viewWidth / contentWidth;
    const hThumbWidth = Math.max(40, viewWidth * hRatio);
    const hProgress = (-viewOffset.x - contentBounds.minX) / (contentWidth - viewWidth);
    const vRatio = viewHeight / contentHeight;
    const vThumbHeight = Math.max(40, viewHeight * vRatio);
    const vProgress = (-viewOffset.y - contentBounds.minY) / (contentHeight - viewHeight);
    return {
        hThumb: { left: Math.max(0, Math.min(viewWidth - hThumbWidth, hProgress * (viewWidth - hThumbWidth))), width: hThumbWidth },
        vThumb: { top: Math.max(0, Math.min(viewHeight - vThumbHeight, vProgress * (viewHeight - vThumbHeight))), height: vThumbHeight }
    };
  }, [viewOffset, contentBounds]);

  const getStrobeClass = (status: string) => {
    switch(status) {
      case 'online': return 'animate-strobe-green';
      case 'warning': return 'animate-strobe-yellow';
      case 'error': return 'animate-strobe-red';
      default: return 'animate-strobe-green';
    }
  };

  const getStatusConfig = (status: string) => {
    switch(status) {
      case 'online': return { text: '运行', color: 'text-emerald-400', border: 'border-emerald-500/50', glow: 'shadow-[inset_0_0_20px_rgba(52,211,153,0.1)]' };
      case 'warning': return { text: '警告', color: 'text-amber-400', border: 'border-amber-500/50', glow: 'shadow-[inset_0_0_20px_rgba(251,191,36,0.1)]' };
      case 'error': return { text: '故障', color: 'text-rose-400', border: 'border-rose-500/50', glow: 'shadow-[inset_0_0_20px_rgba(244,63,94,0.15)]' };
      default: return { text: '运行', color: 'text-emerald-400', border: 'border-emerald-500/50', glow: 'shadow-[inset_0_0_20px_rgba(52,211,153,0.1)]' };
    }
  };

  const getElementInfo = (id: string) => {
    const node = nodes.find(n => n.id === id);
    if (node) return { x: node.position.x, y: node.position.y, w: 120, h: 40, cx: node.position.x + 60, cy: node.position.y + 20, isGroup: false };
    const group = groups.find(g => g.id === id);
    if (group) return { x: group.position.x, y: group.position.y, w: group.size.width, h: group.size.height, cx: group.position.x + group.size.width / 2, cy: group.position.y + group.size.height / 2, isGroup: true };
    return null;
  };

  const getConnectionPoint = (sourceId: string, targetId: string) => {
    const s = getElementInfo(sourceId);
    const t = getElementInfo(targetId);
    if (!s || !t) return null;
    const getIntersection = (rect: any, otherCenter: {x: number, y: number}) => {
      const dx = otherCenter.x - rect.cx;
      const dy = otherCenter.y - rect.cy;
      const hw = rect.w / 2;
      const hh = rect.h / 2;
      const scale = Math.min(dx !== 0 ? Math.abs(hw / dx) : Infinity, dy !== 0 ? Math.abs(hh / dy) : Infinity);
      return { x: rect.cx + dx * scale, y: rect.cy + dy * scale };
    };
    return { start: getIntersection(s, { x: t.cx, y: t.cy }), end: getIntersection(t, { x: s.cx, y: s.cy }) };
  };

  const getBezierPath = (start: {x: number, y: number}, end: {x: number, y: number}) => {
    const dx = Math.abs(end.x - start.x);
    const dy = Math.abs(end.y - start.y);
    const horizontal = dx > dy;

    const ctrl1 = horizontal 
      ? { x: start.x + dx / 3, y: start.y } 
      : { x: start.x, y: start.y + dy / 3 };

    const ctrl2 = horizontal 
      ? { x: end.x - dx / 3, y: end.y } 
      : { x: end.x, y: end.y - dy / 3 };

    return `M ${start.x} ${start.y} C ${ctrl1.x} ${ctrl1.y}, ${ctrl2.x} ${ctrl2.y}, ${end.x} ${end.y}`;
  };

  const gridBackground = useMemo(() => ({
    backgroundImage: `
      linear-gradient(to right, rgba(14, 165, 233, 0.05) 1px, transparent 1px),
      linear-gradient(to bottom, rgba(14, 165, 233, 0.05) 1px, transparent 1px),
      linear-gradient(to right, rgba(14, 165, 233, 0.02) 1px, transparent 1px),
      linear-gradient(to bottom, rgba(14, 165, 233, 0.02) 1px, transparent 1px)
    `,
    backgroundSize: '100px 100px, 100px 100px, 20px 20px, 20px 20px',
    backgroundPosition: `${viewOffset.x}px ${viewOffset.y}px`
  }), [viewOffset]);

  return (
    <div 
      ref={containerRef}
      style={gridBackground}
      className={`w-full h-full relative select-none transition-colors overflow-hidden ${isPanning ? 'cursor-grabbing' : 'cursor-default'}`}
      onMouseDown={handleMouseDown}
      onMouseMove={handleMouseMove}
      onMouseUp={handleMouseUp}
      onMouseLeave={handleMouseUp}
    >
      <div 
        style={{ 
          transform: `translate(${viewOffset.x}px, ${viewOffset.y}px)`,
          position: 'absolute',
          inset: 0,
          pointerEvents: 'none'
        }}
      >
        {/* 容器层 (Groups) */}
        {groups.map((group) => {
          const statusConfig = getStatusConfig(group.status);
          const strobeClass = getStrobeClass(group.status);

          return (
            <div
              key={group.id}
              style={{
                left: group.position.x,
                top: group.position.y,
                width: group.size.width,
                height: group.size.height,
                pointerEvents: 'auto'
              }}
              className={`absolute group/container z-0 transition-all ${
                isLocked ? 'pointer-events-auto' : 'cursor-move'
              }`}
              onMouseDown={(e) => {
                if (mode === 'select' && !isLocked) {
                   e.stopPropagation();
                   setDraggingId(group.id);
                   setDragType('group');
                }
              }}
            >
              <div className={`absolute inset-0 rounded-2xl bg-slate-900/40 backdrop-blur-md border border-slate-700/30 overflow-hidden ${statusConfig.glow} ${strobeClass}`}>
                 <div className="absolute inset-0 opacity-[0.03] pointer-events-none" style={{ backgroundImage: 'radial-gradient(#38bdf8 1px, transparent 0)', backgroundSize: '10px 10px' }}></div>
                 <div className="absolute inset-0 scan-effect bg-gradient-to-b from-transparent via-sky-500/5 to-transparent h-1/2 w-full"></div>
              </div>

              <div className="absolute top-0 left-0 right-0 h-8 bg-slate-950/40 border-b border-slate-700/20 px-4 flex items-center justify-between pointer-events-none">
                <div className="flex items-center gap-3">
                  <div className={`w-1.5 h-1.5 rounded-full ${group.status === 'online' ? 'bg-emerald-500' : group.status === 'warning' ? 'bg-amber-500' : 'bg-rose-500'} animate-pulse`}></div>
                  <span className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">{group.name}</span>
                </div>
                <div className="flex items-center gap-2">
                   <div className={`text-[8px] font-black px-2 py-0.5 rounded bg-slate-900 border ${statusConfig.border} ${statusConfig.color}`}>{statusConfig.text}</div>
                </div>
              </div>

              {!isLocked && (
                <>
                  <div 
                    className="absolute -bottom-1 -right-1 w-8 h-8 flex items-center justify-center cursor-nwse-resize hover:bg-sky-500/20 rounded-tl-xl rounded-br-2xl transition-all z-30"
                    onMouseDown={(e) => { e.stopPropagation(); setResizingId(group.id); setDragType('resize'); }}
                  >
                    <i className="fas fa-expand-arrows-alt text-sky-400/40 text-xs"></i>
                  </div>
                </>
              )}
            </div>
          );
        })}

        {/* 连线层 */}
        <svg className="absolute inset-0 w-full h-full pointer-events-none z-[5]">
          <defs>
             <filter id="neon-glow" x="-100%" y="-100%" width="300%" height="300%">
                <feGaussianBlur stdDeviation="4" result="blur"/>
                <feComposite in="SourceGraphic" in2="blur" operator="over"/>
             </filter>
             <linearGradient id="grad-online" x1="0%" y1="0%" x2="100%" y2="0%">
                <stop offset="0%" stopColor="rgba(34, 197, 94, 0)" />
                <stop offset="100%" stopColor="rgba(34, 197, 94, 1)" />
             </linearGradient>
             <linearGradient id="grad-warning" x1="0%" y1="0%" x2="100%" y2="0%">
                <stop offset="0%" stopColor="rgba(234, 179, 8, 0)" />
                <stop offset="100%" stopColor="rgba(234, 179, 8, 1)" />
             </linearGradient>
             <linearGradient id="grad-error" x1="0%" y1="0%" x2="100%" y2="0%">
                <stop offset="0%" stopColor="rgba(239, 68, 68, 0)" />
                <stop offset="100%" stopColor="rgba(239, 68, 68, 1)" />
             </linearGradient>

             <marker id="arrow-online" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="4" markerHeight="4" orient="auto">
                <path d="M 0 0 L 10 5 L 0 10 z" fill="#22c55e" opacity="0.6" />
             </marker>
             <marker id="arrow-warning" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="4" markerHeight="4" orient="auto">
                <path d="M 0 0 L 10 5 L 0 10 z" fill="#eab308" opacity="0.6" />
             </marker>
             <marker id="arrow-error" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="4" markerHeight="4" orient="auto">
                <path d="M 0 0 L 10 5 L 0 10 z" fill="#ef4444" opacity="0.6" />
             </marker>
          </defs>

          {connections.map((conn) => {
            const points = getConnectionPoint(conn.sourceId, conn.targetId);
            if (!points) return null;
            const { start, end } = points;
            const status = conn.status || 'online';
            const bezierPath = getBezierPath(start, end);

            // 根据状态选择颜色
            const statusColor = status === 'online' ? '#22c55e' : status === 'warning' ? '#eab308' : '#ef4444';

            return (
              <g key={conn.id}>
                {/* 1. 基础链路轨道：深色低透明度 */}
                <path 
                  d={bezierPath} 
                  stroke={statusColor} 
                  strokeWidth="1.5" 
                  fill="none" 
                  className="opacity-10"
                  markerEnd={`url(#arrow-${status})`}
                />

                {/* 2. 心跳脉冲信号 */}
                <path 
                  d={bezierPath} 
                  stroke={statusColor} 
                  strokeWidth="3" 
                  fill="none"
                  filter="url(#neon-glow)"
                  className="connection-heartbeat" 
                  style={{ 
                    animationDuration: `${Math.max(0.5, 4 - conn.trafficLoad * 3.5)}s`,
                    color: statusColor
                  }}
                />

                {/* 3. 可选：标签文本 */}
                <text 
                   className="text-[8px] font-black tracking-widest opacity-30" 
                   fill={statusColor} 
                   dy="-5"
                >
                   <textPath href={`#path-${conn.id}`} startOffset="50%" textAnchor="middle">
                      {conn.label}
                   </textPath>
                </text>
                {/* 为 textPath 提供路径引用 */}
                <path id={`path-${conn.id}`} d={bezierPath} fill="none" />
              </g>
            );
          })}
        </svg>

        {/* 节点层 */}
        {nodes.map((node) => {
          const isSelected = selectedId === node.id;
          const statusConfig = getStatusConfig(node.status);
          return (
            <div
              key={node.id}
              style={{ left: node.position.x, top: node.position.y, width: '120px', height: '40px', pointerEvents: 'auto' }}
              className="absolute z-10 flex flex-col items-center group/node"
            >
              <div
                className={`w-full h-full node-button rounded-lg shadow-2xl flex items-center justify-center relative ${getStrobeClass(node.status)} ${
                  isSelected ? 'ring-4 ring-white/60 scale-105 z-20' : ''
                } ${isLocked ? 'cursor-default' : 'cursor-pointer hover:scale-105'}`}
                onClick={(e) => { e.stopPropagation(); onElementClick(node.id); }}
                onMouseDown={(e) => {
                  if (mode === 'select' && !isLocked) {
                    e.stopPropagation();
                    setDraggingId(node.id);
                    setDragType('node');
                  }
                }}
              >
                <div className="flex items-center gap-2 pointer-events-none px-2 mb-1">
                  <i className={`fas ${SERVICE_ICONS[node.type]} text-xs text-white`}></i>
                  <span className="text-[10px] font-black text-white uppercase tracking-tighter truncate">{node.name}</span>
                </div>
                <div className={`absolute -bottom-2 left-1/2 -translate-x-1/2 px-2 py-0.5 rounded-full text-[7px] font-black bg-slate-950 border ${statusConfig.border} backdrop-blur-md shadow-xl transition-transform ${statusConfig.color} tracking-[0.2em] uppercase whitespace-nowrap z-20`}>
                  {statusConfig.text}
                </div>
              </div>
            </div>
          );
        })}
      </div>

      {/* 坐标系信息 */}
      <div className="absolute bottom-10 right-10 pointer-events-none opacity-40">
        <div className="flex flex-col items-end gap-1">
          <span className="text-[9px] font-black text-sky-500 uppercase tracking-tighter">拓扑引擎: SVG_HEARTBEAT_V3</span>
          <span className="text-[8px] text-slate-500 underline decoration-sky-500/30 decoration-2 underline-offset-4">状态感知链路已就绪</span>
        </div>
      </div>
    </div>
  );
};

