import React, { useRef, useState, useMemo } from 'react';
import { ServiceNode, Connection, GroupNode } from '../types';
import { SERVICE_ICONS } from '../constants';

interface WorkspaceProps {
  nodes: ServiceNode[];
  groups: GroupNode[];
  connections: Connection[];
  selectedId: string | null;
  selectedConnectionId: string | null;
  onElementClick: (id: string) => void;
  onConnectionClick: (id: string) => void;
  onNodeMove: (id: string, x: number, y: number) => void;
  onUpdateGroup: (id: string, updates: Partial<GroupNode>) => void;
  onDeleteGroup: (id: string) => void;
  onDeleteNode: (id: string) => void;
  mode: string;
  isLocked: boolean;
}

const Workspace: React.FC<WorkspaceProps> = ({ 
  nodes, groups, connections, selectedId, selectedConnectionId,
  onElementClick, onConnectionClick, onNodeMove, onUpdateGroup, onDeleteGroup, onDeleteNode,
  mode, isLocked
}) => {
  const containerRef = useRef<HTMLDivElement>(null);

  const [viewOffset, setViewOffset] = useState({ x: 0, y: 0 });
  const [isPanning, setIsPanning] = useState(false);
  const [lastMousePos, setLastMousePos] = useState({ x: 0, y: 0 });

  const [draggingId, setDraggingId] = useState<string | null>(null);
  const [resizingId, setResizingId] = useState<string | null>(null);
  const [dragType, setDragType] = useState<'node' | 'group' | 'resize' | 'scroll-h' | 'scroll-v'>('node');

  const contentBounds = useMemo(() => {
    let minX = 0, maxX = 1200, minY = 0, maxY = 800;
    nodes.forEach(n => { minX = Math.min(minX, n.position.x - 200); maxX = Math.max(maxX, n.position.x + 300); });
    groups.forEach(g => { minX = Math.min(minX, g.position.x - 200); maxX = Math.max(maxX, g.position.x + g.size.width + 300); });
    return { minX, maxX, minY, maxY, width: maxX - minX, height: maxY - minY };
  }, [nodes, groups]);

  const handleMouseDown = (e: React.MouseEvent) => {
    if (!containerRef.current) return;
    if (e.target === containerRef.current) {
      setIsPanning(true);
      setLastMousePos({ x: e.clientX, y: e.clientY });
    }
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (!containerRef.current) return;
    const rect = containerRef.current.getBoundingClientRect();

    if (isPanning) {
      const dx = e.clientX - lastMousePos.x;
      const dy = e.clientY - lastMousePos.y;
      setViewOffset(prev => ({ x: prev.x + dx, y: prev.y + dy }));
      setLastMousePos({ x: e.clientX, y: e.clientY });
      return;
    }

    if (draggingId === 'scrollbar-h' || draggingId === 'scrollbar-v') {
      if (draggingId === 'scrollbar-h') {
        const ratio = (e.clientX - rect.left) / rect.width;
        setViewOffset(prev => ({ ...prev, x: -(contentBounds.minX + ratio * contentBounds.width - rect.width / 2) }));
      } else {
        const ratio = (e.clientY - rect.top) / rect.height;
        setViewOffset(prev => ({ ...prev, y: -(contentBounds.minY + ratio * contentBounds.height - rect.height / 2) }));
      }
      return;
    }

    if (mode !== 'select' || isLocked) return;
    const x = e.clientX - rect.left - viewOffset.x;
    const y = e.clientY - rect.top - viewOffset.y;

    if (draggingId && dragType === 'node') {
      onNodeMove(draggingId, x - 60, y - 20);
    } else if (draggingId && dragType === 'group') {
      const group = groups.find(g => g.id === draggingId);
      if (group) onUpdateGroup(draggingId, { position: { x: x - group.size.width / 2, y: y - 16 } });
    } else if (resizingId) {
      const group = groups.find(g => g.id === resizingId);
      if (group) onUpdateGroup(resizingId, { size: { width: Math.max(200, x - group.position.x), height: Math.max(150, y - group.position.y) } });
    }
  };

  const handleMouseUp = () => { setIsPanning(false); setDraggingId(null); setResizingId(null); };

  const getScrollStyles = () => {
    if (!containerRef.current) return { h: { left: 0, width: 0 }, v: { top: 0, height: 0 } };
    const { width: viewW, height: viewH } = containerRef.current.getBoundingClientRect();
    const hThumbW = Math.max(40, (viewW / contentBounds.width) * viewW);
    const hThumbL = ((-viewOffset.x - contentBounds.minX) / contentBounds.width) * viewW;
    const vThumbH = Math.max(40, (viewH / contentBounds.height) * viewH);
    const vThumbT = ((-viewOffset.y - contentBounds.minY) / contentBounds.height) * viewH;
    return { h: { left: Math.max(0, Math.min(viewW - hThumbW, hThumbL)), width: hThumbW }, v: { top: Math.max(0, Math.min(viewH - vThumbH, vThumbT)), height: vThumbH } };
  };

  const scrollStyles = getScrollStyles();

  const getStrobeClass = (status: string) => {
    switch(status) {
      case 'online': return 'animate-strobe-green';
      case 'warning': return 'animate-strobe-yellow';
      case 'error': return 'animate-strobe-red';
      default: return 'animate-strobe-green';
    }
  };

  const getStatusConfig = (status: string) => {
    switch(status) {
      case 'online': return { text: '正常', color: 'text-emerald-400', border: 'border-emerald-500/50', glow: 'shadow-[inset_0_0_20px_rgba(52,211,153,0.1)]' };
      case 'warning': return { text: '告警', color: 'text-amber-400', border: 'border-amber-500/50', glow: 'shadow-[inset_0_0_20px_rgba(251,191,36,0.1)]' };
      case 'error': return { text: '故障', color: 'text-rose-400', border: 'border-rose-500/50', glow: 'shadow-[inset_0_0_20px_rgba(244,63,94,0.15)]' };
      default: return { text: '正常', color: 'text-emerald-400', border: 'border-emerald-500/50', glow: 'shadow-[inset_0_0_20px_rgba(52,211,153,0.1)]' };
    }
  };

  const getElementInfo = (id: string) => {
    const node = nodes.find(n => n.id === id);
    if (node) return { x: node.position.x, y: node.position.y, w: 120, h: 40, cx: node.position.x + 60, cy: node.position.y + 20 };
    const group = groups.find(g => g.id === id);
    if (group) return { x: group.position.x, y: group.position.y, w: group.size.width, h: group.size.height, cx: group.position.x + group.size.width / 2, cy: group.position.y + group.size.height / 2 };
    return null;
  };

  const getConnectionPoint = (sourceId: string, targetId: string) => {
    const s = getElementInfo(sourceId);
    const t = getElementInfo(targetId);
    if (!s || !t) return null;
    const getIntersection = (rect: any, otherCenter: {x: number, y: number}) => {
      const dx = otherCenter.x - rect.cx;
      const dy = otherCenter.y - rect.cy;
      const hw = rect.w / 2;
      const hh = rect.h / 2;
      const scale = Math.min(dx !== 0 ? Math.abs(hw / dx) : Infinity, dy !== 0 ? Math.abs(hh / dy) : Infinity);
      return { x: rect.cx + dx * scale, y: rect.cy + dy * scale };
    };
    return { start: getIntersection(s, { x: t.cx, y: t.cy }), end: getIntersection(t, { x: s.cx, y: s.cy }) };
  };

  const getBezierPath = (start: {x: number, y: number}, end: {x: number, y: number}) => {
    const dx = Math.abs(end.x - start.x);
    const dy = Math.abs(end.y - start.y);
    const horizontal = dx > dy;
    const ctrl1 = horizontal ? { x: start.x + dx / 3, y: start.y } : { x: start.x, y: start.y + dy / 3 };
    const ctrl2 = horizontal ? { x: end.x - dx / 3, y: end.y } : { x: end.x, y: end.y - dy / 3 };
    return `M ${start.x} ${start.y} C ${ctrl1.x} ${ctrl1.y}, ${ctrl2.x} ${ctrl2.y}, ${end.x} ${end.y}`;
  };

  const gridBackground = useMemo(() => ({
    backgroundImage: `
      linear-gradient(to right, rgba(14, 165, 233, 0.05) 1px, transparent 1px),
      linear-gradient(to bottom, rgba(14, 165, 233, 0.05) 1px, transparent 1px)
    `,
    backgroundSize: '100px 100px',
    backgroundPosition: `${viewOffset.x}px ${viewOffset.y}px`
  }), [viewOffset]);

  return (
    <div 
      ref={containerRef} style={gridBackground}
      className={`w-full h-full relative select-none overflow-hidden ${isPanning ? 'cursor-grabbing' : 'cursor-default'}`}
      onMouseDown={handleMouseDown} onMouseMove={handleMouseMove} onMouseUp={handleMouseUp} onMouseLeave={handleMouseUp}
    >
      <div style={{ transform: `translate(${viewOffset.x}px, ${viewOffset.y}px)`, position: 'absolute', inset: 0, pointerEvents: 'none' }}>
        {/* 集群容器层 */}
        {groups.map((group) => {
          const isSelected = selectedId === group.id;
          return (
            <div
              key={group.id}
              style={{ left: group.position.x, top: group.position.y, width: group.size.width, height: group.size.height, pointerEvents: 'auto' }}
              className={`absolute group/container z-0 ${isLocked ? 'pointer-events-auto' : 'cursor-move'}`}
              onClick={(e) => { e.stopPropagation(); onElementClick(group.id); }}
              onMouseDown={(e) => { if (mode === 'select' && !isLocked) { e.stopPropagation(); setDraggingId(group.id); setDragType('group'); } }}
            >
              <div className={`absolute inset-0 rounded-2xl bg-slate-900/40 backdrop-blur-md border transition-all ${isSelected ? 'border-sky-500 ring-2 ring-sky-500/20' : 'border-slate-700/30'} ${getStrobeClass(group.status)}`}></div>
              <div className="absolute top-0 left-0 right-0 h-8 px-4 flex items-center justify-between pointer-events-none">
                <span className="text-[10px] font-black text-slate-400 tracking-widest">{group.name}</span>
                <div className={`text-[8px] font-black px-2 py-0.5 rounded bg-slate-900 border ${getStatusConfig(group.status).border} ${getStatusConfig(group.status).color}`}>{getStatusConfig(group.status).text}</div>
              </div>
              {!isLocked && (
                <div className="absolute bottom-1 right-1 w-6 h-6 cursor-nwse-resize opacity-40 hover:opacity-100" onMouseDown={(e) => { e.stopPropagation(); setResizingId(group.id); }}>
                  <div className="w-3 h-3 border-r-2 border-b-2 border-sky-400/80 rounded-br-sm"></div>
                </div>
              )}
            </div>
          );
        })}

        {/* 拓扑连线层 */}
        <svg className="absolute inset-0 w-full h-full pointer-events-none z-[5]">
          <defs>
             <filter id="neon-glow" x="-100%" y="-100%" width="300%" height="300%"><feGaussianBlur stdDeviation="4" result="blur"/><feComposite in="SourceGraphic" in2="blur" operator="over"/></filter>
          </defs>
          {connections.map((conn) => {
            const points = getConnectionPoint(conn.sourceId, conn.targetId);
            if (!points) return null;
            const isSelected = selectedConnectionId === conn.id;
            const statusColor = conn.status === 'error' ? '#ef4444' : '#22c55e';
            const bezierPath = getBezierPath(points.start, points.end);
            const textPathD = points.end.x < points.start.x ? getBezierPath(points.end, points.start) : bezierPath;

            return (
              <g key={conn.id}>
                <path d={bezierPath} stroke="transparent" strokeWidth="20" fill="none" className="cursor-pointer pointer-events-auto" onClick={(e) => { e.stopPropagation(); onConnectionClick(conn.id); }} />
                <path d={bezierPath} stroke={statusColor} strokeWidth={isSelected ? "3" : "2"} fill="none" filter="url(#neon-glow)" className="connection-heartbeat transition-all" style={{ animationDuration: `${Math.max(0.4, 3.5 - conn.trafficLoad * 3)}s`, strokeOpacity: isSelected ? 1 : 0.6 } as React.CSSProperties} />
                <text className={`text-[8px] font-black tracking-widest ${isSelected ? 'opacity-100' : 'opacity-40'}`} fill={statusColor} dy="-8">
                   <textPath href={`#path-text-${conn.id}`} startOffset="50%" textAnchor="middle">{conn.label}</textPath>
                </text>
                <path id={`path-text-${conn.id}`} d={textPathD} fill="none" />
              </g>
            );
          })}
        </svg>

        {/* 服务节点层 */}
        {nodes.map((node) => {
          const isSelected = selectedId === node.id;
          const statusConfig = getStatusConfig(node.status);
          return (
            <div key={node.id} style={{ left: node.position.x, top: node.position.y, width: '120px', height: '40px', pointerEvents: 'auto' }} className="absolute z-10 flex flex-col items-center">
              <div className={`w-full h-full node-button rounded-lg shadow-2xl flex items-center justify-center relative ${getStrobeClass(node.status)} ${isSelected ? 'ring-4 ring-white/60 scale-105 z-20' : ''} ${isLocked ? 'cursor-default' : 'cursor-pointer hover:scale-105'}`} onClick={(e) => { e.stopPropagation(); onElementClick(node.id); }} onMouseDown={(e) => { if (mode === 'select' && !isLocked) { e.stopPropagation(); setDraggingId(node.id); setDragType('node'); } }}>
                <div className="flex items-center gap-2 pointer-events-none px-2 mb-1">
                  <i className={`fas ${SERVICE_ICONS[node.type]} text-xs text-white`}></i>
                  <span className="text-[10px] font-black text-white tracking-tighter truncate">{node.name}</span>
                </div>
                <div className={`absolute -bottom-2 left-1/2 -translate-x-1/2 px-2 py-0.5 rounded-full text-[7px] font-black bg-slate-950 border ${statusConfig.border} ${statusConfig.color} tracking-[0.2em] uppercase z-20`}>{statusConfig.text}</div>
              </div>
            </div>
          );
        })}
      </div>

      {/* 滚动条组件 (H) */}
      <div className="absolute bottom-1 left-4 right-4 h-1.5 bg-slate-900/50 rounded-full cursor-pointer z-[50]" onMouseDown={(e) => { e.stopPropagation(); setDraggingId('scrollbar-h'); }}>
        <div className="absolute h-full bg-sky-500/30 border border-sky-400/50 rounded-full" style={{ left: `${scrollStyles.h.left}px`, width: `${scrollStyles.h.width}px` }} />
      </div>

      {/* 滚动条组件 (V) */}
      <div className="absolute top-4 bottom-4 right-1 w-1.5 bg-slate-900/50 rounded-full cursor-pointer z-[50]" onMouseDown={(e) => { e.stopPropagation(); setDraggingId('scrollbar-v'); }}>
        <div className="absolute w-full bg-sky-500/30 border border-sky-400/50 rounded-full" style={{ top: `${scrollStyles.v.top}px`, height: `${scrollStyles.v.height}px` }} />
      </div>
    </div>
  );
};

export default Workspace;

export enum ServiceType {
  DATABASE = 'database',
  SERVER = 'server',
  GATEWAY = 'gateway',
  CACHE = 'cache',
  LOAD_BALANCER = 'load_balancer',
  FIREWALL = 'firewall',
  CONTAINER = 'container'
}

export interface Vector3Array {
  x: number;
  y: number;
  z: number;
}

export interface ServiceNode {
  id: string;
  name: string;
  type: ServiceType;
  position: Vector3Array;
  status: 'online' | 'warning' | 'error';
  lastUpdated: string;
}

export interface GroupNode {
  id: string;
  name: string;
  position: { x: number; y: number };
  size: { width: number; height: number };
  color: string;
  status: 'online' | 'warning' | 'error';
}

export interface Connection {
  id: string;
  sourceId: string;
  targetId: string;
  label: string;
  trafficLoad: number; // 0-1
  status?: 'online' | 'warning' | 'error';
}

export interface AppState {
  nodes: ServiceNode[];
  groups: GroupNode[];
  connections: Connection[];
  selectedNodeId: string | null;
  mode: 'select' | 'add' | 'connect';
}

import React, { useState, useCallback, useEffect, useRef } from 'react';
import Sidebar from './components/Sidebar';
import UIOverlay from './components/UIOverlay';
import Workspace from './components/Workspace';
import { ServiceNode, Connection, ServiceType, GroupNode } from './types';
import { suggestLayout } from './geminiService';

const STORAGE_KEY = 'NEOOPS_LAYOUT_DATA';

const App: React.FC = () => {
  const [nodes, setNodes] = useState<ServiceNode[]>([]);
  const [groups, setGroups] = useState<GroupNode[]>([]);
  const [connections, setConnections] = useState<Connection[]>([]);
  const [toast, setToast] = useState<{ message: string; visible: boolean }>({ message: '', visible: false });

  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [selectedConnectionId, setSelectedConnectionId] = useState<string | null>(null);
  const [mode, setMode] = useState<'select' | 'add' | 'connect'>('select');
  const [isLocked, setIsLocked] = useState(false);
  const [connectSourceId, setConnectSourceId] = useState<string | null>(null);
  const [isAnalyzing, setIsAnalyzing] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const savedData = localStorage.getItem(STORAGE_KEY);
    if (savedData) {
      try {
        const parsed = JSON.parse(savedData);
        setNodes(parsed.nodes || []);
        setGroups(parsed.groups || []);
        setConnections(parsed.connections || []);
        showToast("检测到本地存档，已自动加载配置");
      } catch (e) {
        console.error("Failed to load layout", e);
      }
    } else {
      setNodes([
        { id: '1', name: 'UserGateway', type: ServiceType.GATEWAY, position: { x: 150, y: 250, z: 0 }, status: 'online', lastUpdated: new Date().toISOString() },
        { id: '2', name: 'AuthService', type: ServiceType.SERVER, position: { x: 450, y: 200, z: 0 }, status: 'online', lastUpdated: new Date().toISOString() },
        { id: '3', name: 'ProductDB', type: ServiceType.DATABASE, position: { x: 750, y: 350, z: 0 }, status: 'warning', lastUpdated: new Date().toISOString() },
      ]);
      setGroups([
        { id: 'g1', name: 'ProdCluster_A', position: { x: 100, y: 150 }, size: { width: 500, height: 350 }, color: '#38bdf8', status: 'online' }
      ]);
      setConnections([
        { id: 'c1', sourceId: '1', targetId: '2', label: 'HTTP-Auth', trafficLoad: 0.4, status: 'online' },
        { id: 'c2', sourceId: '2', targetId: '3', label: 'SQL-Query', trafficLoad: 0.8, status: 'online' },
      ]);
    }
  }, []);

  const showToast = (message: string) => {
    setToast({ message, visible: true });
    setTimeout(() => setToast({ message: '', visible: false }), 3000);
  };

  const handleSaveLayout = useCallback(() => {
    const dataToSave = { nodes, groups, connections };
    localStorage.setItem(STORAGE_KEY, JSON.stringify(dataToSave));
    showToast("当前拓扑布局已保存至本地");
  }, [nodes, groups, connections]);

  const handleExportConfig = useCallback(() => {
    const data = { nodes, groups, connections, timestamp: new Date().toISOString() };
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `neoops-config-${new Date().getTime()}.json`;
    link.click();
    URL.revokeObjectURL(url);
    showToast("配置文件已下载");
  }, [nodes, groups, connections]);

  const handleImportConfig = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const parsed = JSON.parse(event.target?.result as string);
        if (parsed.nodes && parsed.connections) {
          setNodes(parsed.nodes);
          setGroups(parsed.groups || []);
          setConnections(parsed.connections);
          showToast("外部配置导入成功");
        }
      } catch (err) {
        showToast("无效的配置文件格式");
      }
    };
    reader.readAsText(file);
    if (fileInputRef.current) fileInputRef.current.value = '';
  }, []);

  const toggleLock = useCallback(() => {
    setIsLocked(prev => !prev);
    if (!isLocked) {
      handleSaveLayout();
      showToast("布局已保存并锁定");
    } else {
      showToast("编辑模式已解锁");
    }
  }, [isLocked, handleSaveLayout]);

  const addNode = useCallback((type: ServiceType, name: string, status: 'online' | 'warning' | 'error' = 'online') => {
    if (isLocked) return;
    const newNode: ServiceNode = {
      id: `node-${Date.now()}`,
      name,
      type,
      position: { x: 200, y: 200, z: 0 },
      status,
      lastUpdated: new Date().toISOString()
    };
    setNodes(prev => [...prev, newNode]);
  }, [isLocked]);

  const addGroup = useCallback((name: string, status: 'online' | 'warning' | 'error' = 'online') => {
    if (isLocked) return;
    const newGroup: GroupNode = {
      id: `group-${Date.now()}`,
      name,
      position: { x: 200, y: 200 },
      size: { width: 400, height: 300 },
      color: '#818cf8',
      status: status
    };
    setGroups(prev => [...prev, newGroup]);
  }, [isLocked]);

  const updateGroup = useCallback((id: string, updates: Partial<GroupNode>) => {
    if (isLocked) return;
    setGroups(prev => prev.map(g => g.id === id ? { ...g, ...updates } : g));
  }, [isLocked]);

  const deleteGroup = useCallback((id: string) => {
    if (isLocked) return;
    setGroups(prev => prev.filter(g => g.id !== id));
    setConnections(prev => prev.filter(c => c.sourceId !== id && c.targetId !== id));
    setSelectedId(null);
  }, [isLocked]);

  const deleteNode = useCallback((id: string) => {
    if (isLocked) return;
    setNodes(prev => prev.filter(n => n.id !== id));
    setConnections(prev => prev.filter(c => c.sourceId !== id && c.targetId !== id));
    setSelectedId(null);
  }, [isLocked]);

  const updateConnection = useCallback((id: string, updates: Partial<Connection>) => {
    if (isLocked) return;
    setConnections(prev => prev.map(c => c.id === id ? { ...c, ...updates } : c));
  }, [isLocked]);

  const deleteConnection = useCallback((id: string) => {
    if (isLocked) return;
    setConnections(prev => prev.filter(c => c.id !== id));
    setSelectedConnectionId(null);
  }, [isLocked]);

  const handleElementInteraction = useCallback((id: string) => {
    if (mode === 'connect' && !isLocked) {
      if (!connectSourceId) {
        setConnectSourceId(id);
      } else if (connectSourceId !== id) {
        setConnections(prev => [...prev, {
          id: `c-${Date.now()}`,
          sourceId: connectSourceId,
          targetId: id,
          label: 'NewLink',
          trafficLoad: 0.2,
          status: 'online'
        }]);
        setConnectSourceId(null);
        setMode('select');
      }
    } else {
      setSelectedId(id === selectedId ? null : id);
      setSelectedConnectionId(null);
    }
  }, [mode, connectSourceId, selectedId, isLocked]);

  const handleConnectionClick = useCallback((id: string) => {
    if (mode === 'select') {
      setSelectedConnectionId(id === selectedConnectionId ? null : id);
      setSelectedId(null);
    }
  }, [mode, selectedConnectionId]);

  const updateNodePosition = useCallback((id: string, x: number, y: number) => {
    if (isLocked) return;
    setNodes(prev => prev.map(n => n.id === id ? { ...n, position: { ...n.position, x, y } } : n));
  }, [isLocked]);

  const handleAutoLayout = async (desc: string) => {
    if (!desc || isLocked) return;
    setIsAnalyzing(true);
    try {
        const layout = await suggestLayout(desc);
        const newNodes: ServiceNode[] = layout.nodes.map((n: any, i: number) => ({
            id: `ai-node-${i}-${Date.now()}`,
            name: n.name,
            type: n.type as ServiceType,
            position: { x: (n.x + 10) * 40, y: (n.y + 10) * 30, z: 0 },
            status: 'online',
            lastUpdated: new Date().toISOString()
        }));

        const newConns: Connection[] = layout.connections.map((c: any, i: number) => ({
            id: `ai-conn-${i}-${Date.now()}`,
            sourceId: newNodes[c.sourceIndex].id,
            targetId: newNodes[c.targetIndex].id,
            label: c.label,
            trafficLoad: Math.random() * 0.5,
            status: 'online'
        }));

        setNodes(newNodes);
        setConnections(newConns);
    } catch (e) {
        console.error("AI Layout failed", e);
    }
    setIsAnalyzing(false);
  };

  const getActiveSourceLabel = () => {
    if (!connectSourceId) return null;
    const node = nodes.find(n => n.id === connectSourceId);
    if (node) return node.name;
    const group = groups.find(g => g.id === connectSourceId);
    if (group) return group.name;
    return "Unknown";
  };

  return (
    <div className="flex h-screen w-screen bg-slate-950 text-slate-100 overflow-hidden font-sans">
      <style>{`
        @keyframes strobe-green {
          0%, 100% { background-color: rgba(34, 197, 94, 0.08); box-shadow: 0 0 20px rgba(34, 197, 94, 0.1), inset 0 0 10px rgba(34, 197, 94, 0.05); border-color: rgba(34, 197, 94, 0.4); }
          50% { background-color: rgba(34, 197, 94, 0.02); box-shadow: 0 0 5px rgba(34, 197, 94, 0.02); border-color: rgba(34, 197, 94, 0.1); }
        }
        @keyframes strobe-yellow {
          0%, 100% { background-color: rgba(234, 179, 8, 0.15); box-shadow: 0 0 30px rgba(234, 179, 8, 0.2); border-color: rgba(234, 179, 8, 0.6); }
          50% { background-color: rgba(234, 179, 8, 0.05); box-shadow: 0 0 10px rgba(234, 179, 8, 0.05); border-color: rgba(234, 179, 8, 0.2); }
        }
        @keyframes strobe-red {
          0%, 100% { background-color: rgba(239, 68, 68, 0.2); box-shadow: 0 0 40px rgba(239, 68, 68, 0.4); border-color: rgba(239, 68, 68, 0.8); }
          50% { background-color: rgba(239, 68, 68, 0.03); box-shadow: 0 0 10px rgba(239, 68, 68, 0.1); border-color: rgba(239, 68, 68, 0.2); }
        }
        @keyframes scan-line {
          0% { transform: translateY(-100%); opacity: 0; }
          50% { opacity: 0.1; }
          100% { transform: translateY(100%); opacity: 0; }
        }
        @keyframes signal-flow {
          0% { stroke-dashoffset: 400; }
          100% { stroke-dashoffset: 0; }
        }
        .animate-strobe-green { animation: strobe-green 4s ease-in-out infinite; }
        .animate-strobe-yellow { animation: strobe-yellow 2.5s ease-in-out infinite; }
        .animate-strobe-red { animation: strobe-red 1.2s ease-in-out infinite; }
        .scan-effect { animation: scan-line 6s linear infinite; }

        .connection-heartbeat {
          stroke-dasharray: 60, 340;
          animation: signal-flow 3s linear infinite;
          stroke-linecap: round;
        }
      `}</style>

      {toast.visible && (
        <div className="fixed top-6 right-6 z-[100] bg-slate-900 border border-sky-500/50 px-6 py-3 rounded-xl shadow-[0_0_30px_rgba(14,165,233,0.2)] flex items-center gap-4 animate-in fade-in slide-in-from-top-4">
          <div className="w-2 h-2 rounded-full bg-sky-500 animate-ping"></div>
          <span className="text-xs font-black text-sky-400 uppercase tracking-widest">{toast.message}</span>
        </div>
      )}

      <input type="file" ref={fileInputRef} onChange={handleImportConfig} className="hidden" accept=".json" />

      <Sidebar 
        nodes={nodes} groups={groups} connections={connections}
        selectedId={selectedId} selectedConnectionId={selectedConnectionId}
        addNode={addNode} addGroup={addGroup} deleteNode={deleteNode} deleteGroup={deleteGroup}
        deleteConnection={deleteConnection} updateConnection={updateConnection}
        isAnalyzing={isAnalyzing} onAutoLayout={handleAutoLayout} isLocked={isLocked}
        onExport={handleExportConfig} onImport={() => fileInputRef.current?.click()}
      />

      <main className="flex-1 relative overflow-hidden bg-[radial-gradient(circle_at_center,_#1e293b_0%,_#020617_100%)]">
        <UIOverlay mode={mode} setMode={setMode} connectSource={getActiveSourceLabel()} isLocked={isLocked} setIsLocked={toggleLock} />

        <Workspace 
          nodes={nodes} groups={groups} connections={connections}
          selectedId={selectedId} selectedConnectionId={selectedConnectionId}
          onElementClick={handleElementInteraction} onConnectionClick={handleConnectionClick}
          onNodeMove={updateNodePosition} onUpdateGroup={updateGroup}
          onDeleteGroup={deleteGroup} onDeleteNode={deleteNode} mode={mode} isLocked={isLocked}
        />

        {isAnalyzing && (
            <div className="absolute inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-md">
                <div className="bg-slate-900 p-8 rounded-2xl shadow-2xl border border-sky-500/50 flex flex-col items-center">
                    <div className="w-16 h-16 border-4 border-sky-500 border-t-transparent rounded-full animate-spin mb-4"></div>
                    <h3 className="text-xl font-bold text-sky-400 font-mono tracking-widest text-center">AI_SYNTHESIZING...</h3>
                </div>
            </div>
        )}
      </main>
    </div>
  );
};

export default App;

import React, { useRef, useState, useMemo } from 'react';
import { ServiceNode, Connection, GroupNode } from '../types';
import { SERVICE_ICONS } from '../constants';

interface WorkspaceProps {
  nodes: ServiceNode[];
  groups: GroupNode[];
  connections: Connection[];
  selectedId: string | null;
  selectedConnectionId: string | null;
  onElementClick: (id: string) => void;
  onConnectionClick: (id: string) => void;
  onNodeMove: (id: string, x: number, y: number) => void;
  onUpdateGroup: (id: string, updates: Partial<GroupNode>) => void;
  onDeleteGroup: (id: string) => void;
  onDeleteNode: (id: string) => void;
  mode: string;
  isLocked: boolean;
}

const Workspace: React.FC<WorkspaceProps> = ({ 
  nodes, groups, connections, selectedId, selectedConnectionId,
  onElementClick, onConnectionClick, onNodeMove, onUpdateGroup, onDeleteGroup, onDeleteNode,
  mode, isLocked
}) => {
  const containerRef = useRef<HTMLDivElement>(null);

  const [viewOffset, setViewOffset] = useState({ x: 0, y: 0 });
  const [isPanning, setIsPanning] = useState(false);
  const [lastMousePos, setLastMousePos] = useState({ x: 0, y: 0 });

  const [draggingId, setDraggingId] = useState<string | null>(null);
  const [resizingId, setResizingId] = useState<string | null>(null);
  const [dragType, setDragType] = useState<'node' | 'group' | 'resize' | 'scroll-h' | 'scroll-v'>('node');

  const contentBounds = useMemo(() => {
    let minX = 0, maxX = 1200, minY = 0, maxY = 800;
    nodes.forEach(n => { minX = Math.min(minX, n.position.x - 200); maxX = Math.max(maxX, n.position.x + 300); });
    groups.forEach(g => { minX = Math.min(minX, g.position.x - 200); maxX = Math.max(maxX, g.position.x + g.size.width + 300); });
    return { minX, maxX, minY, maxY, width: maxX - minX, height: maxY - minY };
  }, [nodes, groups]);

  const handleMouseDown = (e: React.MouseEvent) => {
    if (!containerRef.current) return;
    if (e.target === containerRef.current) {
      setIsPanning(true);
      setLastMousePos({ x: e.clientX, y: e.clientY });
    }
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (!containerRef.current) return;
    const rect = containerRef.current.getBoundingClientRect();

    if (isPanning) {
      const dx = e.clientX - lastMousePos.x;
      const dy = e.clientY - lastMousePos.y;
      setViewOffset(prev => ({ x: prev.x + dx, y: prev.y + dy }));
      setLastMousePos({ x: e.clientX, y: e.clientY });
      return;
    }

    if (draggingId === 'scrollbar-h' || draggingId === 'scrollbar-v') {
      if (draggingId === 'scrollbar-h') {
        const ratio = (e.clientX - rect.left) / rect.width;
        setViewOffset(prev => ({ ...prev, x: -(contentBounds.minX + ratio * contentBounds.width - rect.width / 2) }));
      } else {
        const ratio = (e.clientY - rect.top) / rect.height;
        setViewOffset(prev => ({ ...prev, y: -(contentBounds.minY + ratio * contentBounds.height - rect.height / 2) }));
      }
      return;
    }

    if (mode !== 'select' || isLocked) return;
    const x = e.clientX - rect.left - viewOffset.x;
    const y = e.clientY - rect.top - viewOffset.y;

    if (draggingId && dragType === 'node') {
      onNodeMove(draggingId, x - 60, y - 20);
    } else if (draggingId && dragType === 'group') {
      const group = groups.find(g => g.id === draggingId);
      if (group) onUpdateGroup(draggingId, { position: { x: x - group.size.width / 2, y: y - 16 } });
    } else if (resizingId) {
      const group = groups.find(g => g.id === resizingId);
      if (group) onUpdateGroup(resizingId, { size: { width: Math.max(200, x - group.position.x), height: Math.max(150, y - group.position.y) } });
    }
  };

  const handleMouseUp = () => { setIsPanning(false); setDraggingId(null); setResizingId(null); };

  const getScrollStyles = () => {
    if (!containerRef.current) return { h: { left: 0, width: 0 }, v: { top: 0, height: 0 } };
    const { width: viewW, height: viewH } = containerRef.current.getBoundingClientRect();
    const hThumbW = Math.max(40, (viewW / contentBounds.width) * viewW);
    const hThumbL = ((-viewOffset.x - contentBounds.minX) / contentBounds.width) * viewW;
    const vThumbH = Math.max(40, (viewH / contentBounds.height) * viewH);
    const vThumbT = ((-viewOffset.y - contentBounds.minY) / contentBounds.height) * viewH;
    return { h: { left: Math.max(0, Math.min(viewW - hThumbW, hThumbL)), width: hThumbW }, v: { top: Math.max(0, Math.min(viewH - vThumbH, vThumbT)), height: vThumbH } };
  };

  const scrollStyles = getScrollStyles();

  const getStrobeClass = (status: string) => {
    switch(status) {
      case 'online': return 'animate-strobe-green';
      case 'warning': return 'animate-strobe-yellow';
      case 'error': return 'animate-strobe-red';
      default: return 'animate-strobe-green';
    }
  };

  const getStatusConfig = (status: string) => {
    switch(status) {
      case 'online': return { text: '正常', color: 'text-emerald-400', border: 'border-emerald-500/50', glow: 'shadow-[inset_0_0_20px_rgba(52,211,153,0.1)]' };
      case 'warning': return { text: '告警', color: 'text-amber-400', border: 'border-amber-500/50', glow: 'shadow-[inset_0_0_20px_rgba(251,191,36,0.1)]' };
      case 'error': return { text: '故障', color: 'text-rose-400', border: 'border-rose-500/50', glow: 'shadow-[inset_0_0_20px_rgba(244,63,94,0.15)]' };
      default: return { text: '正常', color: 'text-emerald-400', border: 'border-emerald-500/50', glow: 'shadow-[inset_0_0_20px_rgba(52,211,153,0.1)]' };
    }
  };

  const getElementInfo = (id: string) => {
    const node = nodes.find(n => n.id === id);
    if (node) return { x: node.position.x, y: node.position.y, w: 120, h: 40, cx: node.position.x + 60, cy: node.position.y + 20 };
    const group = groups.find(g => g.id === id);
    if (group) return { x: group.position.x, y: group.position.y, w: group.size.width, h: group.size.height, cx: group.position.x + group.size.width / 2, cy: group.position.y + group.size.height / 2 };
    return null;
  };

  const getConnectionPoint = (sourceId: string, targetId: string) => {
    const s = getElementInfo(sourceId);
    const t = getElementInfo(targetId);
    if (!s || !t) return null;
    const getIntersection = (rect: any, otherCenter: {x: number, y: number}) => {
      const dx = otherCenter.x - rect.cx;
      const dy = otherCenter.y - rect.cy;
      const hw = rect.w / 2;
      const hh = rect.h / 2;
      const scale = Math.min(dx !== 0 ? Math.abs(hw / dx) : Infinity, dy !== 0 ? Math.abs(hh / dy) : Infinity);
      return { x: rect.cx + dx * scale, y: rect.cy + dy * scale };
    };
    return { start: getIntersection(s, { x: t.cx, y: t.cy }), end: getIntersection(t, { x: s.cx, y: s.cy }) };
  };

  const getBezierPath = (start: {x: number, y: number}, end: {x: number, y: number}) => {
    const dx = Math.abs(end.x - start.x);
    const dy = Math.abs(end.y - start.y);
    const horizontal = dx > dy;
    const ctrl1 = horizontal ? { x: start.x + dx / 3, y: start.y } : { x: start.x, y: start.y + dy / 3 };
    const ctrl2 = horizontal ? { x: end.x - dx / 3, y: end.y } : { x: end.x, y: end.y - dy / 3 };
    return `M ${start.x} ${start.y} C ${ctrl1.x} ${ctrl1.y}, ${ctrl2.x} ${ctrl2.y}, ${end.x} ${end.y}`;
  };

  const gridBackground = useMemo(() => ({
    backgroundImage: `
      linear-gradient(to right, rgba(14, 165, 233, 0.05) 1px, transparent 1px),
      linear-gradient(to bottom, rgba(14, 165, 233, 0.05) 1px, transparent 1px)
    `,
    backgroundSize: '100px 100px',
    backgroundPosition: `${viewOffset.x}px ${viewOffset.y}px`
  }), [viewOffset]);

  return (
    <div 
      ref={containerRef} style={gridBackground}
      className={`w-full h-full relative select-none overflow-hidden ${isPanning ? 'cursor-grabbing' : 'cursor-default'}`}
      onMouseDown={handleMouseDown} onMouseMove={handleMouseMove} onMouseUp={handleMouseUp} onMouseLeave={handleMouseUp}
    >
      <div style={{ transform: `translate(${viewOffset.x}px, ${viewOffset.y}px)`, position: 'absolute', inset: 0, pointerEvents: 'none' }}>
        {/* 集群容器层 */}
        {groups.map((group) => {
          const isSelected = selectedId === group.id;
          return (
            <div
              key={group.id}
              style={{ left: group.position.x, top: group.position.y, width: group.size.width, height: group.size.height, pointerEvents: 'auto' }}
              className={`absolute group/container z-0 ${isLocked ? 'pointer-events-auto' : 'cursor-move'}`}
              onClick={(e) => { e.stopPropagation(); onElementClick(group.id); }}
              onMouseDown={(e) => { if (mode === 'select' && !isLocked) { e.stopPropagation(); setDraggingId(group.id); setDragType('group'); } }}
            >
              <div className={`absolute inset-0 rounded-2xl bg-slate-900/40 backdrop-blur-md border transition-all ${isSelected ? 'border-sky-500 ring-2 ring-sky-500/20' : 'border-slate-700/30'} ${getStrobeClass(group.status)}`}></div>
              <div className="absolute top-0 left-0 right-0 h-8 px-4 flex items-center justify-between pointer-events-none">
                <span className="text-[10px] font-black text-slate-400 tracking-widest">{group.name}</span>
                <div className={`text-[8px] font-black px-2 py-0.5 rounded bg-slate-900 border ${getStatusConfig(group.status).border} ${getStatusConfig(group.status).color}`}>{getStatusConfig(group.status).text}</div>
              </div>
              {!isLocked && (
                <div className="absolute bottom-1 right-1 w-6 h-6 cursor-nwse-resize opacity-40 hover:opacity-100" onMouseDown={(e) => { e.stopPropagation(); setResizingId(group.id); }}>
                  <div className="w-3 h-3 border-r-2 border-b-2 border-sky-400/80 rounded-br-sm"></div>
                </div>
              )}
            </div>
          );
        })}

        {/* 拓扑连线层 */}
        <svg className="absolute inset-0 w-full h-full pointer-events-none z-[5]">
          <defs>
             <filter id="neon-glow" x="-100%" y="-100%" width="300%" height="300%"><feGaussianBlur stdDeviation="4" result="blur"/><feComposite in="SourceGraphic" in2="blur" operator="over"/></filter>
          </defs>
          {connections.map((conn) => {
            const points = getConnectionPoint(conn.sourceId, conn.targetId);
            if (!points) return null;
            const isSelected = selectedConnectionId === conn.id;
            const statusColor = conn.status === 'error' ? '#ef4444' : '#22c55e';
            const bezierPath = getBezierPath(points.start, points.end);
            const textPathD = points.end.x < points.start.x ? getBezierPath(points.end, points.start) : bezierPath;

            return (
              <g key={conn.id}>
                <path d={bezierPath} stroke="transparent" strokeWidth="20" fill="none" className="cursor-pointer pointer-events-auto" onClick={(e) => { e.stopPropagation(); onConnectionClick(conn.id); }} />
                <path d={bezierPath} stroke={statusColor} strokeWidth={isSelected ? "3" : "2"} fill="none" filter="url(#neon-glow)" className="connection-heartbeat transition-all" style={{ animationDuration: `${Math.max(0.4, 3.5 - conn.trafficLoad * 3)}s`, strokeOpacity: isSelected ? 1 : 0.6 } as React.CSSProperties} />
                <text className={`text-[8px] font-black tracking-widest ${isSelected ? 'opacity-100' : 'opacity-40'}`} fill={statusColor} dy="-8">
                   <textPath href={`#path-text-${conn.id}`} startOffset="50%" textAnchor="middle">{conn.label}</textPath>
                </text>
                <path id={`path-text-${conn.id}`} d={textPathD} fill="none" />
              </g>
            );
          })}
        </svg>

        {/* 服务节点层 */}
        {nodes.map((node) => {
          const isSelected = selectedId === node.id;
          const statusConfig = getStatusConfig(node.status);
          return (
            <div key={node.id} style={{ left: node.position.x, top: node.position.y, width: '120px', height: '40px', pointerEvents: 'auto' }} className="absolute z-10 flex flex-col items-center">
              <div className={`w-full h-full node-button rounded-lg shadow-2xl flex items-center justify-center relative ${getStrobeClass(node.status)} ${isSelected ? 'ring-4 ring-white/60 scale-105 z-20' : ''} ${isLocked ? 'cursor-default' : 'cursor-pointer hover:scale-105'}`} onClick={(e) => { e.stopPropagation(); onElementClick(node.id); }} onMouseDown={(e) => { if (mode === 'select' && !isLocked) { e.stopPropagation(); setDraggingId(node.id); setDragType('node'); } }}>
                <div className="flex items-center gap-2 pointer-events-none px-2 mb-1">
                  <i className={`fas ${SERVICE_ICONS[node.type]} text-xs text-white`}></i>
                  <span className="text-[10px] font-black text-white tracking-tighter truncate">{node.name}</span>
                </div>
                <div className={`absolute -bottom-2 left-1/2 -translate-x-1/2 px-2 py-0.5 rounded-full text-[7px] font-black bg-slate-950 border ${statusConfig.border} ${statusConfig.color} tracking-[0.2em] uppercase z-20`}>{statusConfig.text}</div>
              </div>
            </div>
          );
        })}
      </div>

      {/* 滚动条组件 (H) */}
      <div className="absolute bottom-1 left-4 right-4 h-1.5 bg-slate-900/50 rounded-full cursor-pointer z-[50]" onMouseDown={(e) => { e.stopPropagation(); setDraggingId('scrollbar-h'); }}>
        <div className="absolute h-full bg-sky-500/30 border border-sky-400/50 rounded-full" style={{ left: `${scrollStyles.h.left}px`, width: `${scrollStyles.h.width}px` }} />
      </div>

      {/* 滚动条组件 (V) */}
      <div className="absolute top-4 bottom-4 right-1 w-1.5 bg-slate-900/50 rounded-full cursor-pointer z-[50]" onMouseDown={(e) => { e.stopPropagation(); setDraggingId('scrollbar-v'); }}>
        <div className="absolute w-full bg-sky-500/30 border border-sky-400/50 rounded-full" style={{ top: `${scrollStyles.v.top}px`, height: `${scrollStyles.v.height}px` }} />
      </div>
    </div>
  );
};

