    <div className="flex h-screen w-screen bg-slate-950 text-slate-100 overflow-hidden font-sans antialiased selection:bg-sky-500/30">
      <style>{`
        /* 1. 状态灯闪烁动画 (Strobe) */
        @keyframes strobe-green { 0%, 100% { border-color: #10b981; box-shadow: 0 0 15px #10b98140; } 50% { border-color: #05966930; box-shadow: 0 0 2px transparent; } }
        @keyframes strobe-yellow { 0%, 100% { border-color: #f59e0b; box-shadow: 0 0 15px #f59e0b40; } 50% { border-color: #d9770630; box-shadow: 0 0 2px transparent; } }
        @keyframes strobe-red { 0%, 100% { border-color: #ef4444; box-shadow: 0 0 20px #ef444460; } 50% { border-color: #dc262620; box-shadow: 0 0 2px transparent; } }

        /* 2. 医院级 EKG 核心动画：单段脉冲移动 + 高频尖峰跳动 */
        @keyframes ekg-move { 0% { stroke-dashoffset: 1000; } 100% { stroke-dashoffset: 0; } }
        @keyframes ekg-spike {
          0%, 100% { stroke-width: 2.5px; filter: drop-shadow(0 0 1px currentColor); opacity: 0.4; }
          15% { stroke-width: 5px; filter: drop-shadow(0 -8px 4px currentColor) brightness(2); opacity: 1; } /* 上冲 */
          25% { stroke-width: 4px; filter: drop-shadow(0 4px 3px currentColor) brightness(1.5); opacity: 0.8; } /* 回弹 */
        }

        /* 3. 示波器动画：高频数字干扰感 */
        @keyframes scope-noise { 0% { stroke-dashoffset: 80; } 100% { stroke-dashoffset: 0; } }

        /* 4. 标准信号流动 */
        @keyframes signal-run { 0% { stroke-dashoffset: 400; } 100% { stroke-dashoffset: 0; } }

        .connection-signal { stroke-dasharray: 60, 340; animation: signal-run 3s linear infinite; }
        .connection-ekg { 
           stroke-dasharray: 45, 1000; 
           animation: ekg-move 2.2s linear infinite, ekg-spike 0.7s ease-out infinite; 
           stroke-linecap: round;
        }
        .connection-oscilloscope { stroke-dasharray: 8, 4, 15, 6; animation: scope-noise 0.4s steps(5) infinite; }
        .connection-flicker { stroke-dasharray: 4; animation: pulse 0.15s ease-in-out infinite; }

        .animate-strobe-green { animation: strobe-green 4s infinite; }
        .animate-strobe-yellow { animation: strobe-yellow 2.5s infinite; }
        .animate-strobe-red { animation: strobe-red 1s infinite; }

        .scanline-overlay {
           background: linear-gradient(rgba(18, 16, 16, 0) 50%, rgba(0, 0, 0, 0.25) 50%), linear-gradient(90deg, rgba(255, 0, 0, 0.06), rgba(0, 255, 0, 0.02), rgba(0, 0, 255, 0.06));
           background-size: 100% 2px, 3px 100%;
           pointer-events: none;
        }
      `}</style>

      {/* 扫视线全屏覆盖，增加工业感 */}
      <div className="fixed inset-0 scanline-overlay z-[60] opacity-20"></div>

      {toast.visible && (
        <div className="fixed top-8 left-1/2 -translate-x-1/2 z-[100] bg-slate-900/90 border border-sky-500/50 px-8 py-3 rounded-full shadow-[0_0_40px_rgba(14,165,233,0.3)] backdrop-blur-md flex items-center gap-4 animate-in fade-in slide-in-from-top-10">
          <div className="w-2 h-2 rounded-full bg-sky-400 animate-ping"></div>
          <span className="text-[11px] font-black text-sky-400 uppercase tracking-widest">{toast.message}</span>
        </div>
      )}

      <input type="file" ref={fileInputRef} onChange={handleImportConfig} className="hidden" accept=".json" />

      <Sidebar 
        nodes={nodes} groups={groups} connections={connections}
        selectedId={selectedId} selectedConnectionId={selectedConnectionId}
        addNode={addNode} addGroup={addGroup}
        deleteNode={(id) => { setNodes(n => n.filter(x => x.id !== id)); setConnections(c => c.filter(x => x.sourceId !== id && x.targetId !== id)); setSelectedId(null); }}
        deleteGroup={(id) => { setGroups(g => g.filter(x => x.id !== id)); setSelectedId(null); }}
        deleteConnection={(id) => { setConnections(c => c.filter(x => x.id !== id)); setSelectedConnectionId(null); }}
        updateConnection={(id, updates) => setConnections(prev => prev.map(c => c.id === id ? { ...c, ...updates } : c))}
        isAnalyzing={isAnalyzing} onAutoLayout={handleAutoLayout}
        isLocked={isLocked} onExport={handleExportConfig}
        onImport={() => fileInputRef.current?.click()}
      />

      <main className="flex-1 relative overflow-hidden">
        <UIOverlay mode={mode} setMode={setMode} connectSource={nodes.find(n => n.id === connectSourceId)?.name || groups.find(g => g.id === connectSourceId)?.name} isLocked={isLocked} setIsLocked={toggleLock} />

        <Workspace 
          nodes={nodes} groups={groups} connections={connections}
          selectedId={selectedId} selectedConnectionId={selectedConnectionId}
          onElementClick={handleElementInteraction}
          onConnectionClick={(id) => { setSelectedConnectionId(id === selectedConnectionId ? null : id); setSelectedId(null); }}
          onNodeMove={(id, x, y) => !isLocked && setNodes(prev => prev.map(n => n.id === id ? { ...n, position: { ...n.position, x, y } } : n))}
          onUpdateGroup={(id, updates) => !isLocked && setGroups(prev => prev.map(g => g.id === id ? { ...g, ...updates } : g))}
          mode={mode} isLocked={isLocked}
        />

        {isAnalyzing && (
            <div className="absolute inset-0 z-50 flex items-center justify-center bg-black/80 backdrop-blur-lg">
                <div className="flex flex-col items-center gap-6">
                    <div className="relative w-24 h-24">
                        <div className="absolute inset-0 border-4 border-sky-500/20 rounded-full"></div>
                        <div className="absolute inset-0 border-4 border-sky-500 border-t-transparent rounded-full animate-spin"></div>
                    </div>
                    <p className="text-sky-400 font-mono text-sm font-black tracking-[0.5em] animate-pulse">NEURAL_LAYOUT_SYNTHESIZING...</p>
                </div>
            </div>
        )}
      </main>
    </div>
  );
};

export default App;

/**
 * NeoOps 核心领域模型定义
 */

export enum ServiceType {
  DATABASE = 'database',
  SERVER = 'server',
  GATEWAY = 'gateway',
  CACHE = 'cache',
  LOAD_BALANCER = 'load_balancer',
  FIREWALL = 'firewall',
  CONTAINER = 'container'
}

/** 
 * 链路视觉特效类型
 * signal: 标准线性脉冲
 * fluid: 医院级 EKG 脉冲
 * packet: 示波器干扰风格
 * dashed: 异常闪烁风格
 */
export type ConnectionStyle = 'signal' | 'fluid' | 'packet' | 'dashed';

export interface Vector3Array {
  x: number;
  y: number;
  z: number;
}

/** 具体的服务节点（叶子节点） */
export interface ServiceNode {
  id: string;
  name: string;
  type: ServiceType;
  position: Vector3Array;
  status: 'online' | 'warning' | 'error';
  lastUpdated: string;
}

/** 逻辑分组容器（可包含多个节点） */
export interface GroupNode {
  id: string;
  name: string;
  position: { x: number; y: number };
  size: { width: number; height: number };
  color: string;
  status: 'online' | 'warning' | 'error';
}

/** 拓扑连接（有向图边） */
export interface Connection {
  id: string;
  sourceId: string;
  targetId: string;
  label: string;
  trafficLoad: number; // 0.0 - 1.0 模拟负载
  status?: 'online' | 'warning' | 'error';
  style?: ConnectionStyle;
}

import { GoogleGenAI, Type } from "@google/genai";

/**
 * 智能布局生成服务
 * 基于 Google Gemini 3 Pro 深度规划拓扑结构
 */

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || "" });

export async function suggestLayout(description: string) {
  const response = await ai.models.generateContent({
    model: 'gemini-3-pro-preview',
    contents: `你是一名顶级云原生架构师。请根据用户的自然语言描述，生成一套逻辑严密、布局美观的 2D 拓扑结构。

    用户描述: ${description}

    输出约束:
    1. 坐标系 X/Y 范围为 0 到 15。请确保节点之间有足够的间隔，不要重叠。
    2. 节点类型 type 必须为以下之一: [database, server, gateway, cache, load_balancer, firewall]。
    3. 连接 connections 的 sourceIndex 和 targetIndex 指向 nodes 数组的下标（从0开始）。
    4. 必须严格返回合法的 JSON 对象。`,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          nodes: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                name: { type: Type.STRING, description: "服务名称，需简洁明了" },
                type: { type: Type.STRING, description: "服务类型" },
                x: { type: Type.NUMBER, description: "横坐标 0-15" },
                y: { type: Type.NUMBER, description: "纵坐标 0-15" }
              },
              required: ["name", "type", "x", "y"]
            }
          },
          connections: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                sourceIndex: { type: Type.NUMBER },
                targetIndex: { type: Type.NUMBER },
                label: { type: Type.STRING, description: "连接的协议或功能描述" }
              },
              required: ["sourceIndex", "targetIndex", "label"]
            }
          }
        },
        required: ["nodes", "connections"]
      }
    }
  });

  try {
    return JSON.parse(response.text || "{\"nodes\":[], \"connections\":[]}");
  } catch (e) {
    console.error("AI 响应 JSON 解析异常:", e);
    throw new Error("AI 生成的架构定义无效");
  }
}

