        @keyframes strobe-yellow { 0%, 100% { border-color: #f59e0b; box-shadow: 0 0 15px #f59e0b40; } 50% { border-color: #d9770630; box-shadow: 0 0 2px transparent; } }
        @keyframes strobe-red { 0%, 100% { border-color: #ef4444; box-shadow: 0 0 20px #ef444460; } 50% { border-color: #dc262620; box-shadow: 0 0 2px transparent; } }

        /* 2. 医院级 EKG 核心动画：单段脉冲移动 + 高频尖峰跳动 */
        @keyframes ekg-move { 0% { stroke-dashoffset: 1000; } 100% { stroke-dashoffset: 0; } }
        @keyframes ekg-spike {
          0%, 100% { stroke-width: 2.5px; filter: drop-shadow(0 0 1px currentColor); opacity: 0.4; }
          15% { stroke-width: 5px; filter: drop-shadow(0 -8px 4px currentColor) brightness(2); opacity: 1; } /* 上冲 */
          25% { stroke-width: 4px; filter: drop-shadow(0 4px 3px currentColor) brightness(1.5); opacity: 0.8; } /* 回弹 */
        }

        /* 3. 示波器动画：高频数字干扰感 */
        @keyframes scope-noise { 0% { stroke-dashoffset: 80; } 100% { stroke-dashoffset: 0; } }

        /* 4. 标准信号流动 */
        @keyframes signal-run { 0% { stroke-dashoffset: 400; } 100% { stroke-dashoffset: 0; } }

        .connection-signal { stroke-dasharray: 60, 340; animation: signal-run 3s linear infinite; }
        .connection-ekg { 
           stroke-dasharray: 45, 1000; 
           animation: ekg-move 2.2s linear infinite, ekg-spike 0.7s ease-out infinite; 
           stroke-linecap: round;
        }
        .connection-oscilloscope { stroke-dasharray: 8, 4, 15, 6; animation: scope-noise 0.4s steps(5) infinite; }
