        .animate-strobe-yellow { animation: strobe-yellow 2.5s infinite; }
        .animate-strobe-red { animation: strobe-red 1s infinite; }

        .scanline-overlay {
           background: linear-gradient(rgba(18, 16, 16, 0) 50%, rgba(0, 0, 0, 0.25) 50%), linear-gradient(90deg, rgba(255, 0, 0, 0.06), rgba(0, 255, 0, 0.02), rgba(0, 0, 255, 0.06));
           background-size: 100% 2px, 3px 100%;
           pointer-events: none;
        }
      `}</style>

      {/* 扫视线全屏覆盖，增加工业感 */}
      <div className="fixed inset-0 scanline-overlay z-[60] opacity-20"></div>

      {toast.visible && (
        <div className="fixed top-8 left-1/2 -translate-x-1/2 z-[100] bg-slate-900/90 border border-sky-500/50 px-8 py-3 rounded-full shadow-[0_0_40px_rgba(14,165,233,0.3)] backdrop-blur-md flex items-center gap-4 animate-in fade-in slide-in-from-top-10">
          <div className="w-2 h-2 rounded-full bg-sky-400 animate-ping"></div>
          <span className="text-[11px] font-black text-sky-400 uppercase tracking-widest">{toast.message}</span>
        </div>
      )}

      <input type="file" ref={fileInputRef} onChange={handleImportConfig} className="hidden" accept=".json" />

      <Sidebar 
        nodes={nodes} groups={groups} connections={connections}
        selectedId={selectedId} selectedConnectionId={selectedConnectionId}
        addNode={addNode} addGroup={addGroup}
        deleteNode={handleDeleteNode}
        deleteGroup={handleDeleteGroup}
        deleteConnection={(id) => { setConnections(c => c.filter(x => x.id !== id)); setSelectedConnectionId(null); }}
        updateConnection={(id, updates) => setConnections(prev => prev.map(c => c.id === id ? { ...c, ...updates } : c))}
        isAnalyzing={isAnalyzing} onAutoLayout={handleAutoLayout}
        isLocked={isLocked} onExport={handleExportConfig}
        onImport={() => fileInputRef.current?.click()}
      />

      <main className="flex-1 relative overflow-hidden">
        <UIOverlay mode={mode} setMode={setMode} connectSource={nodes.find(n => n.id === connectSourceId)?.name || groups.find(g => g.id === connectSourceId)?.name} isLocked={isLocked} setIsLocked={toggleLock} />

        <Workspace 
          nodes={nodes} groups={groups} connections={connections}
          selectedId={selectedId} selectedConnectionId={selectedConnectionId}
          onElementClick={handleElementInteraction}
          onConnectionClick={(id) => { setSelectedConnectionId(id === selectedConnectionId ? null : id); setSelectedId(null); }}
          onNodeMove={(id, x, y) => !isLocked && setNodes(prev => prev.map(n => n.id === id ? { ...n, position: { ...n.position, x, y } } : n))}
          onUpdateGroup={(id, updates) => !isLocked && setGroups(prev => prev.map(g => g.id === id ? { ...g, ...updates } : g))}
          onDeleteGroup={handleDeleteGroup}
          onDeleteNode={handleDeleteNode}
          mode={mode} isLocked={isLocked}
        />

        {isAnalyzing && (
            <div className="absolute inset-0 z-50 flex items-center justify-center bg-black/80 backdrop-blur-lg">
                <div className="flex flex-col items-center gap-6">
                    <div className="relative w-24 h-24">
                        <div className="absolute inset-0 border-4 border-sky-500/20 rounded-full"></div>
                        <div className="absolute inset-0 border-4 border-sky-500 border-t-transparent rounded-full animate-spin"></div>
                    </div>
                    <p className="text-sky-400 font-mono text-sm font-black tracking-[0.5em] animate-pulse">NEURAL_LAYOUT_SYNTHESIZING...</p>
                </div>
            </div>
        )}
      </main>
    </div>
  );
};

