      setConnections([
        { id: 'c1', sourceId: 'n1', targetId: 'n2', label: 'TLS 1.3', trafficLoad: 0.3, status: 'online', style: 'signal' },
        { id: 'c2', sourceId: 'n2', targetId: 'n3', label: 'SQL Session', trafficLoad: 0.7, status: 'online', style: 'fluid' },
      ]);
    }
  }, []);

  const showToast = (message: string) => {
    setToast({ message, visible: true });
    setTimeout(() => setToast({ message: '', visible: false }), 3000);
  };

  const handleSaveLayout = useCallback(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify({ nodes, groups, connections }));
    showToast("布局配置已固化");
  }, [nodes, groups, connections]);

  const toggleLock = useCallback(() => {
    setIsLocked(prev => !prev);
    if (!isLocked) {
      handleSaveLayout();
      showToast("编辑锁定");
    } else {
      showToast("编辑模式已开启");
    }
  }, [isLocked, handleSaveLayout]);

  const handleDeleteNode = useCallback((id: string) => {
    setNodes(n => n.filter(x => x.id !== id));
    setConnections(c => c.filter(x => x.sourceId !== id && x.targetId !== id));
    setSelectedId(null);
  }, []);

  const handleDeleteGroup = useCallback((id: string) => {
    setGroups(g => g.filter(x => x.id !== id));
    setSelectedId(null);
  }, []);

  const handleAutoLayout = async (desc: string) => {
    if (!desc || isLocked) return;
    setIsAnalyzing(true);
    try {
      const layout = await suggestLayout(desc);
      const newNodes: ServiceNode[] = layout.nodes.map((n: any, i: number) => ({
        id: `ai-n-${i}-${Date.now()}`,
        name: n.name,
        type: n.type as ServiceType,
        position: { x: (n.x + 1) * 60, y: (n.y + 1) * 50, z: 0 },
        status: 'online',
        lastUpdated: new Date().toISOString()
      }));
      const newConns: Connection[] = layout.connections.map((c: any, i: number) => ({
        id: `ai-c-${i}-${Date.now()}`,
        sourceId: newNodes[c.sourceIndex].id,
        targetId: newNodes[c.targetIndex].id,
        label: c.label,
        trafficLoad: 0.2,
        status: 'online',
        style: 'signal'
      }));
      setNodes(newNodes);
      setConnections(newConns);
      showToast("AI 拓扑生成完成");
    } catch (e) {
      showToast("AI 规划失败");
    }
    setIsAnalyzing(false);
  };

  return (
    <div className="flex h-screen w-screen bg-slate-950 text-slate-100 overflow-hidden font-sans">
      <style>{`
        /* --- 节点基础样式恢复 --- */
        .node-button {
          background: rgba(15, 23, 42, 0.7);
          backdrop-filter: blur(12px);
          border: 1px solid rgba(255, 255, 255, 0.08);
          transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
        }
        .node-button:hover {
          background: rgba(30, 41, 59, 0.9);
          border-color: rgba(56, 189, 248, 0.4);
        }

        /* --- 状态呼吸灯 --- */
        @keyframes strobe-green { 0%, 100% { border-color: rgba(16, 185, 129, 0.5); box-shadow: 0 0 15px rgba(16, 185, 129, 0.2); } 50% { border-color: rgba(16, 185, 129, 0.1); box-shadow: 0 0 2px transparent; } }
        @keyframes strobe-yellow { 0%, 100% { border-color: rgba(245, 158, 11, 0.5); box-shadow: 0 0 15px rgba(245, 158, 11, 0.2); } 50% { border-color: rgba(245, 158, 11, 0.1); box-shadow: 0 0 2px transparent; } }
        @keyframes strobe-red { 0%, 100% { border-color: rgba(239, 68, 68, 0.6); box-shadow: 0 0 20px rgba(239, 68, 68, 0.3); } 50% { border-color: rgba(239, 68, 68, 0.1); box-shadow: 0 0 2px transparent; } }

        /* --- EKG 心电图动画 --- */
        @keyframes ekg-move { 0% { stroke-dashoffset: 1000; } 100% { stroke-dashoffset: 0; } }
        @keyframes ekg-spike {
          0%, 100% { stroke-width: 2.5px; opacity: 0.5; filter: drop-shadow(0 0 1px currentColor); }
          15% { stroke-width: 5.5px; opacity: 1; filter: drop-shadow(0 -8px 4px currentColor) brightness(2); }
          25% { stroke-width: 4.5px; opacity: 0.9; filter: drop-shadow(0 4px 3px currentColor) brightness(1.5); }
        }

        /* --- 动画类 --- */
        .animate-strobe-green { animation: strobe-green 3s infinite ease-in-out; }
        .animate-strobe-yellow { animation: strobe-yellow 2.5s infinite ease-in-out; }
        .animate-strobe-red { animation: strobe-red 1.2s infinite ease-in-out; }

        .connection-signal { stroke-dasharray: 60, 340; animation: signal-run 3s linear infinite; }
        .connection-ekg { 
           stroke-dasharray: 50, 1000; 
           animation: ekg-move 2s linear infinite, ekg-spike 0.7s ease-out infinite; 
           stroke-linecap: round;
        }
        @keyframes signal-run { 0% { stroke-dashoffset: 400; } 100% { stroke-dashoffset: 0; } }
        @keyframes scope-noise { 0% { stroke-dashoffset: 80; } 100% { stroke-dashoffset: 0; } }
        .connection-oscilloscope { stroke-dasharray: 10, 5, 20, 5; animation: scope-noise 0.4s steps(4) infinite; }
        .connection-flicker { stroke-dasharray: 4; animation: pulse 0.15s ease-in-out infinite; }

        .scanline-bg {
           background: linear-gradient(rgba(18, 16, 16, 0) 50%, rgba(0, 0, 0, 0.2) 50%);
           background-size: 100% 4px;
           pointer-events: none;
        }
      `}</style>

      {/* 扫视线全屏背景 */}
