      <main className="flex-1 relative overflow-hidden">
        <UIOverlay mode={mode} setMode={setMode} connectSource={nodes.find(n => n.id === connectSourceId)?.name || groups.find(g => n.id === connectSourceId)?.name} isLocked={isLocked} setIsLocked={toggleLock} />

        <Workspace 
          nodes={nodes} groups={groups} connections={connections}
          selectedId={selectedId} selectedConnectionId={selectedConnectionId}
