          }}
          onConnectionClick={(id) => { setSelectedConnectionId(id === selectedConnectionId ? null : id); setSelectedId(null); }}
          onNodeMove={(id, x, y) => !isLocked && setNodes(prev => prev.map(n => n.id === id ? { ...n, position: { ...n.position, x, y } } : n))}
          onUpdateGroup={(id, updates) => !isLocked && setGroups(prev => prev.map(g => g.id === id ? { ...g, ...updates } : g))}
          onDeleteGroup={handleDeleteGroup}
          onDeleteNode={handleDeleteNode}
          mode={mode} isLocked={isLocked}
        />

        {isAnalyzing && (
            <div className="absolute inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-md">
                <div className="flex flex-col items-center gap-6">
                    <div className="w-16 h-16 border-2 border-sky-500/20 border-t-sky-500 rounded-full animate-spin"></div>
                    <p className="text-sky-400 font-mono text-[10px] font-black tracking-[0.8em] animate-pulse">SYNTHESIZING_TOPOLOGY...</p>
                </div>
            </div>
        )}
      </main>
    </div>
  );
};

export default App;

import React, { useRef, useState, useMemo, useEffect } from 'react';
import { ServiceNode, Connection, GroupNode } from '../types';
import { SERVICE_ICONS, SERVICE_COLORS } from '../constants';

interface WorkspaceProps {
  nodes: ServiceNode[];
  groups: GroupNode[];
  connections: Connection[];
  selectedId: string | null;
  selectedConnectionId: string | null;
  onElementClick: (id: string) => void;
  onConnectionClick: (id: string) => void;
  onNodeMove: (id: string, x: number, y: number) => void;
  onUpdateGroup: (id: string, updates: Partial<GroupNode>) => void;
  onDeleteGroup: (id: string) => void;
  onDeleteNode: (id: string) => void;
  mode: string;
  isLocked: boolean;
}

const Workspace: React.FC<WorkspaceProps> = ({ 
  nodes, 
  groups,
  connections, 
  selectedId,
  selectedConnectionId,
  onElementClick,
  onConnectionClick,
  onNodeMove, 
  onUpdateGroup,
  onDeleteGroup,
  onDeleteNode,
  mode,
  isLocked
}) => {
  const containerRef = useRef<HTMLDivElement>(null);

  const [viewOffset, setViewOffset] = useState({ x: 0, y: 0 });
  const [isPanning, setIsPanning] = useState(false);
  const [lastMousePos, setLastMousePos] = useState({ x: 0, y: 0 });

  const [draggingId, setDraggingId] = useState<string | null>(null);
  const [resizingId, setResizingId] = useState<string | null>(null);
  const [dragType, setDragType] = useState<'node' | 'group' | 'resize' | 'scroll-h' | 'scroll-v'>('node');

  const contentBounds = useMemo(() => {
    let minX = 0, maxX = 1500, minY = 0, maxY = 1000;
    nodes.forEach(n => {
      minX = Math.min(minX, n.position.x - 300);
      maxX = Math.max(maxX, n.position.x + 400);
      minY = Math.min(minY, n.position.y - 300);
      maxY = Math.max(maxY, n.position.y + 400);
    });
    return { minX, maxX, minY, maxY, width: maxX - minX, height: maxY - minY };
  }, [nodes]);

  const handleMouseDown = (e: React.MouseEvent) => {
    if (!containerRef.current) return;
    if (e.target === containerRef.current) {
      setIsPanning(true);
      setLastMousePos({ x: e.clientX, y: e.clientY });
    }
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (!containerRef.current) return;
    const rect = containerRef.current.getBoundingClientRect();

    if (isPanning) {
      const dx = e.clientX - lastMousePos.x;
      const dy = e.clientY - lastMousePos.y;
      setViewOffset(prev => ({ x: prev.x + dx, y: prev.y + dy }));
      setLastMousePos({ x: e.clientX, y: e.clientY });
      return;
    }

    if (draggingId === 'scrollbar-h' || draggingId === 'scrollbar-v') {
      if (draggingId === 'scrollbar-h') {
        const ratio = (e.clientX - rect.left) / rect.width;
        setViewOffset(prev => ({ ...prev, x: -(contentBounds.minX + ratio * contentBounds.width - rect.width / 2) }));
      } else {
        const ratio = (e.clientY - rect.top) / rect.height;
        setViewOffset(prev => ({ ...prev, y: -(contentBounds.minY + ratio * contentBounds.height - rect.height / 2) }));
      }
      return;
    }

    if (mode !== 'select' || isLocked) return;

    const x = e.clientX - rect.left - viewOffset.x;
    const y = e.clientY - rect.top - viewOffset.y;

    if (draggingId && dragType === 'node') {
      onNodeMove(draggingId, x - 65, y - 22);
    } else if (draggingId && dragType === 'group') {
      const group = groups.find(g => g.id === draggingId);
      if (group) onUpdateGroup(draggingId, { position: { x: x - group.size.width / 2, y: y - 16 } });
    } else if (resizingId) {
      const group = groups.find(g => g.id === resizingId);
      if (group) {
        onUpdateGroup(resizingId, { size: { width: Math.max(200, x - group.position.x), height: Math.max(150, y - group.position.y) } });
      }
    }
  };

  const handleMouseUp = () => {
    setIsPanning(false);
    setDraggingId(null);
    setResizingId(null);
  };

  const getStrobeClass = (status: string) => {
    switch(status) {
      case 'online': return 'animate-strobe-green';
      case 'warning': return 'animate-strobe-yellow';
      case 'error': return 'animate-strobe-red';
      default: return 'animate-strobe-green';
    }
  };

  const getStatusConfig = (status: string) => {
    switch(status) {
      case 'online': return { text: 'RUNNING', color: 'text-emerald-400', border: 'border-emerald-500/30' };
      case 'warning': return { text: 'STRESSED', color: 'text-amber-400', border: 'border-amber-500/30' };
      case 'error': return { text: 'OFFLINE', color: 'text-rose-400', border: 'border-rose-500/30' };
      default: return { text: 'RUNNING', color: 'text-emerald-400', border: 'border-emerald-500/30' };
    }
  };

  const getElementInfo = (id: string) => {
    const node = nodes.find(n => n.id === id);
    if (node) return { x: node.position.x, y: node.position.y, w: 130, h: 44, cx: node.position.x + 65, cy: node.position.y + 22, isGroup: false };
    const group = groups.find(g => g.id === id);
    if (group) return { x: group.position.x, y: group.position.y, w: group.size.width, h: group.size.height, cx: group.position.x + group.size.width / 2, cy: group.position.y + group.size.height / 2, isGroup: true };
    return null;
  };

  const getConnectionPoint = (sourceId: string, targetId: string) => {
    const s = getElementInfo(sourceId);
    const t = getElementInfo(targetId);
    if (!s || !t) return null;
    const getIntersection = (rect: any, otherCenter: {x: number, y: number}) => {
      const dx = otherCenter.x - rect.cx;
      const dy = otherCenter.y - rect.cy;
      const hw = rect.w / 2;
      const hh = rect.h / 2;
      const scale = Math.min(dx !== 0 ? Math.abs(hw / dx) : Infinity, dy !== 0 ? Math.abs(hh / dy) : Infinity);
      return { x: rect.cx + dx * scale, y: rect.cy + dy * scale };
    };
    return { start: getIntersection(s, { x: t.cx, y: t.cy }), end: getIntersection(t, { x: s.cx, y: s.cy }) };
  };

  const getBezierPath = (start: {x: number, y: number}, end: {x: number, y: number}) => {
    const dx = Math.abs(end.x - start.x);
    const dy = Math.abs(end.y - start.y);
    const horizontal = dx > dy;
    const ctrl1 = horizontal ? { x: start.x + dx / 4, y: start.y } : { x: start.x, y: start.y + dy / 4 };
    const ctrl2 = horizontal ? { x: end.x - dx / 4, y: end.y } : { x: end.x, y: end.y - dy / 4 };
    return `M ${start.x} ${start.y} C ${ctrl1.x} ${ctrl1.y}, ${ctrl2.x} ${ctrl2.y}, ${end.x} ${end.y}`;
  };

  const gridBackground = useMemo(() => ({
    backgroundImage: `
      linear-gradient(to right, rgba(14, 165, 233, 0.04) 1px, transparent 1px),
      linear-gradient(to bottom, rgba(14, 165, 233, 0.04) 1px, transparent 1px)
    `,
    backgroundSize: '40px 40px',
    backgroundPosition: `${viewOffset.x}px ${viewOffset.y}px`
  }), [viewOffset]);

  return (
    <div 
      ref={containerRef}
      style={gridBackground}
      className={`w-full h-full relative select-none overflow-hidden ${isPanning ? 'cursor-grabbing' : 'cursor-default'}`}
      onMouseDown={handleMouseDown}
      onMouseMove={handleMouseMove}
      onMouseUp={handleMouseUp}
      onMouseLeave={handleMouseUp}
    >
      <div style={{ transform: `translate(${viewOffset.x}px, ${viewOffset.y}px)`, position: 'absolute', inset: 0, pointerEvents: 'none' }}>
        {/* 分组层 */}
        {groups.map((group) => (
          <div
            key={group.id}
            style={{ left: group.position.x, top: group.position.y, width: group.size.width, height: group.size.height, pointerEvents: 'auto' }}
            className={`absolute z-0 transition-all ${isLocked ? 'pointer-events-auto' : 'cursor-move'}`}
            onClick={(e) => { e.stopPropagation(); onElementClick(group.id); }}
            onMouseDown={(e) => { if (mode === 'select' && !isLocked) { e.stopPropagation(); setDraggingId(group.id); setDragType('group'); } }}
          >
            <div className={`absolute inset-0 rounded-3xl bg-slate-950/20 backdrop-blur-sm border transition-all duration-500 ${selectedId === group.id ? 'border-sky-500 shadow-[0_0_40px_rgba(14,165,233,0.1)] ring-1 ring-sky-500/30' : 'border-slate-800/40'} ${getStrobeClass(group.status)}`}></div>
            <div className="absolute top-4 left-6 flex items-center gap-3 opacity-60">
              <span className="text-[9px] font-black text-slate-500 tracking-[0.3em] uppercase">{group.name}</span>
            </div>
            {!isLocked && (
              <div 
                className="absolute bottom-3 right-3 w-6 h-6 cursor-nwse-resize opacity-20 hover:opacity-100 transition-opacity"
                onMouseDown={(e) => { e.stopPropagation(); setResizingId(group.id); }}
              >
                <div className="w-full h-full border-r-2 border-b-2 border-slate-500 rounded-br"></div>
              </div>
            )}
          </div>
        ))}

        {/* 连线层 */}
        <svg className="absolute inset-0 w-full h-full pointer-events-none z-[5]">
          <defs>
            <filter id="glow" x="-20%" y="-20%" width="140%" height="140%">
              <feGaussianBlur stdDeviation="3" result="blur" />
              <feComposite in="SourceGraphic" in2="blur" operator="over" />
            </filter>
          </defs>
          {connections.map((conn) => {
            const points = getConnectionPoint(conn.sourceId, conn.targetId);
            if (!points) return null;
            const { start, end } = points;
            const bezierPath = getBezierPath(start, end);
            const isSelected = selectedConnectionId === conn.id;
            const color = conn.status === 'error' ? '#ef4444' : '#0ea5e9';
            return (
              <g key={conn.id}>
                <path d={bezierPath} stroke="transparent" strokeWidth="24" fill="none" className="cursor-pointer pointer-events-auto" onClick={(e) => { e.stopPropagation(); onConnectionClick(conn.id); }} />
                <path d={bezierPath} stroke={color} strokeWidth={isSelected ? 4 : 2} fill="none" className={conn.style === 'fluid' ? 'connection-ekg' : 'connection-signal'} filter="url(#glow)" style={{ opacity: isSelected ? 1 : 0.4, color }} />
                <text className="text-[7px] font-black tracking-widest" fill={color} dy="-8" style={{ opacity: isSelected ? 1 : 0.3 }}>
                  <textPath href={`#p-${conn.id}`} startOffset="50%" textAnchor="middle">{conn.label}</textPath>
                </text>
                <path id={`p-${conn.id}`} d={end.x < start.x ? getBezierPath(end, start) : bezierPath} fill="none" />
              </g>
            );
          })}
        </svg>

        {/* 节点层 (服务按钮) */}
        {nodes.map((node) => {
          const isSelected = selectedId === node.id;
          const statusConfig = getStatusConfig(node.status);
          const serviceColor = SERVICE_COLORS[node.type];
          return (
            <div key={node.id} style={{ left: node.position.x, top: node.position.y, width: '130px', height: '44px', pointerEvents: 'auto' }} className="absolute z-10">
              <div 
                className={`w-full h-full node-button rounded-xl flex items-center px-3 relative ${getStrobeClass(node.status)} ${isSelected ? 'ring-2 ring-sky-500/50 scale-105 z-20' : ''} ${isLocked ? 'cursor-default' : 'cursor-pointer'}`}
                onClick={(e) => { e.stopPropagation(); onElementClick(node.id); }}
                onMouseDown={(e) => { if (mode === 'select' && !isLocked) { e.stopPropagation(); setDraggingId(node.id); setDragType('node'); } }}
              >
                <div className="flex items-center gap-3 w-full">
                  <div className="w-8 h-8 rounded-lg bg-slate-900/50 flex items-center justify-center border border-white/5 shadow-inner">
                    <i className={`fas ${SERVICE_ICONS[node.type]} text-xs`} style={{ color: serviceColor, filter: `drop-shadow(0 0 5px ${serviceColor}40)` }}></i>
                  </div>
                  <div className="flex flex-col min-w-0">
                    <span className="text-[9px] font-black text-slate-100 tracking-wider truncate uppercase">{node.name}</span>
                    <span className={`text-[7px] font-bold tracking-widest ${statusConfig.color} mt-0.5`}>{statusConfig.text}</span>
                  </div>
                </div>
                {/* 右上角运行指示点 */}
                <div className="absolute top-2 right-2">
                   <div className={`w-1 h-1 rounded-full ${node.status === 'online' ? 'bg-emerald-400' : node.status === 'warning' ? 'bg-amber-400' : 'bg-rose-400'} shadow-[0_0_5px_currentColor]`}></div>
                </div>
              </div>
            </div>
          );
        })}
      </div>

      {/* 底部装饰标识 */}
      <div className="absolute bottom-8 right-10 pointer-events-none">
        <div className="flex flex-col items-end opacity-20">
          <span className="text-[10px] font-black text-sky-500 tracking-[0.5em] uppercase">NEOOPS_SYSTEM_ACTIVE</span>
          <div className="w-32 h-[1px] bg-sky-500/30 mt-1"></div>
        </div>
      </div>
    </div>
  );
};

export default Workspace;

import React, { useState, useCallback, useEffect, useRef } from 'react';
import Sidebar from './components/Sidebar';
import UIOverlay from './components/UIOverlay';
import Workspace from './components/Workspace';
import { ServiceNode, Connection, ServiceType, GroupNode } from './types';
import { suggestLayout } from './geminiService';

/**
 * NeoOps 运维系统主程序
 * 负责核心状态管理、全局 CSS 动画定义及持久化逻辑
 */

const STORAGE_KEY = 'NEOOPS_CORE_STORAGE';

const App: React.FC = () => {
  const [nodes, setNodes] = useState<ServiceNode[]>([]);
  const [groups, setGroups] = useState<GroupNode[]>([]);
  const [connections, setConnections] = useState<Connection[]>([]);

  const [toast, setToast] = useState<{ message: string; visible: boolean }>({ message: '', visible: false });
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [selectedConnectionId, setSelectedConnectionId] = useState<string | null>(null);
  const [mode, setMode] = useState<'select' | 'add' | 'connect'>('select');
  const [isLocked, setIsLocked] = useState(false);
  const [connectSourceId, setConnectSourceId] = useState<string | null>(null);
  const [isAnalyzing, setIsAnalyzing] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);

  // 初始化：加载本地存储
  useEffect(() => {
    const savedData = localStorage.getItem(STORAGE_KEY);
    if (savedData) {
      try {
        const parsed = JSON.parse(savedData);
        setNodes(parsed.nodes || []);
        setGroups(parsed.groups || []);
        setConnections(parsed.connections || []);
      } catch (e) {
        console.error("配置恢复失败", e);
      }
    } else {
      // 默认演示数据
      setNodes([
        { id: 'n1', name: '接入网关 (Nginx)', type: ServiceType.GATEWAY, position: { x: 150, y: 350, z: 0 }, status: 'online', lastUpdated: new Date().toISOString() },
        { id: 'n2', name: '用户鉴权中心', type: ServiceType.SERVER, position: { x: 450, y: 300, z: 0 }, status: 'online', lastUpdated: new Date().toISOString() },
        { id: 'n3', name: '核心数据库 (MySQL)', type: ServiceType.DATABASE, position: { x: 750, y: 450, z: 0 }, status: 'warning', lastUpdated: new Date().toISOString() },
      ]);
      setGroups([
        { id: 'g1', name: '核心业务区', position: { x: 300, y: 200 }, size: { width: 600, height: 450 }, color: '#38bdf8', status: 'online' }
      ]);
      setConnections([
        { id: 'c1', sourceId: 'n1', targetId: 'n2', label: 'SSL/TLS', trafficLoad: 0.3, status: 'online', style: 'signal' },
        { id: 'c2', sourceId: 'n2', targetId: 'n3', label: 'DB_POOL', trafficLoad: 0.8, status: 'online', style: 'fluid' },
      ]);
    }
  }, []);

  const showToast = (message: string) => {
    setToast({ message, visible: true });
    setTimeout(() => setToast({ message: '', visible: false }), 3000);
  };

  const handleSaveLayout = useCallback(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify({ nodes, groups, connections }));
    showToast("布局配置已保存");
  }, [nodes, groups, connections]);

  const toggleLock = useCallback(() => {
    setIsLocked(prev => !prev);
    if (!isLocked) {
      handleSaveLayout();
      showToast("布局已锁定");
    } else {
      showToast("开启自由编排");
    }
  }, [isLocked, handleSaveLayout]);

  const handleDeleteNode = useCallback((id: string) => {
    setNodes(n => n.filter(x => x.id !== id));
    setConnections(c => c.filter(x => x.sourceId !== id && x.targetId !== id));
    setSelectedId(null);
  }, []);

  const handleDeleteGroup = useCallback((id: string) => {
    setGroups(g => g.filter(x => x.id !== id));
    setSelectedId(null);
  }, []);

  const handleAutoLayout = async (desc: string) => {
    if (!desc || isLocked) return;
    setIsAnalyzing(true);
    try {
      const layout = await suggestLayout(desc);
      const newNodes: ServiceNode[] = layout.nodes.map((n: any, i: number) => ({
        id: `ai-n-${i}-${Date.now()}`,
        name: n.name,
        type: n.type as ServiceType,
        position: { x: (n.x + 1) * 60, y: (n.y + 1) * 50, z: 0 },
        status: 'online',
        lastUpdated: new Date().toISOString()
      }));
      const newConns: Connection[] = layout.connections.map((c: any, i: number) => ({
        id: `ai-c-${i}-${Date.now()}`,
        sourceId: newNodes[c.sourceIndex].id,
        targetId: newNodes[c.targetIndex].id,
        label: c.label,
        trafficLoad: 0.2,
        status: 'online',
        style: 'signal'
      }));
      setNodes(newNodes);
      setConnections(newConns);
      showToast("AI 拓扑已生成");
    } catch (e) {
      showToast("AI 服务请求超时");
    }
    setIsAnalyzing(false);
  };

  return (
    <div className="flex h-screen w-screen bg-[#020617] text-slate-100 overflow-hidden font-sans antialiased">
      <style>{`
        /* --- 节点(按钮)高级样式重塑 --- */
        .node-button {
          background: rgba(15, 23, 42, 0.45);
          backdrop-filter: blur(16px);
          -webkit-backdrop-filter: blur(16px);
          border: 1px solid rgba(255, 255, 255, 0.05);
          box-shadow: 
            0 8px 32px 0 rgba(0, 0, 0, 0.37),
            inset 0 0 12px rgba(255, 255, 255, 0.02);
          transition: all 0.4s cubic-bezier(0.16, 1, 0.3, 1);
          overflow: hidden;
        }

        .node-button::before {
          content: "";
          position: absolute;
          top: -50%;
          left: -150%;
          width: 200%;
          height: 200%;
          background: linear-gradient(
            to right,
            transparent,
            rgba(255, 255, 255, 0.05),
            transparent
          );
          transform: rotate(30deg);
          transition: 0.5s;
          pointer-events: none;
        }
        .node-button:hover::before {
          animation: node-shine 1.5s infinite;
        }
        @keyframes node-shine {
          0% { left: -150%; }
          100% { left: 150%; }
        }

        .node-button:hover {
          background: rgba(30, 41, 59, 0.6);
          border-color: rgba(56, 189, 248, 0.4);
          transform: translateY(-2px) scale(1.02);
          box-shadow: 
            0 12px 40px rgba(0, 0, 0, 0.5),
            0 0 20px rgba(14, 165, 233, 0.1);
        }

        /* 状态呼吸灯核心动画 */
        @keyframes strobe-green { 0%, 100% { border-color: rgba(16, 185, 129, 0.4); box-shadow: 0 0 10px rgba(16, 185, 129, 0.1); } 50% { border-color: rgba(16, 185, 129, 0.2); } }
        @keyframes strobe-yellow { 0%, 100% { border-color: rgba(245, 158, 11, 0.4); box-shadow: 0 0 10px rgba(245, 158, 11, 0.1); } 50% { border-color: rgba(245, 158, 11, 0.2); } }
        @keyframes strobe-red { 0%, 100% { border-color: rgba(239, 68, 68, 0.5); box-shadow: 0 0 15px rgba(239, 68, 68, 0.2); } 50% { border-color: rgba(239, 68, 68, 0.2); } }

        .animate-strobe-green { animation: strobe-green 4s infinite ease-in-out; }
        .animate-strobe-yellow { animation: strobe-yellow 2.5s infinite ease-in-out; }
        .animate-strobe-red { animation: strobe-red 1.2s infinite ease-in-out; }

        /* --- 拓扑连线动效修复与增强 --- */
        @keyframes signal-run { 0% { stroke-dashoffset: 400; } 100% { stroke-dashoffset: 0; } }
        @keyframes ekg-move { 0% { stroke-dashoffset: 1000; } 100% { stroke-dashoffset: 0; } }
        @keyframes ekg-spike {
          0%, 100% { stroke-width: 2.5px; opacity: 0.4; }
          15% { stroke-width: 5px; opacity: 1; filter: drop-shadow(0 -5px 5px currentColor); }
          25% { stroke-width: 3.5px; opacity: 0.7; }
        }
        @keyframes scope-noise { 0% { stroke-dashoffset: 80; filter: brightness(1); } 100% { stroke-dashoffset: 0; filter: brightness(1.5); } }
        @keyframes pulse-flicker { 0%, 100% { opacity: 0.2; } 50% { opacity: 1; stroke-width: 4px; } }

        /* 基础信号流动 */
        .connection-signal { 
          stroke-dasharray: 60, 340; 
          animation: signal-run 3s linear infinite; 
        }

        /* 心电图脉冲 */
        .connection-ekg { 
           stroke-dasharray: 45, 1000; 
           animation: ekg-move 2.5s linear infinite, ekg-spike 0.8s ease-out infinite; 
           stroke-linecap: round;
        }

        /* 示波器干扰效果 */
        .connection-oscilloscope { 
          stroke-dasharray: 12, 6, 20, 4; 
          animation: scope-noise 0.4s steps(5) infinite; 
          stroke-linecap: square;
        }

        /* 异常频闪效果 */
        .connection-flicker { 
          stroke-dasharray: 6, 2; 
          animation: pulse-flicker 0.15s ease-in-out infinite; 
          stroke-width: 3px;
        }

        /* 全屏装饰扫视线 */
        .scanline {
           position: fixed; top: 0; left: 0; width: 100%; height: 100%;
           background: linear-gradient(rgba(18, 16, 16, 0) 50%, rgba(0, 0, 0, 0.15) 50%);
           background-size: 100% 4px;
           z-index: 60; pointer-events: none; opacity: 0.08;
        }
      `}</style>

      <div className="scanline"></div>

      {toast.visible && (
        <div className="fixed top-10 left-1/2 -translate-x-1/2 z-[100] bg-slate-900/90 border border-sky-500/30 px-6 py-2 rounded-full shadow-2xl backdrop-blur-xl animate-in fade-in slide-in-from-top-4">
          <span className="text-[10px] font-bold text-sky-400 uppercase tracking-[0.2em]">{toast.message}</span>
        </div>
      )}

      <input type="file" ref={fileInputRef} onChange={(e) => {
        const file = e.target.files?.[0];
        if (!file) return;
        const reader = new FileReader();
        reader.onload = (event) => {
          try {
            const parsed = JSON.parse(event.target?.result as string);
            if (parsed.nodes) {
              setNodes(parsed.nodes);
              setGroups(parsed.groups || []);
              setConnections(parsed.connections || []);
              showToast("配置文件已导入");
            }
          } catch { showToast("无效的格式"); }
        };
        reader.readAsText(file);
      }} className="hidden" accept=".json" />

      <Sidebar 
        nodes={nodes} groups={groups} connections={connections}
        selectedId={selectedId} selectedConnectionId={selectedConnectionId}
        addNode={(type, name, status) => setNodes(prev => [...prev, { id: `n-${Date.now()}`, name, type, position: { x: 200, y: 200, z: 0 }, status, lastUpdated: new Date().toISOString() }])}
        addGroup={(name, status) => setGroups(prev => [...prev, { id: `g-${Date.now()}`, name, position: { x: 200, y: 200 }, size: { width: 450, height: 350 }, color: '#818cf8', status }])}
        deleteNode={handleDeleteNode}
        deleteGroup={handleDeleteGroup}
        deleteConnection={(id) => { setConnections(c => c.filter(x => x.id !== id)); setSelectedConnectionId(null); }}
        updateConnection={(id, updates) => setConnections(prev => prev.map(c => c.id === id ? { ...c, ...updates } : c))}
        isAnalyzing={isAnalyzing} onAutoLayout={handleAutoLayout}
        isLocked={isLocked} onExport={() => {
            const data = { nodes, groups, connections, timestamp: new Date().toISOString() };
            const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
            const url = URL.createObjectURL(blob);
            const link = document.createElement('a');
            link.href = url; link.download = 'topology-config.json'; link.click();
            showToast("配置已导出");
        }}
        onImport={() => fileInputRef.current?.click()}
      />

      <main className="flex-1 relative overflow-hidden bg-[radial-gradient(circle_at_50%_50%,_#0f172a_0%,_#020617_100%)]">
        <UIOverlay 
          mode={mode} 
          setMode={setMode} 
          connectSource={nodes.find(n => n.id === connectSourceId)?.name || groups.find(g => g.id === connectSourceId)?.name} 
          isLocked={isLocked} 
          setIsLocked={toggleLock} 
        />

        <Workspace 
          nodes={nodes} groups={groups} connections={connections}
          selectedId={selectedId} selectedConnectionId={selectedConnectionId}
          onElementClick={(id) => {
            if (mode === 'connect' && !isLocked) {
              if (!connectSourceId) setConnectSourceId(id);
              else {
                setConnections(prev => [...prev, { id: `c-${Date.now()}`, sourceId: connectSourceId, targetId: id, label: 'AUTH_TRAFFIC', trafficLoad: 0.2, style: 'signal' }]);
                setConnectSourceId(null); setMode('select');
              }
            } else { setSelectedId(id === selectedId ? null : id); setSelectedConnectionId(null); }
          }}
          onConnectionClick={(id) => { setSelectedConnectionId(id === selectedConnectionId ? null : id); setSelectedId(null); }}
          onNodeMove={(id, x, y) => !isLocked && setNodes(prev => prev.map(n => n.id === id ? { ...n, position: { ...n.position, x, y } } : n))}
          onUpdateGroup={(id, updates) => !isLocked && setGroups(prev => prev.map(g => g.id === id ? { ...g, ...updates } : g))}
          onDeleteGroup={handleDeleteGroup}
          onDeleteNode={handleDeleteNode}
          mode={mode} isLocked={isLocked}
        />

        {isAnalyzing && (
            <div className="absolute inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-md">
                <div className="flex flex-col items-center gap-6">
                    <div className="w-16 h-16 border-2 border-sky-500/20 border-t-sky-500 rounded-full animate-spin"></div>
                    <p className="text-sky-400 font-mono text-[10px] font-black tracking-[0.8em] animate-pulse">SYNTHESIZING_TOPOLOGY...</p>
                </div>
            </div>
        )}
      </main>
    </div>
  );
};

export default App;

import React, { useRef, useState, useMemo, useEffect } from 'react';
import { ServiceNode, Connection, GroupNode } from '../types';
import { SERVICE_ICONS, SERVICE_COLORS } from '../constants';

interface WorkspaceProps {
  nodes: ServiceNode[];
  groups: GroupNode[];
  connections: Connection[];
  selectedId: string | null;
  selectedConnectionId: string | null;
  onElementClick: (id: string) => void;
  onConnectionClick: (id: string) => void;
  onNodeMove: (id: string, x: number, y: number) => void;
  onUpdateGroup: (id: string, updates: Partial<GroupNode>) => void;
  onDeleteGroup: (id: string) => void;
  onDeleteNode: (id: string) => void;
  mode: string;
  isLocked: boolean;
}

const Workspace: React.FC<WorkspaceProps> = ({ 
  nodes, 
  groups,
  connections, 
  selectedId,
  selectedConnectionId,
  onElementClick,
  onConnectionClick,
  onNodeMove, 
  onUpdateGroup,
  onDeleteGroup,
  onDeleteNode,
  mode,
  isLocked
}) => {
  const containerRef = useRef<HTMLDivElement>(null);

  const [viewOffset, setViewOffset] = useState({ x: 0, y: 0 });
  const [isPanning, setIsPanning] = useState(false);
  const [lastMousePos, setLastMousePos] = useState({ x: 0, y: 0 });

  const [draggingId, setDraggingId] = useState<string | null>(null);
  const [resizingId, setResizingId] = useState<string | null>(null);
  const [dragType, setDragType] = useState<'node' | 'group' | 'resize' | 'scroll-h' | 'scroll-v'>('node');

  const contentBounds = useMemo(() => {
    let minX = 0, maxX = 1500, minY = 0, maxY = 1000;
    nodes.forEach(n => {
      minX = Math.min(minX, n.position.x - 300);
      maxX = Math.max(maxX, n.position.x + 400);
      minY = Math.min(minY, n.position.y - 300);
      maxY = Math.max(maxY, n.position.y + 400);
    });
    return { minX, maxX, minY, maxY, width: maxX - minX, height: maxY - minY };
  }, [nodes]);

  const handleMouseDown = (e: React.MouseEvent) => {
    if (!containerRef.current) return;
    if (e.target === containerRef.current) {
      setIsPanning(true);
      setLastMousePos({ x: e.clientX, y: e.clientY });
    }
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (!containerRef.current) return;
    const rect = containerRef.current.getBoundingClientRect();

    if (isPanning) {
      const dx = e.clientX - lastMousePos.x;
      const dy = e.clientY - lastMousePos.y;
      setViewOffset(prev => ({ x: prev.x + dx, y: prev.y + dy }));
      setLastMousePos({ x: e.clientX, y: e.clientY });
      return;
    }

    if (draggingId === 'scrollbar-h' || draggingId === 'scrollbar-v') {
      if (draggingId === 'scrollbar-h') {
        const ratio = (e.clientX - rect.left) / rect.width;
        setViewOffset(prev => ({ ...prev, x: -(contentBounds.minX + ratio * contentBounds.width - rect.width / 2) }));
      } else {
        const ratio = (e.clientY - rect.top) / rect.height;
        setViewOffset(prev => ({ ...prev, y: -(contentBounds.minY + ratio * contentBounds.height - rect.height / 2) }));
      }
      return;
    }

    if (mode !== 'select' || isLocked) return;

    const x = e.clientX - rect.left - viewOffset.x;
    const y = e.clientY - rect.top - viewOffset.y;

    if (draggingId && dragType === 'node') {
      onNodeMove(draggingId, x - 65, y - 22);
    } else if (draggingId && dragType === 'group') {
      const group = groups.find(g => g.id === draggingId);
      if (group) onUpdateGroup(draggingId, { position: { x: x - group.size.width / 2, y: y - 16 } });
    } else if (resizingId) {
      const group = groups.find(g => g.id === resizingId);
      if (group) {
        onUpdateGroup(resizingId, { size: { width: Math.max(200, x - group.position.x), height: Math.max(150, y - group.position.y) } });
      }
    }
  };

  const handleMouseUp = () => {
    setIsPanning(false);
    setDraggingId(null);
    setResizingId(null);
  };

  const getStrobeClass = (status: string) => {
    switch(status) {
      case 'online': return 'animate-strobe-green';
      case 'warning': return 'animate-strobe-yellow';
      case 'error': return 'animate-strobe-red';
      default: return 'animate-strobe-green';
    }
  };

  const getStatusConfig = (status: string) => {
    switch(status) {
      case 'online': return { text: 'RUNNING', color: 'text-emerald-400', border: 'border-emerald-500/30' };
      case 'warning': return { text: 'STRESSED', color: 'text-amber-400', border: 'border-amber-500/30' };
      case 'error': return { text: 'OFFLINE', color: 'text-rose-400', border: 'border-rose-500/30' };
      default: return { text: 'RUNNING', color: 'text-emerald-400', border: 'border-emerald-500/30' };
    }
  };

  const getElementInfo = (id: string) => {
    const node = nodes.find(n => n.id === id);
    if (node) return { x: node.position.x, y: node.position.y, w: 130, h: 44, cx: node.position.x + 65, cy: node.position.y + 22, isGroup: false };
    const group = groups.find(g => g.id === id);
    if (group) return { x: group.position.x, y: group.position.y, w: group.size.width, h: group.size.height, cx: group.position.x + group.size.width / 2, cy: group.position.y + group.size.height / 2, isGroup: true };
    return null;
  };

  const getConnectionPoint = (sourceId: string, targetId: string) => {
    const s = getElementInfo(sourceId);
    const t = getElementInfo(targetId);
    if (!s || !t) return null;
    const getIntersection = (rect: any, otherCenter: {x: number, y: number}) => {
      const dx = otherCenter.x - rect.cx;
      const dy = otherCenter.y - rect.cy;
      const hw = rect.w / 2;
      const hh = rect.h / 2;
      const scale = Math.min(dx !== 0 ? Math.abs(hw / dx) : Infinity, dy !== 0 ? Math.abs(hh / dy) : Infinity);
      return { x: rect.cx + dx * scale, y: rect.cy + dy * scale };
    };
    return { start: getIntersection(s, { x: t.cx, y: t.cy }), end: getIntersection(t, { x: s.cx, y: s.cy }) };
  };

  const getBezierPath = (start: {x: number, y: number}, end: {x: number, y: number}) => {
    const dx = Math.abs(end.x - start.x);
    const dy = Math.abs(end.y - start.y);
    const horizontal = dx > dy;
    const ctrl1 = horizontal ? { x: start.x + dx / 4, y: start.y } : { x: start.x, y: start.y + dy / 4 };
    const ctrl2 = horizontal ? { x: end.x - dx / 4, y: end.y } : { x: end.x, y: end.y - dy / 4 };
    return `M ${start.x} ${start.y} C ${ctrl1.x} ${ctrl1.y}, ${ctrl2.x} ${ctrl2.y}, ${end.x} ${end.y}`;
  };

  const gridBackground = useMemo(() => ({
    backgroundImage: `
      linear-gradient(to right, rgba(14, 165, 233, 0.04) 1px, transparent 1px),
      linear-gradient(to bottom, rgba(14, 165, 233, 0.04) 1px, transparent 1px)
    `,
    backgroundSize: '40px 40px',
    backgroundPosition: `${viewOffset.x}px ${viewOffset.y}px`
  }), [viewOffset]);

  // 根据 style 映射 CSS 类名
  const getConnectionClass = (style: string | undefined) => {
    switch (style) {
      case 'fluid': return 'connection-ekg';
      case 'packet': return 'connection-oscilloscope';
      case 'dashed': return 'connection-flicker';
      case 'signal': 
      default: return 'connection-signal';
    }
  };

  return (
    <div 
      ref={containerRef}
      style={gridBackground}
      className={`w-full h-full relative select-none overflow-hidden ${isPanning ? 'cursor-grabbing' : 'cursor-default'}`}
      onMouseDown={handleMouseDown}
      onMouseMove={handleMouseMove}
      onMouseUp={handleMouseUp}
      onMouseLeave={handleMouseUp}
    >
      <div style={{ transform: `translate(${viewOffset.x}px, ${viewOffset.y}px)`, position: 'absolute', inset: 0, pointerEvents: 'none' }}>
        {/* 分组层 */}
        {groups.map((group) => (
          <div
            key={group.id}
            style={{ left: group.position.x, top: group.position.y, width: group.size.width, height: group.size.height, pointerEvents: 'auto' }}
            className={`absolute z-0 transition-all ${isLocked ? 'pointer-events-auto' : 'cursor-move'}`}
            onClick={(e) => { e.stopPropagation(); onElementClick(group.id); }}
            onMouseDown={(e) => { if (mode === 'select' && !isLocked) { e.stopPropagation(); setDraggingId(group.id); setDragType('group'); } }}
          >
            <div className={`absolute inset-0 rounded-3xl bg-slate-950/20 backdrop-blur-sm border transition-all duration-500 ${selectedId === group.id ? 'border-sky-500 shadow-[0_0_40px_rgba(14,165,233,0.1)] ring-1 ring-sky-500/30' : 'border-slate-800/40'} ${getStrobeClass(group.status)}`}></div>
            <div className="absolute top-4 left-6 flex items-center gap-3 opacity-60">
              <span className="text-[9px] font-black text-slate-500 tracking-[0.3em] uppercase">{group.name}</span>
            </div>
            {!isLocked && (
              <div 
                className="absolute bottom-3 right-3 w-6 h-6 cursor-nwse-resize opacity-20 hover:opacity-100 transition-opacity"
                onMouseDown={(e) => { e.stopPropagation(); setResizingId(group.id); }}
              >
                <div className="w-full h-full border-r-2 border-b-2 border-slate-500 rounded-br"></div>
              </div>
            )}
          </div>
        ))}

        {/* 连线层 */}
        <svg className="absolute inset-0 w-full h-full pointer-events-none z-[5]">
          <defs>
            <filter id="glow" x="-20%" y="-20%" width="140%" height="140%">
              <feGaussianBlur stdDeviation="3" result="blur" />
              <feComposite in="SourceGraphic" in2="blur" operator="over" />
            </filter>
          </defs>
          {connections.map((conn) => {
            const points = getConnectionPoint(conn.sourceId, conn.targetId);
            if (!points) return null;
            const { start, end } = points;
            const bezierPath = getBezierPath(start, end);
            const isSelected = selectedConnectionId === conn.id;
            const color = conn.status === 'error' ? '#ef4444' : '#0ea5e9';
            return (
              <g key={conn.id}>
                <path d={bezierPath} stroke="transparent" strokeWidth="24" fill="none" className="cursor-pointer pointer-events-auto" onClick={(e) => { e.stopPropagation(); onConnectionClick(conn.id); }} />
                <path 
                  d={bezierPath} 
                  stroke={color} 
                  strokeWidth={isSelected ? 4 : 2} 
                  fill="none" 
                  className={getConnectionClass(conn.style)} 
                  filter="url(#glow)" 
                  style={{ opacity: isSelected ? 1 : 0.4, color }} 
                />
                <text className="text-[7px] font-black tracking-widest" fill={color} dy="-8" style={{ opacity: isSelected ? 1 : 0.3 }}>
                  <textPath href={`#p-${conn.id}`} startOffset="50%" textAnchor="middle">{conn.label}</textPath>
                </text>
                <path id={`p-${conn.id}`} d={end.x < start.x ? getBezierPath(end, start) : bezierPath} fill="none" />
              </g>
            );
          })}
        </svg>

        {/* 节点层 (服务按钮) */}
        {nodes.map((node) => {
          const isSelected = selectedId === node.id;
          const statusConfig = getStatusConfig(node.status);
          const serviceColor = SERVICE_COLORS[node.type];
          return (
            <div key={node.id} style={{ left: node.position.x, top: node.position.y, width: '130px', height: '44px', pointerEvents: 'auto' }} className="absolute z-10">
              <div 
                className={`w-full h-full node-button rounded-xl flex items-center px-3 relative ${getStrobeClass(node.status)} ${isSelected ? 'ring-2 ring-sky-500/50 scale-105 z-20' : ''} ${isLocked ? 'cursor-default' : 'cursor-pointer'}`}
                onClick={(e) => { e.stopPropagation(); onElementClick(node.id); }}
                onMouseDown={(e) => { if (mode === 'select' && !isLocked) { e.stopPropagation(); setDraggingId(node.id); setDragType('node'); } }}
              >
                <div className="flex items-center gap-3 w-full">
                  <div className="w-8 h-8 rounded-lg bg-slate-900/50 flex items-center justify-center border border-white/5 shadow-inner">
                    <i className={`fas ${SERVICE_ICONS[node.type]} text-xs`} style={{ color: serviceColor, filter: `drop-shadow(0 0 5px ${serviceColor}40)` }}></i>
                  </div>
                  <div className="flex flex-col min-w-0">
                    <span className="text-[9px] font-black text-slate-100 tracking-wider truncate uppercase">{node.name}</span>
                    <span className={`text-[7px] font-bold tracking-widest ${statusConfig.color} mt-0.5`}>{statusConfig.text}</span>
                  </div>
                </div>
                {/* 右上角运行指示点 */}
                <div className="absolute top-2 right-2">
                   <div className={`w-1 h-1 rounded-full ${node.status === 'online' ? 'bg-emerald-400' : node.status === 'warning' ? 'bg-amber-400' : 'bg-rose-400'} shadow-[0_0_5px_currentColor]`}></div>
                </div>
              </div>
            </div>
          );
        })}
      </div>

      {/* 底部装饰标识 */}
      <div className="absolute bottom-8 right-10 pointer-events-none">
        <div className="flex flex-col items-end opacity-20">
          <span className="text-[10px] font-black text-sky-500 tracking-[0.5em] uppercase">NEOOPS_SYSTEM_ACTIVE</span>
          <div className="w-32 h-[1px] bg-sky-500/30 mt-1"></div>
        </div>
      </div>
    </div>
  );
};

export default Workspace;

import React, { useState, useCallback, useEffect, useRef } from 'react';
import Sidebar from './components/Sidebar';
import UIOverlay from './components/UIOverlay';
import Workspace from './components/Workspace';
import { ServiceNode, Connection, ServiceType, GroupNode } from './types';
import { suggestLayout } from './geminiService';

/**
 * NeoOps 运维系统 v3.0 - Visual Evolution
 * 核心升级：动态场域、霓虹发光系统、多层视觉叠加工艺
 */

const STORAGE_KEY = 'NEOOPS_CORE_STORAGE_V3';

const App: React.FC = () => {
  const [nodes, setNodes] = useState<ServiceNode[]>([]);
  const [groups, setGroups] = useState<GroupNode[]>([]);
  const [connections, setConnections] = useState<Connection[]>([]);

  const [toast, setToast] = useState<{ message: string; visible: boolean }>({ message: '', visible: false });
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [selectedConnectionId, setSelectedConnectionId] = useState<string | null>(null);
  const [mode, setMode] = useState<'select' | 'add' | 'connect'>('select');
  const [isLocked, setIsLocked] = useState(false);
  const [connectSourceId, setConnectSourceId] = useState<string | null>(null);
  const [isAnalyzing, setIsAnalyzing] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const savedData = localStorage.getItem(STORAGE_KEY);
    if (savedData) {
      try {
        const parsed = JSON.parse(savedData);
        setNodes(parsed.nodes || []);
        setGroups(parsed.groups || []);
        setConnections(parsed.connections || []);
      } catch (e) {
        console.error("Layout restoration failed", e);
      }
    } else {
      // 默认演示布局
      setNodes([
        { id: 'n1', name: 'CORE_GATEWAY', type: ServiceType.GATEWAY, position: { x: 100, y: 350, z: 0 }, status: 'online', lastUpdated: new Date().toISOString() },
        { id: 'n2', name: 'AUTH_CLUSTER', type: ServiceType.SERVER, position: { x: 400, y: 300, z: 0 }, status: 'online', lastUpdated: new Date().toISOString() },
        { id: 'n3', name: 'MASTER_DB', type: ServiceType.DATABASE, position: { x: 750, y: 450, z: 0 }, status: 'warning', lastUpdated: new Date().toISOString() },
      ]);
      setGroups([
        { id: 'g1', name: 'PRODUCTION_ZONE', position: { x: 300, y: 180 }, size: { width: 620, height: 480 }, color: '#38bdf8', status: 'online' }
      ]);
      setConnections([
        { id: 'c1', sourceId: 'n1', targetId: 'n2', label: 'TRAFFIC_IN', trafficLoad: 0.2, status: 'online', style: 'signal' },
        { id: 'c2', sourceId: 'n2', targetId: 'n3', label: 'SQL_STREAM', trafficLoad: 0.85, status: 'online', style: 'fluid' },
      ]);
    }
  }, []);

  const showToast = (message: string) => {
    setToast({ message, visible: true });
    setTimeout(() => setToast({ message: '', visible: false }), 3000);
  };

  const handleSaveLayout = useCallback(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify({ nodes, groups, connections }));
    showToast("CORE_MEMORY_SYNCED // 布局已同步");
  }, [nodes, groups, connections]);

  const toggleLock = useCallback(() => {
    setIsLocked(prev => !prev);
    if (!isLocked) {
      handleSaveLayout();
      showToast("SYSTEM_LOCK_ENGAGED");
    } else {
      showToast("SYSTEM_FREE_ORCHESTRATION");
    }
  }, [isLocked, handleSaveLayout]);

  const handleAutoLayout = async (desc: string) => {
    if (!desc || isLocked) return;
    setIsAnalyzing(true);
    try {
      const layout = await suggestLayout(desc);
      const newNodes: ServiceNode[] = layout.nodes.map((n: any, i: number) => ({
        id: `ai-n-${i}-${Date.now()}`,
        name: n.name.toUpperCase(),
        type: n.type as ServiceType,
        position: { x: (n.x + 1) * 70, y: (n.y + 1) * 60, z: 0 },
        status: 'online',
        lastUpdated: new Date().toISOString()
      }));
      const newConns: Connection[] = layout.connections.map((c: any, i: number) => ({
        id: `ai-c-${i}-${Date.now()}`,
        sourceId: newNodes[c.sourceIndex].id,
        targetId: newNodes[c.targetIndex].id,
        label: c.label.toUpperCase(),
        trafficLoad: 0.1,
        status: 'online',
        style: 'signal'
      }));
      setNodes(newNodes);
      setConnections(newConns);
      showToast("AI_ARCHITECT_COMPLETED");
    } catch (e) {
      showToast("AI_NEURAL_LINK_ERROR");
    }
    setIsAnalyzing(false);
  };

  return (
    <div className="flex h-screen w-screen bg-[#02040a] text-slate-100 overflow-hidden font-sans antialiased selection:bg-sky-500/30">
      <style>{`
        /* --- 核心：高级节点动效 --- */
        .node-button {
          background: linear-gradient(135deg, rgba(15, 23, 42, 0.7), rgba(2, 6, 23, 0.8));
          backdrop-filter: blur(20px) saturate(180%);
          border: 1px solid rgba(56, 189, 248, 0.1);
          box-shadow: 
            0 10px 40px -10px rgba(0, 0, 0, 0.5),
            inset 0 1px 1px rgba(255, 255, 255, 0.05);
          transition: all 0.5s cubic-bezier(0.19, 1, 0.22, 1);
        }

        .node-button:hover {
          background: rgba(30, 41, 59, 0.8);
          border-color: rgba(56, 189, 248, 0.5);
          transform: translateY(-4px) scale(1.02);
          box-shadow: 
            0 20px 50px -15px rgba(14, 165, 233, 0.3),
            0 0 15px rgba(14, 165, 233, 0.1);
        }

        /* 旋转装饰环 */
        .status-ring {
          position: absolute;
          inset: -5px;
          border: 1px dashed transparent;
          border-radius: 14px;
          pointer-events: none;
          transition: all 0.5s;
        }
        .node-button:hover .status-ring {
          border-color: rgba(14, 165, 233, 0.4);
          animation: spin 8s linear infinite;
          inset: -8px;
        }

        @keyframes spin { from { transform: rotate(0deg); } to { transform: rotate(360deg); } }

        /* --- 链路视觉引擎 --- */
        @keyframes signal-run { 0% { stroke-dashoffset: 400; } 100% { stroke-dashoffset: 0; } }
        @keyframes ekg-move { 0% { stroke-dashoffset: 800; } 100% { stroke-dashoffset: 0; } }
        @keyframes ekg-spike {
          0%, 100% { stroke-width: 2px; opacity: 0.3; }
          10%, 20% { stroke-width: 5px; opacity: 1; filter: drop-shadow(0 0 8px currentColor); }
        }
        @keyframes glitched {
          0% { opacity: 0.1; stroke-dashoffset: 0; }
          20% { opacity: 0.8; stroke-dashoffset: 40; }
          21% { opacity: 0.1; }
          100% { opacity: 0.1; stroke-dashoffset: 200; }
        }
        @keyframes packet-dash {
          0% { stroke-dashoffset: 100; opacity: 1; }
          100% { stroke-dashoffset: 0; opacity: 0.4; }
        }

        .connection-signal { stroke-dasharray: 50, 350; animation: signal-run 2s linear infinite; }
        .connection-ekg { 
           stroke-dasharray: 60, 740; 
           animation: ekg-move 1.5s linear infinite, ekg-spike 0.6s ease-out infinite; 
           stroke-linecap: round;
        }
        .connection-oscilloscope { 
           stroke-dasharray: 10, 5, 2, 5; 
           animation: packet-dash 0.3s steps(4) infinite; 
        }
        .connection-flicker { 
           stroke-dasharray: 4, 1; 
           animation: glitched 0.2s infinite; 
        }

        /* 全局扫描与噪点 */
        .scanline {
          position: fixed; inset: 0;
          background: linear-gradient(to bottom, transparent 50%, rgba(0, 0, 0, 0.1) 50%);
          background-size: 100% 4px;
          z-index: 60; pointer-events: none; opacity: 0.15;
        }
        .noise {
          position: fixed; inset: 0;
          background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noiseFilter'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.65' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noiseFilter)'/%3E%3C/svg%3E");
          z-index: 59; pointer-events: none; opacity: 0.03;
        }
      `}</style>

      <div className="scanline"></div>
      <div className="noise"></div>

      {toast.visible && (
        <div className="fixed top-12 left-1/2 -translate-x-1/2 z-[100] bg-slate-900/90 border border-sky-500/40 px-10 py-3 rounded-full shadow-[0_0_80px_rgba(14,165,233,0.4)] backdrop-blur-3xl animate-in fade-in zoom-in duration-300">
          <div className="flex items-center gap-4">
            <div className="w-1.5 h-1.5 rounded-full bg-sky-400 animate-ping"></div>
            <span className="text-[10px] font-black text-sky-400 uppercase tracking-[0.6em]">{toast.message}</span>
          </div>
        </div>
      )}

      <Sidebar 
        nodes={nodes} groups={groups} connections={connections}
        selectedId={selectedId} selectedConnectionId={selectedConnectionId}
        addNode={(type, name, status) => setNodes(prev => [...prev, { id: `n-${Date.now()}`, name: name.toUpperCase(), type, position: { x: 250, y: 250, z: 0 }, status, lastUpdated: new Date().toISOString() }])}
        addGroup={(name, status) => setGroups(prev => [...prev, { id: `g-${Date.now()}`, name: name.toUpperCase(), position: { x: 200, y: 200 }, size: { width: 480, height: 380 }, color: '#818cf8', status }])}
        deleteNode={(id) => { setNodes(n => n.filter(x => x.id !== id)); setConnections(c => c.filter(x => x.sourceId !== id && x.targetId !== id)); setSelectedId(null); }}
        deleteGroup={(id) => { setGroups(g => g.filter(x => x.id !== id)); setSelectedId(null); }}
        deleteConnection={(id) => { setConnections(c => c.filter(x => x.id !== id)); setSelectedConnectionId(null); }}
        updateConnection={(id, updates) => setConnections(prev => prev.map(c => c.id === id ? { ...c, ...updates } : c))}
        isAnalyzing={isAnalyzing} onAutoLayout={handleAutoLayout}
        isLocked={isLocked} onExport={() => {
            const data = { nodes, groups, connections, version: "3.0" };
            const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
            const url = URL.createObjectURL(blob);
            const link = document.createElement('a');
            link.href = url; link.download = 'NEOOPS_ARCH.json'; link.click();
            showToast("DATA_EXTRACTED");
        }}
        onImport={() => fileInputRef.current?.click()}
      />

      <main className="flex-1 relative overflow-hidden bg-[radial-gradient(circle_at_50%_50%,_#0a0f1d_0%,_#02040a_100%)]">
        <UIOverlay 
          mode={mode} setMode={setMode} 
          connectSource={nodes.find(n => n.id === connectSourceId)?.name || groups.find(g => g.id === connectSourceId)?.name} 
          isLocked={isLocked} setIsLocked={toggleLock} 
        />

        <Workspace 
          nodes={nodes} groups={groups} connections={connections}
          selectedId={selectedId} selectedConnectionId={selectedConnectionId}
          onElementClick={(id) => {
            if (mode === 'connect' && !isLocked) {
              if (!connectSourceId) setConnectSourceId(id);
              else {
                setConnections(prev => [...prev, { id: `c-${Date.now()}`, sourceId: connectSourceId, targetId: id, label: 'LINK_ESTABLISHED', trafficLoad: 0.15, style: 'signal', status: 'online' }]);
                setConnectSourceId(null); setMode('select');
              }
            } else { setSelectedId(id === selectedId ? null : id); setSelectedConnectionId(null); }
          }}
          onConnectionClick={(id) => { setSelectedConnectionId(id === selectedConnectionId ? null : id); setSelectedId(null); }}
          onNodeMove={(id, x, y) => !isLocked && setNodes(prev => prev.map(n => n.id === id ? { ...n, position: { ...n.position, x, y } } : n))}
          onUpdateGroup={(id, updates) => !isLocked && setGroups(prev => prev.map(g => g.id === id ? { ...g, ...updates } : g))}
          onDeleteGroup={(id) => setGroups(g => g.filter(x => x.id !== id))}
          onDeleteNode={(id) => setNodes(n => n.filter(x => x.id !== id))}
          mode={mode} isLocked={isLocked}
        />

        {isAnalyzing && (
            <div className="absolute inset-0 z-50 flex items-center justify-center bg-black/80 backdrop-blur-2xl">
                <div className="flex flex-col items-center gap-12">
                    <div className="relative w-24 h-24">
                        <div className="absolute inset-0 border-2 border-sky-500/20 rounded-full"></div>
                        <div className="absolute inset-0 border-2 border-sky-400 border-t-transparent rounded-full animate-spin"></div>
                        <div className="absolute inset-4 border border-indigo-500/30 rounded-full animate-[spin_3s_linear_infinite_reverse]"></div>
                    </div>
                    <p className="text-sky-400 font-mono text-[11px] font-black tracking-[1em] animate-pulse">NEURAL_SYNTHESIS_IN_PROGRESS</p>
                </div>
            </div>
        )}
      </main>

      <input type="file" ref={fileInputRef} onChange={(e) => {
        const file = e.target.files?.[0];
        if (!file) return;
        const reader = new FileReader();
        reader.onload = (event) => {
          try {
            const parsed = JSON.parse(event.target?.result as string);
            setNodes(parsed.nodes || []);
            setGroups(parsed.groups || []);
            setConnections(parsed.connections || []);
            showToast("RESTORE_SUCCESSFUL");
          } catch { showToast("CORE_DATA_CORRUPTED"); }
        };
        reader.readAsText(file);
      }} className="hidden" />
    </div>
  );
};

export default App;

import React, { useRef, useState, useMemo } from 'react';
import { ServiceNode, Connection, GroupNode } from '../types';
import { SERVICE_ICONS, SERVICE_COLORS } from '../constants';

interface WorkspaceProps {
  nodes: ServiceNode[];
  groups: GroupNode[];
  connections: Connection[];
  selectedId: string | null;
  selectedConnectionId: string | null;
  onElementClick: (id: string) => void;
  onConnectionClick: (id: string) => void;
  onNodeMove: (id: string, x: number, y: number) => void;
  onUpdateGroup: (id: string, updates: Partial<GroupNode>) => void;
  onDeleteGroup: (id: string) => void;
  onDeleteNode: (id: string) => void;
  mode: string;
  isLocked: boolean;
}

const Workspace: React.FC<WorkspaceProps> = ({ 
  nodes, groups, connections, selectedId, selectedConnectionId, onElementClick, onConnectionClick, onNodeMove, onUpdateGroup, isLocked, mode
}) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const [viewOffset, setViewOffset] = useState({ x: 0, y: 0 });
  const [isPanning, setIsPanning] = useState(false);
  const [lastMousePos, setLastMousePos] = useState({ x: 0, y: 0 });
  const [draggingId, setDraggingId] = useState<string | null>(null);
  const [resizingId, setResizingId] = useState<string | null>(null);
  const [dragType, setDragType] = useState<'node' | 'group'>('node');

  const handleMouseDown = (e: React.MouseEvent) => {
    if (!containerRef.current) return;
    if (e.target === containerRef.current) {
      setIsPanning(true);
      setLastMousePos({ x: e.clientX, y: e.clientY });
    }
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (!containerRef.current) return;
    const rect = containerRef.current.getBoundingClientRect();

    if (isPanning) {
      const dx = e.clientX - lastMousePos.x;
      const dy = e.clientY - lastMousePos.y;
      setViewOffset(prev => ({ x: prev.x + dx, y: prev.y + dy }));
      setLastMousePos({ x: e.clientX, y: e.clientY });
      return;
    }

    if (mode !== 'select' || isLocked) return;
    const x = e.clientX - rect.left - viewOffset.x;
    const y = e.clientY - rect.top - viewOffset.y;

    if (draggingId) {
      if (dragType === 'node') onNodeMove(draggingId, x - 75, y - 25);
      else {
        const group = groups.find(g => g.id === draggingId);
        if (group) onUpdateGroup(draggingId, { position: { x: x - group.size.width / 2, y: y - 20 } });
      }
    } else if (resizingId) {
      const group = groups.find(g => g.id === resizingId);
      if (group) {
        onUpdateGroup(resizingId, { size: { width: Math.max(200, x - group.position.x), height: Math.max(150, y - group.position.y) } });
      }
    }
  };

  const handleMouseUp = () => { setIsPanning(false); setDraggingId(null); setResizingId(null); };

  const getElementInfo = (id: string) => {
    const node = nodes.find(n => n.id === id);
    if (node) return { x: node.position.x, y: node.position.y, w: 150, h: 50, cx: node.position.x + 75, cy: node.position.y + 25 };
    const group = groups.find(g => g.id === id);
    if (group) return { x: group.position.x, y: group.position.y, w: group.size.width, h: group.size.height, cx: group.position.x + group.size.width / 2, cy: group.position.y + group.size.height / 2 };
    return null;
  };

  const getConnectionPoint = (sourceId: string, targetId: string) => {
    const s = getElementInfo(sourceId);
    const t = getElementInfo(targetId);
    if (!s || !t) return null;
    const getIntersection = (rect: any, other: any) => {
      const dx = other.cx - rect.cx;
      const dy = other.cy - rect.cy;
      const hw = rect.w / 2;
      const hh = rect.h / 2;
      const scale = Math.min(dx !== 0 ? Math.abs(hw / dx) : Infinity, dy !== 0 ? Math.abs(hh / dy) : Infinity);
      return { x: rect.cx + dx * scale, y: rect.cy + dy * scale };
    };
    return { start: getIntersection(s, t), end: getIntersection(t, s) };
  };

  const getBezierPath = (start: {x: number, y: number}, end: {x: number, y: number}) => {
    const midX = (start.x + end.x) / 2;
    return `M ${start.x} ${start.y} C ${midX} ${start.y}, ${midX} ${end.y}, ${end.x} ${end.y}`;
  };

  const gridStyle = useMemo(() => ({
    background: `
      radial-gradient(circle at 1px 1px, rgba(56, 189, 248, 0.05) 1px, transparent 0),
      linear-gradient(to right, rgba(56, 189, 248, 0.03) 1px, transparent 1px),
      linear-gradient(to bottom, rgba(56, 189, 248, 0.03) 1px, transparent 1px)
    `,
    backgroundSize: '20px 20px, 100px 100px, 100px 100px',
    backgroundPosition: `${viewOffset.x}px ${viewOffset.y}px`,
  }), [viewOffset]);

  const getConnectionClass = (style: string | undefined) => {
    switch (style) {
      case 'fluid': return 'connection-ekg';
      case 'packet': return 'connection-oscilloscope';
      case 'dashed': return 'connection-flicker';
      default: return 'connection-signal';
    }
  };

  return (
    <div 
      ref={containerRef}
      style={gridStyle}
      className={`w-full h-full relative select-none overflow-hidden ${isPanning ? 'cursor-grabbing' : 'cursor-default'}`}
      onMouseDown={handleMouseDown}
      onMouseMove={handleMouseMove}
      onMouseUp={handleMouseUp}
      onMouseLeave={handleMouseUp}
    >
      <div style={{ transform: `translate(${viewOffset.x}px, ${viewOffset.y}px)`, position: 'absolute', inset: 0, pointerEvents: 'none' }}>
        {/* 背景光晕装饰 */}
        <div className="absolute top-[20%] left-[30%] w-[600px] h-[600px] bg-sky-500/5 rounded-full blur-[120px] pointer-events-none"></div>
        <div className="absolute bottom-[10%] right-[20%] w-[400px] h-[400px] bg-indigo-500/5 rounded-full blur-[100px] pointer-events-none"></div>

        {/* 分组层 */}
        {groups.map((group) => (
          <div
            key={group.id}
            style={{ left: group.position.x, top: group.position.y, width: group.size.width, height: group.size.height, pointerEvents: 'auto' }}
            className={`absolute z-0 group ${isLocked ? '' : 'cursor-move'}`}
            onMouseDown={(e) => { if (mode === 'select' && !isLocked) { e.stopPropagation(); setDraggingId(group.id); setDragType('group'); } }}
            onClick={(e) => { e.stopPropagation(); onElementClick(group.id); }}
          >
            <div className={`absolute inset-0 rounded-[32px] bg-slate-900/10 backdrop-blur-md border transition-all duration-500 ${selectedId === group.id ? 'border-sky-500/50 shadow-[0_0_60px_rgba(14,165,233,0.15)] bg-sky-500/5' : 'border-slate-800/40'}`}></div>
            <div className="absolute top-6 left-8 flex items-center gap-4">
               <div className="w-1.5 h-1.5 rounded-full bg-sky-500 shadow-[0_0_8px_rgba(14,165,233,0.8)]"></div>
               <span className="text-[10px] font-black text-slate-500 tracking-[0.4em] uppercase">{group.name}</span>
            </div>
            {!isLocked && (
              <div 
                className="absolute bottom-4 right-4 w-6 h-6 cursor-nwse-resize opacity-0 group-hover:opacity-40 transition-opacity"
                onMouseDown={(e) => { e.stopPropagation(); setResizingId(group.id); }}
              >
                <div className="w-full h-full border-r-2 border-b-2 border-slate-500 rounded-br-lg"></div>
              </div>
            )}
          </div>
        ))}

        {/* 连线层 */}
        <svg className="absolute inset-0 w-full h-full pointer-events-none z-[5]">
          <defs>
            <filter id="neon-glow" x="-50%" y="-50%" width="200%" height="200%">
              <feGaussianBlur stdDeviation="3.5" result="blur" />
              <feComposite in="SourceGraphic" in2="blur" operator="over" />
            </filter>
          </defs>
          {connections.map((conn) => {
            const points = getConnectionPoint(conn.sourceId, conn.targetId);
            if (!points) return null;
            const { start, end } = points;
            const path = getBezierPath(start, end);
            const isSelected = selectedConnectionId === conn.id;
            const color = conn.status === 'error' ? '#f43f5e' : isSelected ? '#38bdf8' : '#0ea5e9';
            return (
              <g key={conn.id}>
                <path d={path} stroke="transparent" strokeWidth="20" fill="none" className="cursor-pointer pointer-events-auto" onClick={(e) => { e.stopPropagation(); onConnectionClick(conn.id); }} />
                <path 
                  d={path} stroke={color} strokeWidth={isSelected ? 4 : 2} fill="none" 
                  className={getConnectionClass(conn.style)} filter="url(#neon-glow)"
                  style={{ opacity: isSelected ? 1 : 0.4 }} 
                />
                <text className="text-[8px] font-black tracking-widest fill-sky-400" dy="-10" style={{ opacity: isSelected ? 0.9 : 0.2 }}>
                  <textPath href={`#p-${conn.id}`} startOffset="50%" textAnchor="middle">{conn.label}</textPath>
                </text>
                <path id={`p-${conn.id}`} d={end.x < start.x ? getBezierPath(end, start) : path} fill="none" />
              </g>
            );
          })}
        </svg>

        {/* 节点层 */}
        {nodes.map((node) => {
          const isSelected = selectedId === node.id;
          const statusColor = node.status === 'online' ? 'emerald' : node.status === 'warning' ? 'amber' : 'rose';
          return (
            <div key={node.id} style={{ left: node.position.x, top: node.position.y, width: '150px', height: '50px', pointerEvents: 'auto' }} className="absolute z-10">
              <div 
                className={`w-full h-full node-button rounded-xl flex items-center px-4 relative ${isSelected ? 'ring-2 ring-sky-500/60 scale-105 z-20' : ''}`}
                onClick={(e) => { e.stopPropagation(); onElementClick(node.id); }}
                onMouseDown={(e) => { if (mode === 'select' && !isLocked) { e.stopPropagation(); setDraggingId(node.id); setDragType('node'); } }}
              >
                <div className="status-ring"></div>
                <div className="flex items-center gap-4 w-full relative z-10">
                  <div className="w-9 h-9 rounded-lg bg-slate-950/60 flex items-center justify-center border border-white/5">
                    <i className={`fas ${SERVICE_ICONS[node.type]} text-xs`} style={{ color: SERVICE_COLORS[node.type] }}></i>
                  </div>
                  <div className="flex flex-col min-w-0">
                    <span className="text-[10px] font-black text-slate-100 tracking-wider truncate">{node.name}</span>
                    <span className={`text-[7px] font-black tracking-[0.2em] text-${statusColor}-400/80 mt-1 uppercase`}>{node.status === 'online' ? 'Active' : 'Alert'}</span>
                  </div>
                </div>
                <div className={`absolute top-2 right-2 w-1 h-1 rounded-full bg-${statusColor}-400 shadow-[0_0_10px_currentColor]`}></div>
              </div>
            </div>
          );
        })}
      </div>

      {/* 装饰边框水印 */}
      <div className="absolute bottom-10 right-12 pointer-events-none opacity-20">
         <div className="flex flex-col items-end gap-1">
            <span className="text-[9px] font-black tracking-[1em] text-sky-500">NEOOPS_OS_CORE</span>
            <div className="w-48 h-[1px] bg-gradient-to-r from-transparent via-sky-500 to-transparent"></div>
         </div>
      </div>
    </div>
  );
};

