import React, { useRef, useMemo } from 'react';
import { useFrame } from '@react-three/fiber';
import * as THREE from 'three';
import { QuadraticBezierLine } from '@react-three/drei';
import { Connection } from '../types';

interface ConnectionLineProps {
  connection: Connection;
  start: { x: number, y: number, z: number };
  end: { x: number, y: number, z: number };
}

const ConnectionLine: React.FC<ConnectionLineProps> = ({ connection, start, end }) => {
  const particleRef = useRef<THREE.Mesh>(null);

  // 映射到 3D 坐标
  const startVec = useMemo(() => new THREE.Vector3(start.x / 50, 0, start.y / 50), [start]);
  const endVec = useMemo(() => new THREE.Vector3(end.x / 50, 0, end.y / 50), [end]);

  const mid = useMemo(() => {
    const v = new THREE.Vector3().addVectors(startVec, endVec).multiplyScalar(0.5);
    // 负载越高，曲线弧度越大
    v.y += connection.trafficLoad * 2 + 0.5;
    return v;
  }, [startVec, endVec, connection.trafficLoad]);

  const curve = useMemo(() => {
    return new THREE.QuadraticBezierCurve3(startVec, mid, endVec);
  }, [startVec, mid, endVec]);

  useFrame((state) => {
    if (particleRef.current) {
      const speed = 0.4 * (1 + connection.trafficLoad);
      const time = (state.clock.getElapsedTime() * speed) % 1;
      const point = curve.getPoint(time);
      particleRef.current.position.copy(point);

      // 粒子发光动效
      const material = particleRef.current.material as THREE.MeshBasicMaterial;
      material.opacity = 0.5 + Math.sin(state.clock.getElapsedTime() * 10) * 0.5;
    }
  });

  const color = connection.status === 'error' ? "#f43f5e" : connection.trafficLoad > 0.7 ? "#fbbf24" : "#0ea5e9";

  return (
    <group>
      <QuadraticBezierLine
        start={startVec}
        end={endVec}
        mid={mid}
        color={color}
        lineWidth={2}
        transparent
        opacity={0.3}
      />

      {/* 3D 流量粒子 - 模拟数据包 */}
      <mesh ref={particleRef}>
        <sphereGeometry args={[0.08, 16, 16]} />
        <meshBasicMaterial color={color} transparent opacity={0.8} />
      </mesh>

      {/* 链路标签 */}
      <Html position={[mid.x, mid.y + 0.2, mid.z]} center distanceFactor={10}>
        <div className="px-2 py-0.5 bg-slate-900/60 backdrop-blur-md border border-white/10 rounded text-[7px] font-black text-sky-400 whitespace-nowrap opacity-40">
          {connection.label}
        </div>
      </Html>
    </group>
  );
};

