  draggable: boolean;
}

const ServiceNodeMesh: React.FC<ServiceNodeMeshProps> = ({ node, isSelected, onClick }) => {
  const meshRef = useRef<THREE.Group>(null);
  const [hovered, setHovered] = useState(false);

  const statusColor = node.status === 'online' ? 'emerald' : node.status === 'warning' ? 'amber' : 'rose';
  const serviceColor = SERVICE_COLORS[node.type];

  useFrame((state) => {
    if (meshRef.current) {
      const time = state.clock.getElapsedTime();
      // 3D 浮动感
      meshRef.current.position.y = (node.position.y / 50) + Math.sin(time + Number(node.id || 0)) * 0.1;
    }
  });

  return (
    <group 
      ref={meshRef} 
      position={[node.position.x / 50, 0, node.position.y / 50]}
      onClick={onClick}
      onPointerOver={() => setHovered(true)}
      onPointerOut={() => setHovered(false)}
    >
      {/* 3D 基座 */}
      <RoundedBox args={[0.2, 0.2, 0.1]} radius={0.02} smoothness={4} position={[0, -0.1, 0]}>
        <meshStandardMaterial 
          color={isSelected ? '#0ea5e9' : hovered ? '#1e293b' : '#0f172a'} 
          emissive={isSelected ? '#0ea5e9' : '#000'}
          emissiveIntensity={0.5}
        />
      </RoundedBox>

      {/* 2D 高级 UI 按钮融合 */}
      <Html center distanceFactor={8} position={[0, 0, 0]}>
        <div 
          className={`node-button w-[140px] h-[48px] rounded-xl flex items-center px-3 relative transition-all duration-300 ${
            isSelected ? 'ring-2 ring-sky-500 shadow-[0_0_30px_rgba(14,165,233,0.5)] scale-110' : ''
          } cursor-pointer`}
          style={{ transform: hovered && !isSelected ? 'scale(1.05)' : '' }}
        >
          {/* 旋转装饰环 */}
          <div className="status-ring"></div>

          <div className="flex items-center gap-3 w-full relative z-10">
            <div className="w-8 h-8 rounded-lg bg-slate-950/60 flex items-center justify-center border border-white/5">
              <i className={`fas ${SERVICE_ICONS[node.type]} text-xs`} style={{ color: serviceColor }}></i>
            </div>
            <div className="flex flex-col min-w-0">
              <span className="text-[9px] font-black text-slate-100 tracking-wider truncate uppercase">{node.name}</span>
              <span className={`text-[7px] font-black tracking-[0.2em] text-${statusColor}-400 mt-0.5 uppercase`}>
                {node.status}
              </span>
            </div>
          </div>

          {/* 状态呼吸灯 */}
          <div className="absolute top-2 right-2">
             <div className={`w-1 h-1 rounded-full bg-${statusColor}-400 shadow-[0_0_8px_currentColor] ${node.status !== 'online' ? 'animate-pulse' : ''}`}></div>
          </div>
        </div>
      </Html>
    </group>
  );
};

export default ServiceNodeMesh;

/// <reference types="@react-three/fiber" />
import React from 'react';
import ServiceNodeMesh from './ServiceNodeMesh';
import ConnectionLine from './ConnectionLine';
import { ServiceNode, Connection } from '../types';

interface SceneProps {
  nodes: ServiceNode[];
  connections: Connection[];
  selectedId: string | null;
  onNodeClick: (id: string) => void;
  onNodeMove: (id: string, x: number, y: number) => void;
  mode: string;
}

const Scene: React.FC<SceneProps> = ({ nodes, connections, selectedId, onNodeClick, onNodeMove, mode }) => {
  return (
    <group>
      {nodes.map((node) => (
        <ServiceNodeMesh 
          key={node.id} 
          node={node} 
          isSelected={selectedId === node.id}
          onClick={() => onNodeClick(node.id)}
          onMove={(pos) => onNodeMove(node.id, pos.x, pos.y)}
          draggable={mode === 'select'}
        />
      ))}

      {connections.map((conn) => {
        const sourceNode = nodes.find(n => n.id === conn.sourceId);
        const targetNode = nodes.find(n => n.id === conn.targetId);

        if (!sourceNode || !targetNode) return null;

        return (
          <ConnectionLine 
            key={conn.id} 
            connection={conn}
            start={sourceNode.position}
            end={targetNode.position}
          />
        );
      })}
    </group>
  );
};

export default Scene;

