import React, { useState, useCallback, useEffect } from 'react';
import Sidebar from './components/Sidebar';
import UIOverlay from './components/UIOverlay';
import Workspace from './components/Workspace';
import { ServiceNode, Connection, ServiceType, GroupNode } from './types';
import { suggestLayout } from './geminiService';

/**
 * NeoOps 3D 智能运维系统 - 核心控制中心
 */

const STORAGE_KEY = 'NEOOPS_CORE_STORAGE_V3';

const App: React.FC = () => {
  const [nodes, setNodes] = useState<ServiceNode[]>([]);
  const [groups, setGroups] = useState<GroupNode[]>([]);
  const [connections, setConnections] = useState<Connection[]>([]);

  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [selectedConnectionId, setSelectedConnectionId] = useState<string | null>(null);
  const [mode, setMode] = useState<'select' | 'add' | 'connect'>('select');
  const [isLocked, setIsLocked] = useState(false);
  const [connectSourceId, setConnectSourceId] = useState<string | null>(null);
  const [isAnalyzing, setIsAnalyzing] = useState(false);

  // 初始化数据加载
  useEffect(() => {
    const savedData = localStorage.getItem(STORAGE_KEY);
    if (savedData) {
      try {
        const parsed = JSON.parse(savedData);
        setNodes(parsed.nodes || []);
        setGroups(parsed.groups || []);
        setConnections(parsed.connections || []);
      } catch (e) {
        console.error("数据加载失败", e);
      }
    } else {
      // 默认示例数据
      setNodes([
        { id: '1', name: '接入网关', type: ServiceType.GATEWAY, position: { x: 0, y: 0, z: 0 }, status: 'online', lastUpdated: new Date().toISOString() },
        { id: '2', name: '核心服务', type: ServiceType.SERVER, position: { x: 5, y: 0, z: 5 }, status: 'online', lastUpdated: new Date().toISOString() },
        { id: '3', name: '生产数据库', type: ServiceType.DATABASE, position: { x: 10, y: 0, z: 0 }, status: 'warning', lastUpdated: new Date().toISOString() },
      ]);
      setConnections([
        { id: 'c1', sourceId: '1', targetId: '2', label: 'HTTP/JSON', trafficLoad: 0.3, status: 'online', style: 'signal' },
        { id: 'c2', sourceId: '2', targetId: '3', label: 'gRPC/SQL', trafficLoad: 0.8, status: 'online', style: 'fluid' },
      ]);
    }
  }, []);

  const handleSaveLayout = useCallback(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify({ nodes, groups, connections }));
  }, [nodes, groups, connections]);

  const toggleLock = useCallback(() => {
    setIsLocked(prev => !prev);
    if (!isLocked) handleSaveLayout();
  }, [isLocked, handleSaveLayout]);

  const handleAutoLayout = async (desc: string) => {
    if (!desc || isLocked) return;
    setIsAnalyzing(true);
    try {
      const layout = await suggestLayout(desc);
      const newNodes: ServiceNode[] = layout.nodes.map((n: any, i: number) => ({
        id: `ai-${i}-${Date.now()}`,
        name: n.name,
        type: n.type as ServiceType,
        position: { x: n.x, y: 0, z: n.y },
        status: 'online',
        lastUpdated: new Date().toISOString()
      }));
      const newConns: Connection[] = layout.connections.map((c: any, i: number) => ({
        id: `aic-${i}-${Date.now()}`,
        sourceId: newNodes[c.sourceIndex].id,
        targetId: newNodes[c.targetIndex].id,
        label: c.label,
        trafficLoad: 0.1,
        status: 'online',
        style: 'signal'
      }));
      setNodes(newNodes);
      setConnections(newConns);
    } catch (e) {
      alert("AI 生成失败，请重试");
    }
    setIsAnalyzing(false);
  };

  const onElementClick = (id: string) => {
    if (mode === 'connect' && !isLocked) {
      if (!connectSourceId) {
        setConnectSourceId(id);
      } else if (connectSourceId !== id) {
        setConnections(prev => [...prev, {
          id: `c-${Date.now()}`,
          sourceId: connectSourceId,
          targetId: id,
          label: 'NEW_LINK',
          trafficLoad: 0.1,
          style: 'signal',
          status: 'online'
        }]);
        setConnectSourceId(null);
        setMode('select');
      }
    } else {
      setSelectedId(id === selectedId ? null : id);
      setSelectedConnectionId(null);
    }
  };

  const onConnectionClick = (id: string) => {
    setSelectedConnectionId(id === selectedConnectionId ? null : id);
    setSelectedId(null);
  };

  return (
    <div className="flex h-screen w-screen bg-[#02040a] text-slate-100 overflow-hidden font-sans antialiased">
      {/* 注入全局 CSS 变量和动效 */}
      <style>{`
        .node-button {
          background: rgba(15, 23, 42, 0.7);
          backdrop-filter: blur(12px);
          border: 1px solid rgba(56, 189, 248, 0.2);
          transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
        }
        .status-ring {
          position: absolute;
          inset: -4px;
          border: 1px dashed rgba(14, 165, 233, 0);
          border-radius: 12px;
          transition: all 0.5s;
        }
        .node-button:hover .status-ring {
          border-color: rgba(14, 165, 233, 0.4);
          animation: spin 6s linear infinite;
        }
        @keyframes spin { from { transform: rotate(0deg); } to { transform: rotate(360deg); } }
        .custom-scrollbar::-webkit-scrollbar { width: 4px; }
        .custom-scrollbar::-webkit-scrollbar-track { background: transparent; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: rgba(255, 255, 255, 0.1); border-radius: 10px; }
      `}</style>

      <Sidebar 
        nodes={nodes} 
        groups={groups} 
        connections={connections}
        selectedId={selectedId} 
        selectedConnectionId={selectedConnectionId}
        addNode={(type, name, status) => setNodes(prev => [...prev, { 
          id: `n-${Date.now()}`, 
          name, 
          type, 
          position: { x: Math.random() * 10, y: 0, z: Math.random() * 10 }, 
          status, 
          lastUpdated: new Date().toISOString() 
        }])}
        addGroup={(name, status) => setGroups(prev => [...prev, { 
          id: `g-${Date.now()}`, 
          name, 
          position: { x: 0, y: 0 }, 
          size: { width: 400, height: 300 }, 
          color: '#38bdf8', 
          status 
        }])}
        deleteNode={(id) => { setNodes(n => n.filter(x => x.id !== id)); setConnections(c => c.filter(x => x.sourceId !== id && x.targetId !== id)); setSelectedId(null); }}
        deleteGroup={(id) => { setGroups(g => g.filter(x => x.id !== id)); setSelectedId(null); }}
        deleteConnection={(id) => { setConnections(c => c.filter(x => x.id !== id)); setSelectedConnectionId(null); }}
        updateConnection={(id, updates) => setConnections(prev => prev.map(c => c.id === id ? { ...c, ...updates } : c))}
        isAnalyzing={isAnalyzing} 
        onAutoLayout={handleAutoLayout}
        isLocked={isLocked}
        onExport={() => {
          const blob = new Blob([JSON.stringify({ nodes, groups, connections })], { type: 'application/json' });
          const url = URL.createObjectURL(blob);
          const a = document.createElement('a');
          a.href = url; a.download = 'neoops-layout.json'; a.click();
        }}
        onImport={() => {
          const input = document.createElement('input');
          input.type = 'file';
          input.onchange = (e: any) => {
            const file = e.target.files[0];
            const reader = new FileReader();
            reader.onload = (ev: any) => {
              const data = JSON.parse(ev.target.result);
              setNodes(data.nodes || []);
              setConnections(data.connections || []);
            };
            reader.readAsText(file);
          };
          input.click();
        }}
      />

      <main className="flex-1 relative">
        <UIOverlay 
          mode={mode} 
          setMode={setMode} 
          connectSource={nodes.find(n => n.id === connectSourceId)?.name} 
          isLocked={isLocked} 
          setIsLocked={toggleLock} 
        />

        <Workspace 
          nodes={nodes} 
          groups={groups} 
          connections={connections}
          selectedId={selectedId} 
          selectedConnectionId={selectedConnectionId}
          onElementClick={onElementClick}
          onConnectionClick={onConnectionClick}
          onNodeMove={(id, x, z) => !isLocked && setNodes(prev => prev.map(n => n.id === id ? { ...n, position: { ...n.position, x, z } } : n))}
          onUpdateGroup={(id, updates) => !isLocked && setGroups(prev => prev.map(g => g.id === id ? { ...g, ...updates } : g))}
          onDeleteGroup={(id) => setGroups(g => g.filter(x => x.id !== id))}
          onDeleteNode={(id) => setNodes(n => n.filter(x => x.id !== id))}
          mode={mode} 
          isLocked={isLocked}
        />

        {isAnalyzing && (
          <div className="absolute inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-md">
            <div className="flex flex-col items-center gap-4">
              <div className="w-12 h-12 border-4 border-sky-500 border-t-transparent rounded-full animate-spin"></div>
              <p className="text-sky-400 font-black tracking-widest text-xs uppercase">AI 架构规划中...</p>
            </div>
          </div>
        )}
      </main>
    </div>
  );
};

export default App;

