import React, { useRef, useState, useMemo } from 'react';
import { ServiceNode, Connection, GroupNode } from '../types';
import { SERVICE_ICONS, SERVICE_COLORS } from '../constants';

interface WorkspaceProps {
  nodes: ServiceNode[];
  groups: GroupNode[];
  connections: Connection[];
  selectedId: string | null;
  selectedConnectionId: string | null;
  onElementClick: (id: string) => void;
  onConnectionClick: (id: string) => void;
  onNodeMove: (id: string, x: number, y: number) => void;
  onUpdateGroup: (id: string, updates: Partial<GroupNode>) => void;
  onDeleteGroup: (id: string) => void;
  onDeleteNode: (id: string) => void;
  mode: string;
  isLocked: boolean;
}

const Workspace: React.FC<WorkspaceProps> = ({ 
  nodes, groups, connections, selectedId, selectedConnectionId, onElementClick, onConnectionClick, onNodeMove, onUpdateGroup, mode, isLocked
}) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const [viewOffset, setViewOffset] = useState({ x: 0, y: 0 });
  const [isPanning, setIsPanning] = useState(false);
  const [lastMousePos, setLastMousePos] = useState({ x: 0, y: 0 });
  const [draggingId, setDraggingId] = useState<string | null>(null);
  const [resizingId, setResizingId] = useState<string | null>(null);
  const [dragType, setDragType] = useState<'node' | 'group'>('node');

  const handleMouseDown = (e: React.MouseEvent) => {
    if (e.target === containerRef.current) {
      setIsPanning(true);
      setLastMousePos({ x: e.clientX, y: e.clientY });
    }
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (isPanning) {
      const dx = e.clientX - lastMousePos.x;
      const dy = e.clientY - lastMousePos.y;
      setViewOffset(prev => ({ x: prev.x + dx, y: prev.y + dy }));
      setLastMousePos({ x: e.clientX, y: e.clientY });
      return;
    }
    if (mode !== 'select' || isLocked) return;
    const rect = containerRef.current?.getBoundingClientRect();
    if (!rect) return;
    const x = e.clientX - rect.left - viewOffset.x;
    const y = e.clientY - rect.top - viewOffset.y;

    if (draggingId) {
      if (dragType === 'node') onNodeMove(draggingId, x - 70, y - 24);
      else {
        const group = groups.find(g => g.id === draggingId);
        if (group) onUpdateGroup(draggingId, { position: { x: x - group.size.width / 2, y: y - 16 } });
      }
    } else if (resizingId) {
      const group = groups.find(g => g.id === resizingId);
      if (group) onUpdateGroup(resizingId, { size: { width: Math.max(200, x - group.position.x), height: Math.max(150, y - group.position.y) } });
    }
  };

  const handleMouseUp = () => {
    setIsPanning(false);
    setDraggingId(null);
    setResizingId(null);
  };

  const getElementInfo = (id: string) => {
    const node = nodes.find(n => n.id === id);
    if (node) return { x: node.position.x, y: node.position.y, w: 140, h: 48, cx: node.position.x + 70, cy: node.position.y + 24 };
    const group = groups.find(g => g.id === id);
    if (group) return { x: group.position.x, y: group.position.y, w: group.size.width, h: group.size.height, cx: group.position.x + group.size.width / 2, cy: group.position.y + group.size.height / 2 };
    return null;
  };

  const getBezierPath = (sourceId: string, targetId: string) => {
    const s = getElementInfo(sourceId);
    const t = getElementInfo(targetId);
    if (!s || !t) return "";
    const dx = t.cx - s.cx;
    const dy = t.cy - s.cy;
    const ctrl1 = { x: s.cx + dx * 0.4, y: s.cy };
    const ctrl2 = { x: t.cx - dx * 0.4, y: t.cy };
    return `M ${s.cx} ${s.cy} C ${ctrl1.x} ${ctrl1.y}, ${ctrl2.x} ${ctrl2.y}, ${t.cx} ${t.cy}`;
  };

  return (
    <div 
      ref={containerRef}
      onMouseDown={handleMouseDown}
      onMouseMove={handleMouseMove}
      onMouseUp={handleMouseUp}
      onMouseLeave={handleMouseUp}
      style={{
        backgroundImage: `
          radial-gradient(circle at 2px 2px, rgba(56, 189, 248, 0.05) 1px, transparent 0),
          linear-gradient(to right, rgba(56, 189, 248, 0.02) 1px, transparent 1px),
          linear-gradient(to bottom, rgba(56, 189, 248, 0.02) 1px, transparent 1px)
        `,
        backgroundSize: '30px 30px, 90px 90px, 90px 90px',
        backgroundPosition: `${viewOffset.x}px ${viewOffset.y}px`
      }}
      className={`w-full h-full relative select-none ${isPanning ? 'cursor-grabbing' : 'cursor-default'}`}
    >
      <div style={{ transform: `translate(${viewOffset.x}px, ${viewOffset.y}px)`, position: 'absolute', inset: 0, pointerEvents: 'none' }}>
        {/* 连线层 */}
        <svg className="absolute inset-0 w-full h-full pointer-events-none z-[5]">
          <defs>
            <filter id="glow-fx" x="-20%" y="-20%" width="140%" height="140%">
              <feGaussianBlur stdDeviation="3" result="blur" />
              <feComposite in="SourceGraphic" in2="blur" operator="over" />
            </filter>
          </defs>
          {connections.map((conn) => {
            const path = getBezierPath(conn.sourceId, conn.targetId);
            const isSelected = selectedConnectionId === conn.id;
            const color = conn.status === 'error' ? '#f43f5e' : conn.trafficLoad > 0.7 ? '#fbbf24' : '#38bdf8';
            return (
              <g key={conn.id} className="cursor-pointer pointer-events-auto" onClick={(e) => { e.stopPropagation(); onConnectionClick(conn.id); }}>
                <path d={path} stroke="transparent" strokeWidth="20" fill="none" />
                <path 
                  d={path} 
                  stroke={color} 
                  strokeWidth={isSelected ? 4 : 1.5} 
                  fill="none" 
                  className={`path-glow transition-all duration-300 ${conn.style === 'fluid' ? 'anim-ekg' : 'anim-packet'}`}
                  style={{ opacity: isSelected ? 1 : 0.4, color }} 
                />
                {isSelected && (
                  <circle r="4" fill={color}>
                    <animateMotion path={path} dur={`${1.5 - conn.trafficLoad}s`} repeatCount="indefinite" />
                  </circle>
                )}
              </g>
            );
          })}
        </svg>

        {/* 分组层 */}
        {groups.map((group) => (
          <div
            key={group.id}
            style={{ left: group.position.x, top: group.position.y, width: group.size.width, height: group.size.height, pointerEvents: 'auto' }}
            className={`absolute z-0 rounded-[2rem] border transition-all duration-700 ${
              selectedId === group.id ? 'border-sky-500/40 bg-sky-500/5 shadow-[0_0_50px_rgba(14,165,233,0.1)]' : 'border-slate-800/30 bg-slate-900/10'
            }`}
            onClick={(e) => { e.stopPropagation(); onElementClick(group.id); }}
            onMouseDown={(e) => { if (mode === 'select' && !isLocked) { e.stopPropagation(); setDraggingId(group.id); setDragType('group'); } }}
          >
            <div className="absolute top-6 left-8 flex items-center gap-3 opacity-40">
              <i className="fas fa-microchip text-[10px] text-sky-400"></i>
              <span className="text-[10px] font-black text-slate-400 tracking-[0.4em] uppercase">{group.name}</span>
            </div>
            {!isLocked && (
              <div 
                className="absolute bottom-4 right-4 w-6 h-6 cursor-nwse-resize opacity-20 hover:opacity-100 transition-opacity"
                onMouseDown={(e) => { e.stopPropagation(); setResizingId(group.id); }}
              >
                <div className="w-full h-full border-r-2 border-b-2 border-slate-700 rounded-br-lg"></div>
              </div>
            )}
          </div>
        ))}

        {/* 节点层 */}
        {nodes.map((node) => {
          const isSelected = selectedId === node.id;
          const serviceColor = SERVICE_COLORS[node.type];
          const statusColorClass = node.status === 'online' ? 'text-emerald-400' : node.status === 'warning' ? 'text-amber-400' : 'text-rose-400';
          return (
            <div 
              key={node.id} 
              style={{ left: node.position.x, top: node.position.y, width: '140px', height: '48px', pointerEvents: 'auto' }} 
              className="absolute z-10"
            >
              <div 
                className={`w-full h-full node-card rounded-xl flex items-center px-3 relative cursor-pointer ${isSelected ? 'ring-1 ring-sky-500/60 scale-105 z-20' : ''}`}
                onClick={(e) => { e.stopPropagation(); onElementClick(node.id); }}
                onMouseDown={(e) => { if (mode === 'select' && !isLocked) { e.stopPropagation(); setDraggingId(node.id); setDragType('node'); } }}
              >
                {/* 状态旋转环 */}
                <div className="status-ring" style={{ color: node.status === 'online' ? '#10b981' : node.status === 'warning' ? '#f59e0b' : '#f43f5e' }}></div>

                <div className="flex items-center gap-3 w-full relative z-10">
                  <div className="w-9 h-9 rounded-lg bg-slate-950/60 flex items-center justify-center border border-white/5 shadow-inner transition-transform group-hover:scale-110">
                    <i className={`fas ${SERVICE_ICONS[node.type]} text-[13px]`} style={{ color: serviceColor, filter: `drop-shadow(0 0 8px ${serviceColor}80)` }}></i>
                  </div>
                  <div className="flex flex-col min-w-0">
                    <span className="text-[10px] font-black text-slate-100 tracking-wider truncate uppercase">{node.name}</span>
                    <div className="flex items-center gap-1.5 mt-0.5">
                      <span className={`w-1 h-1 rounded-full ${node.status === 'online' ? 'bg-emerald-400' : node.status === 'warning' ? 'bg-amber-400' : 'bg-rose-400'} animate-pulse`}></span>
                      <span className={`text-[8px] font-black tracking-widest ${statusColorClass} opacity-80 uppercase`}>{node.status}</span>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          );
        })}
      </div>

      {/* 装饰水印 */}
      <div className="absolute bottom-12 right-12 pointer-events-none select-none opacity-20 group">
        <div className="flex flex-col items-end gap-1">
          <div className="flex items-center gap-2">
            <div className="w-12 h-[1px] bg-sky-500/40"></div>
            <span className="text-[9px] font-black text-sky-500 tracking-[0.8em] uppercase">Core_System_Sync</span>
          </div>
          <p className="text-[7px] text-slate-500 font-mono">NODE_CLUSTER_V4 // STABLE_CONNECTION</p>
        </div>
      </div>
    </div>
  );
};

