                <button 
                  onClick={() => { if (newNodeName) { addNode(newNodeType, newNodeName, 'online'); setNewNodeName(''); } }} 
                  disabled={!newNodeName}
                  className="w-full bg-white hover:bg-sky-50 text-slate-950 font-black py-4 rounded-2xl text-[11px] uppercase tracking-[0.3em] transition-all disabled:opacity-10 shadow-[0_10px_30px_rgba(255,255,255,0.05)] active:scale-95"
                >
                  DEPLOY_RESOURCE
                </button>
            </div>
          </section>
        )}

        {/* Global Controls */}
        <section className="pt-8 border-t border-white/5 space-y-4">
          <div className="grid grid-cols-2 gap-3">
            <button onClick={onExport} className="glass-panel hover:bg-white/5 py-3 rounded-xl text-[9px] font-black uppercase tracking-widest text-slate-400 transition-all border-white/5">
              EXPORT_JSON
            </button>
            <button onClick={onImport} className="glass-panel hover:bg-white/5 py-3 rounded-xl text-[9px] font-black uppercase tracking-widest text-slate-400 transition-all border-white/5">
              IMPORT_JSON
            </button>
          </div>
          <p className="text-[7px] text-slate-700 font-mono text-center tracking-[0.5em] uppercase">Security_Protocol_Active // 2025</p>
        </section>
      </div>
    </aside>
  );
};

export default Sidebar;

