  addGroup: (name: string, status: 'online' | 'warning' | 'error') => void;
  deleteNode: (id: string) => void;
  deleteGroup: (id: string) => void;
  deleteConnection: (id: string) => void;
  updateConnection: (id: string, updates: Partial<Connection>) => void;
  isAnalyzing: boolean;
  onAutoLayout: (desc: string) => void;
  isLocked: boolean;
  onExport: () => void;
  onImport: () => void;
}

const SERVICE_TYPE_LABELS: Record<ServiceType, string> = {
  [ServiceType.DATABASE]: '时序数据库',
  [ServiceType.SERVER]: '微服务集群',
  [ServiceType.GATEWAY]: '边缘网关',
  [ServiceType.CACHE]: '高速缓存',
  [ServiceType.LOAD_BALANCER]: '弹性负载',
  [ServiceType.FIREWALL]: '安全协议层',
  [ServiceType.CONTAINER]: '逻辑容器'
};

const Sidebar: React.FC<SidebarProps> = ({ 
  nodes, groups, connections, selectedId, selectedConnectionId, addNode, addGroup, deleteNode, deleteGroup, deleteConnection, updateConnection, isAnalyzing, onAutoLayout, isLocked, onExport, onImport
}) => {
  const [newNodeName, setNewNodeName] = useState('');
  const [newNodeType, setNewNodeType] = useState<ServiceType>(ServiceType.SERVER);
  const [aiPrompt, setAiPrompt] = useState('');

  const selectedNode = nodes.find(n => n.id === selectedId);
  const selectedGroup = groups.find(g => g.id === selectedId);
  const selectedConnection = connections.find(c => c.id === selectedConnectionId);

  return (
    <aside className="w-85 border-r border-white/5 flex flex-col bg-[#05080f]/95 backdrop-blur-3xl z-30 shadow-[24px_0_60px_rgba(0,0,0,0.6)]">
      {/* 头部标题区 */}
      <div className="p-8 border-b border-white/5 relative overflow-hidden group">
        <div className="absolute -top-10 -left-10 w-32 h-32 bg-sky-500/10 rounded-full blur-3xl group-hover:bg-sky-500/20 transition-all"></div>
        <h1 className="text-3xl font-black italic bg-gradient-to-br from-white via-slate-400 to-sky-500 bg-clip-text text-transparent tracking-tighter">NEOOPS</h1>
        <div className="flex items-center gap-3 mt-2">
          <div className="flex gap-1">
             <span className="w-1 h-1 bg-sky-500 rounded-full animate-pulse"></span>
             <span className="w-1 h-1 bg-sky-500/40 rounded-full"></span>
          </div>
          <p className="text-[9px] text-slate-500 uppercase tracking-[0.4em] font-black">系统管理控制台 v4.5</p>
        </div>
      </div>

      <div className="flex-1 overflow-y-auto p-6 space-y-10 custom-scrollbar">

        {/* 对象审查面板 */}
        {(selectedNode || selectedGroup || selectedConnection) ? (
          <section className="animate-in fade-in slide-in-from-right-4 duration-500">
             <div className="mb-4 flex items-center justify-between">
                <h3 className="text-[10px] font-black text-sky-500 uppercase tracking-widest">Inspector // 对象审查</h3>
                <span className="text-[8px] text-slate-600 font-mono">ID: {selectedId || selectedConnectionId}</span>
             </div>

             {selectedNode && (
                <div className="glass-panel p-5 rounded-2xl border-sky-500/20 relative group overflow-hidden">
                  <div className="flex items-start justify-between mb-6">
                    <div>
                      <h4 className="font-black text-lg text-white mb-1 truncate max-w-[140px]">{selectedNode.name}</h4>
                      <span className="px-2 py-0.5 bg-sky-500/10 text-sky-400 text-[8px] font-black rounded uppercase tracking-tighter border border-sky-500/20">
                        {SERVICE_TYPE_LABELS[selectedNode.type]}
                      </span>
                    </div>
                    <div className="w-12 h-12 rounded-xl bg-slate-900 flex items-center justify-center text-xl shadow-inner border border-white/5" style={{ color: SERVICE_COLORS[selectedNode.type] }}>
                       <i className={`fas ${SERVICE_ICONS[selectedNode.type]}`}></i>
