                  </div>

                  <div className="grid grid-cols-2 gap-4 text-[10px] mb-6">
                     <div className="space-y-1">
                        <p className="text-slate-500 font-bold uppercase">实时响应</p>
                        <p className="text-slate-100 font-black">12.5 ms / 0.1%</p>
                     </div>
                     <div className="space-y-1 text-right">
                        <p className="text-slate-500 font-bold uppercase">健康指数</p>
                        <p className={`font-black ${selectedNode.status === 'online' ? 'text-emerald-400' : 'text-rose-400'}`}>99.9% 稳定</p>
                     </div>
                  </div>

                  {!isLocked && (
                    <button 
                      onClick={() => deleteNode(selectedNode.id)} 
                      className="w-full bg-rose-500/10 hover:bg-rose-500/20 text-rose-500 py-3 rounded-xl text-[10px] font-black uppercase tracking-[0.2em] border border-rose-500/20 transition-all active:scale-95"
