import React, { useRef, useState } from 'react';
import { ServiceNode, Connection, GroupNode } from '../types';
import { SERVICE_ICONS, SERVICE_COLORS } from '../constants';

interface WorkspaceProps {
  nodes: ServiceNode[];
  groups: GroupNode[];
  connections: Connection[];
  selectedId: string | null;
  selectedConnectionId: string | null;
  onElementClick: (id: string) => void;
  onConnectionClick: (id: string) => void;
  onNodeMove: (id: string, x: number, y: number) => void;
  onUpdateGroup: (id: string, updates: Partial<GroupNode>) => void;
  onDeleteGroup: (id: string) => void;
  onDeleteNode: (id: string) => void;
  mode: string;
  isLocked: boolean;
}

const Workspace: React.FC<WorkspaceProps> = ({ 
  nodes, groups, connections, selectedId, selectedConnectionId, onElementClick, onConnectionClick, onNodeMove, onUpdateGroup, mode, isLocked
}) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const [viewOffset, setViewOffset] = useState({ x: 0, y: 0 });
  const [isPanning, setIsPanning] = useState(false);
  const [lastMousePos, setLastMousePos] = useState({ x: 0, y: 0 });
  const [draggingId, setDraggingId] = useState<string | null>(null);
  const [resizingId, setResizingId] = useState<string | null>(null);
  const [dragType, setDragType] = useState<'node' | 'group'>('node');

  const handleMouseDown = (e: React.MouseEvent) => {
    if (e.target === containerRef.current) {
      setIsPanning(true);
      setLastMousePos({ x: e.clientX, y: e.clientY });
    }
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (isPanning) {
      const dx = e.clientX - lastMousePos.x;
      const dy = e.clientY - lastMousePos.y;
      setViewOffset(prev => ({ x: prev.x + dx, y: prev.y + dy }));
      setLastMousePos({ x: e.clientX, y: e.clientY });
      return;
    }
    if (mode !== 'select' || isLocked) return;
    const rect = containerRef.current?.getBoundingClientRect();
    if (!rect) return;
    const x = e.clientX - rect.left - viewOffset.x;
    const y = e.clientY - rect.top - viewOffset.y;

    if (draggingId) {
      if (dragType === 'node') onNodeMove(draggingId, x - 70, y - 24);
      else {
        const group = groups.find(g => g.id === draggingId);
        if (group) onUpdateGroup(draggingId, { position: { x: x - group.size.width / 2, y: y - 16 } });
      }
    } else if (resizingId) {
      const group = groups.find(g => g.id === resizingId);
      if (group) onUpdateGroup(resizingId, { size: { width: Math.max(200, x - group.position.x), height: Math.max(150, y - group.position.y) } });
    }
  };

  const handleMouseUp = () => {
    setIsPanning(false);
    setDraggingId(null);
    setResizingId(null);
  };

  const getElementInfo = (id: string) => {
    const node = nodes.find(n => n.id === id);
    if (node) return { x: node.position.x, y: node.position.y, w: 140, h: 48, cx: node.position.x + 70, cy: node.position.y + 24 };
    const group = groups.find(g => g.id === id);
    if (group) return { x: group.position.x, y: group.position.y, w: group.size.width, h: group.size.height, cx: group.position.x + group.size.width / 2, cy: group.position.y + group.size.height / 2 };
    return null;
  };

  const getBezierPath = (sourceId: string, targetId: string) => {
    const s = getElementInfo(sourceId);
    const t = getElementInfo(targetId);
    if (!s || !t) return "";
    const dx = t.cx - s.cx;
    const dy = t.cy - s.cy;
    const ctrl1 = { x: s.cx + dx * 0.5, y: s.cy };
    const ctrl2 = { x: t.cx - dx * 0.5, y: t.cy };
    return `M ${s.cx} ${s.cy} C ${ctrl1.x} ${ctrl1.y}, ${ctrl2.x} ${ctrl2.y}, ${t.cx} ${t.cy}`;
  };

  return (
    <div 
      ref={containerRef}
      onMouseDown={handleMouseDown}
      onMouseMove={handleMouseMove}
      onMouseUp={handleMouseUp}
      onMouseLeave={handleMouseUp}
      style={{
        backgroundImage: `
          radial-gradient(circle at 2px 2px, rgba(56, 189, 248, 0.08) 1px, transparent 0),
          linear-gradient(to right, rgba(56, 189, 248, 0.03) 1px, transparent 1px),
          linear-gradient(to bottom, rgba(56, 189, 248, 0.03) 1px, transparent 1px)
        `,
        backgroundSize: '30px 30px, 120px 120px, 120px 120px',
        backgroundPosition: `${viewOffset.x}px ${viewOffset.y}px`
      }}
      className={`w-full h-full relative select-none ${isPanning ? 'cursor-grabbing' : 'cursor-default'}`}
    >
      <div style={{ transform: `translate(${viewOffset.x}px, ${viewOffset.y}px)`, position: 'absolute', inset: 0, pointerEvents: 'none' }}>
        {/* SVG 连线层 */}
        <svg className="absolute inset-0 w-full h-full pointer-events-none z-[5]">
          <defs>
            <filter id="glow-fx" x="-20%" y="-20%" width="140%" height="140%">
              <feGaussianBlur stdDeviation="3" result="blur" />
              <feComposite in="SourceGraphic" in2="blur" operator="over" />
            </filter>
          </defs>
          {connections.map((conn) => {
            const path = getBezierPath(conn.sourceId, conn.targetId);
            const isSelected = selectedConnectionId === conn.id;
            const color = conn.status === 'error' ? '#f43f5e' : conn.trafficLoad > 0.8 ? '#fbbf24' : '#38bdf8';
            return (
              <g key={conn.id} className="cursor-pointer pointer-events-auto" onClick={(e) => { e.stopPropagation(); onConnectionClick(conn.id); }}>
                <path d={path} stroke="transparent" strokeWidth="20" fill="none" />
                <path 
                  d={path} 
                  stroke={color} 
                  strokeWidth={isSelected ? 4 : 2} 
                  fill="none" 
                  className={`path-glow transition-all duration-300 ${conn.style === 'fluid' ? 'anim-ekg' : 'anim-packet'}`}
                  style={{ opacity: isSelected ? 1 : 0.5, color }} 
                />
                <text className="text-[7px] font-black tracking-widest uppercase" fill={color} dy="-8" style={{ opacity: isSelected ? 0.8 : 0.2 }}>
                   <textPath href={`#p-${conn.id}`} startOffset="50%" textAnchor="middle">{conn.label}</textPath>
                </text>
                <path id={`p-${conn.id}`} d={path} fill="none" />
              </g>
            );
          })}
        </svg>

        {/* 分组层 */}
        {groups.map((group) => (
          <div
            key={group.id}
            style={{ left: group.position.x, top: group.position.y, width: group.size.width, height: group.size.height, pointerEvents: 'auto' }}
            className={`absolute z-0 rounded-[2.5rem] border transition-all duration-700 ${
              selectedId === group.id ? 'border-sky-500/50 bg-sky-500/5 shadow-[0_0_60px_rgba(14,165,233,0.1)]' : 'border-slate-800/40 bg-slate-900/10'
            }`}
            onClick={(e) => { e.stopPropagation(); onElementClick(group.id); }}
            onMouseDown={(e) => { if (mode === 'select' && !isLocked) { e.stopPropagation(); setDraggingId(group.id); setDragType('group'); } }}
          >
            <div className="absolute top-6 left-8 flex items-center gap-3 opacity-30">
              <i className="fas fa-microchip text-[10px] text-sky-400"></i>
              <span className="text-[10px] font-black text-slate-400 tracking-[0.4em] uppercase">{group.name}</span>
            </div>
            {!isLocked && (
              <div 
                className="absolute bottom-5 right-5 w-6 h-6 cursor-nwse-resize opacity-20 hover:opacity-100 transition-opacity"
                onMouseDown={(e) => { e.stopPropagation(); setResizingId(group.id); }}
              >
                <div className="w-full h-full border-r-2 border-b-2 border-slate-700 rounded-br-xl"></div>
              </div>
            )}
          </div>
        ))}

        {/* 节点层 */}
        {nodes.map((node) => {
          const isSelected = selectedId === node.id;
          const serviceColor = SERVICE_COLORS[node.type];
          const statusColor = node.status === 'online' ? '#10b981' : node.status === 'warning' ? '#f59e0b' : '#f43f5e';
          return (
            <div 
              key={node.id} 
              style={{ left: node.position.x, top: node.position.y, width: '140px', height: '48px', pointerEvents: 'auto' }} 
              className="absolute z-10"
            >
              <div 
                className={`w-full h-full node-card rounded-xl flex items-center px-3 relative cursor-pointer ${isSelected ? 'ring-1 ring-sky-500/80 scale-105 z-20 shadow-[0_0_30px_rgba(14,165,233,0.3)]' : ''}`}
                onClick={(e) => { e.stopPropagation(); onElementClick(node.id); }}
                onMouseDown={(e) => { if (mode === 'select' && !isLocked) { e.stopPropagation(); setDraggingId(node.id); setDragType('node'); } }}
              >
                {/* 动态健康度旋转环 */}
                <div className="status-ring" style={{ color: statusColor }}></div>

                <div className="flex items-center gap-3 w-full relative z-10">
                  <div className="w-9 h-9 rounded-lg bg-slate-950/70 flex items-center justify-center border border-white/5 shadow-inner">
                    <i className={`fas ${SERVICE_ICONS[node.type]} text-[13px]`} style={{ color: serviceColor, filter: `drop-shadow(0 0 8px ${serviceColor}90)` }}></i>
                  </div>
                  <div className="flex flex-col min-w-0">
                    <span className="text-[10px] font-black text-slate-100 tracking-wider truncate uppercase">{node.name}</span>
                    <div className="flex items-center gap-1.5 mt-0.5">
                      <span className={`w-1 h-1 rounded-full animate-pulse`} style={{ backgroundColor: statusColor, boxShadow: `0 0 6px ${statusColor}` }}></span>
                      <span className="text-[8px] font-black tracking-widest uppercase opacity-70" style={{ color: statusColor }}>{node.status === 'online' ? '就绪' : node.status === 'warning' ? '警告' : '故障'}</span>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          );
        })}
      </div>

      {/* 视觉装饰 */}
      <div className="absolute bottom-12 right-12 pointer-events-none select-none opacity-20">
        <div className="flex flex-col items-end gap-1">
          <div className="flex items-center gap-2">
            <div className="w-16 h-[1px] bg-sky-500/40"></div>
            <span className="text-[9px] font-black text-sky-500 tracking-[0.8em] uppercase">SYSTEM_LINK_ACTIVE</span>
          </div>
          <p className="text-[7px] text-slate-600 font-mono tracking-widest uppercase">Encryption_Channel // Stable_0049</p>
        </div>
      </div>
    </div>
  );
};

export default Workspace;

import React, { useRef, useState, useMemo } from 'react';
import { useFrame, ThreeEvent } from '@react-three/fiber';
import { Text, Float, RoundedBox, Html } from '@react-three/drei';
import * as THREE from 'three';
import { ServiceNode, ServiceType } from '../types';
import { SERVICE_COLORS, SERVICE_ICONS } from '../constants';

interface ServiceNodeMeshProps {
  node: ServiceNode;
  isSelected: boolean;
  onClick: (e: ThreeEvent<MouseEvent>) => void;
  onMove: (pos: { x: number, y: number, z: number }) => void;
  draggable: boolean;
}

const ServiceNodeMesh: React.FC<ServiceNodeMeshProps> = ({ node, isSelected, onClick, onMove, draggable }) => {
  const meshRef = useRef<THREE.Group>(null);
  const ring1Ref = useRef<THREE.Mesh>(null);
  const ring2Ref = useRef<THREE.Mesh>(null);
  const [hovered, setHovered] = useState(false);

  const color = SERVICE_COLORS[node.type];
  const statusColor = node.status === 'online' ? '#10b981' : node.status === 'warning' ? '#f59e0b' : '#ef4444';
  const statusText = node.status === 'online' ? '就绪' : node.status === 'warning' ? '警告' : '故障';

  // 轨道参数
  const orbitParams = useMemo(() => ({
    speed1: (Math.random() - 0.5) * 2,
    speed2: (Math.random() - 0.5) * 2,
    offset: Math.random() * Math.PI
  }), []);

  useFrame((state) => {
    const t = state.clock.getElapsedTime();
    if (meshRef.current) {
      // 更加丝滑的悬浮感
      meshRef.current.position.y = node.position.y + Math.sin(t * 0.8 + orbitParams.offset) * 0.15;
    }
    if (ring1Ref.current) {
      ring1Ref.current.rotation.z += 0.01 * orbitParams.speed1;
      ring1Ref.current.rotation.x = Math.sin(t * 0.5) * 0.2;
    }
    if (ring2Ref.current) {
      ring2Ref.current.rotation.z -= 0.015 * orbitParams.speed2;
      ring2Ref.current.rotation.y = Math.cos(t * 0.5) * 0.2;
    }
  });

  const Group = 'group' as any;
  const Mesh = 'mesh' as any;
  const RingGeometry = 'ringGeometry' as any;
  const MeshBasicMaterial = 'meshBasicMaterial' as any;
  const MeshStandardMaterial = 'meshStandardMaterial' as any;
  const TorusGeometry = 'torusGeometry' as any;
  const SphereGeometry = 'sphereGeometry' as any;

  return (
    <Group 
      ref={meshRef} 
      position={[node.position.x, node.position.y, node.position.z]}
      onClick={(e: ThreeEvent<MouseEvent>) => {
        e.stopPropagation();
        onClick(e);
      }}
      onPointerOver={() => setHovered(true)}
      onPointerOut={() => setHovered(false)}
    >
      {/* 核心几何体：科幻感圆角方块 */}
      <RoundedBox args={[1.3, 1.3, 0.4]} radius={0.12} smoothness={4}>
        <MeshStandardMaterial 
          color={isSelected ? '#38bdf8' : hovered ? '#1e293b' : '#0a0f1e'} 
          emissive={isSelected ? '#0ea5e9' : hovered ? '#0ea5e9' : '#000'}
          emissiveIntensity={isSelected ? 0.8 : hovered ? 0.2 : 0}
          roughness={0.05}
          metalness={0.9}
        />
      </RoundedBox>

      {/* 动态内旋转环 (数据交换感) */}
      <Mesh ref={ring1Ref} rotation={[Math.PI / 2, 0, 0]}>
        <TorusGeometry args={[0.9, 0.02, 16, 64]} />
        <MeshBasicMaterial color={statusColor} transparent opacity={0.6} />
      </Mesh>

      {/* 动态外旋转环 (重力场感) */}
      <Mesh ref={ring2Ref} rotation={[0, Math.PI / 2, 0]}>
        <TorusGeometry args={[1.1, 0.01, 8, 48]} />
        <MeshBasicMaterial color={color} transparent opacity={0.3} />
      </Mesh>

      {/* 状态呼吸光点 */}
      <Mesh position={[0, 0, 0.25]}>
        <SphereGeometry args={[0.08, 16, 16]} />
        <MeshBasicMaterial color={statusColor} />
      </Mesh>

      {/* 文本标签：使用中文字体支持 */}
      <Text
        position={[0, -1, 0]}
        fontSize={0.25}
        color="#94a3b8"
        anchorX="center"
        anchorY="middle"
        font="https://fonts.gstatic.com/s/notosanssc/v26/k3kXo84MPtRZneW4fH3287zQldD_ycy8.woff"
      >
        {node.name}
      </Text>

      {/* 悬浮 UI 卡片 */}
      <Html position={[0, 1, 0]} center distanceFactor={8} className="pointer-events-none select-none">
        <div className="flex flex-col items-center">
          <div className="glass-panel px-3 py-1 rounded-full border-sky-500/20 backdrop-blur-md flex items-center gap-2 shadow-[0_0_20px_rgba(0,0,0,0.5)]">
            <span className={`w-2 h-2 rounded-full animate-pulse`} style={{ backgroundColor: statusColor, boxShadow: `0 0 8px ${statusColor}` }}></span>
            <span className="text-[10px] font-black text-slate-100 uppercase tracking-widest">{statusText}</span>
          </div>
          <div className="mt-2 w-10 h-10 rounded-xl bg-slate-900/80 border border-white/10 flex items-center justify-center backdrop-blur-sm">
            <i className={`fas ${SERVICE_ICONS[node.type]} text-sm`} style={{ color }}></i>
          </div>
        </div>
      </Html>

      {/* 选中时的地面投影圈 */}
      {isSelected && (
         <Mesh rotation={[Math.PI / 2, 0, 0]} position={[0, -2, 0]}>
           <TorusGeometry args={[1.8, 0.03, 2, 100]} />
           <MeshBasicMaterial color="#0ea5e9" transparent opacity={0.4} />
         </Mesh>
      )}
    </Group>
  );
};

export default ServiceNodeMesh;

import React, { useRef, useMemo } from 'react';
import { useFrame } from '@react-three/fiber';
import * as THREE from 'three';
import { QuadraticBezierLine } from '@react-three/drei';
import { Connection, Vector3Array } from '../types';

interface ConnectionLineProps {
  connection: Connection;
  start: Vector3Array;
  end: Vector3Array;
}

const ConnectionLine: React.FC<ConnectionLineProps> = ({ connection, start, end }) => {
  const packetRef = useRef<THREE.Mesh>(null);

  const startVec = useMemo(() => new THREE.Vector3(start.x, start.y, start.z), [start]);
  const endVec = useMemo(() => new THREE.Vector3(end.x, end.y, end.z), [end]);

  // 贝塞尔中点控制，增加弧度
  const mid = useMemo(() => {
    const v = new THREE.Vector3().addVectors(startVec, endVec).multiplyScalar(0.5);
    const dist = startVec.distanceTo(endVec);
    v.y += dist * 0.2; // 根据跨度自动调整高度
    return v;
  }, [startVec, endVec]);

  const curve = useMemo(() => {
    return new THREE.QuadraticBezierCurve3(startVec, mid, endVec);
  }, [startVec, mid, endVec]);

  // 数据包流动逻辑
  useFrame((state) => {
    if (packetRef.current) {
      // 流量越大，流动越快
      const speed = 0.3 + (connection.trafficLoad * 1.5);
      const time = (state.clock.getElapsedTime() * speed) % 1;
      const point = curve.getPoint(time);
      packetRef.current.position.copy(point);

      // 数据包缩放呼吸
      const s = 1 + Math.sin(state.clock.getElapsedTime() * 10) * 0.2;
      packetRef.current.scale.set(s, s, s);
    }
  });

  const Group = 'group' as any;
  const Mesh = 'mesh' as any;
  const SphereGeometry = 'sphereGeometry' as any;
  const MeshBasicMaterial = 'meshBasicMaterial' as any;

  const statusColor = connection.status === 'error' ? "#f43f5e" : connection.trafficLoad > 0.8 ? "#fbbf24" : "#0ea5e9";

  return (
    <Group>
      {/* 基础链路轨迹 */}
      <QuadraticBezierLine
        start={startVec}
        end={endVec}
        mid={mid}
        color={statusColor}
        lineWidth={1.5}
        transparent
        opacity={0.3}
      />

      {/* 发光流动轨迹（叠加一层增加亮度） */}
      <QuadraticBezierLine
        start={startVec}
        end={endVec}
        mid={mid}
        color={statusColor}
        lineWidth={3}
        transparent
        opacity={0.1}
      />

      {/* 高级流光数据包 */}
      <Mesh ref={packetRef}>
        <SphereGeometry args={[0.12, 12, 12]} />
        <MeshBasicMaterial color={statusColor} />
      </Mesh>

      {/* 连接指示点 */}
      <Mesh position={[mid.x, mid.y, mid.z]}>
        <SphereGeometry args={[0.04, 8, 8]} />
        <MeshBasicMaterial color="#475569" transparent opacity={0.5} />
      </Mesh>
    </Group>
  );
};

export default ConnectionLine;

import React, { useRef, useState, useMemo } from 'react';
import { ServiceNode, Connection, GroupNode } from '../types';
import { SERVICE_ICONS, SERVICE_COLORS } from '../constants';

interface WorkspaceProps {
  nodes: ServiceNode[];
  groups: GroupNode[];
  connections: Connection[];
  selectedId: string | null;
  selectedConnectionId: string | null;
  onElementClick: (id: string) => void;
  onConnectionClick: (id: string) => void;
  onNodeMove: (id: string, x: number, y: number) => void;
  onUpdateGroup: (id: string, updates: Partial<GroupNode>) => void;
  onDeleteGroup: (id: string) => void;
  onDeleteNode: (id: string) => void;
  mode: string;
  isLocked: boolean;
}

const Workspace: React.FC<WorkspaceProps> = ({ 
  nodes, groups, connections, selectedId, selectedConnectionId, onElementClick, onConnectionClick, onNodeMove, onUpdateGroup, mode, isLocked
}) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const [viewOffset, setViewOffset] = useState({ x: 0, y: 0 });
  const [isPanning, setIsPanning] = useState(false);
  const [lastMousePos, setLastMousePos] = useState({ x: 0, y: 0 });
  const [draggingId, setDraggingId] = useState<string | null>(null);
  const [resizingId, setResizingId] = useState<string | null>(null);
  const [dragType, setDragType] = useState<'node' | 'group'>('node');

  const handleMouseDown = (e: React.MouseEvent) => {
    if (e.target === containerRef.current) {
      setIsPanning(true);
      setLastMousePos({ x: e.clientX, y: e.clientY });
    }
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (isPanning) {
      const dx = e.clientX - lastMousePos.x;
      const dy = e.clientY - lastMousePos.y;
      setViewOffset(prev => ({ x: prev.x + dx, y: prev.y + dy }));
      setLastMousePos({ x: e.clientX, y: e.clientY });
      return;
    }
    if (mode !== 'select' || isLocked) return;
    const rect = containerRef.current?.getBoundingClientRect();
    if (!rect) return;
    const x = e.clientX - rect.left - viewOffset.x;
    const y = e.clientY - rect.top - viewOffset.y;

    if (draggingId) {
      if (dragType === 'node') onNodeMove(draggingId, x - 70, y - 24);
      else {
        const group = groups.find(g => g.id === draggingId);
        if (group) onUpdateGroup(draggingId, { position: { x: x - group.size.width / 2, y: y - 16 } });
      }
    } else if (resizingId) {
      const group = groups.find(g => g.id === resizingId);
      if (group) onUpdateGroup(resizingId, { size: { width: Math.max(200, x - group.position.x), height: Math.max(150, y - group.position.y) } });
    }
  };

  const handleMouseUp = () => {
    setIsPanning(false);
    setDraggingId(null);
    setResizingId(null);
  };

  const getElementInfo = (id: string) => {
    const node = nodes.find(n => n.id === id);
    if (node) return { x: node.position.x, y: node.position.y, w: 140, h: 48, cx: node.position.x + 70, cy: node.position.y + 24 };
    const group = groups.find(g => g.id === id);
    if (group) return { x: group.position.x, y: group.position.y, w: group.size.width, h: group.size.height, cx: group.position.x + group.size.width / 2, cy: group.position.y + group.size.height / 2 };
    return null;
  };

  const getBezierPath = (sourceId: string, targetId: string) => {
    const s = getElementInfo(sourceId);
    const t = getElementInfo(targetId);
    if (!s || !t) return "";
    const dx = t.cx - s.cx;
    const dy = t.cy - s.cy;
    const ctrl1 = { x: s.cx + dx * 0.4, y: s.cy };
    const ctrl2 = { x: t.cx - dx * 0.4, y: t.cy };
    return `M ${s.cx} ${s.cy} C ${ctrl1.x} ${ctrl1.y}, ${ctrl2.x} ${ctrl2.y}, ${t.cx} ${t.cy}`;
  };

  return (
    <div 
      ref={containerRef}
      onMouseDown={handleMouseDown}
      onMouseMove={handleMouseMove}
      onMouseUp={handleMouseUp}
      onMouseLeave={handleMouseUp}
      style={{
        backgroundImage: `
          radial-gradient(circle at 2px 2px, rgba(56, 189, 248, 0.05) 1px, transparent 0),
          linear-gradient(to right, rgba(56, 189, 248, 0.02) 1px, transparent 1px),
          linear-gradient(to bottom, rgba(56, 189, 248, 0.02) 1px, transparent 1px)
        `,
        backgroundSize: '30px 30px, 90px 90px, 90px 90px',
        backgroundPosition: `${viewOffset.x}px ${viewOffset.y}px`
      }}
      className={`w-full h-full relative select-none ${isPanning ? 'cursor-grabbing' : 'cursor-default'}`}
    >
      <div style={{ transform: `translate(${viewOffset.x}px, ${viewOffset.y}px)`, position: 'absolute', inset: 0, pointerEvents: 'none' }}>
        {/* SVG 连线层 */}
        <svg className="absolute inset-0 w-full h-full pointer-events-none z-[5]">
          {connections.map((conn) => {
            const path = getBezierPath(conn.sourceId, conn.targetId);
            const isSelected = selectedConnectionId === conn.id;
            const color = conn.status === 'error' ? '#f43f5e' : conn.trafficLoad > 0.7 ? '#fbbf24' : '#38bdf8';
            return (
              <g key={conn.id} className="cursor-pointer pointer-events-auto" onClick={(e) => { e.stopPropagation(); onConnectionClick(conn.id); }}>
                <path d={path} stroke="transparent" strokeWidth="20" fill="none" />
                <path 
                  d={path} 
                  stroke={color} 
                  strokeWidth={isSelected ? 4 : 2} 
                  fill="none" 
                  className={`transition-all duration-300 ${conn.style === 'fluid' ? 'anim-ekg' : 'anim-packet'}`}
                  style={{ opacity: isSelected ? 1 : 0.4, color }} 
                  filter="drop-shadow(0 0 4px currentColor)"
                />
              </g>
            );
          })}
        </svg>

        {/* 分组层 */}
        {groups.map((group) => (
          <div
            key={group.id}
            style={{ left: group.position.x, top: group.position.y, width: group.size.width, height: group.size.height, pointerEvents: 'auto' }}
            className={`absolute z-0 rounded-[2.5rem] border transition-all duration-700 ${
              selectedId === group.id ? 'border-sky-500/40 bg-sky-500/5 shadow-[0_0_50px_rgba(14,165,233,0.1)]' : 'border-slate-800/20 bg-slate-900/10'
            }`}
            onClick={(e) => { e.stopPropagation(); onElementClick(group.id); }}
            onMouseDown={(e) => { if (mode === 'select' && !isLocked) { e.stopPropagation(); setDraggingId(group.id); setDragType('group'); } }}
          >
            <div className="absolute top-6 left-8 flex items-center gap-3 opacity-30">
              <span className="text-[10px] font-black text-slate-400 tracking-[0.4em] uppercase">{group.name}</span>
            </div>
            {!isLocked && (
              <div 
                className="absolute bottom-4 right-4 w-6 h-6 cursor-nwse-resize opacity-20 hover:opacity-100 transition-opacity"
                onMouseDown={(e) => { e.stopPropagation(); setResizingId(group.id); }}
              >
                <div className="w-full h-full border-r-2 border-b-2 border-slate-700 rounded-br-lg"></div>
              </div>
            )}
          </div>
        ))}

        {/* 节点层 (资源按钮优化版) */}
        {nodes.map((node) => {
          const isSelected = selectedId === node.id;
          const serviceColor = SERVICE_COLORS[node.type];
          const statusColorClass = node.status === 'online' ? 'text-emerald-400' : node.status === 'warning' ? 'text-amber-400' : 'text-rose-400';
          const statusLabel = node.status === 'online' ? '运行中' : node.status === 'warning' ? '负载高' : '已宕机';

          return (
            <div 
              key={node.id} 
              style={{ left: node.position.x, top: node.position.y, width: '140px', height: '48px', pointerEvents: 'auto' }} 
              className="absolute z-10"
            >
              <div 
                className={`w-full h-full node-card rounded-xl flex items-center px-3 relative cursor-pointer overflow-hidden ${isSelected ? 'ring-1 ring-sky-500/80 scale-105 z-20 shadow-[0_0_30px_rgba(14,165,233,0.3)]' : ''}`}
                onClick={(e) => { e.stopPropagation(); onElementClick(node.id); }}
                onMouseDown={(e) => { if (mode === 'select' && !isLocked) { e.stopPropagation(); setDraggingId(node.id); setDragType('node'); } }}
              >
                {/* 能量状态环 */}
                <div className="status-ring" style={{ color: node.status === 'online' ? '#10b981' : node.status === 'warning' ? '#f59e0b' : '#f43f5e' }}></div>

                {/* 激光扫描层 */}
                <div className="absolute inset-0 bg-gradient-to-r from-transparent via-white/10 to-transparent -translate-x-full hover:animate-[shine_1.5s_infinite] pointer-events-none"></div>

                <div className="flex items-center gap-3 w-full relative z-10">
                  <div className="w-9 h-9 rounded-lg bg-slate-950/80 flex items-center justify-center border border-white/5 shadow-inner">
                    <i className={`fas ${SERVICE_ICONS[node.type]} text-[13px]`} style={{ color: serviceColor, filter: `drop-shadow(0 0 6px ${serviceColor}80)` }}></i>
                  </div>
                  <div className="flex flex-col min-w-0">
                    <span className="text-[10px] font-black text-slate-100 tracking-wider truncate uppercase">{node.name}</span>
                    <div className="flex items-center gap-1.5 mt-0.5">
                      <span className={`w-1 h-1 rounded-full animate-pulse`} style={{ backgroundColor: node.status === 'online' ? '#10b981' : node.status === 'warning' ? '#f59e0b' : '#f43f5e', boxShadow: `0 0 6px currentColor` }}></span>
                      <span className={`text-[8px] font-black tracking-widest ${statusColorClass} opacity-80 uppercase`}>{statusLabel}</span>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          );
        })}
      </div>

      {/* 水印装饰 */}
      <div className="absolute bottom-12 right-12 pointer-events-none select-none opacity-20">
        <div className="flex flex-col items-end gap-1">
          <div className="flex items-center gap-2">
            <div className="w-16 h-[1px] bg-sky-500/40"></div>
            <span className="text-[9px] font-black text-sky-500 tracking-[0.8em] uppercase">NEOOPS_SYNAPSE</span>
          </div>
          <p className="text-[7px] text-slate-600 font-mono tracking-widest uppercase">Encryption_Channel // Stable_v4.5</p>
        </div>
      </div>

      <style>{`
        @keyframes shine {
          0% { transform: translateX(-100%) skewX(-30deg); }
          100% { transform: translateX(200%) skewX(-30deg); }
        }
      `}</style>
    </div>
  );
};

