        @keyframes pulse-slow { 0%, 100% { opacity: 0.2; transform: scale(1); } 50% { opacity: 0.6; transform: scale(1.05); } }
        @keyframes pulse-medium { 0%, 100% { opacity: 0.2; transform: scale(1); } 50% { opacity: 0.8; transform: scale(1.1); } }
        @keyframes pulse-fast { 0%, 100% { opacity: 0.3; transform: scale(1); } 50% { opacity: 1; transform: scale(1.15); } }

        .status-pulse-online { animation: pulse-slow 3s ease-in-out infinite; }
        .status-pulse-warning { animation: pulse-medium 1.5s ease-in-out infinite; }
        .status-pulse-error { animation: pulse-fast 0.6s ease-in-out infinite; }

        .anim-packet {
          stroke-dasharray: 6, 14;
          animation: packet-move 20s linear infinite;
        }
        @keyframes packet-move { to { stroke-dashoffset: -1000; } }

        @keyframes ekg {
          0%, 100% { stroke-width: 2px; opacity: 0.4; }
