import React, { useState, useCallback, useEffect, useRef } from 'react';
import Sidebar from './components/Sidebar';
import UIOverlay from './components/UIOverlay';
import Workspace from './components/Workspace';
import { ServiceNode, Connection, ServiceType, GroupNode } from './types';
import { suggestLayout } from './geminiService';

const STORAGE_KEY = 'NEOOPS_PRO_V4_STORAGE';

const App: React.FC = () => {
  const [nodes, setNodes] = useState<ServiceNode[]>([]);
  const [groups, setGroups] = useState<GroupNode[]>([]);
  const [connections, setConnections] = useState<Connection[]>([]);

  const [toast, setToast] = useState<{ message: string; visible: boolean }>({ message: '', visible: false });
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [selectedConnectionId, setSelectedConnectionId] = useState<string | null>(null);
  const [mode, setMode] = useState<'select' | 'add' | 'connect'>('select');
  const [isLocked, setIsLocked] = useState(false);
  const [connectSourceId, setConnectSourceId] = useState<string | null>(null);
  const [isAnalyzing, setIsAnalyzing] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const savedData = localStorage.getItem(STORAGE_KEY);
    if (savedData) {
      try {
        const parsed = JSON.parse(savedData);
        setNodes(parsed.nodes || []);
        setGroups(parsed.groups || []);
        setConnections(parsed.connections || []);
      } catch (e) {
        console.error("配置恢复失败", e);
      }
    } else {
      setNodes([
        { id: 'n1', name: '智能负载网关', type: ServiceType.GATEWAY, position: { x: 150, y: 350, z: 0 }, status: 'online', lastUpdated: new Date().toISOString() },
        { id: 'n2', name: 'API 核心集群', type: ServiceType.SERVER, position: { x: 450, y: 300, z: 0 }, status: 'online', lastUpdated: new Date().toISOString() },
        { id: 'n3', name: '生产级时序库', type: ServiceType.DATABASE, position: { x: 750, y: 450, z: 0 }, status: 'warning', lastUpdated: new Date().toISOString() },
      ]);
      setGroups([
        { id: 'g1', name: '核心内网业务区', position: { x: 300, y: 200 }, size: { width: 600, height: 450 }, color: '#38bdf8', status: 'online' }
      ]);
      setConnections([
        { id: 'c1', sourceId: 'n1', targetId: 'n2', label: 'SSL/TLS', trafficLoad: 0.3, status: 'online', style: 'signal' },
        { id: 'c2', sourceId: 'n2', targetId: 'n3', label: 'DB_POOL', trafficLoad: 0.8, status: 'online', style: 'fluid' },
      ]);
    }
  }, []);

  const showToast = (message: string) => {
    setToast({ message, visible: true });
    setTimeout(() => setToast({ message: '', visible: false }), 3000);
  };

  const handleSaveLayout = useCallback(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify({ nodes, groups, connections }));
    showToast("同步至本地加密存储成功");
  }, [nodes, groups, connections]);

  const toggleLock = useCallback(() => {
    setIsLocked(prev => !prev);
    if (!isLocked) {
      handleSaveLayout();
      showToast("拓扑结构已固化");
    } else {
      showToast("开启自由编排模式");
    }
  }, [isLocked, handleSaveLayout]);

  const handleAutoLayout = async (desc: string) => {
    if (!desc || isLocked) return;
    setIsAnalyzing(true);
    try {
      const layout = await suggestLayout(desc);
      const newNodes: ServiceNode[] = layout.nodes.map((n: any, i: number) => ({
        id: `ai-n-${i}-${Date.now()}`,
        name: n.name,
        type: n.type as ServiceType,
        position: { x: (n.x + 1) * 60, y: (n.y + 1) * 50, z: 0 },
        status: 'online',
        lastUpdated: new Date().toISOString()
      }));
      const newConns: Connection[] = layout.connections.map((c: any, i: number) => ({
        id: `ai-c-${i}-${Date.now()}`,
        sourceId: newNodes[c.sourceIndex].id,
        targetId: newNodes[c.targetIndex].id,
        label: c.label,
        trafficLoad: 0.2,
        status: 'online',
        style: 'signal'
      }));
      setNodes(newNodes);
      setConnections(newConns);
      showToast("AI 辅助编排完成");
    } catch (e) {
      showToast("架构师模型连接超时");
    }
    setIsAnalyzing(false);
  };

  return (
    <div className="flex h-screen w-screen bg-[#02040a] text-slate-100 overflow-hidden font-sans antialiased selection:bg-sky-500/30">
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=JetBrains+Mono:wght@400;700&display=swap');
        body { font-family: 'JetBrains Mono', 'PingFang SC', sans-serif; }

        .glass-panel {
          background: rgba(10, 15, 25, 0.75);
          backdrop-filter: blur(24px);
          border: 1px solid rgba(56, 189, 248, 0.15);
          box-shadow: 0 8px 32px 0 rgba(0, 0, 0, 0.8);
        }

        .node-card {
          backdrop-filter: blur(16px);
          border: 1px solid rgba(56, 189, 248, 0.2);
          transition: all 0.4s cubic-bezier(0.23, 1, 0.32, 1);
        }

        /* 整个背景闪烁动画定义 */
        @keyframes bg-pulse-green {
          0%, 100% { background: rgba(16, 185, 129, 0.05); border-color: rgba(16, 185, 129, 0.2); box-shadow: inset 0 0 10px rgba(16, 185, 129, 0.05); }
          50% { background: rgba(16, 185, 129, 0.15); border-color: rgba(16, 185, 129, 0.5); box-shadow: inset 0 0 20px rgba(16, 185, 129, 0.1), 0 0 15px rgba(16, 185, 129, 0.2); }
        }

        @keyframes bg-pulse-yellow {
          0%, 100% { background: rgba(245, 158, 11, 0.05); border-color: rgba(245, 158, 11, 0.2); box-shadow: inset 0 0 10px rgba(245, 158, 11, 0.05); }
          50% { background: rgba(245, 158, 11, 0.25); border-color: rgba(245, 158, 11, 0.6); box-shadow: inset 0 0 25px rgba(245, 158, 11, 0.2), 0 0 20px rgba(245, 158, 11, 0.3); }
        }

        @keyframes bg-pulse-red {
          0%, 100% { background: rgba(244, 63, 94, 0.1); border-color: rgba(244, 63, 94, 0.3); box-shadow: inset 0 0 15px rgba(244, 63, 94, 0.1); }
          50% { background: rgba(244, 63, 94, 0.4); border-color: rgba(244, 63, 94, 0.8); box-shadow: inset 0 0 35px rgba(244, 63, 94, 0.3), 0 0 30px rgba(244, 63, 94, 0.5); }
        }

        /* 状态类映射 */
        .card-online { animation: bg-pulse-green 4s ease-in-out infinite; }
        .card-warning { animation: bg-pulse-yellow 1.5s ease-in-out infinite; }
        .card-error { animation: bg-pulse-red 0.6s ease-in-out infinite; }

        .status-ring {
          position: absolute;
          inset: -6px;
          border: 1px dashed currentColor;
          border-radius: 14px;
          opacity: 0.2;
          pointer-events: none;
          z-index: 0;
        }

        .anim-packet {
          stroke-dasharray: 6, 14;
          animation: packet-move 20s linear infinite;
        }
        @keyframes packet-move { to { stroke-dashoffset: -1000; } }

        @keyframes ekg {
          0%, 100% { stroke-width: 2px; opacity: 0.4; }
          50% { stroke-width: 4px; opacity: 1; filter: drop-shadow(0 0 6px currentColor); }
        }
        .anim-ekg { animation: ekg 1.2s ease-in-out infinite; }

        .crt-overlay::after {
          content: " ";
          display: block;
          position: absolute;
          top: 0; left: 0; bottom: 0; right: 0;
          background: linear-gradient(rgba(18, 16, 16, 0) 50%, rgba(0, 0, 0, 0.08) 50%), linear-gradient(90deg, rgba(255, 0, 0, 0.02), rgba(0, 255, 0, 0.01), rgba(0, 0, 255, 0.02));
          z-index: 100;
          background-size: 100% 3px, 3px 100%;
          pointer-events: none;
          opacity: 0.2;
        }

        .scanline {
          width: 100%; height: 2px;
          background: rgba(14, 165, 233, 0.1);
          position: absolute;
          animation: scan 8s linear infinite;
          z-index: 90;
          pointer-events: none;
        }
        @keyframes scan { from { top: -5%; } to { top: 105%; } }

        .custom-scrollbar::-webkit-scrollbar { width: 4px; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: rgba(56, 189, 248, 0.2); border-radius: 10px; }
      `}</style>

      <div className="crt-overlay absolute inset-0 pointer-events-none"></div>
      <div className="scanline"></div>

      {toast.visible && (
        <div className="fixed top-12 left-1/2 -translate-x-1/2 z-[200] glass-panel px-8 py-3 rounded-full border-sky-500/40 animate-in fade-in slide-in-from-top-6">
          <div className="flex items-center gap-3">
            <span className="w-1.5 h-1.5 bg-sky-400 rounded-full animate-ping"></span>
            <span className="text-[11px] font-black text-sky-300 uppercase tracking-[0.3em]">{toast.message}</span>
          </div>
        </div>
      )}

      <input type="file" ref={fileInputRef} onChange={(e) => {
        const file = e.target.files?.[0];
        if (!file) return;
        const reader = new FileReader();
        reader.onload = (event) => {
          try {
            const parsed = JSON.parse(event.target?.result as string);
            setNodes(parsed.nodes || []);
            setGroups(parsed.groups || []);
            setConnections(parsed.connections || []);
            showToast("架构配置导入成功");
          } catch { showToast("导入失败：非法 JSON 格式"); }
        };
        reader.readAsText(file);
      }} className="hidden" accept=".json" />

      <Sidebar 
        nodes={nodes} groups={groups} connections={connections}
        selectedId={selectedId} selectedConnectionId={selectedConnectionId}
        addNode={(type, name, status) => setNodes(prev => [...prev, { id: `n-${Date.now()}`, name, type, position: { x: 200, y: 200, z: 0 }, status, lastUpdated: new Date().toISOString() }])}
        addGroup={(name, status) => setGroups(prev => [...prev, { id: `g-${Date.now()}`, name, position: { x: 200, y: 200 }, size: { width: 450, height: 350 }, color: '#818cf8', status }])}
        deleteNode={(id) => { setNodes(n => n.filter(x => x.id !== id)); setConnections(c => c.filter(x => x.sourceId !== id && x.targetId !== id)); setSelectedId(null); }}
        deleteGroup={(id) => { setGroups(g => g.filter(x => x.id !== id)); setSelectedId(null); }}
        deleteConnection={(id) => { setConnections(c => c.filter(x => x.id !== id)); setSelectedConnectionId(null); }}
        updateConnection={(id, updates) => setConnections(prev => prev.map(c => c.id === id ? { ...c, ...updates } : c))}
        isAnalyzing={isAnalyzing} onAutoLayout={handleAutoLayout}
        isLocked={isLocked} onExport={() => {
            const data = { nodes, groups, connections, version: '4.5', timestamp: new Date().toISOString() };
            const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
            const url = URL.createObjectURL(blob);
            const link = document.createElement('a');
            link.href = url; link.download = 'neoops-pro.json'; link.click();
            showToast("本地导出就绪");
        }}
        onImport={() => fileInputRef.current?.click()}
      />

      <main className="flex-1 relative overflow-hidden bg-[radial-gradient(circle_at_50%_50%,_#0a0f1e_0%,_#02040a_100%)]">
        <UIOverlay 
          mode={mode} 
          setMode={setMode} 
          connectSource={nodes.find(n => n.id === connectSourceId)?.name} 
          isLocked={isLocked} 
          setIsLocked={toggleLock} 
        />

        <Workspace 
          nodes={nodes} groups={groups} connections={connections}
          selectedId={selectedId} selectedConnectionId={selectedConnectionId}
          onElementClick={(id) => {
            if (mode === 'connect' && !isLocked) {
              if (!connectSourceId) setConnectSourceId(id);
              else {
                setConnections(prev => [...prev, { id: `c-${Date.now()}`, sourceId: connectSourceId, targetId: id, label: 'AUTH_BRIDGE', trafficLoad: 0.1, style: 'signal' }]);
                setConnectSourceId(null); setMode('select');
              }
            } else { setSelectedId(id === selectedId ? null : id); setSelectedConnectionId(null); }
          }}
          onConnectionClick={(id) => { setSelectedConnectionId(id === selectedConnectionId ? null : id); setSelectedId(null); }}
          onNodeMove={(id, x, y) => !isLocked && setNodes(prev => prev.map(n => n.id === id ? { ...n, position: { ...n.position, x, y } } : n))}
          onUpdateGroup={(id, updates) => !isLocked && setGroups(prev => prev.map(g => g.id === id ? { ...g, ...updates } : g))}
          onDeleteGroup={(id) => setGroups(g => g.filter(x => x.id !== id))}
          onDeleteNode={(id) => setNodes(n => n.filter(x => x.id !== id))}
          mode={mode} isLocked={isLocked}
        />

        {isAnalyzing && (
            <div className="absolute inset-0 z-[150] flex items-center justify-center bg-black/80 backdrop-blur-2xl">
                <div className="flex flex-col items-center gap-8">
                    <div className="relative">
                      <div className="w-24 h-24 border-2 border-sky-500/10 border-t-sky-500 rounded-full animate-spin"></div>
                      <div className="absolute inset-0 flex items-center justify-center">
                         <i className="fas fa-brain text-sky-400 text-2xl animate-pulse"></i>
                      </div>
                    </div>
                    <div className="text-center space-y-3">
                      <p className="text-sky-400 font-black tracking-[0.8em] text-xs uppercase animate-pulse">Neural_Network_Active</p>
                      <p className="text-slate-500 font-bold text-[10px] uppercase">正在解构云端架构需求并规划最佳拓扑...</p>
                    </div>
                </div>
            </div>
        )}
      </main>
    </div>
  );
};

