            transform: translateY(0);
            stroke-width: 2px;
          }
        }

        /* 选中时的“过载/高亮”彩色抖动特效 */
        @keyframes ekg-chromatic {
          0%, 100% { filter: drop-shadow(0 0 8px currentColor); }
          33% { filter: drop-shadow(2px 0 10px #f43f5e) drop-shadow(-2px 0 10px #0ea5e9); }
          66% { filter: drop-shadow(-1px 0 12px #10b981) drop-shadow(1px 0 8px #f59e0b); }
        }

        .connection-signal { stroke-dasharray: 60, 340; animation: signal-run 3s linear infinite; }

        .connection-ekg { 
          stroke-dasharray: 50, 1000; 
          animation: ekg-move 3s linear infinite, ekg-heartbeat 1.6s cubic-bezier(0.4, 0, 0.2, 1) infinite; 
          stroke-linecap: round; 
