          0%, 12%, 50%, 100% { 
            transform: translateY(0) scaleY(1);
            stroke-width: 2px;
            opacity: 0.3;
            filter: drop-shadow(0 0 2px transparent);
          }
          15% { /* Lub Beat (第一心音 - 小跳) */
            transform: translateY(-5px) scaleY(1.3);
            stroke-width: 3.5px;
            opacity: 0.7;
            filter: drop-shadow(0 0 5px currentColor);
          }
          19% { /* 中间间歇 */
            transform: translateY(1px);
          }
          22% { /* Dub Beat (第二心音 - 强跳/R波爆发) */
            transform: translateY(-24px) scaleY(3.2);
            stroke-width: 9px;
            opacity: 1;
            filter: drop-shadow(0 0 15px currentColor) brightness(2.5);
          }
          25% { /* S点快速回弹 */
            transform: translateY(6px) scaleY(1.5);
            stroke-width: 4px;
          }
          35% { /* T波 - 复极化恢复 */
            transform: translateY(-6px) scaleY(1.1);
            stroke-width: 3.2px;
            opacity: 0.8;
            filter: drop-shadow(0 0 8px currentColor);
          }
        }

        /* 3. 选中状态下的高频电子色散 (Chromatic Overload) */
        @keyframes ekg-chromatic-jitter {
          0%, 100% { transform: translate(0, 0); filter: brightness(1.5); }
          25% { transform: translate(1.5px, -1px); filter: brightness(2.5) drop-shadow(2px 0 4px #ff3b3b) drop-shadow(-2px 0 4px #00f2ff); }
          50% { transform: translate(-1px, 1.2px); filter: brightness(2) drop-shadow(-1px 0 6px #00ff88); }
          75% { transform: translate(0.5px, -1.5px); filter: brightness(3) drop-shadow(1px 2px 8px #ffcc00); }
        }

        .connection-signal { stroke-dasharray: 60, 340; animation: signal-run 3s linear infinite; }

        /* 心电图样式：升级为爱心律动 UI */
        .connection-ekg { 
          stroke-dasharray: 120, 1080; 
          stroke-linecap: round;
          transform-box: fill-box;
          transform-origin: center;
          animation: 
            ekg-scan-premium 3.8s linear infinite, 
            ekg-heartbeat-vivid 1.6s cubic-bezier(0.17, 0.88, 0.32, 1.27) infinite; 
          will-change: transform, stroke-width, opacity, filter;
        }

        /* 选中状态：强化律动速度与干扰视觉 */
        .connection-ekg.selected-jump {
          animation: 
            ekg-scan-premium 1.5s linear infinite, 
            ekg-heartbeat-vivid 0.8s cubic-bezier(0.16, 1, 0.3, 1) infinite,
