        @keyframes signal-run { 0% { stroke-dashoffset: 400; } 100% { stroke-dashoffset: 0; } }

        /* 1. 心电图信号流动：磷光余晖 */
        @keyframes ekg-flow-vivid { 
          0% { stroke-dashoffset: 1200; opacity: 0.2; } 
          10%, 90% { opacity: 0.9; }
          100% { stroke-dashoffset: 0; opacity: 0.2; } 
        }

        /* 2. 爱心律动核心 (Heart-Beat Dynamics)：模拟真实心脏 Lub-Dub 跳动 */
        @keyframes ekg-heartbeat-pulse {
          0%, 12%, 46%, 100% { 
            transform: translateY(0) scaleY(1);
            stroke-width: 2.5px;
            opacity: 0.4;
            filter: drop-shadow(0 0 2px transparent);
          }
          15% { /* 第一心音 (Lub)：心房收缩 */
            transform: translateY(-4px) scaleY(1.3);
            stroke-width: 4px;
            opacity: 0.8;
            filter: drop-shadow(0 0 6px currentColor);
          }
          19% { /* 中间蓄力 */
            transform: translateY(1.5px);
          }
          22% { /* 第二心音 (Dub)：心室强力泵血 (QRS复合波) */
            transform: translateY(-28px) scaleY(3.5);
            stroke-width: 9px;
            opacity: 1;
            filter: drop-shadow(0 0 25px currentColor) brightness(2.8);
          }
          25% { /* 极速回弹 */
            transform: translateY(7px) scaleY(1.8);
            stroke-width: 5px;
          }
          35% { /* T波：复极化阶段 */
            transform: translateY(-8px) scaleY(1.4);
            stroke-width: 4.5px;
            opacity: 0.9;
            filter: drop-shadow(0 0 12px currentColor);
          }
        }

        /* 3. 选中增强：高频色散与心脏过载感 */
        @keyframes ekg-cardiac-overload {
          0%, 100% { transform: translate(0, 0); filter: brightness(1.5) contrast(1.2); }
          20% { transform: translate(1.8px, -1.2px); filter: brightness(3) drop-shadow(3px 0 6px #ff1e1e) drop-shadow(-3px 0 6px #00eaff); }
          40% { transform: translate(-2px, 1px); filter: brightness(2.5) drop-shadow(-2px 0 10px #00ff88); }
          60% { transform: translate(1px, 2px); filter: brightness(3.5) drop-shadow(0 3px 12px #ffcc00); }
