        }

        .scanline {
           position: fixed; top: 0; left: 0; width: 100%; height: 100%;
           background: linear-gradient(rgba(18, 16, 16, 0) 50%, rgba(0, 0, 0, 0.15) 50%);
           background-size: 100% 4px;
           z-index: 60; pointer-events: none; opacity: 0.08;
