        @keyframes signal-ultra-pulse { 
          0% { stroke-dashoffset: 400; filter: brightness(1.2) drop-shadow(0 0 5px currentColor); } 
          50% { stroke-width: 5px; filter: brightness(5) drop-shadow(0 0 15px currentColor) drop-shadow(0 0 30px currentColor); }
          100% { stroke-dashoffset: 0; filter: brightness(1.2) drop-shadow(0 0 5px currentColor); } 
        }
        .connection-signal { 
