        <UIOverlay 
          mode={mode} 
          setMode={setMode} 
          connectSource={nodes.find(n => n.id === connectSourceId)?.name || groups.find(g => g.id === connectSourceId)?.name} 
          isLocked={isLocked} 
          setIsLocked={toggleLock} 
        />

        <Workspace 
          nodes={nodes} groups={groups} connections={connections}
