        }

        .card-online { animation: bg-pulse-green 4s ease-in-out infinite; }
        .card-warning { animation: bg-pulse-yellow 1.5s ease-in-out infinite; }
        .card-error { animation: bg-pulse-red 0.6s ease-in-out infinite; }

        .node-button {
