        }

        /**
         * --- 拓扑连线特效 (Visual FX) ---
         */

        /* 1. 标准脉冲 (Signal) */
        @keyframes signal-ultra-flow { 
          0% { stroke-dashoffset: 600; filter: drop-shadow(0 0 2px currentColor); } 
          50% { filter: drop-shadow(0 0 12px currentColor); }
          100% { stroke-dashoffset: 0; filter: drop-shadow(0 0 2px currentColor); } 
        }
        .connection-signal { 
          stroke-dasharray: 40, 20, 5, 20, 15, 60; 
          stroke-linecap: round; 
          animation: signal-ultra-flow 4s linear infinite; 
          stroke-width: 3px;
        }

        /* 2. 心电图 (EKG/ECG) - 深度优化版 (Deep Optimization)
           - 设计语言：Bio-Digital（生物数字）。模拟生命体征在数字网络中的映射。
           - 改进：周期调整为 5s，既不躁动也不死寂。
           - 改进：R 波形态重构，ScaleY 振幅提升至 1.6 倍，配合亮度滤镜，营造电流击穿感。
        */
        @keyframes ekg-vitality-wave {
          0%, 30%, 70%, 100% { 
            transform: scaleY(1) translateY(0);
            stroke-width: 2px;
            opacity: 0.2;
            filter: drop-shadow(0 0 1px currentColor);
          }
          32% { /* P波 - 预加载 */
            transform: scaleY(1.1) translateY(-0.5px);
            stroke-width: 2.5px;
            opacity: 0.4;
          }
          35% { /* Q点 - 蓄力 */
            transform: scaleY(0.9) translateY(0.5px);
            stroke-width: 2px;
          }
          36% { /* R波 - 绝对爆发 (Absolute Discharge) */
            transform: scaleY(1.6) translateY(-4px); /* 更夸张的振幅 */
            stroke-width: 8px; /* 极细到极粗的瞬间变化 */
            opacity: 1;
            /* 三重辉光：核心高亮 + 局部散射 + 环境氛围，叠加亮度滤镜 */
            filter: drop-shadow(0 0 5px currentColor) drop-shadow(0 0 15px currentColor) drop-shadow(0 0 40px currentColor) brightness(1.2);
          }
          38% { /* S波 - 深度过冲 */
            transform: scaleY(0.5) translateY(3px);
            stroke-width: 3px;
            filter: drop-shadow(0 0 5px currentColor);
          }
          45% { /* T波 - 能量耗散 (Echo) */
            transform: scaleY(1.2) translateY(-1.5px);
            stroke-width: 4px;
            opacity: 0.6;
            filter: drop-shadow(0 0 10px currentColor);
          }
          55% { /* 回归平静 */
            transform: scaleY(1) translateY(0);
            opacity: 0.2;
          }
        }

        @keyframes ekg-transmit-flow {
          0% { stroke-dashoffset: 1000; }
          100% { stroke-dashoffset: 0; }
        }

        .connection-ekg { 
          /* 
