          */
          stroke-dasharray: 200, 800; 
          stroke-linecap: round;
          transform-box: fill-box;
          transform-origin: center;

          /* 5s 循环：保持数据流动的持续感 */
          animation: 
            ekg-transmit-flow 5s linear infinite, 
            ekg-vitality-wave 5s cubic-bezier(0.2, 0.8, 0.2, 1) infinite; 

          will-change: transform, stroke-width, filter, stroke-dashoffset;
        }

        /* 选中状态：急救模式 (Emergency Mode) */
        .connection-ekg.selected-jump {
          animation-duration: 1.5s; /* 心率飙升 */
          stroke-width: 6px;
          filter: drop-shadow(0 0 20px currentColor) brightness(1.5) !important;
        }

        /* 3. 示波器 (Oscilloscope) */
        @keyframes oscilloscope-pro-jitter {
          0% { stroke-dashoffset: 0; transform: skewX(0deg); }
          25% { stroke-dashoffset: 40; transform: skewX(1deg); stroke-width: 5px; }
          50% { stroke-dashoffset: -20; transform: skewX(-1deg); stroke-width: 2px; }
          75% { stroke-dashoffset: 60; transform: skewX(0.5deg); stroke-width: 6px; }
          100% { stroke-dashoffset: 0; transform: skewX(0deg); }
        }
        .connection-oscilloscope { 
          stroke-dasharray: 15, 5, 2, 5, 25, 10; 
          stroke-linecap: square;
          animation: oscilloscope-pro-jitter 0.5s steps(8) infinite; 
          stroke-width: 3.5px;
          filter: contrast(1.5) drop-shadow(0 0 8px currentColor);
        }

        /* 4. 异常频闪 (Flicker) */
        @keyframes flicker-pro-glitch {
          0%, 100% { opacity: 0.05; stroke-width: 1px; transform: translate(0, 0); filter: blur(0px); }
          1% { opacity: 1; stroke-width: 14px; transform: translate(-1.5px, 0.5px); filter: drop-shadow(0 0 35px currentColor); }
          3% { opacity: 0.4; stroke-width: 5px; transform: translate(1px, -1px); filter: blur(1px); }
          5% { opacity: 0.9; stroke-width: 10px; transform: translate(-0.5px, 1.5px); filter: drop-shadow(0 0 20px currentColor); }
          10% { opacity: 0.1; stroke-width: 2px; }
          85% { opacity: 0.08; stroke-width: 1.5px; }
          95% { opacity: 0.7; stroke-width: 7px; transform: skew(2deg); filter: brightness(2); }
        }
        @keyframes flicker-strobe-dash {
          0% { stroke-dasharray: 5, 120, 20, 50; }
          33% { stroke-dasharray: 2, 10, 80, 5; }
          66% { stroke-dasharray: 50, 5, 5, 100; }
          100% { stroke-dasharray: 5, 120, 20, 50; }
        }
        .connection-flicker { 
          stroke-linecap: butt;
          animation: 
            flicker-pro-glitch 0.9s steps(12) infinite,
