            filter: drop-shadow(0 0 8px currentColor) drop-shadow(0 0 25px currentColor) drop-shadow(0 0 60px currentColor) brightness(3.0);
          }
          38% { /* S波 - 深度过冲 */
            transform: scaleY(0.5) translateY(3px);
