          filter: drop-shadow(0 0 20px currentColor) brightness(3.5) !important;
        }

        /* 3. 示波器 (Oscilloscope) */
        @keyframes oscilloscope-pro-jitter {
          0% { stroke-dashoffset: 0; transform: skewX(0deg); }
          25% { stroke-dashoffset: 40; transform: skewX(1deg); stroke-width: 5px; }
          50% { stroke-dashoffset: -20; transform: skewX(-1deg); stroke-width: 2px; }
