            stroke-width: 2.2px; 
            opacity: 0.6; 
            filter: drop-shadow(0 0 4px currentColor);
          }
          20% { transform: scaleY(1); }

          /* PR Segment (等电位线) */
          25% { transform: scaleY(1); }

          /* Q Point (下蹲) */
          27% { transform: scaleY(0.96); }

          /* R Wave (Main peak) - 室缩 (持续约 8% 周期) */
