import React, { useRef, useState, useMemo, useEffect } from 'react';
import { ServiceNode, Connection, GroupNode } from '../types';
import { SERVICE_ICONS, SERVICE_COLORS } from '../constants';

interface WorkspaceProps {
  nodes: ServiceNode[];
  groups: GroupNode[];
  connections: Connection[];
  selectedId: string | null;
  selectedConnectionId: string | null;
  onElementClick: (id: string) => void;
  onConnectionClick: (id: string) => void;
  onNodeMove: (id: string, x: number, y: number) => void;
  onUpdateGroup: (id: string, updates: Partial<GroupNode>) => void;
  onDeleteGroup: (id: string) => void;
  onDeleteNode: (id: string) => void;
  mode: string;
  isLocked: boolean;
}

const Workspace: React.FC<WorkspaceProps> = ({ 
  nodes, 
  groups,
  connections, 
  selectedId,
  selectedConnectionId,
  onElementClick,
  onConnectionClick,
  onNodeMove, 
  onUpdateGroup,
  mode,
  isLocked
}) => {
  const containerRef = useRef<HTMLDivElement>(null);

  const [viewOffset, setViewOffset] = useState({ x: 0, y: 0 });
  const [isPanning, setIsPanning] = useState(false);
  const [lastMousePos, setLastMousePos] = useState({ x: 0, y: 0 });

  const [draggingId, setDraggingId] = useState<string | null>(null);
  const [resizingId, setResizingId] = useState<string | null>(null);
  const [dragType, setDragType] = useState<'node' | 'group' | 'scroll-h' | 'scroll-v'>('node');

  // 动态计算虚拟画布的边界
  const contentBounds = useMemo(() => {
    if (nodes.length === 0 && groups.length === 0) {
      return { minX: -2000, maxX: 2000, minY: -2000, maxY: 2000 };
    }
    let minX = 0, maxX = 1000, minY = 0, maxY = 1000;
    nodes.forEach(n => {
      minX = Math.min(minX, n.position.x - 500);
      maxX = Math.max(maxX, n.position.x + 800);
      minY = Math.min(minY, n.position.y - 500);
      maxY = Math.max(maxY, n.position.y + 800);
    });
    groups.forEach(g => {
      minX = Math.min(minX, g.position.x - 500);
      maxX = Math.max(maxX, g.position.x + g.size.width + 800);
      minY = Math.min(minY, g.position.y - 500);
      maxY = Math.max(maxY, g.position.y + g.size.height + 800);
    });
    return { minX, maxX, minY, maxY, width: maxX - minX, height: maxY - minY };
  }, [nodes, groups]);

  const handleWheel = (e: React.WheelEvent) => {
    if (!containerRef.current) return;
    const rect = containerRef.current.getBoundingClientRect();
    const dx = e.deltaX;
    const dy = e.deltaY;
    setViewOffset(prev => ({
      x: Math.min(Math.max(prev.x - dx, rect.width - contentBounds.maxX), -contentBounds.minX),
      y: Math.min(Math.max(prev.y - dy, rect.height - contentBounds.maxY), -contentBounds.minY)
    }));
  };

  const handleMouseDown = (e: React.MouseEvent) => {
    if (!containerRef.current) return;
    if (e.target === containerRef.current) {
      setIsPanning(true);
      setLastMousePos({ x: e.clientX, y: e.clientY });
    }
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (!containerRef.current) return;
    const rect = containerRef.current.getBoundingClientRect();
    if (isPanning) {
      const dx = e.clientX - lastMousePos.x;
      const dy = e.clientY - lastMousePos.y;
      setViewOffset(prev => ({ 
        x: Math.min(Math.max(prev.x + dx, rect.width - contentBounds.maxX), -contentBounds.minX),
        y: Math.min(Math.max(prev.y + dy, rect.height - contentBounds.maxY), -contentBounds.minY)
      }));
      setLastMousePos({ x: e.clientX, y: e.clientY });
      return;
    }
    if (draggingId === 'scrollbar-h') {
      const dx = e.clientX - lastMousePos.x;
      const movePercent = dx / rect.width;
      const offsetDelta = movePercent * contentBounds.width;
      setViewOffset(prev => ({ ...prev, x: Math.min(Math.max(prev.x - offsetDelta, rect.width - contentBounds.maxX), -contentBounds.minX) }));
      setLastMousePos({ x: e.clientX, y: e.clientY });
      return;
    }
    if (draggingId === 'scrollbar-v') {
      const dy = e.clientY - lastMousePos.y;
      const movePercent = dy / rect.height;
      const offsetDelta = movePercent * contentBounds.height;
      setViewOffset(prev => ({ ...prev, y: Math.min(Math.max(prev.y - offsetDelta, rect.height - contentBounds.maxY), -contentBounds.minY) }));
      setLastMousePos({ x: e.clientX, y: e.clientY });
      return;
    }
    if (mode !== 'select' || isLocked) return;
    const x = e.clientX - rect.left - viewOffset.x;
    const y = e.clientY - rect.top - viewOffset.y;
    if (draggingId && dragType === 'node') {
      onNodeMove(draggingId, x - 65, y - 22);
    } else if (draggingId && dragType === 'group') {
      const group = groups.find(g => g.id === draggingId);
      if (group) onUpdateGroup(draggingId, { position: { x: x - group.size.width / 2, y: y - 16 } });
    } else if (resizingId) {
      const group = groups.find(g => g.id === resizingId);
      if (group) onUpdateGroup(resizingId, { size: { width: Math.max(200, x - group.position.x), height: Math.max(150, y - group.position.y) } });
    }
  };

  const handleMouseUp = () => { setIsPanning(false); setDraggingId(null); setResizingId(null); };

  const scrollMetrics = useMemo(() => {
    if (!containerRef.current) return { h: { pos: 0, size: 0 }, v: { pos: 0, size: 0 } };
    const rect = containerRef.current.getBoundingClientRect();
    const hSize = Math.max(40, (rect.width / contentBounds.width) * rect.width);
    const vSize = Math.max(40, (rect.height / contentBounds.height) * rect.height);
    const hPos = ((-viewOffset.x - contentBounds.minX) / contentBounds.width) * rect.width;
    const vPos = ((-viewOffset.y - contentBounds.minY) / contentBounds.height) * rect.height;
    return { h: { pos: Math.max(0, Math.min(rect.width - hSize, hPos)), size: hSize }, v: { pos: Math.max(0, Math.min(rect.height - vSize, vPos)), size: vSize } };
  }, [viewOffset, contentBounds]);

  const getStatusConfig = (status: string) => {
    switch(status) {
      case 'online': return { text: 'RUNNING', color: 'text-emerald-400' };
      case 'warning': return { text: 'STRESSED', color: 'text-amber-400' };
      case 'error': return { text: 'OFFLINE', color: 'text-rose-400' };
      default: return { text: 'RUNNING', color: 'text-emerald-400' };
    }
  };

  const getElementInfo = (id: string) => {
    const node = nodes.find(n => n.id === id);
    if (node) return { x: node.position.x, y: node.position.y, w: 130, h: 44, cx: node.position.x + 65, cy: node.position.y + 22 };
    const group = groups.find(g => g.id === id);
    if (group) return { x: group.position.x, y: group.position.y, w: group.size.width, h: group.size.height, cx: group.position.x + group.size.width / 2, cy: group.position.y + group.size.height / 2 };
    return null;
  };

  const getConnectionPoint = (sourceId: string, targetId: string) => {
    const s = getElementInfo(sourceId);
    const t = getElementInfo(targetId);
    if (!s || !t) return null;
    const getIntersection = (rect: any, otherCenter: {x: number, y: number}) => {
      const dx = otherCenter.x - rect.cx;
      const dy = otherCenter.y - rect.cy;
      const hw = rect.w / 2;
      const hh = rect.h / 2;
      const scale = Math.min(dx !== 0 ? Math.abs(hw / dx) : Infinity, dy !== 0 ? Math.abs(hh / dy) : Infinity);
      return { x: rect.cx + dx * scale, y: rect.cy + dy * scale };
    };
    return { start: getIntersection(s, { x: t.cx, y: t.cy }), end: getIntersection(t, { x: s.cx, y: s.cy }) };
  };

  const getBezierPath = (start: {x: number, y: number}, end: {x: number, y: number}) => {
    const dx = Math.abs(end.x - start.x);
    const dy = Math.abs(end.y - start.y);
    const horizontal = dx > dy;
    const ctrl1 = horizontal ? { x: start.x + dx / 4, y: start.y } : { x: start.x, y: start.y + dy / 4 };
    const ctrl2 = horizontal ? { x: end.x - dx / 4, y: end.y } : { x: end.x, y: end.y - dy / 4 };
    return `M ${start.x} ${start.y} C ${ctrl1.x} ${ctrl1.y}, ${ctrl2.x} ${ctrl2.y}, ${end.x} ${end.y}`;
  };

  const getConnectionClass = (style: string | undefined) => {
    switch (style) {
      case 'fluid': return 'connection-ekg';
      case 'packet': return 'connection-oscilloscope';
      case 'dashed': return 'connection-flicker';
      default: return 'connection-signal';
    }
  };

  return (
    <div ref={containerRef} className={`w-full h-full relative select-none overflow-hidden ${isPanning ? 'cursor-grabbing' : 'cursor-default'}`} onMouseDown={handleMouseDown} onMouseMove={handleMouseMove} onMouseUp={handleMouseUp} onWheel={handleWheel} style={{ backgroundImage: `linear-gradient(to right, rgba(14, 165, 233, 0.04) 1px, transparent 1px), linear-gradient(to bottom, rgba(14, 165, 233, 0.04) 1px, transparent 1px)`, backgroundSize: '40px 40px', backgroundPosition: `${viewOffset.x}px ${viewOffset.y}px` }}>
      <div style={{ transform: `translate(${viewOffset.x}px, ${viewOffset.y}px)`, position: 'absolute', inset: 0, pointerEvents: 'none' }}>
        {groups.map((group) => (
          <div key={group.id} style={{ left: group.position.x, top: group.position.y, width: group.size.width, height: group.size.height, pointerEvents: 'auto' }} className={`absolute z-0 transition-all ${isLocked ? 'pointer-events-auto' : 'cursor-move'}`} onClick={(e) => { e.stopPropagation(); onElementClick(group.id); }} onMouseDown={(e) => { if (mode === 'select' && !isLocked) { e.stopPropagation(); setDraggingId(group.id); setDragType('group'); } }}>
            <div className={`absolute inset-0 rounded-3xl bg-slate-950/20 backdrop-blur-sm border transition-all duration-500 ${selectedId === group.id ? 'border-sky-500 shadow-[0_0_40px_rgba(14,165,233,0.1)]' : 'border-slate-800/40'} ${group.status === 'online' ? 'card-online' : group.status === 'warning' ? 'card-warning' : 'card-error'}`}>
              <div className="absolute top-0 left-0 right-0 p-4 flex items-center justify-between pointer-events-none">
                 <div className="flex flex-col">
                   <span className="text-[10px] font-black text-slate-100 uppercase tracking-widest">{group.name}</span>
                   <span className={`text-[8px] font-bold ${getStatusConfig(group.status).color}`}>{getStatusConfig(group.status).text}</span>
                 </div>
                 <i className="fas fa-cubes text-slate-600 text-xs opacity-50"></i>
              </div>
            </div>
            {!isLocked && (
              <div className="absolute bottom-4 right-4 w-4 h-4 cursor-nwse-resize opacity-20 hover:opacity-100" onMouseDown={(e) => { e.stopPropagation(); setResizingId(group.id); }}>
                <i className="fas fa-expand-arrows-alt text-xs text-sky-400"></i>
              </div>
            )}
          </div>
        ))}

        <svg className="absolute inset-0 w-full h-full pointer-events-none z-[5]">
          <defs>
            <filter id="glow" x="-20%" y="-20%" width="140%" height="140%">
              <feGaussianBlur stdDeviation="3" result="blur" />
              <feMerge>
                <feMergeNode in="blur" />
                <feMergeNode in="SourceGraphic" />
              </feMerge>
            </filter>
          </defs>
          {connections.map((conn) => {
            const points = getConnectionPoint(conn.sourceId, conn.targetId);
            if (!points) return null;
            const isSelected = selectedConnectionId === conn.id;

            // 颜色状态映射：绿色正常，红色故障
            const color = conn.status === 'error' ? '#ff003c' : '#00ff9d';

            // 路径流动参数映射：
            // flowDur：控制流动时长，trafficLoad 越大，时长越短（流动越快）
            const flowDur = 2.0 / (0.5 + conn.trafficLoad * 2.5);

            const midX = (points.start.x + points.end.x) / 2;
            const midY = (points.start.y + points.end.y) / 2;

            return (
              <g key={conn.id}>
                <path d={getBezierPath(points.start, points.end)} stroke="transparent" strokeWidth="24" fill="none" className="cursor-pointer pointer-events-auto" onClick={(e) => { e.stopPropagation(); onConnectionClick(conn.id); }} />

                <path 
                  d={getBezierPath(points.start, points.end)} 
                  stroke={color} 
                  strokeWidth={isSelected ? 5 : 3} 
                  fill="none" 
                  className={`${getConnectionClass(conn.style)} ${isSelected ? 'selected-jump' : ''}`} 
                  filter="url(#glow)" 
                  style={{ 
                    opacity: isSelected ? 1 : 0.8, 
                    color,
                    '--flow-dur': `${flowDur}s`
                  } as React.CSSProperties} 
                />

                <text
                  x={midX}
                  y={midY - 8}
                  textAnchor="middle"
                  className="text-[9px] font-black fill-slate-300 pointer-events-none uppercase tracking-widest transition-opacity duration-300"
                  style={{ 
                    opacity: isSelected ? 1 : 0.6,
                    paintOrder: 'stroke',
                    stroke: '#020617',
                    strokeWidth: '4px',
                    strokeLinecap: 'round',
                    strokeLinejoin: 'round'
                  }}
                >
                  {conn.label}
                </text>
              </g>
            );
          })}
        </svg>

        {nodes.map((node) => {
          const isSelected = selectedId === node.id;
          const statusConfig = getStatusConfig(node.status);
          return (
            <div key={node.id} style={{ left: node.position.x, top: node.position.y, width: '130px', height: '44px', pointerEvents: 'auto' }} className="absolute z-10">
              <div className={`w-full h-full node-button rounded-xl flex items-center px-3 relative ${node.status === 'online' ? 'card-online' : node.status === 'warning' ? 'card-warning' : 'card-error'} ${isSelected ? 'ring-2 ring-sky-500/50 scale-105 z-20' : ''}`} onClick={(e) => { e.stopPropagation(); onElementClick(node.id); }} onMouseDown={(e) => { if (mode === 'select' && !isLocked) { e.stopPropagation(); setDraggingId(node.id); setDragType('node'); } }}>
                <div className="flex items-center gap-3 w-full">
                  <div className="w-8 h-8 rounded-lg bg-slate-900/50 flex items-center justify-center border border-white/5"><i className={`fas ${SERVICE_ICONS[node.type]} text-xs`} style={{ color: SERVICE_COLORS[node.type] }}></i></div>
                  <div className="flex flex-col min-w-0"><span className="text-[9px] font-black text-slate-100 truncate uppercase">{node.name}</span><span className={`text-[7px] font-bold ${statusConfig.color}`}>{statusConfig.text}</span></div>
                </div>
              </div>
            </div>
          );
        })}
      </div>
      <div className="absolute bottom-1.5 left-2 right-2 h-1.5 bg-sky-500/5 rounded-full z-50 group hover:h-3 transition-all cursor-pointer"><div className="h-full bg-sky-500/20 rounded-full border border-sky-500/10" style={{ width: `${scrollMetrics.h.size}px`, transform: `translateX(${scrollMetrics.h.pos}px)` }} onMouseDown={(e) => { e.stopPropagation(); setDraggingId('scrollbar-h'); setLastMousePos({ x: e.clientX, y: e.clientY }); }} /></div>
      <div className="absolute top-2 bottom-2 right-1.5 w-1.5 bg-sky-500/5 rounded-full z-50 group hover:w-3 transition-all cursor-pointer"><div className="w-full bg-sky-500/20 rounded-full border border-sky-500/10" style={{ height: `${scrollMetrics.v.size}px`, transform: `translateY(${scrollMetrics.v.pos}px)` }} onMouseDown={(e) => { e.stopPropagation(); setDraggingId('scrollbar-v'); setLastMousePos({ x: e.clientX, y: e.clientY }); }} /></div>
    </div>
  );
};

export default Workspace;

import React, { useState, useCallback, useEffect, useRef } from 'react';
import Sidebar from './components/Sidebar';
import UIOverlay from './components/UIOverlay';
import Workspace from './components/Workspace';
import { ServiceNode, Connection, ServiceType, GroupNode } from './types';
import { suggestLayout } from './geminiService';

/**
 * NeoOps 运维系统主程序
 * 负责核心状态管理、全局 CSS 动画定义及持久化逻辑
 */

const STORAGE_KEY = 'NEOOPS_CORE_STORAGE';

const App: React.FC = () => {
  const [nodes, setNodes] = useState<ServiceNode[]>([]);
  const [groups, setGroups] = useState<GroupNode[]>([]);
  const [connections, setConnections] = useState<Connection[]>([]);

  const [toast, setToast] = useState<{ message: string; visible: boolean }>({ message: '', visible: false });
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [selectedConnectionId, setSelectedConnectionId] = useState<string | null>(null);
  const [mode, setMode] = useState<'select' | 'add' | 'connect'>('select');
  const [isLocked, setIsLocked] = useState(false);
  const [connectSourceId, setConnectSourceId] = useState<string | null>(null);
  const [isAnalyzing, setIsAnalyzing] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);

  // 初始化：加载本地存储
  useEffect(() => {
    const savedData = localStorage.getItem(STORAGE_KEY);
    if (savedData) {
      try {
        const parsed = JSON.parse(savedData);
        setNodes(parsed.nodes || []);
        setGroups(parsed.groups || []);
        setConnections(parsed.connections || []);
      } catch (e) {
        console.error("配置恢复失败", e);
      }
    } else {
      // 默认演示数据
      setNodes([
        { id: 'n1', name: '接入网关 (Nginx)', type: ServiceType.GATEWAY, position: { x: 150, y: 350, z: 0 }, status: 'online', lastUpdated: new Date().toISOString() },
        { id: 'n2', name: '用户鉴权中心', type: ServiceType.SERVER, position: { x: 450, y: 300, z: 0 }, status: 'online', lastUpdated: new Date().toISOString() },
        { id: 'n3', name: '核心数据库 (MySQL)', type: ServiceType.DATABASE, position: { x: 750, y: 450, z: 0 }, status: 'warning', lastUpdated: new Date().toISOString() },
      ]);
      setGroups([
        { id: 'g1', name: '核心业务区', position: { x: 300, y: 200 }, size: { width: 600, height: 450 }, color: '#38bdf8', status: 'online' }
      ]);
      setConnections([
        { id: 'c1', sourceId: 'n1', targetId: 'n2', label: 'SSL/TLS', trafficLoad: 0.2, status: 'online', style: 'signal' },
        { id: 'c2', sourceId: 'n2', targetId: 'n3', label: 'DB_POOL', trafficLoad: 0.6, status: 'online', style: 'fluid' },
      ]);
    }
  }, []);

  const showToast = (message: string) => {
    setToast({ message, visible: true });
    setTimeout(() => setToast({ message: '', visible: false }), 3000);
  };

  const handleSaveLayout = useCallback(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify({ nodes, groups, connections }));
    showToast("布局配置已保存");
  }, [nodes, groups, connections]);

  const toggleLock = useCallback(() => {
    setIsLocked(prev => !prev);
    if (!isLocked) {
      handleSaveLayout();
      showToast("布局已锁定");
    } else {
      showToast("开启自由编排");
    }
  }, [isLocked, handleSaveLayout]);

  const handleDeleteNode = useCallback((id: string) => {
    setNodes(n => n.filter(x => x.id !== id));
    setConnections(c => c.filter(x => x.sourceId !== id && x.targetId !== id));
    setSelectedId(null);
  }, []);

  const handleDeleteGroup = useCallback((id: string) => {
    setGroups(g => g.filter(x => x.id !== id));
    setSelectedId(null);
  }, []);

  const handleUpdateNode = useCallback((id: string, x: number, y: number) => {
    setNodes(prev => prev.map(n => n.id === id ? { ...n, position: { ...n.position, x, y } } : n));
  }, []);

  const handleUpdateGroup = useCallback((id: string, updates: Partial<GroupNode>) => {
    setGroups(prev => prev.map(g => g.id === id ? { ...g, ...updates } : g));
  }, []);

  const handleAddNode = (type: ServiceType, name: string, status: 'online' | 'warning' | 'error') => {
    const newNode: ServiceNode = {
      id: `node-${Date.now()}`,
      name,
      type,
      position: { x: 100, y: 100, z: 0 },
      status,
      lastUpdated: new Date().toISOString()
    };
    setNodes(prev => [...prev, newNode]);
    showToast(`服务 ${name} 已部署`);
  };

  const handleAddGroup = (name: string, status: 'online' | 'warning' | 'error') => {
    const newGroup: GroupNode = {
      id: `group-${Date.now()}`,
      name,
      position: { x: 50, y: 50 },
      size: { width: 300, height: 200 },
      color: '#38bdf8',
      status
    };
    setGroups(prev => [...prev, newGroup]);
    showToast(`容器 ${name} 已创建`);
  };

  const handleDeleteConnection = (id: string) => {
    setConnections(prev => prev.filter(c => c.id !== id));
    setSelectedConnectionId(null);
  };

  const handleUpdateConnection = (id: string, updates: Partial<Connection>) => {
    setConnections(prev => prev.map(c => c.id === id ? { ...c, ...updates } : c));
  };

  const handleElementClick = (id: string) => {
    if (mode === 'connect') {
      if (!connectSourceId) {
        setConnectSourceId(id);
      } else if (connectSourceId !== id) {
        const newConn: Connection = {
          id: `conn-${Date.now()}`,
          sourceId: connectSourceId,
          targetId: id,
          label: 'NEW_LINK',
          trafficLoad: 0.1,
          status: 'online',
          style: 'signal'
        };
        setConnections(prev => [...prev, newConn]);
        setConnectSourceId(null);
        setMode('select');
        showToast("链路已建立");
      }
    } else {
      setSelectedId(id);
      setSelectedConnectionId(null);
    }
  };

  const handleExport = () => {
    const data = JSON.stringify({ nodes, groups, connections }, null, 2);
    const blob = new Blob([data], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `neoops-layout-${Date.now()}.json`;
    a.click();
    showToast("配置已导出");
  };

  const handleFileImport = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const parsed = JSON.parse(event.target?.result as string);
        setNodes(parsed.nodes || []);
        setGroups(parsed.groups || []);
        setConnections(parsed.connections || []);
        showToast("配置导入成功");
      } catch (err) {
        showToast("非法配置文件");
      }
    };
    reader.readAsText(file);
  };

  const handleAutoLayout = async (desc: string) => {
    if (!desc || isLocked) return;
    setIsAnalyzing(true);
    try {
      const layout = await suggestLayout(desc);
      const newNodes: ServiceNode[] = layout.nodes.map((n: any, i: number) => ({
        id: `ai-n-${i}-${Date.now()}`,
        name: n.name,
        type: n.type as ServiceType,
        position: { x: (n.x + 1) * 60, y: (n.y + 1) * 50, z: 0 },
        status: 'online',
        lastUpdated: new Date().toISOString()
      }));
      const newConns: Connection[] = layout.connections.map((c: any, i: number) => ({
        id: `ai-c-${i}-${Date.now()}`,
        sourceId: newNodes[c.sourceIndex].id,
        targetId: newNodes[c.targetIndex].id,
        label: c.label,
        trafficLoad: 0.2,
        status: 'online',
        style: 'signal'
      }));
      setNodes(newNodes);
      setConnections(newConns);
      showToast("AI 拓扑已生成");
    } catch (e) {
      showToast("AI 服务异常");
    }
    setIsAnalyzing(false);
  };

  return (
    <div className="flex h-screen w-screen bg-[#020617] text-slate-100 overflow-hidden font-sans antialiased">
      <style>{`
        /* --- 节点基础背景 --- */
        @keyframes bg-pulse-green {
          0%, 100% { background: rgba(16, 185, 129, 0.05); border-color: rgba(16, 185, 129, 0.2); }
          50% { background: rgba(16, 185, 129, 0.15); border-color: rgba(16, 185, 129, 0.5); }
        }
        @keyframes bg-pulse-yellow {
          0%, 100% { background: rgba(245, 158, 11, 0.05); border-color: rgba(245, 158, 11, 0.2); }
          50% { background: rgba(245, 158, 11, 0.25); border-color: rgba(245, 158, 11, 0.6); }
        }
        @keyframes bg-pulse-red {
          0%, 100% { background: rgba(244, 63, 94, 0.1); border-color: rgba(244, 63, 94, 0.3); }
          50% { background: rgba(244, 63, 94, 0.4); border-color: rgba(244, 63, 94, 0.8); }
        }

        .card-online { animation: bg-pulse-green 4s ease-in-out infinite; }
        .card-warning { animation: bg-pulse-yellow 1.5s ease-in-out infinite; }
        .card-error { animation: bg-pulse-red 0.6s ease-in-out infinite; }

        .node-button {
          backdrop-filter: blur(16px);
          -webkit-backdrop-filter: blur(16px);
          border: 1px solid rgba(255, 255, 255, 0.05);
          transition: all 0.4s cubic-bezier(0.16, 1, 0.3, 1);
        }

        /**
         * --- 拓扑连线特效 (Visual FX) ---
         */

        /* 1. 标准脉冲 (Signal) */
        @keyframes signal-ultra-flow { 
          0% { stroke-dashoffset: 600; filter: drop-shadow(0 0 2px currentColor); } 
          50% { filter: drop-shadow(0 0 12px currentColor); }
          100% { stroke-dashoffset: 0; filter: drop-shadow(0 0 2px currentColor); } 
        }
        .connection-signal { 
          stroke-dasharray: 40, 20, 5, 20, 15, 60; 
          stroke-linecap: round; 
          animation: signal-ultra-flow 4s linear infinite; 
          stroke-width: 3px;
        }

        /* 2. 路径流动特效 (Path Packet Flow) - 代替原有的心电图律动 */
        @keyframes path-packet-transmit {
          from { stroke-dashoffset: 100; }
          to { stroke-dashoffset: 0; }
        }

        @keyframes packet-glow-pulse {
          0%, 100% { filter: drop-shadow(0 0 2px currentColor); opacity: 0.5; }
          50% { filter: drop-shadow(0 0 8px currentColor) drop-shadow(0 0 12px currentColor); opacity: 1; }
        }

        .connection-ekg { 
          /* 线条段落化：12px 线段代表数据包，24px 间隙 */
          stroke-dasharray: 12, 24; 
          stroke-linecap: round;
          /* 线性流动动画：利用 stroke-dashoffset 实现沿路径移动 */
          animation: 
            path-packet-transmit var(--flow-dur, 1.2s) linear infinite,
            packet-glow-pulse 2s ease-in-out infinite;
          will-change: stroke-dashoffset, filter, opacity;
        }

        /* 3. 示波器干扰 (Oscilloscope) */
        @keyframes oscilloscope-glitch {
          0%, 100% { stroke-dashoffset: 0; opacity: 1; }
          50% { stroke-dashoffset: 40; opacity: 0.7; }
        }
        .connection-oscilloscope { stroke-dasharray: 2, 8; animation: oscilloscope-glitch 0.2s steps(2) infinite; }

        /* 4. 异常频闪 (Flicker) */
        @keyframes flicker-error {
          0%, 100% { opacity: 1; stroke-width: 3px; }
          33% { opacity: 0.1; stroke-width: 1px; }
          66% { opacity: 0.5; stroke-width: 5px; }
        }
        .connection-flicker { stroke-dasharray: 10, 5; animation: flicker-error 0.4s ease-in-out infinite; }

        .selected-jump { stroke-width: 6px !important; filter: drop-shadow(0 0 20px #fff) !important; animation-duration: 0.6s !important; }

        /* Custom Scrollbar */
        .custom-scrollbar::-webkit-scrollbar { width: 4px; }
        .custom-scrollbar::-webkit-scrollbar-track { background: transparent; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: rgba(56, 189, 248, 0.2); border-radius: 10px; }
        .custom-scrollbar::-webkit-scrollbar-thumb:hover { background: rgba(56, 189, 248, 0.4); }
      `}</style>

      <Sidebar 
        nodes={nodes}
        groups={groups}
        connections={connections}
        selectedId={selectedId}
        selectedConnectionId={selectedConnectionId}
        addNode={handleAddNode}
        addGroup={handleAddGroup}
        deleteNode={handleDeleteNode}
        deleteGroup={handleDeleteGroup}
        deleteConnection={handleDeleteConnection}
        updateConnection={handleUpdateConnection}
        isAnalyzing={isAnalyzing}
        onAutoLayout={handleAutoLayout}
        isLocked={isLocked}
        onExport={handleExport}
        onImport={() => fileInputRef.current?.click()}
      />

      <main className="flex-1 relative flex flex-col">
        <UIOverlay 
          mode={mode}
          setMode={setMode}
          connectSource={nodes.find(n => n.id === connectSourceId)?.name}
          isLocked={isLocked}
          setIsLocked={toggleLock}
        />

        <Workspace 
          nodes={nodes}
          groups={groups}
          connections={connections}
          selectedId={selectedId}
          selectedConnectionId={selectedConnectionId}
          onElementClick={handleElementClick}
          onConnectionClick={(id) => { setSelectedConnectionId(id); setSelectedId(null); }}
          onNodeMove={handleUpdateNode}
          onUpdateGroup={handleUpdateGroup}
          onDeleteGroup={handleDeleteGroup}
          onDeleteNode={handleDeleteNode}
          mode={mode}
          isLocked={isLocked}
        />

        <input 
          type="file" 
          ref={fileInputRef} 
          className="hidden" 
          accept=".json" 
          onChange={handleFileImport} 
        />

        {toast.visible && (
          <div className="fixed bottom-8 left-1/2 -translate-x-1/2 z-50 bg-slate-900 border border-sky-500/50 px-6 py-3 rounded-2xl shadow-2xl text-xs font-bold animate-in fade-in slide-in-from-bottom-4">
             <span className="bg-sky-500 text-slate-950 px-1.5 py-0.5 rounded mr-2 uppercase text-[10px]">Info</span>
             {toast.message}
          </div>
        )}
      </main>
    </div>
  );
};

export default App;

import React, { useRef, useState, useMemo, useEffect } from 'react';
import { ServiceNode, Connection, GroupNode } from '../types';
import { SERVICE_ICONS, SERVICE_COLORS } from '../constants';

interface WorkspaceProps {
  nodes: ServiceNode[];
  groups: GroupNode[];
  connections: Connection[];
  selectedId: string | null;
  selectedConnectionId: string | null;
  onElementClick: (id: string) => void;
  onConnectionClick: (id: string) => void;
  onNodeMove: (id: string, x: number, y: number) => void;
  onUpdateGroup: (id: string, updates: Partial<GroupNode>) => void;
  onDeleteGroup: (id: string) => void;
  onDeleteNode: (id: string) => void;
  mode: string;
  isLocked: boolean;
}

const Workspace: React.FC<WorkspaceProps> = ({ 
  nodes, 
  groups,
  connections, 
  selectedId,
  selectedConnectionId,
  onElementClick,
  onConnectionClick,
  onNodeMove, 
  onUpdateGroup,
  mode,
  isLocked
}) => {
  const containerRef = useRef<HTMLDivElement>(null);

  const [viewOffset, setViewOffset] = useState({ x: 0, y: 0 });
  const [isPanning, setIsPanning] = useState(false);
  const [lastMousePos, setLastMousePos] = useState({ x: 0, y: 0 });

  const [draggingId, setDraggingId] = useState<string | null>(null);
  const [resizingId, setResizingId] = useState<string | null>(null);
  const [dragType, setDragType] = useState<'node' | 'group' | 'scroll-h' | 'scroll-v'>('node');

  // 动态计算虚拟画布的边界
  const contentBounds = useMemo(() => {
    if (nodes.length === 0 && groups.length === 0) {
      return { minX: -2000, maxX: 2000, minY: -2000, maxY: 2000 };
    }
    let minX = 0, maxX = 1000, minY = 0, maxY = 1000;
    nodes.forEach(n => {
      minX = Math.min(minX, n.position.x - 500);
      maxX = Math.max(maxX, n.position.x + 800);
      minY = Math.min(minY, n.position.y - 500);
      maxY = Math.max(maxY, n.position.y + 800);
    });
    groups.forEach(g => {
      minX = Math.min(minX, g.position.x - 500);
      maxX = Math.max(maxX, g.position.x + g.size.width + 800);
      minY = Math.min(minY, g.position.y - 500);
      maxY = Math.max(maxY, g.position.y + g.size.height + 800);
    });
    return { minX, maxX, minY, maxY, width: maxX - minX, height: maxY - minY };
  }, [nodes, groups]);

  const handleWheel = (e: React.WheelEvent) => {
    if (!containerRef.current) return;
    const rect = containerRef.current.getBoundingClientRect();
    const dx = e.deltaX;
    const dy = e.deltaY;
    setViewOffset(prev => ({
      x: Math.min(Math.max(prev.x - dx, rect.width - contentBounds.maxX), -contentBounds.minX),
      y: Math.min(Math.max(prev.y - dy, rect.height - contentBounds.maxY), -contentBounds.minY)
    }));
  };

  const handleMouseDown = (e: React.MouseEvent) => {
    if (!containerRef.current) return;
    if (e.target === containerRef.current) {
      setIsPanning(true);
      setLastMousePos({ x: e.clientX, y: e.clientY });
    }
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (!containerRef.current) return;
    const rect = containerRef.current.getBoundingClientRect();
    if (isPanning) {
      const dx = e.clientX - lastMousePos.x;
      const dy = e.clientY - lastMousePos.y;
      setViewOffset(prev => ({ 
        x: Math.min(Math.max(prev.x + dx, rect.width - contentBounds.maxX), -contentBounds.minX),
        y: Math.min(Math.max(prev.y + dy, rect.height - contentBounds.maxY), -contentBounds.minY)
      }));
      setLastMousePos({ x: e.clientX, y: e.clientY });
      return;
    }
    if (draggingId === 'scrollbar-h') {
      const dx = e.clientX - lastMousePos.x;
      const movePercent = dx / rect.width;
      const offsetDelta = movePercent * contentBounds.width;
      setViewOffset(prev => ({ ...prev, x: Math.min(Math.max(prev.x - offsetDelta, rect.width - contentBounds.maxX), -contentBounds.minX) }));
      setLastMousePos({ x: e.clientX, y: e.clientY });
      return;
    }
    if (draggingId === 'scrollbar-v') {
      const dy = e.clientY - lastMousePos.y;
      const movePercent = dy / rect.height;
      const offsetDelta = movePercent * contentBounds.height;
      setViewOffset(prev => ({ ...prev, y: Math.min(Math.max(prev.y - offsetDelta, rect.height - contentBounds.maxY), -contentBounds.minY) }));
      setLastMousePos({ x: e.clientX, y: e.clientY });
      return;
    }
    if (mode !== 'select' || isLocked) return;
    const x = e.clientX - rect.left - viewOffset.x;
    const y = e.clientY - rect.top - viewOffset.y;
    if (draggingId && dragType === 'node') {
      onNodeMove(draggingId, x - 65, y - 22);
    } else if (draggingId && dragType === 'group') {
      const group = groups.find(g => g.id === draggingId);
      if (group) onUpdateGroup(draggingId, { position: { x: x - group.size.width / 2, y: y - 16 } });
    } else if (resizingId) {
      const group = groups.find(g => g.id === resizingId);
      if (group) onUpdateGroup(resizingId, { size: { width: Math.max(200, x - group.position.x), height: Math.max(150, y - group.position.y) } });
    }
  };

  const handleMouseUp = () => { setIsPanning(false); setDraggingId(null); setResizingId(null); };

  const scrollMetrics = useMemo(() => {
    if (!containerRef.current) return { h: { pos: 0, size: 0 }, v: { pos: 0, size: 0 } };
    const rect = containerRef.current.getBoundingClientRect();
    const hSize = Math.max(40, (rect.width / contentBounds.width) * rect.width);
    const vSize = Math.max(40, (rect.height / contentBounds.height) * rect.height);
    const hPos = ((-viewOffset.x - contentBounds.minX) / contentBounds.width) * rect.width;
    const vPos = ((-viewOffset.y - contentBounds.minY) / contentBounds.height) * rect.height;
    return { h: { pos: Math.max(0, Math.min(rect.width - hSize, hPos)), size: hSize }, v: { pos: Math.max(0, Math.min(rect.height - vSize, vPos)), size: vSize } };
  }, [viewOffset, contentBounds]);

  const getStatusConfig = (status: string) => {
    switch(status) {
      case 'online': return { text: 'RUNNING', color: 'text-emerald-400' };
      case 'warning': return { text: 'STRESSED', color: 'text-amber-400' };
      case 'error': return { text: 'OFFLINE', color: 'text-rose-400' };
      default: return { text: 'RUNNING', color: 'text-emerald-400' };
    }
  };

  const getElementInfo = (id: string) => {
    const node = nodes.find(n => n.id === id);
    if (node) return { x: node.position.x, y: node.position.y, w: 130, h: 44, cx: node.position.x + 65, cy: node.position.y + 22 };
    const group = groups.find(g => g.id === id);
    if (group) return { x: group.position.x, y: group.position.y, w: group.size.width, h: group.size.height, cx: group.position.x + group.size.width / 2, cy: group.position.y + group.size.height / 2 };
    return null;
  };

  const getConnectionPoint = (sourceId: string, targetId: string) => {
    const s = getElementInfo(sourceId);
    const t = getElementInfo(targetId);
    if (!s || !t) return null;
    const getIntersection = (rect: any, otherCenter: {x: number, y: number}) => {
      const dx = otherCenter.x - rect.cx;
      const dy = otherCenter.y - rect.cy;
      const hw = rect.w / 2;
      const hh = rect.h / 2;
      const scale = Math.min(dx !== 0 ? Math.abs(hw / dx) : Infinity, dy !== 0 ? Math.abs(hh / dy) : Infinity);
      return { x: rect.cx + dx * scale, y: rect.cy + dy * scale };
    };
    return { start: getIntersection(s, { x: t.cx, y: t.cy }), end: getIntersection(t, { x: s.cx, y: s.cy }) };
  };

  const getBezierPath = (start: {x: number, y: number}, end: {x: number, y: number}) => {
    const dx = Math.abs(end.x - start.x);
    const dy = Math.abs(end.y - start.y);
    const horizontal = dx > dy;
    const ctrl1 = horizontal ? { x: start.x + dx / 4, y: start.y } : { x: start.x, y: start.y + dy / 4 };
    const ctrl2 = horizontal ? { x: end.x - dx / 4, y: end.y } : { x: end.x, y: end.y - dy / 4 };
    return `M ${start.x} ${start.y} C ${ctrl1.x} ${ctrl1.y}, ${ctrl2.x} ${ctrl2.y}, ${end.x} ${end.y}`;
  };

  const getConnectionClass = (style: string | undefined) => {
    switch (style) {
      case 'fluid': return 'connection-ekg';
      case 'packet': return 'connection-oscilloscope';
      case 'dashed': return 'connection-flicker';
      default: return 'connection-signal';
    }
  };

  return (
    <div ref={containerRef} className={`w-full h-full relative select-none overflow-hidden ${isPanning ? 'cursor-grabbing' : 'cursor-default'}`} onMouseDown={handleMouseDown} onMouseMove={handleMouseMove} onMouseUp={handleMouseUp} onWheel={handleWheel} style={{ backgroundImage: `linear-gradient(to right, rgba(14, 165, 233, 0.04) 1px, transparent 1px), linear-gradient(to bottom, rgba(14, 165, 233, 0.04) 1px, transparent 1px)`, backgroundSize: '40px 40px', backgroundPosition: `${viewOffset.x}px ${viewOffset.y}px` }}>
      <div style={{ transform: `translate(${viewOffset.x}px, ${viewOffset.y}px)`, position: 'absolute', inset: 0, pointerEvents: 'none' }}>
        {groups.map((group) => (
          <div key={group.id} style={{ left: group.position.x, top: group.position.y, width: group.size.width, height: group.size.height, pointerEvents: 'auto' }} className={`absolute z-0 transition-all ${isLocked ? 'pointer-events-auto' : 'cursor-move'}`} onClick={(e) => { e.stopPropagation(); onElementClick(group.id); }} onMouseDown={(e) => { if (mode === 'select' && !isLocked) { e.stopPropagation(); setDraggingId(group.id); setDragType('group'); } }}>
            <div className={`absolute inset-0 rounded-3xl bg-slate-950/20 backdrop-blur-sm border transition-all duration-500 ${selectedId === group.id ? 'border-sky-500 shadow-[0_0_40px_rgba(14,165,233,0.1)]' : 'border-slate-800/40'} ${group.status === 'online' ? 'card-online' : group.status === 'warning' ? 'card-warning' : 'card-error'}`}>
              <div className="absolute top-0 left-0 right-0 p-4 flex items-center justify-between pointer-events-none">
                 <div className="flex flex-col">
                   <span className="text-[10px] font-black text-slate-100 uppercase tracking-widest">{group.name}</span>
                   <span className={`text-[8px] font-bold ${getStatusConfig(group.status).color}`}>{getStatusConfig(group.status).text}</span>
                 </div>
                 <i className="fas fa-cubes text-slate-600 text-xs opacity-50"></i>
              </div>
            </div>
            {!isLocked && (
              <div className="absolute bottom-4 right-4 w-4 h-4 cursor-nwse-resize opacity-20 hover:opacity-100" onMouseDown={(e) => { e.stopPropagation(); setResizingId(group.id); }}>
                <i className="fas fa-expand-arrows-alt text-xs text-sky-400"></i>
              </div>
            )}
          </div>
        ))}

        <svg className="absolute inset-0 w-full h-full pointer-events-none z-[5]">
          <defs>
            <filter id="glow" x="-20%" y="-20%" width="140%" height="140%">
              <feGaussianBlur stdDeviation="3" result="blur" />
              <feMerge>
                <feMergeNode in="blur" />
                <feMergeNode in="SourceGraphic" />
              </feMerge>
            </filter>
          </defs>
          {connections.map((conn) => {
            const points = getConnectionPoint(conn.sourceId, conn.targetId);
            if (!points) return null;
            const isSelected = selectedConnectionId === conn.id;

            // 路径流动参数映射：
            // 绿色 (#00ff9d) 代表正常，红色 (#ff003c) 代表故障
            const color = conn.status === 'error' ? '#ff003c' : '#00ff9d';

            // 将 0-1 的 trafficLoad 映射为流动周期时长 (flow-dur)
            // 负载越高，周期越短 (流动越快)
            const flowDur = 2.0 / (0.5 + conn.trafficLoad * 2.5);

            const midX = (points.start.x + points.end.x) / 2;
            const midY = (points.start.y + points.end.y) / 2;

            return (
              <g key={conn.id}>
                <path d={getBezierPath(points.start, points.end)} stroke="transparent" strokeWidth="24" fill="none" className="cursor-pointer pointer-events-auto" onClick={(e) => { e.stopPropagation(); onConnectionClick(conn.id); }} />

                <path 
                  d={getBezierPath(points.start, points.end)} 
                  stroke={color} 
                  strokeWidth={isSelected ? 5 : 3} 
                  fill="none" 
                  className={`${getConnectionClass(conn.style)} ${isSelected ? 'selected-jump' : ''}`} 
                  filter="url(#glow)" 
                  style={{ 
                    opacity: isSelected ? 1 : 0.75, 
                    color,
                    '--flow-dur': `${flowDur}s`
                  } as React.CSSProperties} 
                />

                <text
                  x={midX}
                  y={midY - 8}
                  textAnchor="middle"
                  className="text-[9px] font-black fill-slate-300 pointer-events-none uppercase tracking-widest transition-opacity duration-300"
                  style={{ 
                    opacity: isSelected ? 1 : 0.6,
                    paintOrder: 'stroke',
                    stroke: '#020617',
                    strokeWidth: '4px',
                    strokeLinecap: 'round',
                    strokeLinejoin: 'round'
                  }}
                >
                  {conn.label}
                </text>
              </g>
            );
          })}
        </svg>

        {nodes.map((node) => {
          const isSelected = selectedId === node.id;
          const statusConfig = getStatusConfig(node.status);
          return (
            <div key={node.id} style={{ left: node.position.x, top: node.position.y, width: '130px', height: '44px', pointerEvents: 'auto' }} className="absolute z-10">
              <div className={`w-full h-full node-button rounded-xl flex items-center px-3 relative ${node.status === 'online' ? 'card-online' : node.status === 'warning' ? 'card-warning' : 'card-error'} ${isSelected ? 'ring-2 ring-sky-500/50 scale-105 z-20' : ''}`} onClick={(e) => { e.stopPropagation(); onElementClick(node.id); }} onMouseDown={(e) => { if (mode === 'select' && !isLocked) { e.stopPropagation(); setDraggingId(node.id); setDragType('node'); } }}>
                <div className="flex items-center gap-3 w-full">
                  <div className="w-8 h-8 rounded-lg bg-slate-900/50 flex items-center justify-center border border-white/5"><i className={`fas ${SERVICE_ICONS[node.type]} text-xs`} style={{ color: SERVICE_COLORS[node.type] }}></i></div>
                  <div className="flex flex-col min-w-0"><span className="text-[9px] font-black text-slate-100 truncate uppercase">{node.name}</span><span className={`text-[7px] font-bold ${statusConfig.color}`}>{statusConfig.text}</span></div>
                </div>
              </div>
            </div>
          );
        })}
      </div>
      <div className="absolute bottom-1.5 left-2 right-2 h-1.5 bg-sky-500/5 rounded-full z-50 group hover:h-3 transition-all cursor-pointer"><div className="h-full bg-sky-500/20 rounded-full border border-sky-500/10" style={{ width: `${scrollMetrics.h.size}px`, transform: `translateX(${scrollMetrics.h.pos}px)` }} onMouseDown={(e) => { e.stopPropagation(); setDraggingId('scrollbar-h'); setLastMousePos({ x: e.clientX, y: e.clientY }); }} /></div>
      <div className="absolute top-2 bottom-2 right-1.5 w-1.5 bg-sky-500/5 rounded-full z-50 group hover:w-3 transition-all cursor-pointer"><div className="w-full bg-sky-500/20 rounded-full border border-sky-500/10" style={{ height: `${scrollMetrics.v.size}px`, transform: `translateY(${scrollMetrics.v.pos}px)` }} onMouseDown={(e) => { e.stopPropagation(); setDraggingId('scrollbar-v'); setLastMousePos({ x: e.clientX, y: e.clientY }); }} /></div>
    </div>
  );
};

export default Workspace;

import React, { useState, useCallback, useEffect, useRef } from 'react';
import Sidebar from './components/Sidebar';
import UIOverlay from './components/UIOverlay';
import Workspace from './components/Workspace';
import { ServiceNode, Connection, ServiceType, GroupNode } from './types';
import { suggestLayout } from './geminiService';

/**
 * NeoOps 运维系统主程序
 * 负责核心状态管理、全局 CSS 动画定义及持久化逻辑
 */

const STORAGE_KEY = 'NEOOPS_CORE_STORAGE';

const App: React.FC = () => {
  const [nodes, setNodes] = useState<ServiceNode[]>([]);
  const [groups, setGroups] = useState<GroupNode[]>([]);
  const [connections, setConnections] = useState<Connection[]>([]);

  const [toast, setToast] = useState<{ message: string; visible: boolean }>({ message: '', visible: false });
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [selectedConnectionId, setSelectedConnectionId] = useState<string | null>(null);
  const [mode, setMode] = useState<'select' | 'add' | 'connect'>('select');
  const [isLocked, setIsLocked] = useState(false);
  const [connectSourceId, setConnectSourceId] = useState<string | null>(null);
  const [isAnalyzing, setIsAnalyzing] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);

  // 初始化：加载本地存储
  useEffect(() => {
    const savedData = localStorage.getItem(STORAGE_KEY);
    if (savedData) {
      try {
        const parsed = JSON.parse(savedData);
        setNodes(parsed.nodes || []);
        setGroups(parsed.groups || []);
        setConnections(parsed.connections || []);
      } catch (e) {
        console.error("配置恢复失败", e);
      }
    } else {
      // 默认演示数据
      setNodes([
        { id: 'n1', name: '接入网关 (Nginx)', type: ServiceType.GATEWAY, position: { x: 150, y: 350, z: 0 }, status: 'online', lastUpdated: new Date().toISOString() },
        { id: 'n2', name: '用户鉴权中心', type: ServiceType.SERVER, position: { x: 450, y: 300, z: 0 }, status: 'online', lastUpdated: new Date().toISOString() },
        { id: 'n3', name: '核心数据库 (MySQL)', type: ServiceType.DATABASE, position: { x: 750, y: 450, z: 0 }, status: 'warning', lastUpdated: new Date().toISOString() },
      ]);
      setGroups([
        { id: 'g1', name: '核心业务区', position: { x: 300, y: 200 }, size: { width: 600, height: 450 }, color: '#38bdf8', status: 'online' }
      ]);
      setConnections([
        { id: 'c1', sourceId: 'n1', targetId: 'n2', label: 'SSL/TLS', trafficLoad: 0.2, status: 'online', style: 'signal' },
        { id: 'c2', sourceId: 'n2', targetId: 'n3', label: 'DB_POOL', trafficLoad: 0.6, status: 'online', style: 'fluid' },
      ]);
    }
  }, []);

  const showToast = (message: string) => {
    setToast({ message, visible: true });
    setTimeout(() => setToast({ message: '', visible: false }), 3000);
  };

  const handleSaveLayout = useCallback(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify({ nodes, groups, connections }));
    showToast("布局配置已保存");
  }, [nodes, groups, connections]);

  const toggleLock = useCallback(() => {
    setIsLocked(prev => !prev);
    if (!isLocked) {
      handleSaveLayout();
      showToast("布局已锁定");
    } else {
      showToast("开启自由编排");
    }
  }, [isLocked, handleSaveLayout]);

  const handleDeleteNode = useCallback((id: string) => {
    setNodes(n => n.filter(x => x.id !== id));
    setConnections(c => c.filter(x => x.sourceId !== id && x.targetId !== id));
    setSelectedId(null);
  }, []);

  const handleDeleteGroup = useCallback((id: string) => {
    setGroups(g => g.filter(x => x.id !== id));
    setSelectedId(null);
  }, []);

  const handleUpdateNode = useCallback((id: string, x: number, y: number) => {
    setNodes(prev => prev.map(n => n.id === id ? { ...n, position: { ...n.position, x, y } } : n));
  }, []);

  const handleUpdateGroup = useCallback((id: string, updates: Partial<GroupNode>) => {
    setGroups(prev => prev.map(g => g.id === id ? { ...g, ...updates } : g));
  }, []);

  const handleAddNode = (type: ServiceType, name: string, status: 'online' | 'warning' | 'error') => {
    const newNode: ServiceNode = {
      id: `node-${Date.now()}`,
      name,
      type,
      position: { x: 100, y: 100, z: 0 },
      status,
      lastUpdated: new Date().toISOString()
    };
    setNodes(prev => [...prev, newNode]);
    showToast(`服务 ${name} 已部署`);
  };

  const handleAddGroup = (name: string, status: 'online' | 'warning' | 'error') => {
    const newGroup: GroupNode = {
      id: `group-${Date.now()}`,
      name,
      position: { x: 50, y: 50 },
      size: { width: 300, height: 200 },
      color: '#38bdf8',
      status
    };
    setGroups(prev => [...prev, newGroup]);
    showToast(`容器 ${name} 已创建`);
  };

  const handleDeleteConnection = (id: string) => {
    setConnections(prev => prev.filter(c => c.id !== id));
    setSelectedConnectionId(null);
  };

  const handleUpdateConnection = (id: string, updates: Partial<Connection>) => {
    setConnections(prev => prev.map(c => c.id === id ? { ...c, ...updates } : c));
  };

  const handleElementClick = (id: string) => {
    if (mode === 'connect') {
      if (!connectSourceId) {
        setConnectSourceId(id);
      } else if (connectSourceId !== id) {
        const newConn: Connection = {
          id: `conn-${Date.now()}`,
          sourceId: connectSourceId,
          targetId: id,
          label: 'NEW_LINK',
          trafficLoad: 0.1,
          status: 'online',
          style: 'signal'
        };
        setConnections(prev => [...prev, newConn]);
        setConnectSourceId(null);
        setMode('select');
        showToast("链路已建立");
      }
    } else {
      setSelectedId(id);
      setSelectedConnectionId(null);
    }
  };

  const handleExport = () => {
    const data = JSON.stringify({ nodes, groups, connections }, null, 2);
    const blob = new Blob([data], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `neoops-layout-${Date.now()}.json`;
    a.click();
    showToast("配置已导出");
  };

  const handleFileImport = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const parsed = JSON.parse(event.target?.result as string);
        setNodes(parsed.nodes || []);
        setGroups(parsed.groups || []);
        setConnections(parsed.connections || []);
        showToast("配置导入成功");
      } catch (err) {
        showToast("非法配置文件");
      }
    };
    reader.readAsText(file);
  };

  const handleAutoLayout = async (desc: string) => {
    if (!desc || isLocked) return;
    setIsAnalyzing(true);
    try {
      const layout = await suggestLayout(desc);
      const newNodes: ServiceNode[] = layout.nodes.map((n: any, i: number) => ({
        id: `ai-n-${i}-${Date.now()}`,
        name: n.name,
        type: n.type as ServiceType,
        position: { x: (n.x + 1) * 60, y: (n.y + 1) * 50, z: 0 },
        status: 'online',
        lastUpdated: new Date().toISOString()
      }));
      const newConns: Connection[] = layout.connections.map((c: any, i: number) => ({
        id: `ai-c-${i}-${Date.now()}`,
        sourceId: newNodes[c.sourceIndex].id,
        targetId: newNodes[c.targetIndex].id,
        label: c.label,
        trafficLoad: 0.2,
        status: 'online',
        style: 'signal'
      }));
      setNodes(newNodes);
      setConnections(newConns);
      showToast("AI 拓扑已生成");
    } catch (e) {
      showToast("AI 服务异常");
    }
    setIsAnalyzing(false);
  };

  return (
    <div className="flex h-screen w-screen bg-[#020617] text-slate-100 overflow-hidden font-sans antialiased">
      <style>{`
        /* --- 节点基础背景 --- */
        @keyframes bg-pulse-green {
          0%, 100% { background: rgba(16, 185, 129, 0.05); border-color: rgba(16, 185, 129, 0.2); }
          50% { background: rgba(16, 185, 129, 0.15); border-color: rgba(16, 185, 129, 0.5); }
        }
        @keyframes bg-pulse-yellow {
          0%, 100% { background: rgba(245, 158, 11, 0.05); border-color: rgba(245, 158, 11, 0.2); }
          50% { background: rgba(245, 158, 11, 0.25); border-color: rgba(245, 158, 11, 0.6); }
        }
        @keyframes bg-pulse-red {
          0%, 100% { background: rgba(244, 63, 94, 0.1); border-color: rgba(244, 63, 94, 0.3); }
          50% { background: rgba(244, 63, 94, 0.4); border-color: rgba(244, 63, 94, 0.8); }
        }

        .card-online { animation: bg-pulse-green 4s ease-in-out infinite; }
        .card-warning { animation: bg-pulse-yellow 1.5s ease-in-out infinite; }
        .card-error { animation: bg-pulse-red 0.6s ease-in-out infinite; }

        .node-button {
          backdrop-filter: blur(16px);
          -webkit-backdrop-filter: blur(16px);
          border: 1px solid rgba(255, 255, 255, 0.05);
          transition: all 0.4s cubic-bezier(0.16, 1, 0.3, 1);
        }

        /**
         * --- 拓扑连线特效 (Visual FX) ---
         */

        /* 1. 标准脉冲 (Signal) */
        @keyframes signal-ultra-flow { 
          0% { stroke-dashoffset: 600; filter: drop-shadow(0 0 2px currentColor); } 
          50% { filter: drop-shadow(0 0 12px currentColor); }
          100% { stroke-dashoffset: 0; filter: drop-shadow(0 0 2px currentColor); } 
        }
        .connection-signal { 
          stroke-dasharray: 40, 20, 5, 20, 15, 60; 
          stroke-linecap: round; 
          animation: signal-ultra-flow 4s linear infinite; 
          stroke-width: 3px;
        }

        /* 2. 路径流动特效 (Path Packet Flow) - 代替原有的心电图律动 */
        @keyframes path-packet-transmit {
          from { stroke-dashoffset: 100; }
          to { stroke-dashoffset: 0; }
        }

        @keyframes packet-glow-pulse {
          0%, 100% { filter: drop-shadow(0 0 2px currentColor); opacity: 0.5; }
          50% { filter: drop-shadow(0 0 8px currentColor) drop-shadow(0 0 12px currentColor); opacity: 1; }
        }

        .connection-ekg { 
          /* 线条段落化：12px 线段代表数据包，24px 间隙 */
          stroke-dasharray: 12, 24; 
          stroke-linecap: round;
          /* 线性流动动画：利用 stroke-dashoffset 实现沿路径移动 */
          animation: 
            path-packet-transmit var(--flow-dur, 1.2s) linear infinite,
            packet-glow-pulse 2s ease-in-out infinite;
          will-change: stroke-dashoffset, filter, opacity;
        }

        /* 3. 示波器干扰 (Oscilloscope) */
        @keyframes oscilloscope-glitch {
          0%, 100% { stroke-dashoffset: 0; opacity: 1; }
          50% { stroke-dashoffset: 40; opacity: 0.7; }
        }
        .connection-oscilloscope { stroke-dasharray: 2, 8; animation: oscilloscope-glitch 0.2s steps(2) infinite; }

        /* 4. 异常频闪 (Flicker) */
        @keyframes flicker-error {
          0%, 100% { opacity: 1; stroke-width: 3px; }
          33% { opacity: 0.1; stroke-width: 1px; }
          66% { opacity: 0.5; stroke-width: 5px; }
        }
        .connection-flicker { stroke-dasharray: 10, 5; animation: flicker-error 0.4s ease-in-out infinite; }

        /* 选中态样式：将 animation-duration 修改为 3.0s 以减慢流动速度 */
        .selected-jump { 
          stroke-width: 6px !important; 
          filter: drop-shadow(0 0 20px #fff) !important; 
          animation-duration: 3.0s !important; 
        }

        /* Custom Scrollbar */
        .custom-scrollbar::-webkit-scrollbar { width: 4px; }
        .custom-scrollbar::-webkit-scrollbar-track { background: transparent; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: rgba(56, 189, 248, 0.2); border-radius: 10px; }
        .custom-scrollbar::-webkit-scrollbar-thumb:hover { background: rgba(56, 189, 248, 0.4); }
      `}</style>

      <Sidebar 
        nodes={nodes}
        groups={groups}
        connections={connections}
        selectedId={selectedId}
        selectedConnectionId={selectedConnectionId}
        addNode={handleAddNode}
        addGroup={handleAddGroup}
        deleteNode={handleDeleteNode}
        deleteGroup={handleDeleteGroup}
        deleteConnection={handleDeleteConnection}
        updateConnection={handleUpdateConnection}
        isAnalyzing={isAnalyzing}
        onAutoLayout={handleAutoLayout}
        isLocked={isLocked}
        onExport={handleExport}
        onImport={() => fileInputRef.current?.click()}
      />

      <main className="flex-1 relative flex flex-col">
        <UIOverlay 
          mode={mode}
          setMode={setMode}
          connectSource={nodes.find(n => n.id === connectSourceId)?.name}
          isLocked={isLocked}
          setIsLocked={toggleLock}
        />

        <Workspace 
          nodes={nodes}
          groups={groups}
          connections={connections}
          selectedId={selectedId}
          selectedConnectionId={selectedConnectionId}
          onElementClick={handleElementClick}
          onConnectionClick={(id) => { setSelectedConnectionId(id); setSelectedId(null); }}
          onNodeMove={handleUpdateNode}
          onUpdateGroup={handleUpdateGroup}
          onDeleteGroup={handleDeleteGroup}
          onDeleteNode={handleDeleteNode}
          mode={mode}
          isLocked={isLocked}
        />

        <input 
          type="file" 
          ref={fileInputRef} 
          className="hidden" 
          accept=".json" 
          onChange={handleFileImport} 
        />

        {toast.visible && (
          <div className="fixed bottom-8 left-1/2 -translate-x-1/2 z-50 bg-slate-900 border border-sky-500/50 px-6 py-3 rounded-2xl shadow-2xl text-xs font-bold animate-in fade-in slide-in-from-bottom-4">
             <span className="bg-sky-500 text-slate-950 px-1.5 py-0.5 rounded mr-2 uppercase text-[10px]">Info</span>
             {toast.message}
          </div>
        )}
      </main>
    </div>
  );
};

export default App;

import { ServiceType } from './types';

export const SERVICE_ICONS: Record<ServiceType, string> = {
  [ServiceType.DATABASE]: 'fa-database',
  [ServiceType.SERVER]: 'fa-server',
  [ServiceType.GATEWAY]: 'fa-door-open',
  [ServiceType.CACHE]: 'fa-bolt',
  [ServiceType.LOAD_BALANCER]: 'fa-network-wired',
  [ServiceType.FIREWALL]: 'fa-shield-alt',
  [ServiceType.CONTAINER]: 'fa-cubes'
};

export const SERVICE_COLORS: Record<ServiceType, string> = {
  [ServiceType.DATABASE]: '#fb923c',
  [ServiceType.SERVER]: '#60a5fa',
  [ServiceType.GATEWAY]: '#34d399',
  [ServiceType.CACHE]: '#fbbf24',
  [ServiceType.LOAD_BALANCER]: '#a78bfa',
  [ServiceType.FIREWALL]: '#f472b6',
  [ServiceType.CONTAINER]: '#818cf8'
};

import React, { useRef, useState, useMemo, useEffect } from 'react';
import { ServiceNode, Connection, GroupNode } from '../types';
import { SERVICE_ICONS, SERVICE_COLORS } from '../constants';

interface WorkspaceProps {
  nodes: ServiceNode[];
  groups: GroupNode[];
  connections: Connection[];
  selectedId: string | null;
  selectedConnectionId: string | null;
  onElementClick: (id: string) => void;
  onConnectionClick: (id: string) => void;
  onNodeMove: (id: string, x: number, y: number) => void;
  onUpdateGroup: (id: string, updates: Partial<GroupNode>) => void;
  onDeleteGroup: (id: string) => void;
  onDeleteNode: (id: string) => void;
  mode: string;
  isLocked: boolean;
}

const Workspace: React.FC<WorkspaceProps> = ({ 
  nodes, 
  groups,
  connections, 
  selectedId,
  selectedConnectionId,
  onElementClick,
  onConnectionClick,
  onNodeMove, 
  onUpdateGroup,
  mode,
  isLocked
}) => {
  const containerRef = useRef<HTMLDivElement>(null);

  const [viewOffset, setViewOffset] = useState({ x: 0, y: 0 });
  const [isPanning, setIsPanning] = useState(false);
  const [lastMousePos, setLastMousePos] = useState({ x: 0, y: 0 });

  const [draggingId, setDraggingId] = useState<string | null>(null);
  const [resizingId, setResizingId] = useState<string | null>(null);
  const [dragType, setDragType] = useState<'node' | 'group' | 'scroll-h' | 'scroll-v'>('node');

  // 动态计算虚拟画布的边界
  const contentBounds = useMemo(() => {
    if (nodes.length === 0 && groups.length === 0) {
      return { minX: -2000, maxX: 2000, minY: -2000, maxY: 2000 };
    }
    let minX = 0, maxX = 1000, minY = 0, maxY = 1000;
    nodes.forEach(n => {
      minX = Math.min(minX, n.position.x - 500);
      maxX = Math.max(maxX, n.position.x + 800);
      minY = Math.min(minY, n.position.y - 500);
      maxY = Math.max(maxY, n.position.y + 800);
    });
    groups.forEach(g => {
      minX = Math.min(minX, g.position.x - 500);
      maxX = Math.max(maxX, g.position.x + g.size.width + 800);
      minY = Math.min(minY, g.position.y - 500);
      maxY = Math.max(maxY, g.position.y + g.size.height + 800);
    });
    return { minX, maxX, minY, maxY, width: maxX - minX, height: maxY - minY };
  }, [nodes, groups]);

  const handleWheel = (e: React.WheelEvent) => {
    if (!containerRef.current) return;
    const rect = containerRef.current.getBoundingClientRect();
    const dx = e.deltaX;
    const dy = e.deltaY;
    setViewOffset(prev => ({
      x: Math.min(Math.max(prev.x - dx, rect.width - contentBounds.maxX), -contentBounds.minX),
      y: Math.min(Math.max(prev.y - dy, rect.height - contentBounds.maxY), -contentBounds.minY)
    }));
  };

  const handleMouseDown = (e: React.MouseEvent) => {
    if (!containerRef.current) return;
    if (e.target === containerRef.current) {
      setIsPanning(true);
      setLastMousePos({ x: e.clientX, y: e.clientY });
    }
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (!containerRef.current) return;
    const rect = containerRef.current.getBoundingClientRect();
    if (isPanning) {
      const dx = e.clientX - lastMousePos.x;
      const dy = e.clientY - lastMousePos.y;
      setViewOffset(prev => ({ 
        x: Math.min(Math.max(prev.x + dx, rect.width - contentBounds.maxX), -contentBounds.minX),
        y: Math.min(Math.max(prev.y + dy, rect.height - contentBounds.maxY), -contentBounds.minY)
      }));
      setLastMousePos({ x: e.clientX, y: e.clientY });
      return;
    }
    if (draggingId === 'scrollbar-h') {
      const dx = e.clientX - lastMousePos.x;
      const movePercent = dx / rect.width;
      const offsetDelta = movePercent * contentBounds.width;
      setViewOffset(prev => ({ ...prev, x: Math.min(Math.max(prev.x - offsetDelta, rect.width - contentBounds.maxX), -contentBounds.minX) }));
      setLastMousePos({ x: e.clientX, y: e.clientY });
      return;
    }
    if (draggingId === 'scrollbar-v') {
      const dy = e.clientY - lastMousePos.y;
      const movePercent = dy / rect.height;
      const offsetDelta = movePercent * contentBounds.height;
      setViewOffset(prev => ({ ...prev, y: Math.min(Math.max(prev.y - offsetDelta, rect.height - contentBounds.maxY), -contentBounds.minY) }));
      setLastMousePos({ x: e.clientX, y: e.clientY });
      return;
    }
    if (mode !== 'select' || isLocked) return;
    const x = e.clientX - rect.left - viewOffset.x;
    const y = e.clientY - rect.top - viewOffset.y;
    if (draggingId && dragType === 'node') {
      onNodeMove(draggingId, x - 65, y - 22);
    } else if (draggingId && dragType === 'group') {
      const group = groups.find(g => g.id === draggingId);
      if (group) onUpdateGroup(draggingId, { position: { x: x - group.size.width / 2, y: y - 16 } });
    } else if (resizingId) {
      const group = groups.find(g => g.id === resizingId);
      if (group) onUpdateGroup(resizingId, { size: { width: Math.max(200, x - group.position.x), height: Math.max(150, y - group.position.y) } });
    }
  };

  const handleMouseUp = () => { setIsPanning(false); setDraggingId(null); setResizingId(null); };

  const scrollMetrics = useMemo(() => {
    if (!containerRef.current) return { h: { pos: 0, size: 0 }, v: { pos: 0, size: 0 } };
    const rect = containerRef.current.getBoundingClientRect();
    const hSize = Math.max(40, (rect.width / contentBounds.width) * rect.width);
    const vSize = Math.max(40, (rect.height / contentBounds.height) * rect.height);
    const hPos = ((-viewOffset.x - contentBounds.minX) / contentBounds.width) * rect.width;
    const vPos = ((-viewOffset.y - contentBounds.minY) / contentBounds.height) * rect.height;
    return { h: { pos: Math.max(0, Math.min(rect.width - hSize, hPos)), size: hSize }, v: { pos: Math.max(0, Math.min(rect.height - vSize, vPos)), size: vSize } };
  }, [viewOffset, contentBounds]);

  const getStatusConfig = (status: string) => {
    switch(status) {
      case 'online': return { text: 'RUNNING', color: 'text-emerald-400', hex: '#34d399' };
      case 'warning': return { text: 'STRESSED', color: 'text-amber-400', hex: '#fbbf24' };
      case 'error': return { text: 'OFFLINE', color: 'text-rose-400', hex: '#fb7185' };
      default: return { text: 'RUNNING', color: 'text-emerald-400', hex: '#34d399' };
    }
  };

  const getElementInfo = (id: string) => {
    const node = nodes.find(n => n.id === id);
    if (node) return { x: node.position.x, y: node.position.y, w: 130, h: 44, cx: node.position.x + 65, cy: node.position.y + 22 };
    const group = groups.find(g => g.id === id);
    if (group) return { x: group.position.x, y: group.position.y, w: group.size.width, h: group.size.height, cx: group.position.x + group.size.width / 2, cy: group.position.y + group.size.height / 2 };
    return null;
  };

  const getConnectionPoint = (sourceId: string, targetId: string) => {
    const s = getElementInfo(sourceId);
    const t = getElementInfo(targetId);
    if (!s || !t) return null;
    const getIntersection = (rect: any, otherCenter: {x: number, y: number}) => {
      const dx = otherCenter.x - rect.cx;
      const dy = otherCenter.y - rect.cy;
      const hw = rect.w / 2;
      const hh = rect.h / 2;
      const scale = Math.min(dx !== 0 ? Math.abs(hw / dx) : Infinity, dy !== 0 ? Math.abs(hh / dy) : Infinity);
      return { x: rect.cx + dx * scale, y: rect.cy + dy * scale };
    };
    return { start: getIntersection(s, { x: t.cx, y: t.cy }), end: getIntersection(t, { x: s.cx, y: s.cy }) };
  };

  const getBezierPath = (start: {x: number, y: number}, end: {x: number, y: number}) => {
    const dx = Math.abs(end.x - start.x);
    const dy = Math.abs(end.y - start.y);
    const horizontal = dx > dy;
    const ctrl1 = horizontal ? { x: start.x + dx / 4, y: start.y } : { x: start.x, y: start.y + dy / 4 };
    const ctrl2 = horizontal ? { x: end.x - dx / 4, y: end.y } : { x: end.x, y: end.y - dy / 4 };
    return `M ${start.x} ${start.y} C ${ctrl1.x} ${ctrl1.y}, ${ctrl2.x} ${ctrl2.y}, ${end.x} ${end.y}`;
  };

  const getConnectionClass = (style: string | undefined) => {
    switch (style) {
      case 'fluid': return 'connection-ekg';
      case 'packet': return 'connection-oscilloscope';
      case 'dashed': return 'connection-flicker';
      default: return 'connection-signal';
    }
  };

  return (
    <div ref={containerRef} className={`w-full h-full relative select-none overflow-hidden ${isPanning ? 'cursor-grabbing' : 'cursor-default'}`} onMouseDown={handleMouseDown} onMouseMove={handleMouseMove} onMouseUp={handleMouseUp} onWheel={handleWheel} style={{ backgroundImage: `linear-gradient(to right, rgba(14, 165, 233, 0.04) 1px, transparent 1px), linear-gradient(to bottom, rgba(14, 165, 233, 0.04) 1px, transparent 1px)`, backgroundSize: '40px 40px', backgroundPosition: `${viewOffset.x}px ${viewOffset.y}px` }}>
      <div style={{ transform: `translate(${viewOffset.x}px, ${viewOffset.y}px)`, position: 'absolute', inset: 0, pointerEvents: 'none' }}>
        {groups.map((group) => (
          <div key={group.id} style={{ left: group.position.x, top: group.position.y, width: group.size.width, height: group.size.height, pointerEvents: 'auto' }} className={`absolute z-0 transition-all ${isLocked ? 'pointer-events-auto' : 'cursor-move'}`} onClick={(e) => { e.stopPropagation(); onElementClick(group.id); }} onMouseDown={(e) => { if (mode === 'select' && !isLocked) { e.stopPropagation(); setDraggingId(group.id); setDragType('group'); } }}>
            <div className={`absolute inset-0 rounded-3xl bg-slate-950/20 backdrop-blur-sm border transition-all duration-500 ${selectedId === group.id ? 'border-sky-500 shadow-[0_0_40px_rgba(14,165,233,0.1)]' : 'border-slate-800/40'} ${group.status === 'online' ? 'card-online' : group.status === 'warning' ? 'card-warning' : 'card-error'}`}>
              <div className="absolute top-0 left-0 right-0 p-4 flex items-center justify-between pointer-events-none">
                 <div className="flex flex-col">
                   <span className="text-[10px] font-black text-slate-100 uppercase tracking-widest">{group.name}</span>
                   <span className={`text-[8px] font-bold ${getStatusConfig(group.status).color}`}>{getStatusConfig(group.status).text}</span>
                 </div>
                 <i className="fas fa-cubes text-slate-600 text-xs opacity-50"></i>
              </div>
            </div>
            {!isLocked && (
              <div className="absolute bottom-4 right-4 w-4 h-4 cursor-nwse-resize opacity-20 hover:opacity-100" onMouseDown={(e) => { e.stopPropagation(); setResizingId(group.id); }}>
                <i className="fas fa-expand-arrows-alt text-xs text-sky-400"></i>
              </div>
            )}
          </div>
        ))}

        <svg className="absolute inset-0 w-full h-full pointer-events-none z-[5]">
          <defs>
            <filter id="glow" x="-20%" y="-20%" width="140%" height="140%">
              <feGaussianBlur stdDeviation="3" result="blur" />
              <feMerge>
                <feMergeNode in="blur" />
                <feMergeNode in="SourceGraphic" />
              </feMerge>
            </filter>
          </defs>
          {connections.map((conn) => {
            const points = getConnectionPoint(conn.sourceId, conn.targetId);
            if (!points) return null;
            const isSelected = selectedConnectionId === conn.id;

            // 路径流动参数映射：
            // 绿色 (#00ff9d) 代表正常，红色 (#ff003c) 代表故障
            const color = conn.status === 'error' ? '#ff003c' : '#00ff9d';

            // 将 0-1 的 trafficLoad 映射为流动周期时长 (flow-dur)
            // 负载越高，周期越短 (流动越快)
            const flowDur = 2.0 / (0.5 + conn.trafficLoad * 2.5);

            const midX = (points.start.x + points.end.x) / 2;
            const midY = (points.start.y + points.end.y) / 2;

            return (
              <g key={conn.id}>
                <path d={getBezierPath(points.start, points.end)} stroke="transparent" strokeWidth="24" fill="none" className="cursor-pointer pointer-events-auto" onClick={(e) => { e.stopPropagation(); onConnectionClick(conn.id); }} />

                <path 
                  d={getBezierPath(points.start, points.end)} 
                  stroke={color} 
                  strokeWidth={isSelected ? 5 : 3} 
                  fill="none" 
                  className={`${getConnectionClass(conn.style)} ${isSelected ? 'selected-jump' : ''}`} 
                  filter="url(#glow)" 
                  style={{ 
                    opacity: isSelected ? 1 : 0.75, 
                    color,
                    '--flow-dur': `${flowDur}s`
                  } as React.CSSProperties} 
                />

                <text
                  x={midX}
                  y={midY - 8}
                  textAnchor="middle"
                  className="text-[9px] font-black fill-slate-300 pointer-events-none uppercase tracking-widest transition-opacity duration-300"
                  style={{ 
                    opacity: isSelected ? 1 : 0.6,
                    paintOrder: 'stroke',
                    stroke: '#020617',
                    strokeWidth: '4px',
                    strokeLinecap: 'round',
                    strokeLinejoin: 'round'
                  }}
                >
                  {conn.label}
                </text>
              </g>
            );
          })}
        </svg>

        {nodes.map((node) => {
          const isSelected = selectedId === node.id;
          const statusConfig = getStatusConfig(node.status);
          return (
            <div key={node.id} style={{ left: node.position.x, top: node.position.y, width: '130px', height: '44px', pointerEvents: 'auto' }} className="absolute z-10">
              <div className={`w-full h-full node-button rounded-xl flex items-center px-3 relative ${node.status === 'online' ? 'card-online' : node.status === 'warning' ? 'card-warning' : 'card-error'} ${isSelected ? 'ring-2 ring-sky-500/50 scale-105 z-20' : ''}`} onClick={(e) => { e.stopPropagation(); onElementClick(node.id); }} onMouseDown={(e) => { if (mode === 'select' && !isLocked) { e.stopPropagation(); setDraggingId(node.id); setDragType('node'); } }}>
                <div className="flex items-center gap-3 w-full">
                  <div className="w-8 h-8 rounded-lg bg-slate-900/50 flex items-center justify-center border border-white/5">
                    <i className={`fas ${SERVICE_ICONS[node.type]} text-xs transition-colors duration-300`} style={{ color: statusConfig.hex }}></i>
                  </div>
                  <div className="flex flex-col min-w-0"><span className="text-[9px] font-black text-slate-100 truncate uppercase">{node.name}</span><span className={`text-[7px] font-bold ${statusConfig.color}`}>{statusConfig.text}</span></div>
                </div>
              </div>
            </div>
          );
        })}
      </div>
      <div className="absolute bottom-1.5 left-2 right-2 h-1.5 bg-sky-500/5 rounded-full z-50 group hover:h-3 transition-all cursor-pointer"><div className="h-full bg-sky-500/20 rounded-full border border-sky-500/10" style={{ width: `${scrollMetrics.h.size}px`, transform: `translateX(${scrollMetrics.h.pos}px)` }} onMouseDown={(e) => { e.stopPropagation(); setDraggingId('scrollbar-h'); setLastMousePos({ x: e.clientX, y: e.clientY }); }} /></div>
      <div className="absolute top-2 bottom-2 right-1.5 w-1.5 bg-sky-500/5 rounded-full z-50 group hover:w-3 transition-all cursor-pointer"><div className="w-full bg-sky-500/20 rounded-full border border-sky-500/10" style={{ height: `${scrollMetrics.v.size}px`, transform: `translateY(${scrollMetrics.v.pos}px)` }} onMouseDown={(e) => { e.stopPropagation(); setDraggingId('scrollbar-v'); setLastMousePos({ x: e.clientX, y: e.clientY }); }} /></div>
    </div>
  );
};

